"use client";

import { useEffect, useState } from "react";
import { Area, AreaChart, Bar, BarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { apiGet } from "@/lib/api";

function fmtC(v: number) { return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(v); }

export default function AnalyticsPage() {
  const [capital, setCapital] = useState<any[]>([]);
  const [pnl, setPnl] = useState<any>(null);
  const [days, setDays] = useState(30);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    setLoading(true);
    Promise.allSettled([
      apiGet(`/analytics/capital?days=${days}`),
      apiGet("/analytics/pnl"),
    ]).then(([capRes, pnlRes]) => {
      if (capRes.status === "fulfilled") setCapital(capRes.value?.data || []);
      if (pnlRes.status === "fulfilled") setPnl(pnlRes.value);
      setLoading(false);
    });
  }, [days]);

  const dailyPnl = capital.filter((d) => d.pnl !== undefined).map((d) => ({
    time: d.time ? new Date(d.time).toLocaleDateString("en", { month: "short", day: "numeric" }) : "",
    pnl: d.pnl,
    symbol: d.symbol,
  }));

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-[var(--text-primary)]">Analytics</h1>
          <p className="text-[var(--text-secondary)] mt-1 text-[13px]">P&L evolution, capital growth, and performance breakdown.</p>
        </div>
        <div className="flex gap-1 bg-[var(--bg-elevated)] border border-[var(--border-default)] rounded-[var(--radius-md)] p-0.5">
          {[7, 30, 90, 365].map((d) => (
            <button key={d} onClick={() => setDays(d)} className={`px-3 py-1.5 text-[12px] font-medium rounded-[var(--radius-sm)] transition-colors ${days === d ? "bg-[var(--accent-primary)] text-white" : "text-[var(--text-secondary)] hover:text-[var(--text-primary)]"}`}>
              {d === 365 ? "1Y" : `${d}D`}
            </button>
          ))}
        </div>
      </div>

      {/* Summary Metrics */}
      {pnl && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <div className="metric-card">
            <span className="label">Total P&L</span>
            <span className={`value text-[22px] ${pnl.total_pnl >= 0 ? "profit" : "loss"}`}>{fmtC(pnl.total_pnl)}</span>
          </div>
          <div className="metric-card">
            <span className="label">Total Trades</span>
            <span className="value text-[22px]">{pnl.total_trades}</span>
            <span className="caption">{pnl.winning_trades}W / {pnl.losing_trades}L</span>
          </div>
          <div className="metric-card">
            <span className="label">Best Trade</span>
            <span className="value text-[22px] profit">{fmtC(pnl.best_trade)}</span>
          </div>
          <div className="metric-card">
            <span className="label">Worst Trade</span>
            <span className="value text-[22px] loss">{fmtC(pnl.worst_trade)}</span>
          </div>
        </div>
      )}

      {/* Capital Evolution Chart */}
      <div className="card">
        <div className="card-header"><h3>Capital Evolution</h3></div>
        <div className="card-body h-[360px]">
          {loading ? (
            <div className="skeleton h-full w-full" />
          ) : capital.length > 1 ? (
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={capital} margin={{ top: 10, right: 10, left: -10, bottom: 0 }}>
                <defs>
                  <linearGradient id="gradCap" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stopColor="#34D399" stopOpacity={0.2} />
                    <stop offset="100%" stopColor="#34D399" stopOpacity={0} />
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="4 4" stroke="rgba(255,255,255,0.04)" vertical={false} />
                <XAxis dataKey="time" axisLine={false} tickLine={false} tick={{ fill: "#555B6E", fontSize: 11, fontFamily: "JetBrains Mono" }} tickFormatter={(v) => v ? new Date(v).toLocaleDateString("en", { month: "short", day: "numeric" }) : ""} />
                <YAxis axisLine={false} tickLine={false} tick={{ fill: "#555B6E", fontSize: 11, fontFamily: "JetBrains Mono" }} tickFormatter={(v) => `$${(v / 1000).toFixed(0)}k`} />
                <Tooltip contentStyle={{ backgroundColor: "#1A1B25", border: "1px solid rgba(255,255,255,0.1)", borderRadius: "8px", fontFamily: "JetBrains Mono", color: "#8B92A5" }} formatter={(v) => [fmtC(v as number), "Capital"]} />
                <Area type="monotone" dataKey="value" stroke="#34D399" strokeWidth={2} fill="url(#gradCap)" />
              </AreaChart>
            </ResponsiveContainer>
          ) : (
            <div className="flex items-center justify-center h-full text-[var(--text-tertiary)] text-[13px]">No data yet. Charts appear after trades are closed.</div>
          )}
        </div>
      </div>

      {/* Per-Trade P&L Bar Chart */}
      {dailyPnl.length > 0 && (
        <div className="card">
          <div className="card-header"><h3>Per-Trade P&L</h3></div>
          <div className="card-body h-[280px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={dailyPnl} margin={{ top: 10, right: 10, left: -10, bottom: 0 }}>
                <CartesianGrid strokeDasharray="4 4" stroke="rgba(255,255,255,0.04)" vertical={false} />
                <XAxis dataKey="time" axisLine={false} tickLine={false} tick={{ fill: "#555B6E", fontSize: 10, fontFamily: "JetBrains Mono" }} />
                <YAxis axisLine={false} tickLine={false} tick={{ fill: "#555B6E", fontSize: 11, fontFamily: "JetBrains Mono" }} tickFormatter={(v) => `$${v}`} />
                <Tooltip contentStyle={{ backgroundColor: "#1A1B25", border: "1px solid rgba(255,255,255,0.1)", borderRadius: "8px", fontFamily: "JetBrains Mono", color: "#8B92A5" }} formatter={(v) => [fmtC(v as number), "P&L"]} labelFormatter={(l) => l} />
                <Bar dataKey="pnl" radius={[3, 3, 0, 0]} fill="#34D399" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * Next.js catch-all API Route Proxy
 * Forwards all /api/* requests to the FastAPI backend (Cloud Run).
 *
 * Compatible with Next.js 15 where route handler params are async (Promise).
 */
import { NextRequest, NextResponse } from 'next/server';

// BACKEND_URL is the base URL of the backend service.
// It may or may not include a trailing /api — both forms are handled correctly.
// Example: https://scalpyn-api-xxx.a.run.app  OR  https://scalpyn-api-xxx.a.run.app/api
const BACKEND_ROOT = (process.env.BACKEND_URL ?? 'http://localhost:8000')
  .replace(/\/$/, '')    // strip trailing slash
  .replace(/\/api$/, ''); // strip /api suffix if present so we never double it

type RouteContext = { params: Promise<{ path: string[] }> };

// Routes that require trailing slash for FastAPI
const COLLECTION_ROUTES = ['/api/pools', '/api/trades', '/api/orders', '/api/exchanges', '/api/watchlist', '/api/watchlists', '/api/profiles', '/api/custom-watchlists'];

async function proxyRequest(req: NextRequest, context: RouteContext): Promise<NextResponse> {
    // Await params (required in Next.js 15+)
  await context.params;

  // Forward the full /api/... path
  let rawPath = req.nextUrl.pathname;

  // Add trailing slash for collection routes (FastAPI requires it)
  if (COLLECTION_ROUTES.includes(rawPath) && !rawPath.endsWith('/')) {
    rawPath = rawPath + '/';
  }

  const search = req.nextUrl.search ?? '';
  const targetUrl = `${BACKEND_ROOT}${rawPath}${search}`;

  // Forward all headers except host (which would confuse the backend)
  const forwardHeaders: Record<string, string> = {};
  req.headers.forEach((value, key) => {
    const lower = key.toLowerCase();
    if (lower !== 'host' && lower !== 'accept-encoding' && lower !== 'connection') {
      forwardHeaders[key] = value;
    }
  });

  const hasBody = req.method !== 'GET' && req.method !== 'HEAD';
  const body = hasBody ? await req.arrayBuffer() : undefined;

  const startedAt = Date.now();

  let backendRes: Response;
  try {
    backendRes = await fetch(targetUrl, {
      method: req.method,
      headers: forwardHeaders,
      body: body ? Buffer.from(body) : undefined,
      redirect: 'follow',
    });
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    // eslint-disable-next-line no-console
    console.error(
      `[api-proxy] upstream fetch failed method=${req.method} path=${rawPath} elapsed=${Date.now() - startedAt}ms err=${message}`,
    );
    return NextResponse.json(
      { detail: 'Upstream API unreachable' },
      { status: 502 },
    );
  }

  if (!backendRes.ok) {
    // eslint-disable-next-line no-console
    console.warn(
      `[api-proxy] upstream non-2xx method=${req.method} path=${rawPath} status=${backendRes.status} elapsed=${Date.now() - startedAt}ms`,
    );
  }

  // Forward response headers back to client
  const resHeaders = new Headers();
  backendRes.headers.forEach((value, key) => {
    const lower = key.toLowerCase();
    if (lower !== 'transfer-encoding' && lower !== 'content-encoding') {
      resHeaders.set(key, value);
    }
  });

  if (
    backendRes.headers.get("content-type")?.includes("text/event-stream")
  ) {
    return new NextResponse(backendRes.body, {
      status: backendRes.status,
      headers: resHeaders,
    });
  }

  const responseBody = await backendRes.arrayBuffer();

  return new NextResponse(responseBody, {
    status: backendRes.status,
    headers: resHeaders,
  });
}

export async function GET(req: NextRequest, context: RouteContext) {
    return proxyRequest(req, context);
}
export async function POST(req: NextRequest, context: RouteContext) {
    return proxyRequest(req, context);
}
export async function PUT(req: NextRequest, context: RouteContext) {
    return proxyRequest(req, context);
}
export async function PATCH(req: NextRequest, context: RouteContext) {
    return proxyRequest(req, context);
}
export async function DELETE(req: NextRequest, context: RouteContext) {
    return proxyRequest(req, context);
}
export async function OPTIONS(req: NextRequest, context: RouteContext) {
    return proxyRequest(req, context);
}

"use client";

import { useEffect, useState, useCallback, useRef } from "react";
import {
  Bot,
  RefreshCw,
  Play,
  RotateCcw,
  ChevronDown,
  ChevronRight,
  CheckCircle,
  Zap,
  Shield,
} from "lucide-react";
import { apiGet, apiPost } from "@/lib/api";

// ── Types ──────────────────────────────────────────────────────────────────────

interface Profile {
  id: string;
  name: string;
  profile_role: string | null;
  autopilot_enabled: boolean;
}

interface AutopilotStatus {
  profile_id: string;
  profile_name: string;
  profile_role: string | null;
  auto_pilot_enabled: boolean;
  dry_run_mode: boolean;
  last_mutation_at: string | null;
  last_regime: string | null;
  last_mutation_reason: string | null;
  last_analysis_summary: string | null;
  macro_risk: string | null;
  consecutive_regressions: number;
  circuit_breaker_active: boolean;
  circuit_breaker_until: string | null;
  ev_before_last_mutation: number | null;
  ev_after_last_mutation: number | null;
  performance: any;
}

interface AuditLog {
  id: string;
  action: string;
  reason: string;
  regime: string | null;
  perf_snapshot: any;
  version_id: string | null;
  trigger_source: string | null;
  celery_task_id: string | null;
  profile_name: string | null;
  created_at: string;
}

interface ProfileVersion {
  id: string;
  version_number: number;
  regime: string | null;
  ev_at_snapshot: number | null;
  win_rate_at_snapshot: number | null;
  fpr_at_snapshot: number | null;
  n_samples: number | null;
  mutation_reason: string | null;
  created_at: string;
}

// ── Helpers ────────────────────────────────────────────────────────────────────

function fmtDate(iso: string | null) {
  if (!iso) return "—";
  return new Date(iso).toLocaleString("pt-BR", {
    day: "2-digit", month: "2-digit", year: "2-digit",
    hour: "2-digit", minute: "2-digit",
  });
}

function fmtPct(v: number | null) {
  if (v == null) return "—";
  const sign = v >= 0 ? "+" : "";
  return `${sign}${(v * 100).toFixed(2)}%`;
}

function actionBadge(action: string) {
  if (action === "MUTATED")
    return <span className="badge bullish text-[10px]">MUTATED</span>;
  if (action === "DRY_RUN_MUTATED")
    return <span className="badge bullish text-[10px] opacity-70">[DRY RUN] MUTATED</span>;
  if (action === "DRY_RUN_RULES_ADJUSTED")
    return <span className="badge range text-[10px] opacity-80">[DRY RUN] RULES ADJUSTED</span>;
  if (action === "DRY_RUN_ANALYZED")
    return <span className="badge range text-[10px] opacity-70">[DRY RUN] ANALYZED</span>;
  if (action === "RULES_ADJUSTED")
    return <span className="badge bullish text-[10px]">RULES ADJUSTED</span>;
  if (action === "CIRCUIT_BREAKER")
    return <span className="badge bearish text-[10px]">CIRCUIT BREAKER</span>;
  if (action === "KILLED")
    return <span className="badge bearish text-[10px]">KILLED</span>;
  if (action === "SCOPE_VIOLATION_BLOCKED")
    return <span className="badge bearish text-[10px]">SCOPE BLOCKED</span>;
  return <span className="badge range text-[10px]">{action}</span>;
}

function regimeBadge(regime: string | null) {
  if (!regime) return <span className="text-[var(--text-tertiary)]">—</span>;
  const color =
    regime === "TRENDING" ? "bullish" :
    regime === "VOLATILE" ? "bearish" : "range";
  return <span className={`badge ${color} text-[10px]`}>{regime}</span>;
}

// ── Main Page ──────────────────────────────────────────────────────────────────

export default function AutopilotPage() {
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [status, setStatus] = useState<AutopilotStatus | null>(null);
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([]);
  const [versions, setVersions] = useState<ProfileVersion[]>([]);
  const [loadingProfiles, setLoadingProfiles] = useState(true);
  const [loadingDetail, setLoadingDetail] = useState(false);
  const [running, setRunning] = useState(false);
  const [runElapsed, setRunElapsed] = useState(0);
  const [toggling, setToggling] = useState(false);
  const [rollingBack, setRollingBack] = useState<string | null>(null);
  const [runResult, setRunResult] = useState<any>(null);
  const [expandedLog, setExpandedLog] = useState<string | null>(null);
  const runTimerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  // Load profile list
  useEffect(() => {
    (async () => {
      try {
        const data = await apiGet("/profiles");
        const all: Profile[] = data.profiles || [];
        setProfiles(all);
        // Default: first autopilot-enabled profile
        const ap = all.find((p) => p.autopilot_enabled);
        if (ap) setSelectedId(ap.id);
        else if (all.length > 0) setSelectedId(all[0].id);
      } catch (e) {
        console.error(e);
      } finally {
        setLoadingProfiles(false);
      }
    })();
  }, []);

  // Load status + history when profile changes
  const loadDetail = useCallback(async (profileId: string) => {
    setLoadingDetail(true);
    setStatus(null);
    setAuditLogs([]);
    setVersions([]);
    setRunResult(null);
    try {
      const [s, h] = await Promise.all([
        apiGet(`/autopilot/${profileId}/status`),
        apiGet(`/autopilot/${profileId}/history`),
      ]);
      setStatus(s);
      setAuditLogs(h.audit_logs || []);
      setVersions(h.versions || []);
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingDetail(false);
    }
  }, []);

  useEffect(() => {
    if (selectedId) loadDetail(selectedId);
  }, [selectedId, loadDetail]);

  // Toggle Auto-Pilot
  const handleToggle = async () => {
    if (!selectedId || !status) return;
    setToggling(true);
    try {
      await apiPost(`/profiles/${selectedId}/autopilot/toggle`, {
        enabled: !status.auto_pilot_enabled,
      });
      await loadDetail(selectedId);
    } catch (e: any) {
      alert(`Erro ao alterar Auto-Pilot: ${e.message}`);
    } finally {
      setToggling(false);
    }
  };

  // Manual run
  const handleRun = async () => {
    if (!selectedId) return;
    setRunning(true);
    setRunElapsed(0);
    setRunResult(null);
    runTimerRef.current = setInterval(() => setRunElapsed((s) => s + 1), 1000);
    try {
      const res = await apiPost(`/autopilot/${selectedId}/run`);
      await loadDetail(selectedId);
      setRunResult({ ...res, elapsed_s: runElapsed });
    } catch (e: any) {
      setRunResult({ error: e.message });
    } finally {
      if (runTimerRef.current) {
        clearInterval(runTimerRef.current);
        runTimerRef.current = null;
      }
      setRunning(false);
    }
  };

  // Rollback
  const handleRollback = async (versionId: string) => {
    if (!selectedId) return;
    if (!confirm("Restaurar esta versão do profile? A config atual será substituída.")) return;
    setRollingBack(versionId);
    try {
      await apiPost(`/autopilot/${selectedId}/rollback/${versionId}`);
      await loadDetail(selectedId);
    } catch (e: any) {
      alert(`Rollback falhou: ${e.message}`);
    } finally {
      setRollingBack(null);
    }
  };

  // ── Render ─────────────────────────────────────────────────────────────────

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex justify-between items-start">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-[var(--text-primary)] flex items-center gap-2">
            <Bot className="w-6 h-6 text-blue-400" />
            Auto-Pilot
          </h1>
          <p className="text-[var(--text-secondary)] mt-1 text-[13px]">
            Monitoramento e histórico do sistema de evolução autônoma de profiles.
          </p>
        </div>
        {selectedId && (
          <button
            className="btn btn-secondary text-[12px] flex items-center gap-1"
            onClick={() => loadDetail(selectedId)}
            disabled={loadingDetail}
          >
            <RefreshCw className={`w-3.5 h-3.5 ${loadingDetail ? "animate-spin" : ""}`} />
            Atualizar
          </button>
        )}
      </div>

      {/* Profile selector */}
      {loadingProfiles ? (
        <div className="skeleton h-10 w-64 rounded" />
      ) : (
        <div className="flex items-center gap-3 flex-wrap">
          {profiles.map((p) => (
            <button
              key={p.id}
              onClick={() => setSelectedId(p.id)}
              className={`px-3 py-1.5 rounded-lg text-[12px] font-medium border transition-colors ${
                selectedId === p.id
                  ? "bg-blue-600 border-blue-500 text-white"
                  : "bg-[var(--bg-elevated)] border-[var(--border-default)] text-[var(--text-secondary)] hover:border-[var(--border-strong)]"
              }`}
            >
              {p.name}
              {p.autopilot_enabled && (
                <span className="ml-1.5 inline-block w-1.5 h-1.5 rounded-full bg-green-400 align-middle" />
              )}
            </button>
          ))}
        </div>
      )}

      {loadingDetail && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          {[1, 2, 3].map((i) => <div key={i} className="skeleton h-32 rounded-[var(--radius-lg)]" />)}
        </div>
      )}

      {!loadingDetail && status && (
        <>
          {/* Dry-run warning banner — always visible when guardrails.dry_run_mode=true */}
          {(status.dry_run_mode === true || runResult?.dry_run === true || auditLogs.some(l => l.action.startsWith("DRY_RUN"))) && (
            <div className="card p-3 border border-amber-500/40 bg-amber-500/5 flex items-start gap-3">
              <span className="text-amber-400 text-[18px] leading-none">⚠</span>
              <div>
                <span className="text-amber-400 text-[12px] font-semibold uppercase tracking-wide">Modo Simulação Ativo (dry_run_mode = true)</span>
                <p className="text-[11px] text-[var(--text-secondary)] mt-0.5">
                  O Auto-Pilot está analisando mas <strong>não persiste nenhuma mudança</strong> nos profiles. Todos os ajustes são apenas simulados.
                  Para ativar escrita real: <code className="text-amber-300 bg-black/30 px-1 rounded text-[10px]">UPDATE config_profiles SET config_json = config_json || '{`{"dry_run_mode": false}`}'::jsonb WHERE config_type = 'autopilot_guardrails'</code>
                </p>
              </div>
            </div>
          )}
          {/* Status cards */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {/* State */}
            <div className="card p-4 space-y-3">
              <div className="flex items-center justify-between">
                <span className="text-[11px] font-semibold text-[var(--text-tertiary)] uppercase tracking-wider">Estado</span>
                {status.circuit_breaker_active
                  ? <span className="badge bearish text-[10px] flex items-center gap-1"><Shield className="w-3 h-3" />Circuit Breaker</span>
                  : status.auto_pilot_enabled
                    ? <span className="badge bullish text-[10px]">ATIVO</span>
                    : <span className="badge range text-[10px]">INATIVO</span>}
              </div>
              <div className="space-y-1.5">
                <div className="flex justify-between text-[12px]">
                  <span className="text-[var(--text-tertiary)]">Regime</span>
                  {regimeBadge(status.last_regime)}
                </div>
                <div className="flex justify-between text-[12px]">
                  <span className="text-[var(--text-tertiary)]">Risco macro</span>
                  <span className="text-[var(--text-primary)] font-medium">{status.macro_risk || "—"}</span>
                </div>
                <div className="flex justify-between text-[12px]">
                  <span className="text-[var(--text-tertiary)]">Regressões</span>
                  <span className={`font-medium ${status.consecutive_regressions >= 2 ? "text-red-400" : "text-[var(--text-primary)]"}`}>
                    {status.consecutive_regressions}/3
                  </span>
                </div>
                {status.circuit_breaker_until && (
                  <div className="flex justify-between text-[12px]">
                    <span className="text-[var(--text-tertiary)]">Pausa até</span>
                    <span className="text-red-400 font-medium">{fmtDate(status.circuit_breaker_until)}</span>
                  </div>
                )}
              </div>
            </div>

            {/* Last mutation */}
            <div className="card p-4 space-y-3">
              <span className="text-[11px] font-semibold text-[var(--text-tertiary)] uppercase tracking-wider">Última Mutação</span>
              <div className="space-y-1.5">
                <div className="flex justify-between text-[12px]">
                  <span className="text-[var(--text-tertiary)]">Quando</span>
                  <span className="text-[var(--text-primary)] font-medium">{fmtDate(status.last_mutation_at)}</span>
                </div>
                <div className="flex justify-between text-[12px]">
                  <span className="text-[var(--text-tertiary)]">EV antes</span>
                  <span className={`font-medium ${(status.ev_before_last_mutation ?? 0) >= 0 ? "text-green-400" : "text-red-400"}`}>
                    {fmtPct(status.ev_before_last_mutation)}
                  </span>
                </div>
                <div className="flex justify-between text-[12px]">
                  <span className="text-[var(--text-tertiary)]">EV depois</span>
                  <span className={`font-medium ${(status.ev_after_last_mutation ?? 0) >= 0 ? "text-green-400" : "text-red-400"}`}>
                    {fmtPct(status.ev_after_last_mutation)}
                  </span>
                </div>
                {status.last_mutation_reason && (
                  <div className="text-[11px] text-[var(--text-tertiary)] pt-1 border-t border-[var(--border-subtle)]">
