          <linearGradient id="equityUp" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={C.profit} stopOpacity={0.20} />
            <stop offset="85%" stopColor={C.profit} stopOpacity={0} />
          </linearGradient>
