          tick={{ fill: C.textTertiary, fontSize: 11 }}
          tickFormatter={(v: number) => `$${Math.round(v).toLocaleString()}`}
          tickLine={false}
          axisLine={false}
          width={72}
        />
        <Tooltip content={<CustomTooltip />} />
        <Area
          type="monotone"
          dataKey="value"
          stroke={lineColor}
          strokeWidth={2}
          fill={isUp ? "url(#equityUp)" : "url(#equityDown)"}
