    if (!silent) setLoading(true);
    else setRefreshing(true);

    const dateParams = periodToApiParams(periodRef.current, customStartRef.current, customEndRef.current);

    try {
      const [ov, pl] = await Promise.all([
        apiGet<DashboardOverview>(`/analytics/dashboard?${dateParams}&min_value_usdt=10`),
        apiGet<PnlSummary>(`/analytics/pnl?${dateParams}`),
      ]);
      setOverview({
        ...ov,
        capital_evolution: Array.isArray(ov.capital_evolution) ? ov.capital_evolution : [],
        open_positions: Array.isArray(ov.open_positions) ? ov.open_positions : [],
      });
      setPnl(pl);
      setLastFetched(new Date());
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, []);

  const syncTrades = useCallback(async () => {
    setSyncing(true);
    setSyncResult(null);
    try {
      const res = await apiPost<{ message: string; imported: number; skipped: number }>("/trades/sync?all_history=true");
      setSyncResult({ ok: true, message: res.message });
      await fetchAll(true);
    } catch (err: any) {
      setSyncResult({ ok: false, message: err.message ?? "Sync failed" });
    } finally {
      setSyncing(false);
      setTimeout(() => setSyncResult(null), 8000);
    }
  }, [fetchAll]);

  useEffect(() => { fetchAll(); }, [fetchAll]);

  const handlePeriodSelect = (p: Period) => {
    setPeriod(p);
    periodRef.current = p;
    if (p !== "custom") {
      setTimeout(() => fetchAll(true), 0);
    }
  };

  const handleCustomApply = () => {
    if (customStart || customEnd) fetchAll(true);
  };

  const sparkline = useMemo(() => {
    if (!overview?.capital_evolution) return [];
    const pts = overview.capital_evolution;
    return pts.slice(-14).map((p) => p.value);
  }, [overview]);

  const ready = !loading && !!overview;

  return (
    <div className="space-y-6 pb-8" style={{ animation: "fadeIn 400ms ease-out" }}>
      <div className="flex items-start justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold tracking-tight" style={{ color: C.textPrimary }}>
            Performance
          </h1>
          <p className="text-[13px] mt-1" style={{ color: C.textSecondary }}>
            Portfolio analytics · Gate.io backed
          </p>
        </div>
        {activeTab === "overview" && (
          <div className="flex items-center gap-3 flex-shrink-0">
            {lastFetched && (
              <span className="text-[11px]" style={{ color: C.textTertiary }}>
                {lastFetched.toLocaleTimeString("en", { hour: "2-digit", minute: "2-digit" })}
              </span>
            )}
            <button
              onClick={syncTrades}
              disabled={syncing || refreshing}
              className="flex items-center gap-1.5 px-3 py-2 rounded-xl text-[12px] font-medium transition-opacity hover:opacity-80 disabled:opacity-40"
              style={{ background: "rgba(52,211,153,0.10)", color: C.profit, border: "1px solid rgba(52,211,153,0.20)" }}
            >
              <Download size={13} className={syncing ? "animate-bounce" : ""} />
              {syncing ? "Importing…" : "Import from Gate"}
            </button>
            <button
              onClick={() => fetchAll(true)}
              disabled={refreshing}
              className="flex items-center gap-1.5 px-3 py-2 rounded-xl text-[12px] font-medium transition-opacity hover:opacity-80 disabled:opacity-40"
              style={{ background: "rgba(79,123,247,0.12)", color: C.blue, border: "1px solid rgba(79,123,247,0.20)" }}
            >
              <RefreshCw size={13} className={refreshing ? "animate-spin" : ""} />
              Refresh
            </button>
          </div>
        )}
      </div>

      {/* Tab strip */}
      <div
        className="flex gap-1 p-0.5 rounded-xl w-fit"
        role="tablist"
        aria-label="Dashboard sections"
        style={{ background: C.elevated, border: `1px solid ${C.border}` }}
      >
        {(
          [
            { id: "overview", label: "Overview" },
            { id: "monitoring", label: "Monitoring" },
          ] as { id: DashboardTab; label: string }[]
        ).map(({ id, label }) => {
          const active = activeTab === id;
          return (
            <button
              key={id}
              role="tab"
              aria-selected={active}
              onClick={() => setActiveTab(id)}
              className="px-4 py-1.5 text-[12px] font-medium rounded-[10px] transition-all"
              style={
                active
                  ? { background: C.blue, color: "#fff" }
                  : { color: C.textSecondary }
              }
            >
              {label}
            </button>
          );
        })}
      </div>

      {activeTab === "monitoring" && <MonitoringTab />}

      {activeTab === "overview" && (
      <>
      {/* Period filter row */}
      <div className="flex flex-wrap items-center gap-2">
        <div
          className="flex gap-1 p-0.5 rounded-xl"
          style={{ background: C.elevated, border: `1px solid ${C.border}` }}
        >
          {(["1d", "7d", "30d", "90d"] as Period[]).map((p) => (
            <button
              key={p}
              onClick={() => handlePeriodSelect(p)}
              className="px-3 py-1.5 text-[12px] font-medium rounded-[10px] transition-all"
              style={
                period === p
                  ? { background: C.blue, color: "#fff" }
                  : { color: C.textSecondary }
              }
            >
              {PERIOD_LABELS[p]}
            </button>
          ))}
        </div>

        <div className="flex items-center gap-1.5">
          <Calendar size={13} style={{ color: C.textTertiary }} />
          <input
            type="date"
            value={customStart}
            onChange={(e) => { setCustomStart(e.target.value); setPeriod("custom"); customStartRef.current = e.target.value; }}
            className="text-[11px] rounded-lg px-2 py-1.5 focus:outline-none"
            style={{ background: C.elevated, border: `1px solid ${C.border}`, color: C.textPrimary }}
          />
          <span className="text-[11px]" style={{ color: C.textTertiary }}>–</span>
          <input
            type="date"
            value={customEnd}
            onChange={(e) => { setCustomEnd(e.target.value); setPeriod("custom"); customEndRef.current = e.target.value; }}
            className="text-[11px] rounded-lg px-2 py-1.5 focus:outline-none"
            style={{ background: C.elevated, border: `1px solid ${C.border}`, color: C.textPrimary }}
          />
          {period === "custom" && (
            <button
              onClick={handleCustomApply}
              className="px-2.5 py-1.5 text-[11px] font-medium rounded-lg transition-opacity hover:opacity-80"
              style={{ background: C.blue, color: "#fff" }}
            >
              Aplicar
            </button>
          )}
        </div>
      </div>

      {syncResult && (
        <div
          className="flex items-start gap-2.5 px-4 py-3 rounded-xl text-[12px]"
          style={{
            background: syncResult.ok ? "rgba(52,211,153,0.08)" : "rgba(248,113,113,0.08)",
            border: `1px solid ${syncResult.ok ? "rgba(52,211,153,0.20)" : "rgba(248,113,113,0.20)"}`,
            color: syncResult.ok ? C.profit : C.loss,
          }}
        >
          {syncResult.ok
            ? <CheckCircle size={14} className="flex-shrink-0 mt-0.5" />
            : <AlertCircle size={14} className="flex-shrink-0 mt-0.5" />}
          {syncResult.message}
        </div>
      )}

      {loading ? (
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
          {[...Array(4)].map((_, i) => (
            <div key={i} className="rounded-2xl p-5 h-36" style={{ background: C.elevated, border: `1px solid ${C.border}` }}>
              <div className="skeleton h-3 w-20 rounded mb-4" />
              <div className="skeleton h-7 w-28 rounded mb-3" />
              <div className="skeleton h-2.5 w-24 rounded" />
            </div>
          ))}
        </div>
      ) : overview ? (
        <>
          <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
            <KpiCard
              label="Total P&L"
              mainValue={overview.realized_total_pnl}
              helperText={pnl ? `ROI ${fmtPct(pnl.total_pnl_pct)} · ${pnl.total_trades} trades` : undefined}
              delta={pnl?.total_pnl_pct}
              sparkData={sparkline}
              delay={0}
              ready={ready}
            />
            <KpiCard
              label="Today's P&L"
              mainValue={overview.today_pnl}
              helperText={`Unrealized: ${fmtUsd(overview.unrealized_pnl)}`}
              delay={80}
              ready={ready}
            />
            <KpiCard
              label="Portfolio Value"
              mainValue={overview.portfolio_value}
              helperText={`Spot ${fmtUsd(overview.spot_value, true)} · Futures ${fmtUsd(overview.futures_value, true)}`}
              delay={160}
              ready={ready}
            />
            <KpiCard
              label="Win Rate"
              mainValue={pnl?.win_rate ?? overview.win_rate}
              isCurrency={false}
              helperText={
                pnl
                  ? `${pnl.winning_trades}W · ${pnl.losing_trades}L · PF ${pnl.profit_factor?.toFixed(2) ?? "—"}`
                  : undefined
              }
              delay={240}
              ready={ready}
            />
          </div>

          <div className="grid grid-cols-1 xl:grid-cols-[1.6fr,1fr] gap-6">
            <Card>
              <div className="flex items-center justify-between mb-5">
                <div>
                  <SectionHeader title="Equity Curve" />
                </div>
                <div className="flex items-center gap-2">
                  {overview.capital_evolution.length > 0 && (
                    <span
                      className="flex items-center gap-1 text-[12px] font-semibold"
                      style={{
                        color: overview.realized_total_pnl >= 0 ? C.profit : C.loss,
                      }}
                    >
                      {overview.realized_total_pnl >= 0 ? (
                        <TrendingUp size={14} />
                      ) : (
                        <TrendingDown size={14} />
                      )}
                      {fmtUsd(overview.realized_total_pnl)}
                    </span>
                  )}
                  <span className="text-[11px] px-2 py-1 rounded-lg" style={{ background: "rgba(255,255,255,0.04)", color: C.textTertiary }}>{PERIOD_LABELS[period]}</span>
                </div>
              </div>
              <EquityCurve data={overview.capital_evolution} />
            </Card>

            <Card>
              <SectionHeader title="Distribution" sub="Win vs Loss breakdown" />
              <WinLossChart
                winning={pnl?.winning_trades ?? 0}
                losing={pnl?.losing_trades ?? 0}
              />
              <div className="mt-3 flex gap-4 justify-center">
                <span className="flex items-center gap-1.5 text-[12px]" style={{ color: C.textSecondary }}>
                  <span className="w-2.5 h-2.5 rounded-full" style={{ background: C.profit }} />
                  {pnl?.winning_trades ?? 0} wins
                </span>
                <span className="flex items-center gap-1.5 text-[12px]" style={{ color: C.textSecondary }}>
                  <span className="w-2.5 h-2.5 rounded-full" style={{ background: C.loss }} />
                  {pnl?.losing_trades ?? 0} losses
                </span>
              </div>

              {pnl && (
                <div className="mt-4 space-y-0">
                  <StatRow label="Profit Factor" value={pnl.profit_factor?.toFixed(2) ?? "—"} tone={pnl.profit_factor && pnl.profit_factor > 1 ? "profit" : "loss"} />
                  <StatRow label="Sharpe Ratio" value={pnl.sharpe_ratio?.toFixed(2) ?? "—"} tone={pnl.sharpe_ratio && pnl.sharpe_ratio > 1 ? "profit" : "neutral"} />
                  <StatRow label="Max Drawdown" value={fmtUsd(pnl.max_drawdown_pct)} tone={pnl.max_drawdown_pct > 0 ? "loss" : "neutral"} />
                  <StatRow label="Best Trade" value={fmtUsd(pnl.best_trade)} tone="profit" />
                  <StatRow label="Worst Trade" value={fmtUsd(pnl.worst_trade)} tone="loss" />
                  <StatRow label="Avg Hold" value={fmtHours(pnl.avg_holding_seconds)} />
                </div>
              )}
            </Card>
          </div>

          <Card>
            <div className="flex items-center justify-between mb-5">
              <SectionHeader title="Daily P&L" sub="Realized P&L per day" />
            </div>
            <DailyPnlChart data={overview.capital_evolution} />
          </Card>

          {overview.open_positions.length > 0 && (
            <Card>
              <SectionHeader title="Open Positions" sub={`${overview.open_positions.length} active`} />
              <div className="overflow-x-auto">
                <table className="w-full text-[12px]">
                  <thead>
                    <tr style={{ borderBottom: `1px solid ${C.border}` }}>
                      {["Asset", "Direction", "Entry", "Current", "Value", "P&L"].map((h) => (
                        <th
                          key={h}
                          className="px-4 py-2.5 text-left"
                          style={{ color: C.textTertiary, fontWeight: 600, letterSpacing: "0.06em", textTransform: "uppercase", fontSize: 10 }}
                        >
                          {h}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {overview.open_positions.map((pos) => (
                      <tr
                        key={pos.id}
                        className="hover:bg-white/[0.02] transition-colors"
                        style={{ borderBottom: `1px solid ${C.border}` }}
                      >
                        <td className="px-4 py-3 font-semibold" style={{ color: C.textPrimary }}>
                          {pos.symbol.replace("_USDT", "")}
                          <span className="ml-1 text-[10px] font-normal" style={{ color: C.textTertiary }}>{pos.market_type}</span>
                        </td>
                        <td className="px-4 py-3">
                          <span
                            className="px-2 py-0.5 rounded text-[10px] font-semibold uppercase"
                            style={{
                              background: pos.direction === "long" ? "rgba(52,211,153,0.10)" : "rgba(248,113,113,0.10)",
                              color: pos.direction === "long" ? C.profit : C.loss,
                            }}
                          >
                            {pos.direction}
                          </span>
                        </td>
                        <td className="px-4 py-3 tabular-nums" style={{ color: C.textSecondary }}>{fmtUsd(pos.entry_price)}</td>
                        <td className="px-4 py-3 tabular-nums" style={{ color: C.textPrimary }}>{fmtUsd(pos.current_price)}</td>
                        <td className="px-4 py-3 tabular-nums" style={{ color: C.textSecondary }}>{fmtUsd(pos.current_value)}</td>
                        <td className="px-4 py-3 tabular-nums font-semibold" style={{ color: pos.profit_loss >= 0 ? C.profit : C.loss }}>
                          {pos.profit_loss >= 0 ? "+" : ""}
                          {fmtUsd(pos.profit_loss)}
                          <span className="ml-1 text-[11px]">({fmtPct(pos.profit_loss_pct)})</span>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </Card>
          )}

          <TradeTable data={overview.capital_evolution} loading={loading} />
        </>
      ) : (
        <div
          className="flex flex-col items-center justify-center py-24 rounded-2xl"
          style={{ background: C.elevated, border: `1px solid ${C.border}` }}
        >
          <Wallet size={36} className="mb-4 opacity-30" style={{ color: C.textTertiary }} />
          <p className="text-sm" style={{ color: C.textTertiary }}>Unable to load dashboard data.</p>
          <button
            onClick={() => fetchAll()}
            className="mt-4 px-4 py-2 rounded-xl text-[13px] font-medium transition-opacity hover:opacity-80"
            style={{ background: "rgba(79,123,247,0.12)", color: C.blue }}
          >
            Retry
          </button>
        </div>
      )}
      </>
      )}
    </div>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import {
  Activity, AlertTriangle, ArrowDownRight, ArrowUpRight, ChevronDown, ChevronRight,
  Download, Layers, RefreshCw, Settings2, TrendingUp, Wallet,
} from "lucide-react";
import {
  Area, AreaChart, Bar, BarChart, CartesianGrid, Cell,
  Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis,
} from "recharts";
import { apiGet, apiPost } from "@/lib/api";
import {
  ExecutionFilters,
  PerformanceFilter,
  WindowKey,
  usePerformanceByAsset,
  usePerformanceDistribution,
  usePerformanceEquity,
  usePerformanceExecutions,
  usePerformanceSummary,
  useGateAccountToday,
} from "@/hooks/usePerformance";

// ── theme ────────────────────────────────────────────────────────────────────
const C = {
  bg: "#0A0B10",
  surface: "#10121A",
  elevated: "#161824",
  border: "rgba(255,255,255,0.06)",
  borderStrong: "rgba(255,255,255,0.12)",
  text: "#E6E8EE",
  muted: "#8A91A4",
  dim: "#5A6075",
  green: "#22B97A",
  red: "#E5484D",
  blue: "#4F7BF7",
  purple: "#9D7CF7",
  amber: "#F2A33A",
} as const;

const WINDOWS: { key: WindowKey; label: string }[] = [
  { key: "1D", label: "Hoje" },
  { key: "7D", label: "7d" },
  { key: "15D", label: "15d" },
  { key: "30D", label: "30d" },
  { key: "90D", label: "90d" },
];

const dateBoundary = (value: string, nextDay = false) => {
  const date = new Date(`${value}T00:00:00`);
  if (nextDay) date.setDate(date.getDate() + 1);
  return date.toISOString();
};

const fmtUsd = (n: number | null | undefined, dp = 2) =>
  n === null || n === undefined || Number.isNaN(n)
    ? "—"
    : n.toLocaleString("en-US", { minimumFractionDigits: dp, maximumFractionDigits: dp });
const fmtPct = (n: number | null | undefined, dp = 2) =>
  n === null || n === undefined || Number.isNaN(n) ? "—" : `${n.toFixed(dp)}%`;
const fmtSec = (s: number | null | undefined) => {
  if (!s || s < 0) return "—";
  if (s < 60) return `${s}s`;
  if (s < 3600) return `${Math.floor(s / 60)}m ${s % 60}s`;
  if (s < 86400) return `${Math.floor(s / 3600)}h ${Math.floor((s % 3600) / 60)}m`;
  const d = Math.floor(s / 86400);
  const h = Math.floor((s % 86400) / 3600);
  return `${d}d ${h}h`;
};
const num = (n: number | null | undefined, dp = 4) =>
  n === null || n === undefined ? "—" : n.toLocaleString("en-US", { maximumFractionDigits: dp });

const dateInputStyle: React.CSSProperties = {
  colorScheme: "dark", background: C.elevated, color: C.text,
  border: `1px solid ${C.borderStrong}`, borderRadius: 6,
  padding: "5px 8px", fontSize: 11.5,
};

// ── tiny UI helpers ──────────────────────────────────────────────────────────
function StatCard({
  label, value, hint, accent, sub,
}: {
  label: string; value: string; hint?: string;
  accent?: "green" | "red" | "blue" | "amber"; sub?: string;
}) {
  const accentColor = accent === "green" ? C.green : accent === "red" ? C.red : accent === "amber" ? C.amber : C.text;
  return (
    <div style={{ background: C.elevated, border: `1px solid ${C.border}`, borderRadius: 10, padding: "14px 16px" }}>
      <div style={{ fontSize: 11, color: C.muted, letterSpacing: 0.6, textTransform: "uppercase" }}>{label}</div>
      <div style={{ fontSize: 22, fontWeight: 600, fontVariantNumeric: "tabular-nums", color: accentColor, marginTop: 6 }}>
        {value}
      </div>
      {sub ? <div style={{ fontSize: 11, color: C.muted, fontVariantNumeric: "tabular-nums", marginTop: 4 }}>{sub}</div> : null}
      {hint ? <div style={{ fontSize: 10.5, color: C.dim, marginTop: 4 }}>{hint}</div> : null}
    </div>
  );
}

function SectionTitle({ icon, label, right }: { icon?: React.ReactNode; label: string; right?: React.ReactNode }) {
  return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 10 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, color: C.muted, fontSize: 12, letterSpacing: 0.6, textTransform: "uppercase" }}>
        {icon}{label}
      </div>
      {right}
    </div>
  );
}

function ChartCard({ title, children, height = 240 }: { title: string; children: React.ReactNode; height?: number }) {
  return (
    <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 10, padding: 14 }}>
      <div style={{ fontSize: 12, color: C.muted, letterSpacing: 0.6, textTransform: "uppercase", marginBottom: 10 }}>{title}</div>
      <div style={{ width: "100%", height }}>{children}</div>
    </div>
  );
}

// ── filter bar ───────────────────────────────────────────────────────────────
function FilterBar({
  filter, onChange, onSync, syncing,
}: {
  filter: PerformanceFilter;
  onChange: (next: PerformanceFilter) => void;
  onSync: () => void;
  syncing: boolean;
}) {
  return (
    <div style={{
      background: C.surface, border: `1px solid ${C.border}`, borderRadius: 10,
      padding: "10px 14px", display: "flex", alignItems: "center", justifyContent: "space-between",
      gap: 12, flexWrap: "wrap",
    }}>
      <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
        {WINDOWS.map(({ key, label }) => {
          const active = filter.window === key && !filter.from;
          return (
            <button key={key} onClick={() => onChange({ ...filter, window: key, from: undefined, to: undefined })}
              style={{
                background: active ? C.elevated : "transparent",
                color: active ? C.text : C.muted,
                border: `1px solid ${active ? C.borderStrong : C.border}`,
                borderRadius: 6, padding: "5px 10px", fontSize: 11.5, cursor: "pointer",
                letterSpacing: 0.4,
              }}>
              {label}
            </button>
          );
        })}
        <input type="date" aria-label="Data inicial"
          value={filter.from ? filter.from.slice(0, 10) : ""}
          onChange={e => e.target.value && onChange({
            ...filter, from: dateBoundary(e.target.value),
            to: filter.to ?? dateBoundary(e.target.value, true),
          })}
          style={dateInputStyle} />
        <span style={{ color: C.dim, fontSize: 11 }}>até</span>
        <input type="date" aria-label="Data final"
          value={filter.to ? new Date(new Date(filter.to).getTime() - 1).toISOString().slice(0, 10) : ""}
          min={filter.from?.slice(0, 10)}
          onChange={e => e.target.value && onChange({
            ...filter, to: dateBoundary(e.target.value, true),
          })}
          style={dateInputStyle} />
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 8, color: C.muted, fontSize: 11.5 }}>
        <label style={{ display: "flex", alignItems: "center", gap: 6, cursor: "pointer" }}>
          <input type="checkbox" checked={filter.autoRefresh}
            onChange={e => onChange({ ...filter, autoRefresh: e.target.checked })} />
          Auto-refresh 30s
        </label>
        <button onClick={onSync} disabled={syncing}
          style={{
            background: C.elevated, border: `1px solid ${C.borderStrong}`, color: C.text,
            borderRadius: 6, padding: "6px 12px", fontSize: 11.5, cursor: "pointer",
            display: "inline-flex", alignItems: "center", gap: 6, opacity: syncing ? 0.6 : 1,
          }}>
          <RefreshCw size={13} className={syncing ? "spin" : ""} />
          {syncing ? "Sincronizando…" : "Sync Gate.io"}
        </button>
      </div>
      <style jsx>{`
        .spin { animation: spin 1s linear infinite; }
        @keyframes spin { from { transform: rotate(0deg);} to { transform: rotate(360deg);} }
      `}</style>
    </div>
  );
}

// ── flash cards cluster ──────────────────────────────────────────────────────
function FlashCards({ filter }: { filter: PerformanceFilter }) {
  const { data, isLoading, error } = usePerformanceSummary(filter);
  const { data: gateToday, isLoading: gateLoading } = useGateAccountToday(filter.autoRefresh);

  if (error) return (
    <div style={{ background: C.surface, border: `1px solid ${C.red}55`, borderRadius: 10, padding: 14, color: C.red, fontSize: 12 }}>
      <AlertTriangle size={14} style={{ verticalAlign: "middle" }} /> Erro ao carregar resumo: {String(error.message ?? error)}
    </div>
  );

  const s = data;
  const placeholder = isLoading || !s;

  const pnlColor = s && s.pnl.total_usdt >= 0 ? "green" : "red";
  const deltaColor = s && s.pnl.delta_vs_previous >= 0 ? "green" : "red";

  return (
    <>
    <div style={{ display: "grid", gridTemplateColumns: "repeat(3, minmax(0, 1fr))", gap: 12 }}>
      <StatCard label="Ordens executadas na Gate" value={placeholder ? "—" : String(s.stats.executed_trades)} hint="Ordens concluídas únicas · Spot + Futures · fonte Gate API" />
      <StatCard label="PnL de hoje na Gate" value={gateLoading || !gateToday?.available ? "—" : fmtPct(gateToday.pnl_pct)} accent={(gateToday?.pnl_usdt ?? 0) >= 0 ? "green" : "red"} hint="Variação patrimonial desde 00:00 · fonte Gate API" />
      <StatCard label="Valor ganho hoje na Gate" value={gateLoading || !gateToday?.available ? "—" : `${(gateToday.pnl_usdt ?? 0) >= 0 ? "+" : ""}$${fmtUsd(gateToday.pnl_usdt)}`} accent={(gateToday?.pnl_usdt ?? 0) >= 0 ? "green" : "red"} hint={`Capital atual $${fmtUsd(gateToday?.current_equity_usdt)} · inicial $${fmtUsd(gateToday?.start_equity_usdt)}`} />
    </div>
    <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 12 }}>
      {/* Capital cluster */}
      <div>
        <SectionTitle icon={<Wallet size={13} />} label="Capital" />
        <div style={{ display: "grid", gap: 8 }}>
          <StatCard label="Giro executado (período)" value={placeholder ? "—" : `$${fmtUsd(s.capital.invested_usdt)}`} sub="Soma do capital aplicado nos fechamentos; pode reutilizar o mesmo saldo" />
          <StatCard label="Lotes FIFO em aberto" value={placeholder ? "—" : String(s.capital.open_positions)} hint="Projeção histórica; não representa o saldo atual da Gate" />
        </div>
      </div>

      {/* PnL cluster */}
      <div>
        <SectionTitle icon={<TrendingUp size={13} />} label="PnL" />
        <div style={{ display: "grid", gap: 8 }}>
          <StatCard label="PnL realizado FIFO" value={placeholder ? "—" : `$${fmtUsd(s.pnl.total_usdt)}`} accent={pnlColor as "green" | "red"} sub={`ROI sobre lotes fechados ${fmtPct(s?.pnl.roi_pct)} · não é o PnL patrimonial Gate`} />
          <StatCard label="Δ vs período anterior" value={placeholder ? "—" : `${s.pnl.delta_vs_previous >= 0 ? "+" : ""}$${fmtUsd(s.pnl.delta_vs_previous)}`} accent={deltaColor as "green" | "red"} hint={`Taxas pagas $${fmtUsd(s?.pnl.fees_usdt, 4)}`} />
        </div>
      </div>

      {/* Stats cluster */}
      <div>
        <SectionTitle icon={<Layers size={13} />} label="Estatísticas" />
        <div style={{ display: "grid", gap: 8 }}>
          <StatCard
            label="Lotes fechados · Win Rate"
            value={placeholder ? "—" : `${s.stats.total_trades} · ${fmtPct(s.stats.win_rate_pct, 1)}`}
            sub={`W ${s?.stats.wins ?? 0} · L ${s?.stats.losses ?? 0} · PF ${s?.stats.profit_factor ?? "—"}`}
          />
          <StatCard
            label="Médias / Holding"
            value={placeholder ? "—" : `+$${fmtUsd(s.stats.avg_win_usdt)} / -$${fmtUsd(Math.abs(s.stats.avg_loss_usdt))}`}
            sub={`Hold médio ${fmtSec(s?.stats.avg_holding_seconds)} · Sharpe ${s?.stats.sharpe ?? "—"}`}
          />
        </div>
      </div>

      {/* Risk cluster */}
      <div>
        <SectionTitle icon={<AlertTriangle size={13} />} label="Risco" />
        <div style={{ display: "grid", gap: 8 }}>
          <StatCard
            label="Drawdown máximo"
            value={placeholder ? "—" : `$${fmtUsd(s.risk.max_drawdown_usdt)}`}
            accent="amber"
            sub={`Atual $${fmtUsd(s?.risk.current_drawdown_usdt)} · Recovery ${s?.risk.recovery_pct === null || s?.risk.recovery_pct === undefined ? "—" : fmtPct(s.risk.recovery_pct)}`}
          />
          <StatCard
            label="Volume negociado"
            value={placeholder ? "—" : `$${fmtUsd(s.stats.volume_usdt, 0)}`}
            hint={`maior win $${fmtUsd(s?.stats.biggest_win_usdt)} · maior loss $${fmtUsd(s?.stats.biggest_loss_usdt)}`}
          />
        </div>
      </div>
    </div>
    </>
  );
}

