"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import {
  Activity,
  AlertTriangle,
  ArrowDownRight,
  ArrowUpRight,
  ChevronDown,
  ChevronUp,
  Clock,
  Hourglass,
  RefreshCw,
  Target,
  TrendingDown,
  TrendingUp,
  X,
} from "lucide-react";
import { apiGet, ApiError } from "@/lib/api";
import DetailedReportWorkspace from "@/components/shadow-portfolio/DetailedReportWorkspace";
import { ModuleAIAnalysisAction } from "@/components/ai/ModuleAIAnalysisAction";

// ── theme (alinhado com /dashboard/performance) ──────────────────────────────
const C = {
  bg: "#0A0B10",
  surface: "#10121A",
  elevated: "#161824",
  border: "rgba(255,255,255,0.06)",
  borderStrong: "rgba(255,255,255,0.12)",
  text: "#E6E8EE",
  muted: "#8A91A4",
  dim: "#5A6075",
  green: "#22B97A",
  red: "#E5484D",
  blue: "#4F7BF7",
  amber: "#F2A33A",
  purple: "#9D7CF7",
} as const;

// ── domain types (espelham backend/app/schemas/shadow_trade.py) ──────────────
type ShadowStatus = "PENDING" | "RUNNING" | "COMPLETED" | "ERROR";
type ShadowOutcome = "TP_HIT" | "SL_HIT" | "TIMEOUT" | null;

interface ShadowTradeRead {
  id: string;
  symbol: string;
  direction: string | null;
  entry_price: number | null;
  current_price: number | null;
  tp_price: number | null;
  sl_price: number | null;
  amount_usdt: number;
  outcome: ShadowOutcome;
  pnl_pct: number | null;
  pnl_usdt: number | null;
  status: ShadowStatus;
  skip_reason: string | null;
  holding_seconds: number | null;
  created_at: string | null;
  completed_at: string | null;
  entry_timestamp: string | null;
  profile_id: string | null;
  profile_name: string | null;
}

interface ShadowTradeListResponse {
  items: ShadowTradeRead[];
  total: number;
  page: number;
  page_size: number;
}

interface ShadowTradeSummary {
  total: number;
  pending: number;
  completed: number;
  win: number;
  loss: number;
  timeout: number;
  win_rate: number;
  total_pnl_usdt: number;
  avg_pnl_pct: number;
  period_start: string | null;
  period_end: string | null;
}

interface ShadowTradeDetail extends ShadowTradeRead {
  strategy: string | null;
  entry_timestamp: string | null;
  exit_price: number | null;
  exit_timestamp: string | null;
  tp_pct: number | null;
  sl_pct: number | null;
  timeout_candles: number | null;
  decision_id: number | null;
  last_processed_time: string | null;
  updated_at: string | null;
  config_snapshot: Record<string, unknown> | null;
  features_snapshot: Record<string, unknown> | null;
  features_snapshot_exit: Record<string, unknown> | null;
  decision_strategy: string | null;
  decision_score: number | null;
  decision_decision: string | null;
  decision_event_type: string | null;
  decision_l1_pass: boolean | null;
  decision_l2_pass: boolean | null;
  decision_l3_pass: boolean | null;
  decision_latency_ms: number | null;
  decision_created_at: string | null;
  decision_reasons: Record<string, unknown> | null;
  decision_metrics: Record<string, unknown> | null;
  // Task #316 — par entry/exit flat para o painel side-by-side.
  // Backend só preenche quando ENABLE_EXIT_METRICS_UI=true.
  entry_metrics: Record<string, unknown> | null;
  exit_metrics: Record<string, unknown> | null;
  // Strategy Lab fields (migration 077)
  profile_version: string | null;
  strategy_type: string | null;
  rules_snapshot: Record<string, unknown> | null;
  ml_probability: number | null;
  ml_model_id: string | null;
  final_priority_score: number | null;
}

interface ProfileItem {
  id: string;
  name: string;
  description: string | null;
  is_active: boolean;
}

interface ProfileReportRow {
  profile_id: string;
  profile_name: string;
  watchlist_id: string | null;
  watchlist_name: string | null;
  level: string;
  total: number;
  total_trades: number;
  open_count: number;
  open_trades: number;
  win_count: number;
  wins: number;
  decided_count: number;
  completed_trades: number;
  win_rate: number | null;
  pnl_total_usdt: number;
  pnl_avg_pct: number | null;
  avg_pnl_pct: number | null;
  avg_holding_win_seconds: number | null;
  tp_4h_count: number;
  tp_4h_wins: number;
  tp_4h_rate: number | null;
  ev_score: number;
  stat_confidence: string;
  delta_win_rate_vs_baseline: number;
  delta_pnl_vs_baseline: number;
  priority: string;
  priority_reason: string;
  operational_class: string;
  rank_position: number;
  score_components: Record<string, number>;
  computed_at: string;
}
type ProfileClass =
  | "GOOD_4H"
  | "SLOW_WINNER"
  | "GOOD_SHADOW_BAD_4H"
  | "BAD_BOTH"
  | "LOW_SAMPLE"
  | "NO_TRADES";

function classifyProfile(row: ProfileReportRow): ProfileClass {
  if (row.total === 0) return "NO_TRADES";
  if (row.decided_count < 20) return "LOW_SAMPLE";
  const wr = row.win_rate ?? 0;
  const r4h = row.tp_4h_rate ?? 0;
  if (wr >= 50 && r4h >= 40) return "GOOD_4H";
  if (wr >= 50 && r4h < 40) return "SLOW_WINNER";
  if (wr < 50 && r4h >= 20) return "GOOD_SHADOW_BAD_4H";
  return "BAD_BOTH";
}

const CLASS_META: Record<ProfileClass, { label: string; color: string }> = {
  GOOD_4H:            { label: "GOOD 4H",   color: "#22B97A" },
  SLOW_WINNER:        { label: "SLOW WIN",  color: "#F2A33A" },
  GOOD_SHADOW_BAD_4H: { label: "SHADOW/4H", color: "#9D7CF7" },
  BAD_BOTH:           { label: "BAD",        color: "#E5484D" },
  LOW_SAMPLE:         { label: "LOW N",      color: "#5A6075" },
  NO_TRADES:          { label: "EMPTY",      color: "#5A6075" },
};

interface ProfileIntelligenceCandidate {
  profile_id: string;
  watchlist_id: string | null;
  watchlist_name: string | null;
}

// ── filter shape ─────────────────────────────────────────────────────────────
type StatusFilter = "ALL" | "OPEN" | "TP_HIT" | "SL_HIT" | "TIMEOUT";

interface FilterState {
  status: StatusFilter;
  symbol: string;
  minDate: string; // YYYY-MM-DD
  maxDate: string;
  page: number;
  pageSize: number;
}

const DEFAULT_FILTER: FilterState = {
  status: "ALL",
  symbol: "",
  minDate: "",
  maxDate: "",
  page: 1,
  pageSize: 50,
};

// ── formatters ───────────────────────────────────────────────────────────────
function fmtUsd(n: number | null | undefined, dp = 2): string {
  if (n === null || n === undefined || !isFinite(n)) return "—";
  const abs = Math.abs(n);
  const formatted = abs.toLocaleString("en-US", {
    minimumFractionDigits: dp,
    maximumFractionDigits: dp,
  });
  return n < 0 ? `-$${formatted}` : `$${formatted}`;
}

function fmtPct(n: number | null | undefined, dp = 2): string {
  if (n === null || n === undefined || !isFinite(n)) return "—";
  const sign = n > 0 ? "+" : "";
  return `${sign}${n.toFixed(dp)}%`;
}

function fmtPrice(n: number | null | undefined): string {
  if (n === null || n === undefined || !isFinite(n)) return "—";
  const abs = Math.abs(n);
  if (abs === 0) return "$0";
  if (abs < 0.0001) return `$${n.toExponential(2)}`;
  if (abs < 0.01) return `$${n.toFixed(6)}`;
  if (abs < 1) return `$${n.toFixed(4)}`;
  if (abs < 1000) return `$${n.toFixed(2)}`;
  if (abs < 1_000_000) return `$${(n / 1000).toFixed(2)}K`;
  return `$${(n / 1_000_000).toFixed(2)}M`;
}

function fmtDateTime(iso: string | null | undefined): string {
  if (!iso) return "—";
  try {
    const d = new Date(iso);
    if (isNaN(d.getTime())) return "—";
    return d.toLocaleString("pt-BR", {
      day: "2-digit",
      month: "2-digit",
      year: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
    });
  } catch {
    return "—";
  }
}

function fmtHolding(seconds: number | null | undefined): string {
  if (seconds === null || seconds === undefined || seconds < 0) return "—";
  if (seconds < 60) return `${seconds}s`;
  const mins = Math.floor(seconds / 60);
  if (mins < 60) return `${mins}m`;
  const hours = Math.floor(mins / 60);
  const remMins = mins % 60;
  if (hours < 24) return `${hours}h ${remMins}m`;
  const days = Math.floor(hours / 24);
  const remHours = hours % 24;
  return `${days}d ${remHours}h`;
}

// ── status / outcome helpers ─────────────────────────────────────────────────
interface BadgeStyle {
  bg: string;
  fg: string;
  border: string;
  label: string;
}

function statusStyle(status: ShadowStatus): BadgeStyle {
  switch (status) {
    case "PENDING":
      return { bg: `${C.amber}22`, fg: C.amber, border: `${C.amber}55`, label: "Pendente" };
    case "RUNNING":
      return { bg: `${C.blue}22`, fg: C.blue, border: `${C.blue}55`, label: "Em andamento" };
    case "COMPLETED":
      return { bg: `${C.muted}22`, fg: C.text, border: `${C.muted}55`, label: "Finalizado" };
    case "ERROR":
      return { bg: `${C.red}22`, fg: C.red, border: `${C.red}55`, label: "Erro" };
  }
}

function outcomeStyle(outcome: ShadowOutcome): BadgeStyle | null {
  if (!outcome) return null;
  switch (outcome) {
    case "TP_HIT":
      return { bg: `${C.green}22`, fg: C.green, border: `${C.green}55`, label: "TP" };
    case "SL_HIT":
      return { bg: `${C.red}22`, fg: C.red, border: `${C.red}55`, label: "SL" };
    case "TIMEOUT":
      return { bg: `${C.purple}22`, fg: C.purple, border: `${C.purple}55`, label: "Timeout" };
  }
}

function Badge({ style }: { style: BadgeStyle }) {
  return (
    <span
      style={{
        display: "inline-flex",
        alignItems: "center",
        background: style.bg,
        color: style.fg,
        border: `1px solid ${style.border}`,
        borderRadius: 4,
        padding: "2px 8px",
        fontSize: 10.5,
        fontWeight: 600,
        letterSpacing: 0.4,
        textTransform: "uppercase",
        whiteSpace: "nowrap",
      }}
    >
      {style.label}
    </span>
  );
}

// ── stat card (alinhado com /dashboard/performance) ──────────────────────────
function StatCard({
  label,
  value,
  sub,
  accent,
  icon,
}: {
  label: string;
  value: string;
  sub?: string;
  accent?: "green" | "red" | "amber" | "blue" | "purple";
  icon?: React.ReactNode;
}) {
  const accentColor =
    accent === "green"
      ? C.green
      : accent === "red"
      ? C.red
      : accent === "amber"
      ? C.amber
      : accent === "blue"
      ? C.blue
      : accent === "purple"
      ? C.purple
      : C.text;
  return (
    <div
      style={{
        background: C.elevated,
        border: `1px solid ${C.border}`,
        borderRadius: 10,
        padding: "14px 16px",
      }}
    >
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 6,
          fontSize: 11,
          color: C.muted,
          letterSpacing: 0.6,
          textTransform: "uppercase",
        }}
      >
        {icon}
        <span>{label}</span>
      </div>
      <div
        style={{
          fontSize: 22,
          fontWeight: 600,
          fontVariantNumeric: "tabular-nums",
          color: accentColor,
          marginTop: 6,
        }}
      >
        {value}
      </div>
      {sub ? (
        <div
          style={{
            fontSize: 11,
            color: C.muted,
            fontVariantNumeric: "tabular-nums",
            marginTop: 4,
          }}
        >
          {sub}
        </div>
      ) : null}
    </div>
  );
}

// ── filter bar ───────────────────────────────────────────────────────────────
const STATUS_TABS: { key: StatusFilter; label: string }[] = [
  { key: "ALL", label: "Todos" },
  { key: "OPEN", label: "Em aberto" },
  { key: "TP_HIT", label: "TP" },
  { key: "SL_HIT", label: "SL" },
  { key: "TIMEOUT", label: "Timeout" },
];

function FilterBar({
  filter,
  onChange,
  onRefresh,
  loading,
}: {
  filter: FilterState;
  onChange: (next: FilterState) => void;
  onRefresh: () => void;
  loading: boolean;
}) {
  return (
    <div
      style={{
        background: C.surface,
        border: `1px solid ${C.border}`,
        borderRadius: 10,
        padding: "10px 14px",
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        gap: 12,
        flexWrap: "wrap",
      }}
    >
      <div style={{ display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap" }}>
        {STATUS_TABS.map((tab) => {
          const active = filter.status === tab.key;
          return (
            <button
              key={tab.key}
              onClick={() => onChange({ ...filter, status: tab.key, page: 1 })}
              style={{
                background: active ? C.elevated : "transparent",
                color: active ? C.text : C.muted,
                border: `1px solid ${active ? C.borderStrong : C.border}`,
                borderRadius: 6,
                padding: "5px 12px",
                fontSize: 11.5,
                cursor: "pointer",
                letterSpacing: 0.4,
              }}
            >
              {tab.label}
            </button>
          );
        })}
      </div>

      <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
        <input
          type="text"
          value={filter.symbol}
          onChange={(e) =>
            onChange({ ...filter, symbol: e.target.value.toUpperCase(), page: 1 })
          }
          placeholder="Símbolo (ex.: BTC_USDT)"
          style={{
            background: C.elevated,
            border: `1px solid ${C.border}`,
            color: C.text,
            borderRadius: 6,
            padding: "6px 10px",
            fontSize: 11.5,
            width: 170,
            outline: "none",
          }}
        />
        <input
          type="date"
          value={filter.minDate}
          onChange={(e) => onChange({ ...filter, minDate: e.target.value, page: 1 })}
          style={{
            background: C.elevated,
            border: `1px solid ${C.border}`,
            color: C.text,
            borderRadius: 6,
            padding: "6px 10px",
            fontSize: 11.5,
            outline: "none",
            colorScheme: "dark",
          }}
          title="Data inicial"
        />
        <span style={{ color: C.dim, fontSize: 11 }}>até</span>
        <input
          type="date"
          value={filter.maxDate}
          onChange={(e) => onChange({ ...filter, maxDate: e.target.value, page: 1 })}
          style={{
            background: C.elevated,
            border: `1px solid ${C.border}`,
            color: C.text,
            borderRadius: 6,
            padding: "6px 10px",
            fontSize: 11.5,
            outline: "none",
            colorScheme: "dark",
          }}
          title="Data final"
        />
        <button
          onClick={onRefresh}
          disabled={loading}
          style={{
            background: C.elevated,
            border: `1px solid ${C.borderStrong}`,
            color: C.text,
            borderRadius: 6,
            padding: "6px 12px",
            fontSize: 11.5,
            cursor: loading ? "default" : "pointer",
            display: "inline-flex",
            alignItems: "center",
            gap: 6,
            opacity: loading ? 0.6 : 1,
          }}
          title="Atualizar"
        >
          <RefreshCw size={13} className={loading ? "spin" : ""} />
          {loading ? "Carregando…" : "Atualizar"}
        </button>
      </div>
      <style jsx>{`
        .spin {
          animation: spin 1s linear infinite;
        }
        @keyframes spin {
          from {
            transform: rotate(0deg);
          }
          to {
            transform: rotate(360deg);
          }
        }
      `}</style>
    </div>
  );
}

// ── summary cards ────────────────────────────────────────────────────────────
function SummaryCards({
  data,
  loading,
}: {
  data: ShadowTradeSummary | null;
  loading: boolean;
}) {
  const placeholder = loading || !data;
  const pnlAccent: "green" | "red" =
    data && data.total_pnl_usdt >= 0 ? "green" : "red";
  const avgAccent: "green" | "red" = data && data.avg_pnl_pct >= 0 ? "green" : "red";
  const winRateAccent: "green" | "red" | undefined = !data
    ? undefined
    : data.win_rate >= 50
    ? "green"
    : "red";

  return (
    <div
      style={{
        display: "grid",
        gridTemplateColumns: "repeat(5, 1fr)",
        gap: 12,
      }}
    >
      <StatCard
        label="Total"
        icon={<Activity size={12} />}
        value={placeholder ? "—" : String(data!.total)}
        sub={placeholder ? "" : `${data!.completed} finalizados`}
      />
      <StatCard
        label="Em aberto"
        icon={<Hourglass size={12} />}
        value={placeholder ? "—" : String(data!.pending)}
        accent="amber"
        sub="PENDING + RUNNING"
      />
      <StatCard
        label="Win Rate"
        icon={<Target size={12} />}
        value={placeholder ? "—" : `${data!.win_rate.toFixed(1)}%`}
        accent={winRateAccent}
        sub={
          placeholder
            ? ""
            : `W ${data!.win} · L ${data!.loss} · TO ${data!.timeout}`
        }
      />
      <StatCard
        label="P&L Total"
        icon={
          data && data.total_pnl_usdt >= 0 ? (
            <ArrowUpRight size={12} />
          ) : (
            <ArrowDownRight size={12} />
          )
        }
        value={placeholder ? "—" : fmtUsd(data!.total_pnl_usdt)}
        accent={pnlAccent}
        sub="Soma dos finalizados"
      />
      <StatCard
        label="P&L Médio"
        icon={
          data && data.avg_pnl_pct >= 0 ? (
            <TrendingUp size={12} />
          ) : (
            <TrendingDown size={12} />
          )
        }
        value={placeholder ? "—" : fmtPct(data!.avg_pnl_pct)}
        accent={avgAccent}
        sub="Por trade finalizado"
      />
    </div>
  );
}

// ── trade table ──────────────────────────────────────────────────────────────
type TradeSortKey =
  | "entry_price"
  | "current_price"
  | "tp_price"
  | "sl_price"
  | "pnl_pct"
  | "pnl_usdt"
  | "holding_seconds";

const COLS: {
  key: string;
  label: string;
  align?: "left" | "right" | "center";
  sortKey?: TradeSortKey;
}[] = [
  { key: "created_at", label: "Aberto em" },
  { key: "profile", label: "Perfil" },
  { key: "ev_score", label: "EV Score", align: "right" },
  { key: "symbol", label: "Símbolo" },
  { key: "status", label: "Status", align: "center" },
  { key: "entry", label: "Entrada", align: "right", sortKey: "entry_price" },
  { key: "current", label: "Preço Atual", align: "right", sortKey: "current_price" },
  { key: "tp", label: "TP", align: "right", sortKey: "tp_price" },
  { key: "sl", label: "SL", align: "right", sortKey: "sl_price" },
  { key: "outcome", label: "Resultado", align: "center" },
  { key: "pnl_pct", label: "P&L %", align: "right", sortKey: "pnl_pct" },
  { key: "pnl_usdt", label: "P&L $", align: "right", sortKey: "pnl_usdt" },
  { key: "holding", label: "Holding", align: "right", sortKey: "holding_seconds" },
  { key: "completed_at", label: "Fechado em" },
];

function TradeTable({
  items,
  loading,
  error,
  profileEvScores,
  onRowClick,
}: {
  items: ShadowTradeRead[];
  loading: boolean;
  error: string | null;
  profileEvScores: Record<string, number>;
  onRowClick: (trade: ShadowTradeRead) => void;
}) {
  // Tick a cada 30s para o "Holding" das operações em aberto avançar
  // visualmente sem precisar de refetch. P&L em aberto também usa esse
  // re-render quando livePrices chegam (via parent).
  const [nowTick, setNowTick] = useState<number>(() => Date.now());
  useEffect(() => {
    const id = window.setInterval(() => setNowTick(Date.now()), 30_000);
    return () => window.clearInterval(id);
  }, []);

  const [tradeSortKey, setTradeSortKey] = useState<TradeSortKey | null>(null);
  const [tradeSortDir, setTradeSortDir] = useState<"asc" | "desc">("desc");

  const handleTradeSort = (key: TradeSortKey) => {
    if (tradeSortKey === key) {
      setTradeSortDir((d) => (d === "asc" ? "desc" : "asc"));
    } else {
      setTradeSortKey(key);
      setTradeSortDir("desc");
    }
  };

  const TradeSortBtn = ({ col }: { col: TradeSortKey }) => {
    const active = tradeSortKey === col;
    return (
      <button
        onClick={(e) => {
          e.stopPropagation();
          handleTradeSort(col);
        }}
        style={{
          background: "transparent",
          border: "none",
          cursor: "pointer",
          padding: "0 2px",
          color: active ? C.blue : C.dim,
          verticalAlign: "middle",
          lineHeight: 0,
        }}
      >
        {active && tradeSortDir === "asc" ? (
          <ChevronUp size={11} />
        ) : active && tradeSortDir === "desc" ? (
          <ChevronDown size={11} />
        ) : (
          <ChevronDown size={11} style={{ opacity: 0.3 }} />
        )}
      </button>
    );
  };

  const sorted = useMemo(() => {
    if (!tradeSortKey) return items;
    const now = Date.now();
    const getLive = (it: ShadowTradeRead, key: TradeSortKey): number | null => {
      const isOpen = it.status === "PENDING" || it.status === "RUNNING";
      if (key === "pnl_pct") {
        if (isOpen && it.entry_price != null && it.current_price != null && it.entry_price > 0) {
          return ((it.current_price - it.entry_price) / it.entry_price) * 100;
        }
        return it.pnl_pct ?? null;
      }
      if (key === "pnl_usdt") {
        if (isOpen && it.entry_price != null && it.current_price != null && it.entry_price > 0 && it.amount_usdt) {
          const pct = ((it.current_price - it.entry_price) / it.entry_price) * 100;
          return (it.amount_usdt * pct) / 100;
        }
        return it.pnl_usdt ?? null;
      }
      if (key === "holding_seconds") {
        if (isOpen) {
          const ref = it.entry_timestamp ?? it.created_at;
          if (ref) {
            try {
              const ms = new Date(ref).getTime();
              if (!isNaN(ms)) return Math.max(0, Math.floor((now - ms) / 1000));
            } catch { /* ignore */ }
          }
        }
        return it.holding_seconds ?? null;
      }
      return (it as unknown as Record<string, number | null>)[key] ?? null;
    };
    return [...items].sort((a, b) => {
      const nullVal = tradeSortDir === "asc" ? Infinity : -Infinity;
      const av = getLive(a, tradeSortKey) ?? nullVal;
      const bv = getLive(b, tradeSortKey) ?? nullVal;
      return tradeSortDir === "asc" ? av - bv : bv - av;
    });
  }, [items, tradeSortKey, tradeSortDir, nowTick]);

  if (error) {
    return (
      <div
        style={{
          background: C.surface,
          border: `1px solid ${C.red}55`,
          borderRadius: 10,
          padding: 16,
          color: C.red,
          fontSize: 12,
          display: "flex",
          alignItems: "center",
          gap: 8,
        }}
      >
        <AlertTriangle size={14} />
        Erro ao carregar shadow trades: {error}
      </div>
    );
  }

  if (loading && items.length === 0) {
    return (
      <div
        style={{
          background: C.surface,
          border: `1px solid ${C.border}`,
          borderRadius: 10,
          padding: 24,
          color: C.muted,
          fontSize: 12,
          textAlign: "center",
        }}
      >
        Carregando…
      </div>
    );
  }

  if (!loading && items.length === 0) {
    return (
      <div
        style={{
          background: C.surface,
          border: `1px solid ${C.border}`,
          borderRadius: 10,
          padding: 24,
          color: C.muted,
          fontSize: 12,
          textAlign: "center",
        }}
      >
        Nenhum shadow trade no filtro selecionado.
      </div>
    );
  }

  return (
    <div
      style={{
        background: C.surface,
        border: `1px solid ${C.border}`,
        borderRadius: 10,
        overflow: "auto",
      }}
    >
      <table
        style={{
          width: "100%",
          borderCollapse: "collapse",
          fontSize: 12,
          color: C.text,
          fontVariantNumeric: "tabular-nums",
        }}
      >
        <thead>
          <tr style={{ background: C.elevated }}>
            {COLS.map((col) => (
              <th
                key={col.key}
                style={{
                  textAlign: col.align ?? "left",
                  padding: "10px 12px",
                  fontSize: 10.5,
                  fontWeight: 600,
                  color: C.muted,
                  letterSpacing: 0.5,
                  textTransform: "uppercase",
                  borderBottom: `1px solid ${C.border}`,
                  whiteSpace: "nowrap",
                }}
              >
                {col.label}
                {col.sortKey && <TradeSortBtn col={col.sortKey} />}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {sorted.map((it) => {
            const sStyle = statusStyle(it.status);
            const oStyle = outcomeStyle(it.outcome);
            // Para trades em aberto (sem pnl_pct persistido), calcula
            // P&L "marked-to-market" usando current_price vs entry_price.
            // Para trades fechados, usa o valor persistido pelo monitor.
            const isOpen = it.status === "PENDING" || it.status === "RUNNING";
            const livePnlPct: number | null =
              isOpen && it.entry_price != null && it.current_price != null && it.entry_price > 0
                ? ((it.current_price - it.entry_price) / it.entry_price) * 100
                : it.pnl_pct;
            const livePnlUsdt: number | null =
              isOpen && livePnlPct != null && it.amount_usdt
                ? (it.amount_usdt * livePnlPct) / 100
                : it.pnl_usdt;
            // Holding "ao vivo" enquanto a operação está em aberto:
            // entry_timestamp → agora. Para fechados, usa holding_seconds
            // persistido (= entry → exit).
            const entryRef = it.entry_timestamp ?? it.created_at;
            let liveHolding: number | null = it.holding_seconds;
            if (isOpen && entryRef) {
              try {
                const entryMs = new Date(entryRef).getTime();
                if (!isNaN(entryMs)) {
                  liveHolding = Math.max(
                    0,
                    Math.floor((nowTick - entryMs) / 1000),
                  );
                }
              } catch {
                /* keep null */
              }
            }
            const pnlPctColor =
              livePnlPct === null
                ? C.dim
                : livePnlPct >= 0
                ? C.green
                : C.red;
            const pnlUsdtColor =
              livePnlUsdt === null
                ? C.dim
                : livePnlUsdt >= 0
                ? C.green
                : C.red;
            return (
              <tr
                key={it.id}
                onClick={() => onRowClick(it)}
                onKeyDown={(e) => {
                  if (e.key === "Enter" || e.key === " ") {
                    e.preventDefault();
                    onRowClick(it);
                  }
                }}
                tabIndex={0}
                role="button"
                aria-label={`Abrir detalhe de ${it.symbol}`}
                style={{
                  borderBottom: `1px solid ${C.border}`,
                  cursor: "pointer",
                  transition: "background 80ms ease",
                  outline: "none",
                }}
                onFocus={(e) =>
                  ((e.currentTarget as HTMLElement).style.background = C.elevated)
                }
                onBlur={(e) =>
                  ((e.currentTarget as HTMLElement).style.background = "transparent")
                }
                onMouseEnter={(e) =>
                  ((e.currentTarget as HTMLElement).style.background = C.elevated)
                }
                onMouseLeave={(e) =>
                  ((e.currentTarget as HTMLElement).style.background = "transparent")
                }
              >
                <td style={{ padding: "10px 12px", whiteSpace: "nowrap", color: C.muted }}>
                  {fmtDateTime(it.created_at)}
                </td>
                <td
                  style={{ padding: "10px 12px", maxWidth: 180, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}
                  title={it.profile_name ?? undefined}
                >
                  {it.profile_name ?? "—"}
                </td>
                <td
                  style={{
                    padding: "10px 12px",
                    textAlign: "right",
                    color: it.profile_id != null && profileEvScores[it.profile_id] != null
                      ? profileEvScores[it.profile_id] >= 60
                        ? C.green
                        : profileEvScores[it.profile_id] >= 30
                        ? C.amber
                        : C.red
                      : C.dim,
                    fontWeight: 700,
                  }}
                >
                  {it.profile_id != null && profileEvScores[it.profile_id] != null
                    ? profileEvScores[it.profile_id].toFixed(2)
                    : "—"}
                </td>
                <td style={{ padding: "10px 12px", fontWeight: 600 }}>{it.symbol}</td>
                <td style={{ padding: "10px 12px", textAlign: "center" }}>
                  <Badge style={sStyle} />
                </td>
                <td style={{ padding: "10px 12px", textAlign: "right" }}>
                  {fmtPrice(it.entry_price)}
                </td>
                <td
                  style={{
                    padding: "10px 12px",
                    textAlign: "right",
                    color:
                      it.current_price == null || it.entry_price == null
                        ? C.text
                        : it.current_price >= it.entry_price
                        ? C.green
                        : C.red,
                    fontVariantNumeric: "tabular-nums",
                  }}
                  title={
                    it.current_price != null && it.entry_price != null
                      ? `${(((it.current_price - it.entry_price) / it.entry_price) * 100).toFixed(2)}% vs entrada`
                      : undefined
                  }
                >
                  {fmtPrice(it.current_price)}
                </td>
                <td style={{ padding: "10px 12px", textAlign: "right", color: C.green }}>
                  {fmtPrice(it.tp_price)}
                </td>
                <td style={{ padding: "10px 12px", textAlign: "right", color: C.red }}>
                  {fmtPrice(it.sl_price)}
                </td>
                <td style={{ padding: "10px 12px", textAlign: "center" }}>
                  {oStyle ? <Badge style={oStyle} /> : <span style={{ color: C.dim }}>—</span>}
                </td>
                <td
                  style={{
                    padding: "10px 12px",
                    textAlign: "right",
                    color: pnlPctColor,
                    fontWeight: 600,
                  }}
                >
                  {fmtPct(livePnlPct)}
                </td>
                <td
                  style={{
                    padding: "10px 12px",
                    textAlign: "right",
                    color: pnlUsdtColor,
                    fontWeight: 600,
                  }}
                >
                  {fmtUsd(livePnlUsdt)}
                </td>
                <td
                  style={{
                    padding: "10px 12px",
                    textAlign: "right",
                    whiteSpace: "nowrap",
                    color: it.outcome === "TP_HIT" ? C.green : C.muted,
                    fontVariantNumeric: "tabular-nums",
                  }}
                  title={
                    liveHolding != null
                      ? `${liveHolding}s ${
                          isOpen ? "em aberto" : it.outcome === "TP_HIT" ? "até bater o TP" : "até fechar"
                        }`
                      : undefined
                  }
                >
                  {fmtHolding(liveHolding)}
                </td>
                <td style={{ padding: "10px 12px", whiteSpace: "nowrap", color: C.muted }}>
                  {fmtDateTime(it.completed_at)}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

// ── pagination ───────────────────────────────────────────────────────────────
function Pagination({
  page,
  pageSize,
  total,
  onChange,
}: {
  page: number;
  pageSize: number;
  total: number;
  onChange: (page: number) => void;
}) {
  const totalPages = Math.max(1, Math.ceil(total / pageSize));
  const from = total === 0 ? 0 : (page - 1) * pageSize + 1;
  const to = Math.min(page * pageSize, total);

  const btn = (label: string, target: number, disabled: boolean) => (
    <button
      onClick={() => !disabled && onChange(target)}
      disabled={disabled}
      style={{
        background: C.elevated,
        border: `1px solid ${C.border}`,
        color: disabled ? C.dim : C.text,
        borderRadius: 6,
        padding: "5px 10px",
        fontSize: 11.5,
        cursor: disabled ? "default" : "pointer",
        opacity: disabled ? 0.5 : 1,
      }}
    >
      {label}
    </button>
  );

  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        padding: "8px 4px",
        fontSize: 11.5,
        color: C.muted,
      }}
    >
      <span>
        {from}–{to} de {total}
      </span>
      <div style={{ display: "flex", gap: 6 }}>
        {btn("«", 1, page === 1)}
        {btn("‹", page - 1, page === 1)}
        <span style={{ alignSelf: "center", padding: "0 6px" }}>
          {page} / {totalPages}
        </span>
        {btn("›", page + 1, page >= totalPages)}
        {btn("»", totalPages, page >= totalPages)}
      </div>
    </div>
  );
}

// ── detail modal ─────────────────────────────────────────────────────────────
function DetailRow({
  label,
  value,
  color,
}: {
  label: string;
  value: React.ReactNode;
  color?: string;
}) {
  return (
    <div
      style={{
        display: "flex",
        justifyContent: "space-between",
        padding: "8px 0",
        borderBottom: `1px solid ${C.border}`,
        fontSize: 12,
      }}
    >
      <span style={{ color: C.muted }}>{label}</span>
      <span
        style={{
          color: color ?? C.text,
          fontWeight: 500,
          fontVariantNumeric: "tabular-nums",
          textAlign: "right",
        }}
      >
        {value}
      </span>
    </div>
  );
}

function DecisionAuditBlock({ data }: { data: ShadowTradeDetail }) {
  const reasons = data.decision_reasons
    ? Object.entries(data.decision_reasons)
    : [];
  const metrics = data.decision_metrics
    ? Object.entries(data.decision_metrics)
    : [];
  const hasAny =
    data.decision_id !== null ||
    reasons.length > 0 ||
    metrics.length > 0 ||
    data.decision_l1_pass !== null ||
    data.decision_l2_pass !== null ||
    data.decision_l3_pass !== null;

  if (!hasAny) {
    return null;
  }

  const passColor = (v: boolean | null) =>
    v === null ? C.dim : v ? C.green : C.red;
  const passLabel = (v: boolean | null) =>
    v === null ? "—" : v ? "PASS" : "FAIL";

  const fmtMetric = (v: unknown): string => {
    if (v === null || v === undefined) return "—";
    if (typeof v === "number") {
      if (!Number.isFinite(v)) return String(v);
      return Number.isInteger(v) ? String(v) : v.toFixed(2);
    }
    if (typeof v === "boolean") return v ? "true" : "false";
    if (typeof v === "object") {
      const obj = v as Record<string, unknown>;
      if ("value" in obj && typeof obj.value !== "object") {
        return fmtMetric(obj.value);
      }
      return JSON.stringify(v);
    }
    return String(v);
  };

  return (
    <div>
      <div
        style={{
          fontSize: 11,
          color: C.muted,
          letterSpacing: 0.6,
          textTransform: "uppercase",
          marginBottom: 8,
          display: "flex",
          alignItems: "center",
          gap: 8,
        }}
      >
        Auditoria da Decisão (L1/L2/L3)
        {data.decision_strategy ? (
          <span
            style={{
              fontFamily: "monospace",
              fontSize: 10,
              color: C.text,
              background: C.bg,
              border: `1px solid ${C.border}`,
              borderRadius: 4,
              padding: "1px 6px",
              letterSpacing: 0,
              textTransform: "none",
            }}
          >
            {data.decision_strategy}
          </span>
        ) : null}
        {data.decision_score !== null ? (
          <span
            style={{
              fontFamily: "monospace",
              fontSize: 10,
              color: C.text,
              letterSpacing: 0,
              textTransform: "none",
            }}
          >
            score {data.decision_score.toFixed(1)}
          </span>
        ) : null}
        {data.decision_created_at ? (
          <span
            style={{
              fontSize: 10,
              color: C.dim,
