                  />
                  <DetailRow
                    label="Stop Loss"
                    value={`${fmtPrice(data.sl_price)} (${fmtPct(data.sl_pct)})`}
                    color={C.red}
                  />
                  <DetailRow
                    label="Saída"
                    value={fmtPrice(data.exit_price)}
                  />
