                    label="Tamanho"
                    value={fmtUsd(data.amount_usdt)}
                  />
                  <DetailRow
                    label="P&L"
                    value={`${fmtPct(data.pnl_pct)} (${fmtUsd(data.pnl_usdt)})`}
                    color={
                      data.pnl_usdt === null
                        ? undefined
                        : data.pnl_usdt >= 0
                        ? C.green
                        : C.red
                    }
                  />
