type ReportSortKey =
  | "priority"
  | "ev_score"
  | "profile_name"
  | "total"
  | "stat_confidence"
  | "win_rate"
  | "delta_win_rate_vs_baseline"
  | "tp_4h_rate"
  | "pnl_total_usdt"
  | "pnl_avg_pct"
  | "avg_holding_win_seconds";

const PRIORITY_COLOR: Record<string, string> = {
  "A+": "#16A66A",
  A: "#22B97A",
  B: "#4C8DFF",
  C: "#F2A33A",
  D: "#E5484D",
  LOW_N: "#5A6075",
  BLOCKED: "#5A6075",
};

function ProfileReportTable({
  rows,
  loading,
  watchlistNames,
}: {
  rows: ProfileReportRow[];
  loading: boolean;
  watchlistNames: Record<string, string>;
}) {
  const [sortKey, setSortKey] = useState<ReportSortKey>("ev_score");
  const [sortDir, setSortDir] = useState<"asc" | "desc">("desc");

  const sorted = useMemo(() => [...rows].sort((a, b) => {
    const av = a[sortKey] ?? (sortDir === "asc" ? Infinity : -Infinity);
    const bv = b[sortKey] ?? (sortDir === "asc" ? Infinity : -Infinity);
    if (typeof av === "string" && typeof bv === "string") {
      return sortDir === "asc" ? av.localeCompare(bv) : bv.localeCompare(av);
    }
    return sortDir === "asc"
      ? Number(av) - Number(bv)
      : Number(bv) - Number(av);
  }), [rows, sortKey, sortDir]);

  const handleSort = (key: ReportSortKey) => {
    if (sortKey === key) {
      setSortDir((direction) => direction === "asc" ? "desc" : "asc");
    } else {
      setSortKey(key);
      setSortDir(key === "profile_name" || key === "priority" || key === "stat_confidence" ? "asc" : "desc");
    }
  };

  const SortBtn = ({ col }: { col: ReportSortKey }) => {
    const active = sortKey === col;
    return (
      <button
        aria-label={`Ordenar por ${col}`}
        onClick={() => handleSort(col)}
        style={{ background: "transparent", border: "none", cursor: "pointer", padding: "0 2px", color: active ? C.blue : C.dim, verticalAlign: "middle", lineHeight: 0 }}
      >
        {active && sortDir === "asc" ? <ChevronUp size={12} /> : <ChevronDown size={12} style={{ opacity: active ? 1 : 0.35 }} />}
      </button>
    );
  };

  const thStyle: React.CSSProperties = {
    padding: "7px 10px",
    fontSize: 11,
    color: C.muted,
    fontWeight: 500,
    textAlign: "left",
    whiteSpace: "nowrap",
    borderBottom: `1px solid ${C.border}`,
    background: C.elevated,
  };
  const tdStyle: React.CSSProperties = {
    padding: "7px 10px",
    fontSize: 12,
    borderBottom: `1px solid ${C.border}`,
    color: C.text,
  };

  if (loading) return <div style={{ padding: 24, textAlign: "center", color: C.muted, fontSize: 12 }}>Carregando relatório...</div>;
  if (rows.length === 0) return <div style={{ padding: 24, textAlign: "center", color: C.muted, fontSize: 12 }}>Nenhum perfil encontrado.</div>;

  return (
    <div style={{ background: C.surface, border: `1px solid ${C.border}`, borderRadius: 8, overflow: "auto" }}>
      <table style={{ minWidth: 1500, width: "100%", borderCollapse: "collapse" }}>
        <thead>
          <tr>
            <th style={{ ...thStyle, textAlign: "center" }}>Prioridade <SortBtn col="priority" /></th>
            <th
              style={{ ...thStyle, textAlign: "right" }}
              title="EV Score: + P&L médio + Win Rate + confiança estatística + TP 4h + P&L total - holding - baixa amostra - P&L negativo"
            >EV Score <SortBtn col="ev_score" /></th>
            <th style={{ ...thStyle, minWidth: 150 }}>Perfil <SortBtn col="profile_name" /></th>
            <th style={{ ...thStyle, minWidth: 120 }}>Watchlist</th>
            <th style={{ ...thStyle, textAlign: "right" }}>Total <SortBtn col="total" /></th>
            <th style={{ ...thStyle, textAlign: "center" }}>Confiança <SortBtn col="stat_confidence" /></th>
            <th style={{ ...thStyle, textAlign: "right" }}>Win Rate <SortBtn col="win_rate" /></th>
            <th style={{ ...thStyle, textAlign: "right" }}>Delta vs Baseline <SortBtn col="delta_win_rate_vs_baseline" /></th>
            <th style={{ ...thStyle, textAlign: "right" }}>TP 4h <SortBtn col="tp_4h_rate" /></th>
            <th style={{ ...thStyle, textAlign: "right" }}>P&amp;L Médio <SortBtn col="pnl_avg_pct" /></th>
            <th style={{ ...thStyle, textAlign: "right" }}>P&amp;L Total <SortBtn col="pnl_total_usdt" /></th>
            <th style={{ ...thStyle, textAlign: "right" }}>Holding (WIN) <SortBtn col="avg_holding_win_seconds" /></th>
            <th style={{ ...thStyle, textAlign: "center" }}>Classe</th>
            <th style={{ ...thStyle, minWidth: 260 }}>Motivo</th>
          </tr>
        </thead>
        <tbody>
          {sorted.map((row, index) => {
            const priorityColor = PRIORITY_COLOR[row.priority] ?? C.muted;
            const classKey = row.operational_class === "LOW_N" ? "LOW_SAMPLE" : row.operational_class === "EMPTY" ? "NO_TRADES" : row.operational_class;
            const classMeta = CLASS_META[classKey as ProfileClass] ?? CLASS_META.NO_TRADES;
            const watchlist = row.watchlist_name ?? watchlistNames[row.profile_id] ?? "—";
            return (
              <tr key={`${row.profile_id}:${row.watchlist_id ?? "none"}`} style={{ background: index % 2 === 0 ? "transparent" : `${C.elevated}66`, opacity: row.total === 0 ? 0.7 : 1 }}>
                <td style={{ ...tdStyle, textAlign: "center" }}><span style={{ color: priorityColor, border: `1px solid ${priorityColor}66`, borderRadius: 4, padding: "2px 7px", fontWeight: 700 }}>{row.priority}</span></td>
                <td style={{ ...tdStyle, textAlign: "right", color: row.ev_score >= 60 ? C.green : row.ev_score >= 30 ? C.amber : C.red, fontWeight: 700 }} title={JSON.stringify(row.score_components)}>{row.ev_score.toFixed(2)}</td>
                <td style={{ ...tdStyle, maxWidth: 220, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }} title={row.profile_name}>{row.profile_name}</td>
                <td style={{ ...tdStyle, maxWidth: 180, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", color: C.muted }} title={watchlist}>{watchlist}</td>
                <td style={{ ...tdStyle, textAlign: "right" }}>{row.total || "—"}</td>
                <td style={{ ...tdStyle, textAlign: "center", color: row.stat_confidence === "HIGH" ? C.green : row.stat_confidence === "MEDIUM" ? C.blue : C.muted }}>{row.stat_confidence}</td>
                <td style={{ ...tdStyle, textAlign: "right" }}>{row.win_rate == null ? "—" : `${(row.win_rate * 100).toFixed(1)}%`}</td>
                <td style={{ ...tdStyle, textAlign: "right" }} title={`Delta P&L: ${row.delta_pnl_vs_baseline >= 0 ? "+" : ""}${row.delta_pnl_vs_baseline.toFixed(3)} pp`}>
                  {`${row.delta_win_rate_vs_baseline >= 0 ? "+" : ""}${(row.delta_win_rate_vs_baseline * 100).toFixed(1)} pp`}
                </td>
                <td style={{ ...tdStyle, textAlign: "right" }}>{row.tp_4h_rate == null ? "—" : `${(row.tp_4h_rate * 100).toFixed(1)}%`}</td>
                <td style={{ ...tdStyle, textAlign: "right", color: (row.pnl_avg_pct ?? 0) > 0 ? C.green : (row.pnl_avg_pct ?? 0) < 0 ? C.red : C.muted }}>{fmtPct(row.pnl_avg_pct)}</td>
                <td style={{ ...tdStyle, textAlign: "right", color: row.pnl_total_usdt > 0 ? C.green : row.pnl_total_usdt < 0 ? C.red : C.muted }}>{fmtUsd(row.pnl_total_usdt)}</td>
                <td style={{ ...tdStyle, textAlign: "right", color: C.muted }}>{fmtHolding(row.avg_holding_win_seconds)}</td>
                <td style={{ ...tdStyle, textAlign: "center" }}><span style={{ color: classMeta.color, border: `1px solid ${classMeta.color}55`, borderRadius: 4, padding: "1px 6px", whiteSpace: "nowrap" }}>{classMeta.label}</span></td>
                <td style={{ ...tdStyle, maxWidth: 360, color: C.muted, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }} title={row.priority_reason}>{row.priority_reason}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
// ── data hooks ───────────────────────────────────────────────────────────────
// Backend limitation: `status` accepts PENDING|RUNNING|COMPLETED|ERROR.
// Outcome filters still use the bounded client-side strategy below.
const MAX_LOCAL_FETCH = 200; // = _MAX_PAGE_SIZE em backend/app/api/shadow_trades.py
const CLIENT_PAGE_SIZE = 50;

type SourceTab = "L3" | "L3_REJECTED" | "L1_SPECTRUM";

function buildBaseQuery(
  filter: FilterState,
  overrides: { status?: string; page?: number; page_size?: number } = {},
  source?: SourceTab,
  profileId?: string | null,
): string {
  const params = new URLSearchParams();
  if (overrides.status) params.set("status", overrides.status);
  if (filter.symbol.trim()) params.set("symbol", filter.symbol.trim());
  if (filter.minDate) params.set("min_date", filter.minDate);
  if (filter.maxDate) params.set("max_date", filter.maxDate);
  // When profile_id is set, it is the authoritative filter across all sources.
  if (!profileId && source) params.set("source", source);
  if (profileId) params.set("profile_id", profileId);
  params.set("page", String(overrides.page ?? filter.page));
  params.set("page_size", String(overrides.page_size ?? filter.pageSize));
  return params.toString();
}

function buildSummaryQuery(filter: FilterState, source?: SourceTab, profileId?: string | null): string {
  const params = new URLSearchParams();
  if (filter.symbol.trim()) params.set("symbol", filter.symbol.trim());
  if (filter.minDate) params.set("min_date", filter.minDate);
  if (filter.maxDate) params.set("max_date", filter.maxDate);
  // See buildBaseQuery: profile attribution spans more than one shadow source.
  if (!profileId && source) params.set("source", source);
  if (profileId) params.set("profile_id", profileId);
  return params.toString();
}

// ── page ─────────────────────────────────────────────────────────────────────
export default function ShadowPortfolioPage() {
  const router = useRouter();
  const [filter, setFilter] = useState<FilterState>(DEFAULT_FILTER);
  const [list, setList] = useState<ShadowTradeListResponse | null>(null);
  const [summary, setSummary] = useState<ShadowTradeSummary | null>(null);
  const [loadingList, setLoadingList] = useState(false);
  const [loadingSummary, setLoadingSummary] = useState(false);
  const [errorList, setErrorList] = useState<string | null>(null);
  const [tick, setTick] = useState(0);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [livePrices, setLivePrices] = useState<Record<string, number>>({});
  const [sourceTab, setSourceTab] = useState<SourceTab>("L3");
  const [profiles, setProfiles] = useState<ProfileItem[]>([]);
  const [watchlistNames, setWatchlistNames] = useState<Record<string, string>>({});
  const [selectedProfileId, setSelectedProfileId] = useState<string | null>(null);
  const [mainTab, setMainTab] = useState<"trades" | "report" | "detailed-report">("trades");
  const [profileReport, setProfileReport] = useState<ProfileReportRow[]>([]);
  const [loadingReport, setLoadingReport] = useState(false);

  const profileEvScores = useMemo(() => {
    const scores: Record<string, number> = {};
    for (const row of profileReport) {
      if (Number.isFinite(row.ev_score) && (scores[row.profile_id] == null || row.ev_score > scores[row.profile_id])) {
        scores[row.profile_id] = row.ev_score;
      }
    }
    return scores;
  }, [profileReport]);

  // Fetch profiles for profile selector (Profile Intelligence candidates)
  useEffect(() => {
    apiGet<{ items?: ProfileItem[]; profiles?: ProfileItem[] } | ProfileItem[]>("/api/profiles/")
      .then((res) => {
        let items: ProfileItem[] = [];
        if (Array.isArray(res)) {
          items = res;
        } else if (res && typeof res === "object") {
          items = (res as { items?: ProfileItem[]; profiles?: ProfileItem[] }).items
            ?? (res as { profiles?: ProfileItem[] }).profiles
            ?? [];
        }
        setProfiles(items.filter((p) => p.is_active));
      })
      .catch(() => {
        // Silently fail — profile selector is optional
        setProfiles([]);
      });
  }, []);

  // Profile Intelligence creates an exclusive L3 watchlist for each shadow
  // candidate. Keep that association visible in the selector and report.
  useEffect(() => {
    apiGet<{ candidates?: ProfileIntelligenceCandidate[] }>(
      "/api/profile-intelligence/autopilot/candidates?limit=100",
    )
      .then((res) => {
        const names: Record<string, string> = {};
        for (const candidate of res.candidates ?? []) {
          if (candidate.profile_id && candidate.watchlist_name) {
            names[candidate.profile_id] = candidate.watchlist_name;
          }
        }
        setWatchlistNames(names);
      })
      .catch(() => setWatchlistNames({}));
  }, []);

  useEffect(() => {
    setLoadingReport(true);
    apiGet<ProfileReportRow[]>("/api/shadow-trades/profile-report?order_by=ev_score&direction=desc")
      .then(setProfileReport)
      .catch(() => setProfileReport([]))
      .finally(() => setLoadingReport(false));
  }, [tick]);

  const fetchList = useCallback(() => {
    setLoadingList(true);
    setErrorList(null);

    const handleError = (err: unknown) => {
      const msg =
        err instanceof ApiError
          ? err.toDescriptiveString()
          : err instanceof Error
          ? err.message
          : "Erro desconhecido";
      setErrorList(msg);
      setList({
        items: [],
        total: 0,
        page: filter.page,
        page_size: filter.pageSize,
      });
    };

    if (filter.status === "ALL") {
      // Server-side pagination puro.
      const qs = buildBaseQuery(filter, {}, sourceTab, selectedProfileId);
      apiGet<ShadowTradeListResponse>(`/api/shadow-trades?${qs}`)
        .then(setList)
        .catch(handleError)
        .finally(() => setLoadingList(false));
      return;
    }

    if (filter.status === "OPEN") {
      // 2 fetches paralelos (PENDING + RUNNING) e merge — backend não
      // suporta `IN (...)` em status.
      const qsPending = buildBaseQuery(filter, {
        status: "PENDING",
        page: 1,
        page_size: MAX_LOCAL_FETCH,
      }, sourceTab, selectedProfileId);
      const qsRunning = buildBaseQuery(filter, {
        status: "RUNNING",
        page: 1,
        page_size: MAX_LOCAL_FETCH,
      }, sourceTab, selectedProfileId);
      Promise.all([
        apiGet<ShadowTradeListResponse>(`/api/shadow-trades?${qsPending}`),
        apiGet<ShadowTradeListResponse>(`/api/shadow-trades?${qsRunning}`),
      ])
        .then(([pending, running]) => {
          const merged = [...pending.items, ...running.items].sort((a, b) => {
            const ta = a.created_at ? new Date(a.created_at).getTime() : 0;
            const tb = b.created_at ? new Date(b.created_at).getTime() : 0;
            return tb - ta;
          });
          setList({
            items: merged,
            total: pending.total + running.total,
            page: 1,
            page_size: merged.length,
          });
        })
        .catch(handleError)
        .finally(() => setLoadingList(false));
      return;
    }

    // TP_HIT / SL_HIT / TIMEOUT: 1 fetch COMPLETED + filtro local por outcome.
    const qsCompleted = buildBaseQuery(filter, {
      status: "COMPLETED",
      page: 1,
      page_size: MAX_LOCAL_FETCH,
    }, sourceTab, selectedProfileId);
    apiGet<ShadowTradeListResponse>(`/api/shadow-trades?${qsCompleted}`)
      .then((res) => setList(res))
      .catch(handleError)
      .finally(() => setLoadingList(false));
  }, [filter, sourceTab, selectedProfileId]);

  const fetchSummary = useCallback(() => {
    setLoadingSummary(true);
    const qs = buildSummaryQuery(filter, sourceTab, selectedProfileId);
    apiGet<ShadowTradeSummary>(
      qs ? `/api/shadow-trades/summary?${qs}` : `/api/shadow-trades/summary`
    )
      .then((res) => setSummary(res))
      .catch(() => setSummary(null))
      .finally(() => setLoadingSummary(false));
  }, [filter, sourceTab, selectedProfileId]);

  useEffect(() => {
    fetchList();
    fetchSummary();
  }, [fetchList, fetchSummary, tick]);

  // Polling leve de preços correntes a cada 15s, só com símbolos visíveis,
  // sem repaginar a lista. Pausa quando a aba do navegador está oculta.
  useEffect(() => {
    const safeListItems = Array.isArray(list?.items) ? list.items : [];
    if (!list || safeListItems.length === 0) return;
    const symbols = Array.from(new Set(safeListItems.map((it) => it.symbol)));
    if (symbols.length === 0) return;

    let cancelled = false;
    const fetchPrices = () => {
      if (typeof document !== "undefined" && document.hidden) return;
      const qs = new URLSearchParams({ symbols: symbols.join(",") }).toString();
      apiGet<{ prices: Record<string, number>; fetched_at: string }>(
        `/api/shadow-trades/prices?${qs}`,
      )
        .then((res) => {
          if (cancelled) return;
          setLivePrices((prev) => ({ ...prev, ...res.prices }));
        })
        .catch(() => {
          // silencioso — preços continuam exibindo o último valor conhecido
        });
    };
    fetchPrices();
    const interval = setInterval(fetchPrices, 15_000);
    return () => {
      cancelled = true;
      clearInterval(interval);
    };
  }, [list]);

  // Mescla livePrices em cima do current_price vindo do backend.
  const itemsWithLivePrices = useMemo(() => {
    if (!list) return [] as ShadowTradeRead[];
    const safeItems = Array.isArray(list.items) ? list.items : [];
    if (Object.keys(livePrices).length === 0) return safeItems;
    return safeItems.map((it) => {
      const live = livePrices[it.symbol];
      if (live === undefined) return it;
      return { ...it, current_price: live };
    });
  }, [list, livePrices]);

  // Quando status != ALL, paginamos client-side sobre o conjunto local
  // (já filtrado/agregado em fetchList). Ao mudar de aba zeramos a página.
  const filteredAll = useMemo(() => {
    if (!list) return [];
    if (filter.status === "ALL") return itemsWithLivePrices;
    if (filter.status === "OPEN") {
      // fetchList já mergeou PENDING+RUNNING e ordenou desc.
      return itemsWithLivePrices;
    }
    // TP_HIT/SL_HIT/TIMEOUT — itemsWithLivePrices aqui é a janela COMPLETED.
    return itemsWithLivePrices.filter((it) => it.outcome === filter.status);
  }, [list, itemsWithLivePrices, filter.status]);

  const isClientPaginated = filter.status !== "ALL";
  const clientTotal = filteredAll.length;
  const clientPageStart = (filter.page - 1) * CLIENT_PAGE_SIZE;
  const displayItems = isClientPaginated
    ? filteredAll.slice(clientPageStart, clientPageStart + CLIENT_PAGE_SIZE)
    : filteredAll;

  // O fetch local é capado em MAX_LOCAL_FETCH para cada base de status.
  // Se a janela bate o teto, sinalizamos pro usuário que pode haver mais.
  const fetchedAtCap =
    isClientPaginated && list
      ? (filter.status === "OPEN"
          ? list.total >= MAX_LOCAL_FETCH * 2
          : (list.total ?? 0) >= MAX_LOCAL_FETCH)
      : false;

  return (
    <div
      style={{
        background: C.bg,
        minHeight: "100vh",
        padding: "20px 24px 40px",
        color: C.text,
      }}
    >
      <div style={{ maxWidth: 1400, margin: "0 auto", display: "grid", gap: 16 }}>
        <div>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12 }}>
          <h1
            style={{
              fontSize: 20,
              fontWeight: 600,
              margin: 0,
              letterSpacing: 0.2,
            }}
          >
            Shadow Portfolio
          </h1>
          <ModuleAIAnalysisAction
            originModule="shadow_portfolio"
            originView="shadow-portfolio"
            entityIds={(list?.items ?? []).map((item) => item.id)}
            supportsRegenerative
            compact
          />
          </div>
          <div style={{ display: "flex", gap: 6, marginTop: 10 }}>
            {(
              [
                { key: "trades" as const, label: "Shadow Trades" },
                { key: "report" as const, label: "Relatório Executivo" },
                { key: "detailed-report" as const, label: "Relatório Detalhado" },
              ]
            ).map(({ key, label }) => {
              const active = mainTab === key;
              return (
                <button
                  key={key}
                  onClick={() => setMainTab(key)}
                  style={{
                    background: active ? C.blue : C.elevated,
                    color: active ? "#fff" : C.muted,
                    border: `1px solid ${active ? C.blue : C.border}`,
                    borderRadius: 6,
                    padding: "5px 16px",
                    fontSize: 12,
                    cursor: "pointer",
                    fontWeight: active ? 600 : 400,
                  }}
                >
                  {label}
                </button>
              );
            })}
          </div>
          {mainTab === "trades" && (
          <p
            style={{
              fontSize: 12,
              color: C.muted,
              margin: "8px 0 0",
              maxWidth: 720,
            }}
          >
            {sourceTab === "L3" ? (
              <>
                Trades simulados a partir de decisões <code>ALLOW</code> spot do
                pipeline (L3). Alimentados pelo monitor após cada decisão aprovada.
              </>
            ) : sourceTab === "L3_REJECTED" ? (
              <>
                Trades simulados para ativos <code>BLOCK</code> — o que teria
                acontecido se os rejeitados pela L3 tivessem sido operados.
                Usado para medir a qualidade do filtro.
              </>
            ) : (
              <>
                Captures do espectro bruto L1 — exatamente o dataset que o ML
                considera. Sem filtro de score ou regras L3. Win rate esperado ~25%.
              </>
            )}
          </p>
          )}
          {mainTab === "trades" && profiles.length > 0 && (
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 12 }}>
              <span style={{ fontSize: 11, color: C.muted, whiteSpace: "nowrap" }}>
                Profile / Watchlist:
              </span>
              <select
                value={selectedProfileId ?? ""}
                onChange={(e) => {
                  setSelectedProfileId(e.target.value || null);
                  setFilter({ ...DEFAULT_FILTER });
                }}
                style={{
                  background: C.elevated,
                  color: C.text,
                  border: `1px solid ${C.border}`,
                  borderRadius: 6,
                  padding: "4px 10px",
                  fontSize: 11.5,
                  cursor: "pointer",
                  outline: "none",
                }}
              >
                <option value="">Todos os profiles</option>
                {profiles.map((p) => (
                  <option key={p.id} value={p.id}>
                    {`${p.name}${watchlistNames[p.id] ? ` — ${watchlistNames[p.id]}` : ""} — EV ${
                      profileEvScores[p.id] != null ? profileEvScores[p.id].toFixed(2) : "—"
                    }`}
                  </option>
                ))}
              </select>
              {selectedProfileId && (
                <button
                  onClick={() => {
                    setSelectedProfileId(null);
                    setFilter({ ...DEFAULT_FILTER });
                  }}
                  style={{
                    background: "transparent",
                    border: `1px solid ${C.border}`,
                    color: C.muted,
                    borderRadius: 4,
                    padding: "3px 8px",
                    fontSize: 10.5,
                    cursor: "pointer",
                  }}
                >
                  Limpar
                </button>
              )}
            </div>
          )}
          {mainTab === "trades" && (
          <div style={{ display: "flex", gap: 6, marginTop: 12 }}>
            {(
              [
                { key: "L3",           label: "Aprovados (L3)",    color: C.blue   },
                { key: "L3_REJECTED",  label: "Rejeitados (L3)",   color: C.amber  },
                { key: "L1_SPECTRUM",  label: "Dataset ML (L1)",   color: C.blue   },
              ] as { key: SourceTab; label: string; color: string }[]
            ).map(({ key, label, color }) => {
              const active = sourceTab === key;
              return (
                <button
                  key={key}
                  onClick={() => {
                    setSourceTab(key);
                    setFilter({ ...DEFAULT_FILTER });
                  }}
                  style={{
                    background: active ? color : C.elevated,
                    color: active ? "#fff" : C.muted,
                    border: `1px solid ${active ? color : C.border}`,
                    borderRadius: 6,
                    padding: "5px 14px",
                    fontSize: 11.5,
                    cursor: "pointer",
                    fontWeight: active ? 600 : 400,
                    letterSpacing: 0.3,
                  }}
                >
                  {label}
                </button>
              );
            })}
          </div>
          )}
        </div>

        {mainTab === "trades" ? (
          <>
            <FilterBar
              filter={filter}
              onChange={setFilter}
              onRefresh={() => setTick((t) => t + 1)}
              loading={loadingList || loadingSummary}
            />

            <SummaryCards data={summary} loading={loadingSummary} />

            {fetchedAtCap ? (
              <div
                style={{
                  fontSize: 11,
                  color: C.amber,
                  padding: "8px 12px",
                  background: `${C.amber}11`,
                  border: `1px solid ${C.amber}33`,
                  borderRadius: 6,
                  display: "flex",
                  alignItems: "center",
                  gap: 8,
                }}
              >
                <AlertTriangle size={12} />
                Mostrando os {MAX_LOCAL_FETCH} itens mais recentes desse filtro.
                Use intervalo de datas ou filtro de símbolo para ver mais.
              </div>
            ) : null}

            <TradeTable
              items={displayItems}
              loading={loadingList}
              error={errorList}
              profileEvScores={profileEvScores}
              onRowClick={(trade) => {
                if (
                  trade.status === "COMPLETED" &&
                  (trade.outcome === "TP_HIT" || trade.outcome === "SL_HIT")
                ) {
                  router.push(`/dashboard/shadow-portfolio/${trade.id}`);
                  return;
                }
                setSelectedId(trade.id);
              }}
            />

            {list ? (
              isClientPaginated ? (
                <Pagination
                  page={filter.page}
                  pageSize={CLIENT_PAGE_SIZE}
                  total={clientTotal}
                  onChange={(page) => setFilter({ ...filter, page })}
                />
              ) : (
                <Pagination
                  page={list.page}
                  pageSize={list.page_size}
                  total={list.total}
                  onChange={(page) => setFilter({ ...filter, page })}
                />
              )
            ) : null}
          </>
        ) : mainTab === "report" ? (
          <ProfileReportTable
            rows={profileReport}
            loading={loadingReport}
            watchlistNames={watchlistNames}
          />
        ) : (
          <DetailedReportWorkspace />
        )}
      </div>

      {selectedId ? (
        <DetailModal shadowId={selectedId} onClose={() => setSelectedId(null)} />
      ) : null}
    </div>
  );
}

"use client";

import { ReactNode, Suspense, useCallback, useEffect, useMemo, useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import {
  ArrowDown,
  ArrowUp,
  ChevronDown,
  ChevronRight,
  Clock,
  Download,
  FileText,
  Filter,
  RefreshCw,
  Search,
} from "lucide-react";

import { apiGet } from "@/lib/api";
import { DecisionCreatedMessage, DecisionItem, useWebSocket } from "@/hooks/useWebSocket";

interface DecisionsResponse {
  items: DecisionItem[];
  next_cursor: string | null;
}

interface DecisionLogConfig {
  page_size?: number;
  client_buffer_size?: number;
  max_displayed_metrics?: number;
  realtime_highlight_ms?: number;
}

interface ApprovedSnapshotItem {
  symbol: string;
  score: number | null;
  alpha_score: number | null;
  score_long: number | null;
  score_short: number | null;
  direction: "LONG" | "SHORT" | "NEUTRAL" | null;
  watchlist_id: string;
  watchlist_name: string;
  stage: string;
  market_mode: "spot" | "futures";
  approved_at: string | null;
  indicators: Array<Record<string, unknown> | string>;
  score_rules: Array<Record<string, unknown> | string>;
}

interface ApprovedSnapshotResponse {
  items: ApprovedSnapshotItem[];
  total: number;
  as_of: string | null;
}

interface SnapshotWatchlist {
  id: string;
  name: string;
  market_mode: "spot" | "futures";
}

// Tabs de topo da página /decisions.
// - "audit"       — trilha de auditoria (decisions_log)
// - "approved-l3" — snapshot vivo dos approved da pipeline canônica L3
type Tab = "audit" | "approved-l3";
type SnapshotScope = "l3";

type Filters = {
  startDate: string;
  endDate: string;
  symbol: string;
  strategy: string;
  scoreMin: string;
  scoreMax: string;
  decision: "ALL" | "ALLOW" | "BLOCK";
};

type SnapshotFilters = {
  symbol: string;
  marketMode: "all" | "spot" | "futures";
  watchlistId: string;
  sort: "score_desc" | "score_asc" | "symbol_asc" | "approved_at_desc";
};

const DEFAULT_FILTERS: Filters = {
  startDate: "",
  endDate: "",
  symbol: "",
  strategy: "",
  scoreMin: "0",
  scoreMax: "100",
  decision: "ALL",
};

const DEFAULT_SNAPSHOT_FILTERS: SnapshotFilters = {
  symbol: "",
  marketMode: "all",
  watchlistId: "",
  sort: "score_desc",
};

const SNAPSHOT_REFRESH_MS = 30_000;

const INPUT_CLASS =
  "rounded-[var(--radius-sm)] border border-[var(--border-default)] bg-[var(--bg-input)] px-3 py-1.5 text-[12px] text-[var(--text-primary)] outline-none transition-colors placeholder:text-[var(--text-tertiary)] focus:border-[var(--accent-primary)]";

function buildParams(filters: Filters, config?: DecisionLogConfig | null, cursor?: string | null) {
  const params = new URLSearchParams();
  if (filters.startDate) params.set("start_date", filters.startDate);
  if (filters.endDate) params.set("end_date", filters.endDate);
  if (filters.symbol) params.set("symbol", filters.symbol.trim().toUpperCase());
  if (filters.strategy) params.set("strategy", filters.strategy.trim().toUpperCase());
  params.set("score_min", filters.scoreMin || "0");
  params.set("score_max", filters.scoreMax || "100");
  params.set("decision", filters.decision);
  if (config?.page_size) params.set("limit", String(config.page_size));
  if (cursor) params.set("cursor", cursor);
  return params.toString();
}

function buildSnapshotParams(filters: SnapshotFilters) {
  const params = new URLSearchParams();
  if (filters.symbol) params.set("symbol", filters.symbol.trim().toUpperCase());
  if (filters.marketMode !== "all") params.set("market_mode", filters.marketMode);
  if (filters.watchlistId) params.set("watchlist_id", filters.watchlistId);
  if (filters.sort) params.set("sort", filters.sort);
  return params.toString();
}

function matchesFilters(item: DecisionItem, filters: Filters) {
  const score = typeof item.score === "number" ? item.score : 0;
  const createdAt = new Date(item.created_at).getTime();

  if (filters.symbol && item.symbol !== filters.symbol.trim().toUpperCase()) return false;
  if (filters.strategy && item.strategy !== filters.strategy.trim().toUpperCase()) return false;
  if (filters.decision !== "ALL" && item.decision !== filters.decision) return false;
  if (score < Number(filters.scoreMin || 0)) return false;
  if (score > Number(filters.scoreMax || 100)) return false;
  if (filters.startDate && createdAt < new Date(`${filters.startDate}T00:00:00Z`).getTime()) return false;
  if (filters.endDate && createdAt > new Date(`${filters.endDate}T23:59:59.999Z`).getTime()) return false;
  return true;
}

function eventTypeTone(eventType?: string | null): string {
  switch (eventType) {
    case "NEW_SIGNAL":       return "bg-[var(--color-profit-muted)] text-[var(--color-profit)] border-[var(--color-profit-border)]";
    case "SIGNAL_LOST":      return "bg-[var(--color-loss-muted)] text-[var(--color-loss)] border-[var(--color-loss-border)]";
    case "SIGNAL_REGAINED":  return "bg-[rgba(20,184,166,0.12)] text-[rgb(20,184,166)] border-[rgba(20,184,166,0.3)]";
    case "SIGNAL_EVOLVED_SCORE":
    case "SIGNAL_EVOLVED_DIRECTION": return "bg-[rgba(251,191,36,0.12)] text-[var(--color-warning)] border-[rgba(251,191,36,0.25)]";
    case "L3_VISIBLE":       return "bg-[rgba(139,92,246,0.12)] text-[rgb(167,139,250)] border-[rgba(139,92,246,0.3)]";
    default:                 return "bg-[var(--bg-elevated)] text-[var(--text-secondary)] border-[var(--border-default)]";
  }
}

function eventTypeLabel(eventType?: string | null): string {
  switch (eventType) {
    case "NEW_SIGNAL":               return "New";
    case "SIGNAL_LOST":              return "Lost";
    case "SIGNAL_REGAINED":          return "Regained";
    case "SIGNAL_EVOLVED_SCORE":     return "Δ Score";
    case "SIGNAL_EVOLVED_DIRECTION": return "Δ Dir";
    case "L3_VISIBLE":               return "L3 Visible";
    default:                         return eventType ?? "";
  }
}

function scoreTone(score?: number | null) {
  if ((score ?? 0) >= 80) return "bg-[var(--color-profit-muted)] text-[var(--color-profit)] border-[var(--color-profit-border)]";
  if ((score ?? 0) >= 60) return "bg-[rgba(251,191,36,0.12)] text-[var(--color-warning)] border-[rgba(251,191,36,0.25)]";
  return "bg-[var(--bg-elevated)] text-[var(--text-secondary)] border-[var(--border-default)]";
}

function decisionTone(decision: DecisionItem["decision"]) {
  return decision === "ALLOW"
    ? "bg-[var(--color-profit-muted)] text-[var(--color-profit)] border-[var(--color-profit-border)]"
    : "bg-[var(--color-loss-muted)] text-[var(--color-loss)] border-[var(--color-loss-border)]";
}

function directionTone(direction?: ApprovedSnapshotItem["direction"]) {
  if (direction === "LONG") return "bg-[var(--color-profit-muted)] text-[var(--color-profit)] border-[var(--color-profit-border)]";
  if (direction === "SHORT") return "bg-[var(--color-loss-muted)] text-[var(--color-loss)] border-[var(--color-loss-border)]";
  return "bg-[var(--bg-elevated)] text-[var(--text-secondary)] border-[var(--border-default)]";
}

function gateMark(value?: boolean | null) {
  return value ? "✓" : "✗";
}

function formatMetricValue(value: unknown) {
  if (typeof value === "number") return Number.isInteger(value) ? String(value) : value.toFixed(2);
  if (typeof value === "boolean") return value ? "true" : "false";
  if (value === null || value === undefined) return "—";
  if (typeof value === "object") return JSON.stringify(value);
  return String(value);
}

function indicatorChipLabel(entry: Record<string, unknown> | string): string {
  if (typeof entry === "string") return entry;
  const raw = entry as Record<string, unknown>;
  const label =
    (raw.label as string | undefined) ??
    (raw.name as string | undefined) ??
    (raw.indicator as string | undefined) ??
    (raw.key as string | undefined);
  return label ?? JSON.stringify(raw);
}

function DecisionsPageInner() {
  const [tab, setTab] = useState<Tab>("audit");

  const tabs: Array<{ id: Tab; label: string; desc: string }> = [
    { id: "audit", label: "Audit Trail", desc: "Real pipeline audit trail — state transitions only" },
    { id: "approved-l3", label: "L3 Approved", desc: "Snapshot vivo dos ativos aprovados na pipeline L3" },
  ];
  const active = tabs.find((t) => t.id === tab) ?? tabs[0];

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-[var(--text-primary)]">Decision Log</h1>
          <p className="mt-1 text-[13px] text-[var(--text-secondary)]">{active.desc}</p>
        </div>
      </div>

      <div className="flex flex-wrap gap-2 border-b border-[var(--border-subtle)]">
        {tabs.map((t) => {
          const isActive = t.id === tab;
          return (
            <button
              key={t.id}
              type="button"
              onClick={() => setTab(t.id)}
              className={`-mb-px border-b-2 px-3 py-2 text-[13px] font-medium transition-colors ${
                isActive
                  ? "border-[var(--accent-primary)] text-[var(--text-primary)]"
                  : "border-transparent text-[var(--text-tertiary)] hover:text-[var(--text-secondary)]"
              }`}
            >
              {t.label}
            </button>
          );
        })}
      </div>

      {tab === "audit" ? (
        <AuditTrailView />
      ) : (
        <ApprovedSnapshotView scope="l3" />
      )}
