        </div>
        <div
          className={`value ${todayPnl >= 0 ? "profit" : "loss"}`}
          style={{ marginTop: "8px" }}
        >
          {todayPnl >= 0 ? "+" : ""}
          {formatCurrency(todayPnl)}
        </div>
        <p className={`change ${todayPnl >= 0 ? "up" : "down"}`} style={{ marginTop: "4px" }}>
          {todayPnl >= 0 ? "▲" : "▼"} vs. yesterday
