  // Data state
  const [overview, setOverview] = useState<PIOverview | null>(null);
  const [runs, setRuns] = useState<PIRun[]>([]);
  const [profiles, setProfiles] = useState<ProfileRanking[]>([]);
  const [winners, setWinners] = useState<IndicatorStat[]>([]);
  const [losers, setLosers] = useState<IndicatorStat[]>([]);
  const [combinations, setCombinations] = useState<Combination[]>([]);
  const [suggestions, setSuggestions] = useState<Suggestion[]>([]);
  const [audit, setAudit] = useState<AuditEntry[]>([]);
  const [settings, setSettings] = useState<PISettings>({});
  const [mlChallengers, setMlChallengers] = useState<Record<string, {
    available: boolean; implemented: boolean; installed: boolean;
    operational: boolean; status: string; effective_contribution: number;
    can_train: boolean; can_infer: boolean; can_generate_suggestions: boolean;
    influences_autopilot: boolean;
  }> | null>(null);
  const [autopilot, setAutopilot] = useState<AutopilotStatus | null>(null);
  const [autopilotCandidates, setAutopilotCandidates] = useState<AutopilotCandidate[]>([]);
  const [autopilotAudit, setAutopilotAudit] = useState<any[]>([]);
  const [togglingAutopilot, setTogglingAutopilot] = useState(false);
  const [runningAutopilot, setRunningAutopilot] = useState(false);
  const [candidateActionId, setCandidateActionId] = useState<string | null>(null);
  const [selectedAutopilotCandidate, setSelectedAutopilotCandidate] = useState<AutopilotCandidate | null>(null);

  // Live Engine state
  const [liveStatus, setLiveStatus] = useState<any>(null);
  const [liveActivity, setLiveActivity] = useState<any[]>([]);
  const [liveShadow, setLiveShadow] = useState<any>(null);
  const [liveIndicators, setLiveIndicators] = useState<any>(null);
  const [liveAdjustments, setLiveAdjustments] = useState<any[]>([]);
  const [liveAiReview, setLiveAiReview] = useState<any>(null);
  const [liveSafety, setLiveSafety] = useState<any>(null);

  // Calibration Evolution state
  const [calSummary, setCalSummary] = useState<any>(null);
  const [calValidatedVersions, setCalValidatedVersions] = useState<any[]>([]);
  const [calV2Overview, setCalV2Overview] = useState<any>(null);
  const [calV2Proposals, setCalV2Proposals] = useState<any[]>([]);
  const [calAdjustments, setCalAdjustments] = useState<any[]>([]);
  const [calTimeline, setCalTimeline] = useState<any[]>([]);
  const [calIndicators, setCalIndicators] = useState<any[]>([]);
  const [calAiExplanations, setCalAiExplanations] = useState<any[]>([]);
  const [calSafety, setCalSafety] = useState<any>(null);
  const [calTotal, setCalTotal] = useState(0);
  const [selectedCalAdjustment, setSelectedCalAdjustment] = useState<any>(null);
  const [calDetailLoading, setCalDetailLoading] = useState(false);
  const [calDetail, setCalDetail] = useState<any>(null);
  const [calSubTab, setCalSubTab] = useState<"adjustments" | "indicators" | "timeline" | "ai">("adjustments");
  const [calFilterMinConf, setCalFilterMinConf] = useState<string>("");

  // Loading
  const [loadingOverview, setLoadingOverview] = useState(true);
  const [loadingTab, setLoadingTab] = useState(false);

  // UI state
  const [indicatorSubTab, setIndicatorSubTab] = useState<"winners" | "losers">("winners");
  const [expandedIndicator, setExpandedIndicator] = useState<string | null>(null);
  const [selectedIndicatorAdjustment, setSelectedIndicatorAdjustment] = useState<IndicatorStat | null>(null);
  const [indicatorAdjustmentProfileIds, setIndicatorAdjustmentProfileIds] = useState<string[]>([]);
  const [indicatorAdjustmentLoading, setIndicatorAdjustmentLoading] = useState(false);
  const [selectedCombination, setSelectedCombination] = useState<Combination | null>(null);
  const [selectedSuggestion, setSelectedSuggestion] = useState<Suggestion | null>(null);
  const [expandedAudit, setExpandedAudit] = useState<string | null>(null);
  const [showRunModal, setShowRunModal] = useState(false);
  const [showSettingsModal, setShowSettingsModal] = useState(false);
  const [runPayload, setRunPayload] = useState({ ...DEFAULT_RUN_PAYLOAD });
  const [runResult, setRunResult] = useState<any>(null);
  const [running, setRunning] = useState(false);
  const [savingSettings, setSavingSettings] = useState(false);
  const [explainingId, setExplainingId] = useState<string | null>(null);
  const [toast, setToast] = useState<{ msg: string; ok: boolean } | null>(null);

  // Create-profile flow
  const [createProfileSuggestion, setCreateProfileSuggestion] = useState<Suggestion | null>(null);
  const [createDryRunResult, setCreateDryRunResult] = useState<CreateProfileDryRun | null>(null);
  const [createDryRunLoading, setCreateDryRunLoading] = useState(false);
  const [createProfileLoading, setCreateProfileLoading] = useState(false);
  const [createProfileResult, setCreateProfileResult] = useState<CreateProfileResult | null>(null);
  const [confirmLowConfidence, setConfirmLowConfidence] = useState(false);
  const [confirmOverfitRisk, setConfirmOverfitRisk] = useState(false);

  // Sort state for profiles table
  const [profileSort, setProfileSort] = useState<{ col: string; asc: boolean }>({ col: "win_rate", asc: false });

  // Duplicate profile group drawer
  const [selectedDuplicateGroup, setSelectedDuplicateGroup] = useState<ProfileRanking[] | null>(null);

  // Combination dedup toggle
  const [hideComboDuplicates, setHideComboDuplicates] = useState(true);

  // Generate suggestion from combination
  const [generatingSuggestion, setGeneratingSuggestion] = useState(false);
  const [lastGeneratedSuggestionId, setLastGeneratedSuggestionId] = useState<string | null>(null);

  const showToast = (msg: string, ok = true) => {
    setToast({ msg, ok });
    setTimeout(() => setToast(null), 4000);
  };

  const handleGenerateSuggestion = async (combinationId: string) => {
    setGeneratingSuggestion(true);
    setLastGeneratedSuggestionId(null);
    try {
      const res = await apiPost(`/api/profile-intelligence/combinations/${combinationId}/create-suggestion`, {});
      showToast(res.created ? "Suggestion gerada com sucesso" : "Suggestion já existia — abrindo", true);
      setLastGeneratedSuggestionId(res.suggestion?.id || null);
      const data = await apiGet("/api/profile-intelligence/suggestions?limit=50");
      setSuggestions(data.suggestions || []);
    } catch (e: any) {
      showToast(`Erro ao gerar suggestion: ${e.message || "unknown"}`, false);
    } finally {
      setGeneratingSuggestion(false);
    }
  };

  // ── Data fetching ───────────────────────────────────────────────────────────

  const loadOverview = useCallback(async () => {
    setLoadingOverview(true);
    try {
      const [ov, r, ap] = await Promise.all([
        apiGet("/profile-intelligence/overview").catch(() => apiGet("/profile-intelligence/")),
        apiGet("/profile-intelligence/runs").catch(() => ({ runs: [] })),
        apiGet("/profile-intelligence/autopilot").catch(() => null),
      ]);
      setOverview(ov || {});
      const runsArr = r?.runs ?? r; setRuns(Array.isArray(runsArr) ? runsArr : []);
      setAutopilot(ap);
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingOverview(false);
    }
  }, []);

  const loadTab = useCallback(async (tab: Tab) => {
    if (tab === "Overview") return;
    setLoadingTab(true);
    try {
      if (tab === "Live Engine") {
        const [status, activity, shadow, indicators, adjustments, aiReview, safety] = await Promise.all([
          apiGet("/profile-intelligence/live/status").catch(() => null),
          apiGet("/profile-intelligence/live/activity?limit=50").catch(() => null),
          apiGet("/profile-intelligence/live/shadow-summary?hours=24").catch(() => null),
          apiGet("/profile-intelligence/live/indicator-performance?limit=20").catch(() => null),
          apiGet("/profile-intelligence/live/adjustment-suggestions?limit=30").catch(() => null),
          apiGet("/profile-intelligence/live/ai-review").catch(() => null),
          apiGet("/profile-intelligence/live/safety").catch(() => null),
        ]);
        setLiveStatus(status);
        setLiveActivity(activity?.items || []);
        setLiveShadow(shadow);
        setLiveIndicators(indicators);
        setLiveAdjustments(adjustments?.items || []);
        setLiveAiReview(aiReview);
        setLiveSafety(safety);
      } else if (tab === "Calibration Evolution") {
        const [summary, adjustments, timeline, indicators, aiExpl, safety, validatedV, v2Overview, v2Proposals] = await Promise.all([
          apiGet("/profile-intelligence/calibration-evolution/summary").catch(() => null),
          apiGet("/profile-intelligence/calibration-evolution/adjustments?limit=100").catch(() => ({ items: [], total: 0 })),
          apiGet("/profile-intelligence/calibration-evolution/timeline?hours=168&limit=100").catch(() => ({ items: [] })),
          apiGet("/profile-intelligence/calibration-evolution/indicator-impact?limit=50").catch(() => ({ items: [] })),
          apiGet("/profile-intelligence/calibration-evolution/ai-explanations?limit=10").catch(() => ({ items: [] })),
          apiGet("/profile-intelligence/calibration-evolution/safety").catch(() => null),
          apiGet("/profile-intelligence/calibration/versions?status=VALIDATED&limit=50").catch(() => ({ versions: [] })),
          apiGet("/calibration-evolution/v2/overview").catch(() => null),
          apiGet("/calibration-evolution/v2/proposals?limit=25").catch(() => ({ items: [] })),
        ]);
        setCalSummary(summary);
        setCalAdjustments(adjustments?.items || []);
        setCalTotal(adjustments?.total || 0);
        setCalTimeline(timeline?.items || []);
        setCalIndicators(indicators?.items || []);
        setCalAiExplanations(aiExpl?.items || []);
        setCalSafety(safety);
        setCalValidatedVersions(validatedV?.versions || []);
        setCalV2Overview(v2Overview);
        setCalV2Proposals(v2Proposals?.items || []);
      } else if (tab === "Auto-Pilot") {
        const [status, candidates, events] = await Promise.all([
          apiGet("/profile-intelligence/autopilot"),
          apiGet("/profile-intelligence/autopilot/candidates?limit=100"),
          apiGet("/profile-intelligence/autopilot/audit?limit=100"),
        ]);
        setAutopilot(status);
        setAutopilotCandidates(candidates?.candidates || []);
        setAutopilotAudit(events?.events || []);
      } else if (tab === "Profiles") {
        const d = await apiGet("/profile-intelligence/profiles/ranking?lookback_days=60&limit=30");
        const profArr = d?.profiles ?? d; setProfiles(Array.isArray(profArr) ? profArr : []);
      } else if (tab === "Indicators") {
        const [w, l] = await Promise.all([
          apiGet("/profile-intelligence/indicators/top-winners?limit=50"),
          apiGet("/profile-intelligence/indicators/top-losers?limit=50"),
        ]);
        const winArr = w?.indicators ?? w; setWinners(Array.isArray(winArr) ? winArr : []);
        const loseArr = l?.indicators ?? l; setLosers(Array.isArray(loseArr) ? loseArr : []);
      } else if (tab === "Combinations") {
        const d = await apiGet("/profile-intelligence/combinations?limit=100");
        const comboArr = d?.combinations ?? d; setCombinations(Array.isArray(comboArr) ? comboArr : []);
      } else if (tab === "Suggestions") {
        const d = await apiGet("/profile-intelligence/suggestions?limit=50");
        { const sArr = d?.suggestions ?? d; setSuggestions(Array.isArray(sArr) ? sArr : []); }
      } else if (tab === "Audit") {
        const d = await apiGet("/profile-intelligence/audit?limit=100");
        setAudit(d?.events || d?.audit_log || d?.logs || []);
      } else if (tab === "Settings") {
        const d = await apiGet("/profile-intelligence/settings");
        setSettings(d?.settings || d || {});
        if (d?.ml_challengers) setMlChallengers(d.ml_challengers);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingTab(false);
    }
  }, []);

  useEffect(() => { loadOverview(); }, [loadOverview]);
  useEffect(() => { loadTab(activeTab); }, [activeTab, loadTab]);

  // Auto-refresh Live Engine tab every 30 seconds while it's active
  useEffect(() => {
    if (activeTab !== "Live Engine") return;
    const interval = setInterval(() => { loadTab("Live Engine"); }, 30000);
    return () => clearInterval(interval);
  }, [activeTab, loadTab]);

  const handleRefresh = () => {
    loadOverview();
    if (activeTab !== "Overview") loadTab(activeTab);
  };

  const handleToggleAutopilot = async () => {
    const next = !autopilot?.enabled;
    setTogglingAutopilot(true);
    try {
      const result = await apiPut("/profile-intelligence/autopilot", { enabled: next });
      setAutopilot(prev => ({ ...(prev || {} as AutopilotStatus), ...result, enabled: next }));
      showToast(
        next && result?.cycle_status === "queued"
          ? "Auto-Pilot global ligado. Primeiro ciclo enfileirado."
          : next
            ? "Auto-Pilot global ligado."
            : "Auto-Pilot global desligado."
      );
      await loadOverview();
      if (next && result?.cycle_status === "queued") {
        setTimeout(() => { loadOverview(); }, 3000);
      }
    } catch (e: any) {
      showToast(`Erro ao alterar Auto-Pilot: ${e.message}`, false);
    } finally {
      setTogglingAutopilot(false);
    }
  };

  const handleRunAutopilot = async () => {
    setRunningAutopilot(true);
    try {
      await apiPost("/profile-intelligence/autopilot/run-cycle", {});
      showToast("Ciclo do Auto-Pilot enfileirado. Aguardando conclusão...");
      // Polling até o ciclo concluir (máx 60 tentativas × 3s = 3min)
      const prevCycleAt = autopilot?.last_cycle_at;
      let attempts = 0;
      while (attempts < 60) {
        await new Promise((r) => setTimeout(r, 3000));
        attempts++;
        try {
          const fresh = await apiGet("/profile-intelligence/autopilot");
          setAutopilot((prev) => ({ ...(prev || {} as AutopilotStatus), ...fresh }));
          const done = fresh?.latest_cycle?.status === "completed" ||
                       fresh?.latest_cycle?.status === "failed" ||
                       (fresh?.last_cycle_at && fresh.last_cycle_at !== prevCycleAt);
          if (done) break;
        } catch {
          // ignora erros de polling
        }
      }
      await loadTab("Auto-Pilot");
      showToast("Ciclo do Auto-Pilot concluído.");
    } catch (e: any) {
      showToast(`Erro ao iniciar ciclo: ${e.message}`, false);
    } finally {
      setRunningAutopilot(false);
    }
  };

  const refreshAutopilot = async () => {
    await loadTab("Auto-Pilot");
  };

  const openIndicatorAdjustment = (stat: IndicatorStat) => {
    setSelectedIndicatorAdjustment(stat);
    setIndicatorAdjustmentProfileIds((stat.associated_profiles || []).map(profile => profile.id));
  };

  const handleIndicatorShadowAdjustment = async () => {
    if (!selectedIndicatorAdjustment?.can_apply_shadow_adjustment || indicatorAdjustmentProfileIds.length === 0) {
      return;
    }
    setIndicatorAdjustmentLoading(true);
    try {
      const result = await apiPost(
        `/profile-intelligence/indicators/${selectedIndicatorAdjustment.id}/shadow-adjustment`,
        { profile_ids: indicatorAdjustmentProfileIds },
      );
      const candidates = Array.isArray(result?.candidates)
        ? result.candidates as Array<{ created?: boolean }>
        : [];
      const created = candidates.filter(candidate => candidate.created).length;
      showToast(`${created} challenger(s) shadow preparado(s). Incumbentes preservados.`);
      setSelectedIndicatorAdjustment(null);
      setIndicatorAdjustmentProfileIds([]);
      await loadTab("Auto-Pilot");
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : String(error);
      showToast(`Ajuste bloqueado: ${message}`, false);
    } finally {
      setIndicatorAdjustmentLoading(false);
    }
  };

  const authenticatedUserId = () => {
    const raw = typeof window !== "undefined" ? localStorage.getItem("user") : null;
    if (!raw) return null;
    try {
      const user = JSON.parse(raw);
      return user?.id || user?.user_id || null;
    } catch {
      return null;
    }
  };

  const handleApproveCandidate = async (candidate: AutopilotCandidate) => {
    const confirmed = window.confirm(
      "Confirmo que revisei as métricas shadow e autorizo este candidato para ativação live."
    );
    if (!confirmed) return;
    const reason = window.prompt("Informe o motivo técnico da aprovação:");
    const approvedBy = authenticatedUserId();
    if (!reason?.trim() || !approvedBy) {
      showToast("Aprovação exige motivo e usuário autenticado.", false);
      return;
    }
    setCandidateActionId(candidate.id);
    try {
      await apiPost(`/profile-intelligence/autopilot/candidates/${candidate.id}/approve`, {
        approved_by: approvedBy,
        approval_reason: reason.trim(),
        confirm_risk: true,
        approval_source: "profile_intelligence_ui",
      });
      showToast("Candidato aprovado. A ativação live continua separada.");
      await refreshAutopilot();
    } catch (e: any) {
      showToast(`Erro ao aprovar candidato: ${e.message}`, false);
    } finally {
      setCandidateActionId(null);
    }
  };

  const handleRejectCandidate = async (candidate: AutopilotCandidate) => {
    const reason = window.prompt("Informe o motivo da rejeição:");
    if (!reason?.trim()) return;
    setCandidateActionId(candidate.id);
    try {
      await apiPost(`/profile-intelligence/autopilot/candidates/${candidate.id}/reject`, {
        rejection_reason: reason.trim(),
      });
      showToast("Candidato rejeitado.");
      await refreshAutopilot();
    } catch (e: any) {
      showToast(`Erro ao rejeitar candidato: ${e.message}`, false);
    } finally {
      setCandidateActionId(null);
    }
  };

  const handleActivateCandidate = async (candidate: AutopilotCandidate) => {
    if (!window.confirm("Ativar este candidato aprovado em live agora?")) return;
    setCandidateActionId(candidate.id);
    try {
      await apiPost(`/profile-intelligence/autopilot/candidates/${candidate.id}/activate`, {});
      showToast("Candidato ativado em live.");
      await refreshAutopilot();
    } catch (e: any) {
      showToast(`Ativação bloqueada: ${e.message}`, false);
    } finally {
      setCandidateActionId(null);
    }
  };

  const handleRollbackCandidate = async (candidate: AutopilotCandidate) => {
    if (!window.confirm("Executar rollback e restaurar o profile incumbent?")) return;
    setCandidateActionId(candidate.id);
    try {
      await apiPost(`/profile-intelligence/autopilot/candidates/${candidate.id}/rollback`, {});
      showToast("Rollback executado.");
      await refreshAutopilot();
    } catch (e: any) {
      showToast(`Erro no rollback: ${e.message}`, false);
    } finally {
      setCandidateActionId(null);
    }
  };

  // ── Run Analysis ─────────────────────────────────────────────────────────────

  const handleRun = async () => {
    setRunning(true);
    setRunResult(null);
    try {
      const res = await apiPost("/profile-intelligence/run", runPayload);
      setRunResult({ ok: true, run_id: res?.run_id, status: res?.status });
      showToast(`Análise iniciada. Run ID: ${res?.run_id || "—"}`);
      setTimeout(() => { loadOverview(); }, 2000);
    } catch (e: any) {
      setRunResult({ ok: false, error: e.message });
      showToast(`Erro: ${e.message}`, false);
    } finally {
      setRunning(false);
    }
  };

  // ── Explain with AI ──────────────────────────────────────────────────────────

  const handleExplain = async (suggestionId: string) => {
    setExplainingId(suggestionId);
    try {
      const res = await apiPost(`/profile-intelligence/suggestions/${suggestionId}/explain`);
      showToast("Explicação gerada com sucesso.");
      // Refresh suggestion detail
      if (selectedSuggestion?.id === suggestionId) {
        const updated = await apiGet(`/profile-intelligence/suggestions/${suggestionId}`);
        setSelectedSuggestion(updated?.suggestion || updated);
      }
      // Refresh list
      const d = await apiGet("/profile-intelligence/suggestions?limit=50");
      { const sArr = d?.suggestions ?? d; setSuggestions(Array.isArray(sArr) ? sArr : []); }
    } catch (e: any) {
      showToast(`Erro ao explicar: ${e.message}`, false);
    } finally {
      setExplainingId(null);
    }
  };

  // ── Create Profile from Suggestion ──────────────────────────────────────────

  const handleOpenCreateProfile = async (suggestion: Suggestion) => {
    setCreateProfileSuggestion(suggestion);
    setCreateDryRunResult(null);
    setCreateProfileResult(null);
    setConfirmLowConfidence(false);
    setConfirmOverfitRisk(false);
    setCreateDryRunLoading(true);
    try {
      const res = await apiPost(`/profile-intelligence/suggestions/${suggestion.id}/create-profile`, {
        dry_run: true,
        mode: "SHADOW_ONLY",
        confirm_low_confidence: suggestion.confidence_level !== "LOW",
        confirm_overfit_risk: false,
        create_missing_master_rules: true,
        reuse_existing_master_rules: true,
      });
      setCreateDryRunResult(res as CreateProfileDryRun);
    } catch (e: any) {
      showToast(`Dry-run falhou: ${e.message}`, false);
      setCreateProfileSuggestion(null);
    } finally {
      setCreateDryRunLoading(false);
    }
  };

  const handleConfirmCreateProfile = async () => {
    if (!createProfileSuggestion) return;
    setCreateProfileLoading(true);
    try {
      const res = await apiPost(`/profile-intelligence/suggestions/${createProfileSuggestion.id}/create-profile`, {
        dry_run: false,
        mode: "SHADOW_ONLY",
        confirm_low_confidence: confirmLowConfidence || createProfileSuggestion.confidence_level !== "LOW",
        confirm_overfit_risk: confirmOverfitRisk || !(createDryRunResult?.overfit_risk),
        create_missing_master_rules: true,
        reuse_existing_master_rules: true,
      });
      setCreateProfileResult(res as CreateProfileResult);
      showToast(`Profile criado: ${(res as any).profile_name}`);
      // Refresh suggestions list
      const d = await apiGet("/profile-intelligence/suggestions?limit=50");
      { const sArr = d?.suggestions ?? d; setSuggestions(Array.isArray(sArr) ? sArr : []); }
      // Refresh audit
      const a = await apiGet("/profile-intelligence/audit?limit=100");
      setAudit(a?.events || []);
    } catch (e: any) {
      showToast(`Erro ao criar profile: ${e.message}`, false);
    } finally {
      setCreateProfileLoading(false);
    }
  };

  // ── Save Settings ─────────────────────────────────────────────────────────────

  const handleSaveSettings = async () => {
    setSavingSettings(true);
    try {
      const response = await apiPut("/profile-intelligence/settings", settings);
      setSettings(response?.settings || settings);
      showToast("Configurações salvas.");
    } catch (e: any) {
      showToast(`Erro: ${e.message}`, false);
    } finally {
      setSavingSettings(false);
    }
  };

  // ── Profiles sort ────────────────────────────────────────────────────────────

  const sortedProfiles = [...profiles].sort((a, b) => {
    const col = profileSort.col as keyof ProfileRanking;
    const av = (a[col] as number) ?? -Infinity;
    const bv = (b[col] as number) ?? -Infinity;
    return profileSort.asc ? av - bv : bv - av;
  });

  const toggleProfileSort = (col: string) => {
    setProfileSort(prev => prev.col === col ? { col, asc: !prev.asc } : { col, asc: false });
  };

  // Group sorted profiles by name — collapses duplicate-named profiles into one row
  const profileGroups = useMemo(() => {
    const map = new Map<string, ProfileRanking[]>();
    for (const p of sortedProfiles) {
      if (!map.has(p.profile_name)) map.set(p.profile_name, []);
      map.get(p.profile_name)!.push(p);
    }
    return Array.from(map.values());
  }, [sortedProfiles]);

  function aggregateGroup(items: ProfileRanking[]): ProfileRanking & { _count: number } {
    const totalClosed = items.reduce((s, p) => s + (p.closed_trades ?? 0), 0);
    const totalOpen = items.reduce((s, p) => s + (p.open_trades ?? 0), 0);
    const totalWins = items.reduce((s, p) => s + (p.wins ?? 0), 0);
    const totalLosses = items.reduce((s, p) => s + (p.losses ?? 0), 0);
    const withPnl = items.filter(p => p.avg_pnl_pct != null);
    const withMae = items.filter(p => p.avg_mae_pct != null);
    const withTp = items.filter(p => p.tp_30m_rate != null);
    const levels = items.map(p => p.confidence_level);
    const bestLevel = levels.includes("HIGH") ? "HIGH" : levels.includes("MEDIUM") ? "MEDIUM" : levels.includes("LOW") ? "LOW" : null;
    return {
      profile_id: items[0].profile_id,
      profile_name: items[0].profile_name,
      closed_trades: totalClosed,
      open_trades: totalOpen,
      wins: totalWins,
      losses: totalLosses,
      win_rate: totalWins + totalLosses > 0 ? totalWins / (totalWins + totalLosses) : null,
      avg_pnl_pct: withPnl.length > 0 ? withPnl.reduce((s, p) => s + p.avg_pnl_pct!, 0) / withPnl.length : null,
      avg_mae_pct: withMae.length > 0 ? withMae.reduce((s, p) => s + p.avg_mae_pct!, 0) / withMae.length : null,
      tp_30m_rate: withTp.length > 0 ? withTp.reduce((s, p) => s + p.tp_30m_rate!, 0) / withTp.length : null,
      confidence_level: bestLevel,
      _count: items.length,
    };
  }

  // ── Combination deduplication ────────────────────────────────────────────────

  function buildComboCanonicalKey(rules_json: any[] | null | undefined): string {
    if (!rules_json?.length) return "";
    return rules_json
      .map(r => {
        const indicator = r.indicator || r.field || r.item || "";
        const operator = r.operator || "";
        const raw = r.value;
        const value = typeof raw === "number"
          ? raw.toFixed(8).replace(/\.?0+$/, "")
          : String(raw ?? "");
        return `${indicator}|${operator}|${value}`;
      })
      .sort()
      .join("||");
  }

  const displayedCombinations = useMemo(() => {
    if (!hideComboDuplicates) return combinations;
    const best = new Map<string, Combination>();
    for (const c of combinations) {
      const key = buildComboCanonicalKey(c.rules_json) || c.id;
      const existing = best.get(key);
      if (!existing || (c.champion_score ?? 0) > (existing.champion_score ?? 0)) {
        best.set(key, c);
      }
    }
    return [...best.values()].sort((a, b) => (b.champion_score ?? 0) - (a.champion_score ?? 0));
  }, [combinations, hideComboDuplicates]);

  const hiddenComboCount = combinations.length - displayedCombinations.length;

  // ── Render ─────────────────────────────────────────────────────────────────

  return (
    <div className="space-y-5 pb-10">

      {/* Toast */}
      {toast && (
        <div className={`fixed top-4 right-4 z-50 px-4 py-3 rounded-lg text-[13px] font-medium shadow-lg ${toast.ok ? "bg-green-600 text-white" : "bg-red-600 text-white"}`}>
          {toast.msg}
        </div>
      )}

      {/* Header */}
      <div className="flex justify-between items-start gap-4 flex-wrap">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-[var(--text-primary)] flex items-center gap-2">
            <Brain className="w-6 h-6 text-blue-400" />
            Profile Intelligence
          </h1>
          <p className="text-[var(--text-secondary)] mt-1 text-[13px]">
            Mapa de oportunidades, indicadores campeões e combinações ocultas
          </p>
          <div className="flex items-center gap-2 mt-2 flex-wrap">
            {overview?.last_run_at && (
              <span className="text-[11px] text-[var(--text-tertiary)]">
                Última execução: {fmtDate(overview.last_run_at)}
              </span>
            )}
            {overview?.last_run_status && statusBadge(overview.last_run_status)}
            {(overview?.total_suggestions_pending ?? 0) > 0 && (
              <span className="badge range text-[10px]">
                {overview!.total_suggestions_pending} sugestões pendentes
              </span>
            )}
          </div>
        </div>
        <div className="flex items-center gap-2 flex-wrap">
          <button
            className={`btn text-[12px] flex items-center gap-1.5 ${
              autopilot?.enabled
                ? "bg-green-600/20 text-green-400 border border-green-500/40"
                : "btn-secondary"
            }`}
            onClick={handleToggleAutopilot}
            disabled={togglingAutopilot}
            title="Controle global por conta"
          >
            <Power className="w-3.5 h-3.5" />
            Auto-Pilot {autopilot?.enabled ? "Ligado" : "Desligado"}
          </button>
          <button
            className="btn btn-secondary text-[12px] flex items-center gap-1.5"
            onClick={handleRefresh}
            disabled={loadingOverview || loadingTab}
          >
            <RefreshCw className={`w-3.5 h-3.5 ${(loadingOverview || loadingTab) ? "animate-spin" : ""}`} />
            Refresh
          </button>
          <button
            className="btn btn-secondary text-[12px] flex items-center gap-1.5"
            onClick={() => setShowSettingsModal(true)}
          >
            <Settings className="w-3.5 h-3.5" />
            Settings
          </button>
          <button
            className="btn btn-primary text-[12px] flex items-center gap-1.5"
            onClick={() => { setRunResult(null); setShowRunModal(true); }}
          >
            <Play className="w-3.5 h-3.5" />
            Run Analysis
          </button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex gap-1 border-b border-[var(--border-default)] overflow-x-auto">
        {TABS.map(tab => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-4 py-2.5 text-[13px] font-medium whitespace-nowrap border-b-2 transition-colors ${
              activeTab === tab
                ? "border-[var(--accent-primary)] text-[var(--accent-primary)]"
                : "border-transparent text-[var(--text-secondary)] hover:text-[var(--text-primary)]"
            }`}
          >
            {tab}
          </button>
        ))}
      </div>

      {/* ── TAB: Overview ──────────────────────────────────────────────────────── */}
      {activeTab === "Overview" && (
        <div className="space-y-5">
          {loadingOverview ? (
            <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
              {[...Array(10)].map((_, i) => <div key={i} className="skeleton h-24 rounded-[var(--radius-lg)]" />)}
            </div>
          ) : (
            <>
              {/* Executive cards */}
              <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
                {[
                  { label: "Profiles Analisados", value: overview?.total_profiles_analyzed ?? "—", sub: "snapshot do run", hint: "Snapshot do último run do PI Engine (profile_intelligence_runs.total_profiles). Não é query live em shadow_trades." },
                  { label: "Trades Fechados", value: overview?.total_closed_trades ?? "—", sub: "snapshot do run", hint: "Snapshot do último run do PI Engine (profile_intelligence_runs.total_closed_trades). Não é query live em shadow_trades." },
                  { label: "Win Rate Base", value: overview?.base_win_rate != null ? `${(overview.base_win_rate * 100).toFixed(1)}%` : "—", sub: overview?.last_run_at ? `trade-level · ${overview.last_run_lookback_days ?? 7}d · ${fmtDate(overview.last_run_at)}` : "trade-level · snapshot", hint: "Trade-level: TP_HIT / (TP+SL+Timeout). Snapshot congelado do último run do PI Engine. Não atualiza em tempo real. Período: lookback_days configurado no run." },
                  { label: "Melhor Profile", value: overview?.best_profile_name || "—", sub: overview?.best_profile_win_rate != null ? `${(overview.best_profile_win_rate * 100).toFixed(1)}% WR` : "", hint: "Profile com maior win rate (shadow_trades, live, 60d, min 30 trades). Esta é query live — não é snapshot." },
                  { label: "Melhor Combinação", value: overview?.best_combination_name || "—", sub: overview?.best_combination_champion_score != null ? `Score: ${overview.best_combination_champion_score.toFixed(0)}` : "", hint: "Combinação com maior champion score (profile_rule_combinations, live)." },
                  { label: "Combinações", value: overview?.total_combinations ?? "—", hint: "Total de combinações descobertas (profile_rule_combinations, all-time, live)." },
                  { label: "Sugestões do Run", value: overview?.total_suggestions_pending ?? "—", sub: "profile_suggestions · legada", hint: "profile_suggestions com status='pending_user_approval' (tabela legada do PI Engine). DIFERENTE de profile_adjustment_suggestions do Calibration Evolution." },
                  { label: "Alta Confiança (PI)", value: overview?.total_suggestions_high_confidence ?? "—", sub: "profile_suggestions", hint: "profile_suggestions com confidence_level='HIGH' (string). DIFERENTE de profile_adjustment_suggestions com confidence ≥ 0.80 (numérico) do Calibration Evolution." },
                  { label: "Total de Runs", value: overview?.total_runs ?? "—", hint: "Execuções do PI Engine (profile_intelligence_runs, all-time)." },
                  { label: "Status", value: overview?.last_run_status ? overview.last_run_status.toUpperCase() : "—", hint: "Status da última execução do PI Engine." },
                ].map((card, i) => (
                  <div key={i} className="card p-3 space-y-1" title={card.hint}>
                    <div className="text-[10px] font-semibold text-[var(--text-tertiary)] uppercase tracking-wider">{card.label}</div>
                    <div className="text-[18px] font-bold text-[var(--text-primary)] truncate">{String(card.value)}</div>
                    {(card as any).sub && <div className="text-[11px] text-[var(--text-secondary)]">{(card as any).sub}</div>}
                  </div>
                ))}
              </div>

              {/* Runs history */}
              <div className="card">
                <div className="p-4 border-b border-[var(--border-default)]">
                  <h2 className="text-[14px] font-semibold text-[var(--text-primary)]">Histórico de Execuções</h2>
                </div>
                {runs.length === 0 ? (
                  <EmptyState message="Nenhuma execução encontrada. Execute uma análise para começar." onRun={() => setShowRunModal(true)} />
                ) : (
                  <div className="overflow-x-auto">
                    <table className="w-full text-[12px]">
                      <thead>
                        <tr className="border-b border-[var(--border-subtle)]">
                          {["Data", "Origem", "Status", "Lookback", "Trades", "Combinações", "Sugestões", "Win Rate", "Erro"].map(h => (
                            <th key={h} className="px-4 py-2 text-left text-[10px] font-semibold text-[var(--text-tertiary)] uppercase tracking-wider whitespace-nowrap">{h}</th>
                          ))}
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-[var(--border-subtle)]">
                        {runs.map(run => (
                          <tr key={run.id} className="hover:bg-[var(--bg-elevated)] transition-colors">
                            <td className="px-4 py-2.5 font-mono text-[var(--text-secondary)] whitespace-nowrap">{fmtDate(run.run_at)}</td>
                            <td className="px-4 py-2.5">
                              {run.trigger_source === "manual"
                                ? <span className="badge range text-[10px]">manual</span>
                                : run.trigger_source === "beat"
                                  ? <span className="badge bullish text-[10px]">auto</span>
                                  : <span className="text-[var(--text-tertiary)] text-[10px]">—</span>}
                            </td>
                            <td className="px-4 py-2.5">{statusBadge(run.status)}</td>
                            <td className="px-4 py-2.5 text-[var(--text-secondary)]">{run.lookback_days}d</td>
                            <td className="px-4 py-2.5 text-[var(--text-primary)]">{run.total_closed_trades ?? "—"}</td>
                            <td className="px-4 py-2.5 text-[var(--text-primary)]">{run.total_combinations ?? "—"}</td>
                            <td className="px-4 py-2.5 text-[var(--text-primary)]">{run.total_suggestions ?? "—"}</td>
                            <td className="px-4 py-2.5">{run.base_win_rate != null ? `${(run.base_win_rate * 100).toFixed(1)}%` : "—"}</td>
                            <td className="px-4 py-2.5 text-red-400 max-w-[180px] truncate" title={run.error_message || ""}>{run.error_message || "—"}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>

              {/* Safety notice */}
              <div className="card p-4 border-yellow-500/20 bg-yellow-500/5">
                <div className="flex items-start gap-2">
                  <AlertTriangle className="w-4 h-4 text-yellow-400 mt-0.5 shrink-0" />
                  <div className="text-[12px] text-[var(--text-secondary)] space-y-1">
                    <p><strong className="text-yellow-400">Aviso operacional:</strong> O Profile Intelligence Engine é analítico. Sugestões são <em>hipóteses</em>, não recomendações operacionais.</p>
                    <p>Com o Auto-Pilot ligado, clones continuam evoluindo em Shadow. Qualquer ativação live exige aprovação humana explícita e uma ação separada de ativação.</p>
                  </div>
                </div>
              </div>
            </>
          )}
        </div>
      )}

      {/* ── TAB: Calibration Evolution ─────────────────────────────────────── */}
      {activeTab === "Calibration Evolution" && (
        <div className="space-y-4">

          <div className="relative overflow-hidden rounded-xl border border-cyan-400/20 bg-[#071217] p-4 shadow-[inset_0_1px_0_rgba(255,255,255,.04)]">
            <div className="absolute inset-y-0 left-0 w-1 bg-gradient-to-b from-cyan-300 via-emerald-400 to-amber-300" />
            <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
              <div>
                <div className="font-mono text-[10px] uppercase tracking-[0.28em] text-cyan-300">Calibration Evolution · Versioned rail</div>
                <h3 className="mt-1 text-[15px] font-semibold text-slate-100">Evidence → Recommendation → Challenger Shadow</h3>
                <p className="mt-1 max-w-2xl text-[11px] leading-relaxed text-slate-400">O campeão permanece imutável. Promoção live não ocorre nesta etapa; flags e aprovação humana continuam obrigatórias.</p>
              </div>
              <div className="grid grid-cols-3 gap-px overflow-hidden rounded-lg border border-white/10 bg-white/10">
                {[["Recomendações", calV2Overview?.recommendations ?? "—"], ["Propostas", calV2Overview?.proposals ?? "—"], ["Shadow", calV2Overview?.shadow_canaries ?? "—"]].map(([label, value]) => (
                  <div key={String(label)} className="min-w-[92px] bg-[#09181e] px-3 py-2 text-center">
                    <div className="font-mono text-lg text-slate-100">{String(value)}</div>
                    <div className="text-[9px] uppercase tracking-wider text-slate-500">{label}</div>
                  </div>
                ))}
              </div>
            </div>
            {calV2Proposals.length > 0 && <div className="mt-4 flex gap-2 overflow-x-auto pb-1">
              {calV2Proposals.slice(0, 6).map((proposal: any) => <div key={proposal.id} className="min-w-[220px] rounded-lg border border-white/10 bg-white/[.025] p-3">
                <div className="truncate text-[11px] font-medium text-slate-200">{proposal.profile_name}</div>
                <div className="mt-1 flex items-center justify-between font-mono text-[9px] uppercase tracking-wider"><span className="text-cyan-300">{proposal.state}</span><span className="text-slate-500">n={proposal.observed_trades ?? 0}</span></div>
              </div>)}
            </div>}
          </div>

          {/* Legacy validations remain visible, but direct mutation is retired. */}
          {calValidatedVersions.length > 0 && (
            <div className="card p-4 border-amber-500/30 bg-amber-500/5">
              <div className="flex items-center gap-2 mb-3">
                <AlertTriangle className="w-4 h-4 text-amber-400" />
                <h3 className="text-[13px] font-semibold text-amber-400">
                  {calValidatedVersions.length} validação(ões) legada(s) — aplicação direta bloqueada
                </h3>
              </div>
              <div className="space-y-2">
                {calValidatedVersions.map((v: any) => (
                  <div key={v.id} className="flex items-center justify-between gap-3 bg-[var(--bg-elevated)] rounded p-3">
                    <div className="flex-1 min-w-0">
                      <div className="text-[12px] font-medium text-[var(--text-primary)] truncate">
                        {v.profile_name || v.profile_id?.slice(0, 8)}
                      </div>
                      <div className="text-[10px] text-[var(--text-tertiary)] mt-0.5">
                        buy {v.before_snapshot?.scoring?.thresholds?.buy ?? "?"} → {v.after_snapshot?.scoring?.thresholds?.buy ?? "?"}
                        {v.win_rate_after != null && (
                          <span className="ml-2 text-green-400">WR {(v.win_rate_after * 100).toFixed(1)}%</span>
                        )}
                        {v.win_rate_before != null && (
                          <span className="ml-1 text-[var(--text-tertiary)]">(antes: {(v.win_rate_before * 100).toFixed(1)}%)</span>
                        )}
                      </div>
                    </div>
                    <span className="shrink-0 rounded border border-amber-400/20 bg-amber-400/10 px-3 py-1.5 font-mono text-[9px] uppercase tracking-wider text-amber-300">
                      Migrar para V2
                    </span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Safety banner */}
          {calSafety && (
            <div className={`card p-3 flex items-start gap-2 ${calSafety.safety_pass ? "border-green-500/30 bg-green-500/5" : "border-red-500/30 bg-red-500/5"}`}>
              {calSafety.safety_pass
                ? <CheckCircle className="w-4 h-4 text-green-400 mt-0.5 shrink-0" />
                : <AlertTriangle className="w-4 h-4 text-red-400 mt-0.5 shrink-0" />}
              <div className="space-y-1">
                <div className={`text-[12px] font-semibold ${calSafety.safety_pass ? "text-green-400" : "text-red-400"}`}>
                  Safety Guard — {calSafety.safety_status ?? (calSafety.safety_pass ? "PASS" : "FAIL")}
                </div>
                {calSafety.safety_pass ? (
                  <div className="text-[11px] text-[var(--text-secondary)]">
                    AI Critic real review OK · hollow COMPLETED 24h: {calSafety.hollow_ai_reviews_24h ?? 0}
                  </div>
                ) : (
                  <div className="text-[11px] text-red-400">
                    Safety checks falhando — revise antes de qualquer ação.
                    {calSafety.checks?.filter((check: any) => !check.pass).map((check: any) => (
                      <span key={check.name} className="ml-2 font-mono">[{check.name}={check.value}]</span>
                    ))}
                  </div>
                )}
                {(calSafety.legacy_hollow_reviews_24h ?? 0) > 0 && (
                  <div className="text-[11px] text-yellow-400">
                    Aviso informativo: {calSafety.legacy_hollow_reviews_24h} review(s) hollow legado(s) preservado(s) e reclassificado(s).
                  </div>
                )}
              </div>
            </div>
          )}
          {/* Performance do Portfólio Shadow — trade-level, L3 + Strategy Lab */}
          {!loadingTab && calSummary?.portfolio_metrics && (
            <div className="space-y-2">
              <div className="text-[10px] font-semibold text-[var(--text-tertiary)] uppercase tracking-wider">
                Performance do Portfólio Shadow · trade-level · L3 + Strategy Lab · all-time · shadow_trades
              </div>
              <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
                {[
                  {
                    label: "Win Rate (trade-level)",
                    value: calSummary.portfolio_metrics.win_rate != null ? `${(calSummary.portfolio_metrics.win_rate * 100).toFixed(1)}%` : "—",
                    sub: "L3 + L3_LAB · all-time",
                    hint: "Win Rate REAL do portfólio shadow. Fonte: shadow_trades, status=COMPLETED, sources=L3+L3_LAB, all-time. Fórmula: TP_HIT / (TP+SL+Timeout). Comparável com Shadow Portfolio.",
                  },
                  {
                    label: "P&L Médio / Trade",
                    value: calSummary.portfolio_metrics.avg_pnl_pct != null ? `${(calSummary.portfolio_metrics.avg_pnl_pct * 100).toFixed(2)}%` : "—",
                    sub: "trade-level · não é média de buckets",
                    hint: "P&L médio REAL por trade. Fonte: shadow_trades L3+L3_LAB, COMPLETED, pnl_pct IS NOT NULL. NÃO COMPARAR com 'P&L Buckets (48h)' abaixo — são métricas de fonte e agregação diferentes.",
                  },
                  {
                    label: "P&L Total USDT",
                    value: calSummary.portfolio_metrics.pnl_total_usdt != null ? `$${calSummary.portfolio_metrics.pnl_total_usdt.toFixed(0)}` : "—",
                    sub: "USDT simulado",
                    hint: "P&L total acumulado simulado (shadow_trades L3+L3_LAB COMPLETED all-time, SUM(pnl_usdt)).",
                  },
                  {
                    label: "Trades Fechados",
                    value: calSummary.portfolio_metrics.completed_trades ?? "—",
                    sub: "L3 + L3_LAB",
                    hint: "shadow_trades com status=COMPLETED e pnl_pct IS NOT NULL. Sources: L3+L3_LAB.",
                  },
                  {
                    label: "Profiles",
                    value: calSummary.portfolio_metrics.profiles_count ?? "—",
                    sub: "L3 + L3_LAB",
                    hint: "Profiles distintos com shadow trades COMPLETED. Sources: L3+L3_LAB.",
                  },
                ].map((card, i) => (
                  <div key={i} className="card p-3 space-y-1 border-emerald-500/20 bg-emerald-500/5" title={card.hint}>
                    <div className="text-[10px] font-semibold text-[var(--text-tertiary)] uppercase tracking-wider">{card.label}</div>
                    <div className="text-[18px] font-bold text-[var(--text-primary)] truncate">{String(card.value)}</div>
                    <div className="text-[11px] text-[var(--text-secondary)]">{card.sub}</div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Diagnóstico de Indicadores + Calibração — métricas de bucket e sugestões */}
          {loadingTab ? (
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
              {[...Array(8)].map((_, i) => <div key={i} className="skeleton h-20 rounded-[var(--radius-lg)]" />)}
            </div>
          ) : (
            <div className="space-y-2">
              <div className="text-[10px] font-semibold text-[var(--text-tertiary)] uppercase tracking-wider">
                Diagnóstico de Indicadores (48h) · profile_indicator_performance · média por bucket · não comparar com portfólio
              </div>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                {[
                  {
                    label: "Sugestões Registradas",
                    value: calSummary?.suggestions?.total ?? "—",
                    sub: `${calSummary?.suggestions?.profiles_targeted ?? 0} profiles · all-time`,
                    hint: "Total all-time de profile_adjustment_suggestions (Calibration Live Engine). Inclui SHADOW_APPLIED + PENDING_SHADOW_VALIDATION. DIFERENTE de profile_suggestions (PI Engine legado, usado pelo Overview).",
                  },
                  {
                    label: "Pendentes Validação",
                    value: calSummary?.suggestions?.pending_shadow_validation ?? "—",
                    sub: "PENDING_SHADOW_VALIDATION",
                    hint: "profile_adjustment_suggestions com status=PENDING_SHADOW_VALIDATION — aguardando validação shadow antes de ser aplicadas.",
                  },
                  {
                    label: "Alta Confiança",
                    value: calSummary?.suggestions?.high_confidence ?? "—",
                    sub: "conf ≥ 0.80 (numérico)",
                    hint: "profile_adjustment_suggestions com confidence ≥ 0.80 (campo numérico). DIFERENTE de profile_suggestions.confidence_level='HIGH' (string) do Overview.",
                  },
                  {
                    label: "Mutações Aplicadas",
                    value: calSummary?.suggestions?.mutations_applied ?? "—",
                    sub: "mutation_applied=true",
                    hint: "Calibrações efetivamente aplicadas em produção (mutation_applied=true).",
                  },
                  {
                    label: "Indicadores (48h)",
                    value: calSummary?.indicators?.distinct_indicators ?? "—",
                    sub: `${calSummary?.indicators?.profiles_analyzed ?? 0} profiles`,
                    hint: "Indicadores distintos em profile_indicator_performance nas últimas 48h (criados_at >= now() - 48h).",
                  },
                  {
                    label: "Win Rate Buckets (48h)",
                    value: calSummary?.indicators?.avg_win_rate != null ? `${(calSummary.indicators.avg_win_rate * 100).toFixed(1)}%` : "—",
                    sub: "média por bucket · não é WR do portfólio",
                    hint: "AVG(win_rate) sobre todos os rows de profile_indicator_performance 48h. Média SIMPLES por bucket de indicador — inclui buckets com win_rate=0. NÃO COMPARAR com Win Rate trade-level acima.",
                  },
                  {
                    label: "P&L Buckets (48h)",
                    value: calSummary?.indicators?.avg_pnl_pct != null ? `${(calSummary.indicators.avg_pnl_pct * 100).toFixed(2)}%` : "—",
                    sub: "média por bucket · não é P&L do portfólio",
                    hint: "AVG(avg_pnl_pct) sobre todos os rows de profile_indicator_performance 48h. Inclui buckets com avg_pnl_pct=-1.0 (100% SL no bucket). NÃO COMPARAR com P&L Médio/Trade acima.",
                  },
                  {
                    label: "AI Critic",
                    value: calSummary?.latest_ai_review?.status ?? "—",
                    sub: calSummary?.latest_ai_review?.model_name?.replace("claude-", "") ?? "sem review",
                    hint: "Último review do AI Critic (profile_ai_reviews). Fonte: shadow_trades L3+L3_LAB, janela 4h, created_at.",
                  },
                ].map((card, i) => (
                  <div key={i} className="card p-3 space-y-1" title={card.hint}>
                    <div className="text-[10px] font-semibold text-[var(--text-tertiary)] uppercase tracking-wider">{card.label}</div>
                    <div className="text-[18px] font-bold text-[var(--text-primary)] truncate">{String(card.value)}</div>
                    <div className="text-[11px] text-[var(--text-secondary)]">{card.sub}</div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* AI Critic latest summary */}
          {calSummary?.latest_ai_review?.summary_preview && (
            <div className="card p-4 border-blue-500/20 bg-blue-500/5">
              <div className="flex items-start gap-2">
                <Brain className="w-4 h-4 text-blue-400 mt-0.5 shrink-0" />
                <div>
                  <div className="text-[11px] font-semibold text-blue-400 mb-1">
                    AI Critic · {calSummary.latest_ai_review.model_name} · {calSummary.latest_ai_review.tokens_input}↑ {calSummary.latest_ai_review.tokens_output}↓ tokens
                    {calSummary.latest_ai_review.completed_at && (
                      <span className="text-[var(--text-tertiary)] ml-2">{fmtDate(calSummary.latest_ai_review.completed_at)}</span>
                    )}
                  </div>
                  <p className="text-[12px] text-[var(--text-secondary)]">{calSummary.latest_ai_review.summary_preview}</p>
                </div>
              </div>
            </div>
          )}

          {/* Sub-tabs */}
          <div className="flex gap-1 border-b border-[var(--border-default)]">
            {(["adjustments", "indicators", "timeline", "ai"] as const).map(st => (
              <button
                key={st}
                onClick={() => setCalSubTab(st)}
                className={`px-3 py-2 text-[12px] font-medium border-b-2 transition-colors capitalize ${
                  calSubTab === st
                    ? "border-[var(--accent-primary)] text-[var(--accent-primary)]"
                    : "border-transparent text-[var(--text-secondary)] hover:text-[var(--text-primary)]"
                }`}
              >
                {st === "adjustments" ? `Ajustes (${calTotal})` : st === "indicators" ? `Indicadores (${calIndicators.length})` : st === "timeline" ? `Timeline (${calTimeline.length})` : `AI Reviews (${calAiExplanations.length})`}
              </button>
            ))}
            {/* Export buttons */}
            <div className="ml-auto flex gap-1 pb-1">
              {(["csv", "json"] as const).map(fmt => (
                <button
                  key={fmt}
                  className="btn btn-secondary text-[10px]"
                  onClick={async () => {
                    try {
                      const token = typeof window !== "undefined" ? localStorage.getItem("token") : null;
                      const res = await fetch(`/api/profile-intelligence/calibration-evolution/export?fmt=${fmt}`, {
                        headers: token ? { Authorization: `Bearer ${token}` } : {},
                      });
                      if (!res.ok) { showToast(`Erro ao exportar (${res.status})`, false); return; }
                      const blob = await res.blob();
                      const url = URL.createObjectURL(blob);
                      const a = document.createElement("a");
                      a.href = url; a.download = `calibration_adjustments.${fmt}`; a.click();
                      URL.revokeObjectURL(url);
                    } catch { showToast("Erro ao exportar", false); }
                  }}
                >
                  {fmt.toUpperCase()}
                </button>
              ))}
            </div>
          </div>

          {/* ── Sub-tab: Adjustments ── */}
          {calSubTab === "adjustments" && (
            <div className="card">
              {/* Filters */}
              <div className="p-3 border-b border-[var(--border-default)] flex gap-2 flex-wrap items-center">
                <span className="text-[11px] text-[var(--text-tertiary)]">Filtros:</span>
                <input
                  type="number"
                  min={0} max={1} step={0.1}
                  placeholder="Min confiança (0–1)"
                  value={calFilterMinConf}
                  onChange={e => setCalFilterMinConf(e.target.value)}
                  className="input text-[11px] w-44 h-7 px-2"
                />
                <button
                  className="btn btn-secondary text-[10px] h-7"
                  onClick={async () => {
                    setLoadingTab(true);
                    try {
                      const qs = calFilterMinConf ? `&min_confidence=${calFilterMinConf}` : "";
                      const d = await apiGet(`/profile-intelligence/calibration-evolution/adjustments?limit=100${qs}`);
                      setCalAdjustments(d?.items || []);
                      setCalTotal(d?.total || 0);
                    } finally {
                      setLoadingTab(false);
                    }
                  }}
                >
                  Filtrar
                </button>
                <button
                  className="btn btn-secondary text-[10px] h-7"
                  onClick={() => { setCalFilterMinConf(""); loadTab("Calibration Evolution"); }}
                >
                  Limpar
                </button>
              </div>

              {loadingTab ? <TableSkeleton /> : calAdjustments.length === 0 ? (
                <div className="p-8 text-center text-[12px] text-[var(--text-tertiary)]">
                  Nenhuma sugestão de calibração encontrada. Execute o PI Engine para gerar sugestões.
                </div>
              ) : (
                <div className="overflow-x-auto">
                  <table className="w-full text-[12px]">
                    <thead>
                      <tr className="border-b border-[var(--border-subtle)]">
                        {["Profile", "Seção", "Campo", "Tipo", "Confiança", "Status", "Trades Base", "Win Rate Base", "P&L Base", "Criado", "Ações"].map(h => (
                          <th key={h} className="px-3 py-2 text-left text-[10px] font-semibold text-[var(--text-tertiary)] uppercase tracking-wider whitespace-nowrap">{h}</th>
                        ))}
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-[var(--border-subtle)]">
                      {calAdjustments.map((item: any) => (
                        <tr key={item.suggestion_id} className="hover:bg-[var(--bg-elevated)] transition-colors">
                          <td className="px-3 py-2 text-[var(--text-primary)] max-w-[120px] truncate" title={item.profile_name}>{item.profile_name || "—"}</td>
                          <td className="px-3 py-2 text-[var(--text-secondary)]">{item.target_section || "—"}</td>
                          <td className="px-3 py-2 font-mono text-[10px] text-[var(--text-secondary)] max-w-[100px] truncate" title={item.target_field || ""}>{item.target_field || "—"}</td>
                          <td className="px-3 py-2">
                            <span className="badge range text-[10px]">{item.suggestion_type}</span>
                          </td>
                          <td className="px-3 py-2">
                            <span className={`font-mono ${item.confidence >= 0.8 ? "text-green-400" : item.confidence >= 0.6 ? "text-yellow-400" : "text-[var(--text-tertiary)]"}`}>
                              {item.confidence != null ? item.confidence.toFixed(2) : "—"}
                            </span>
                          </td>
                          <td className="px-3 py-2">{statusBadge(item.suggestion_status)}</td>
                          <td className="px-3 py-2 text-[var(--text-secondary)]">{item.baseline?.total_trades ?? "—"}</td>
                          <td className={`px-3 py-2 ${winRateColor(item.baseline?.win_rate)}`}>
                            {item.baseline?.win_rate != null ? `${(item.baseline.win_rate * 100).toFixed(1)}%` : "—"}
                          </td>
                          <td className={`px-3 py-2 ${pnlColor(item.baseline?.avg_pnl_pct)}`}>
                            {item.baseline?.avg_pnl_pct != null ? `${(item.baseline.avg_pnl_pct * 100).toFixed(2)}%` : "—"}
                          </td>
                          <td className="px-3 py-2 whitespace-nowrap text-[var(--text-secondary)]">{fmtDate(item.suggestion_created_at)}</td>
                          <td className="px-3 py-2">
                            <button
                              className="btn btn-secondary text-[10px]"
                              onClick={async () => {
                                setSelectedCalAdjustment(item);
                                setCalDetail(null);
                                setCalDetailLoading(true);
                                try {
                                  const d = await apiGet(`/profile-intelligence/calibration-evolution/adjustments/${item.suggestion_id}`);
                                  setCalDetail(d);
                                } finally {
                                  setCalDetailLoading(false);
                                }
                              }}
                            >
                              Detalhe
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          )}

          {/* ── Sub-tab: Indicators ── */}
          {calSubTab === "indicators" && (
            <div className="card">
              {loadingTab ? <TableSkeleton /> : calIndicators.length === 0 ? (
                <div className="p-8 text-center text-[12px] text-[var(--text-tertiary)]">Nenhum dado de indicador disponível.</div>
              ) : (
                <div className="overflow-x-auto">
                  <table className="w-full text-[12px]">
                    <thead>
                      <tr className="border-b border-[var(--border-subtle)]">
                        {["Profile", "Indicador", "Bucket", "Amostras", "Win Rate", "P&L médio", "Lift", "EV%", "FPR"].map(h => (
                          <th key={h} className="px-3 py-2 text-left text-[10px] font-semibold text-[var(--text-tertiary)] uppercase tracking-wider whitespace-nowrap">{h}</th>
                        ))}
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-[var(--border-subtle)]">
                      {calIndicators.map((ind: any, i: number) => (
                        <tr key={`${ind.profile_id}-${ind.indicator_name}-${i}`} className="hover:bg-[var(--bg-elevated)] transition-colors">
                          <td className="px-3 py-2 text-[var(--text-primary)] max-w-[120px] truncate">{ind.profile_name || "—"}</td>
                          <td className="px-3 py-2 font-mono text-[11px]">{ind.indicator_name}</td>
                          <td className="px-3 py-2 text-[var(--text-secondary)]">{ind.bucket || "—"}</td>
                          <td className="px-3 py-2">{ind.sample_count}</td>
                          <td className={`px-3 py-2 ${winRateColor(ind.win_rate)}`}>{ind.win_rate != null ? `${(ind.win_rate * 100).toFixed(1)}%` : "—"}</td>
                          <td className={`px-3 py-2 ${pnlColor(ind.avg_pnl_pct)}`}>{ind.avg_pnl_pct != null ? `${(ind.avg_pnl_pct * 100).toFixed(2)}%` : "—"}</td>
                          <td className={`px-3 py-2 ${(ind.lift_vs_profile ?? 0) > 0 ? "text-green-400" : "text-red-400"}`}>{ind.lift_vs_profile != null ? `${ind.lift_vs_profile > 0 ? "+" : ""}${(ind.lift_vs_profile * 100).toFixed(1)}%` : "—"}</td>
                          <td className={`px-3 py-2 ${pnlColor(ind.ev_pct)}`}>{ind.ev_pct != null ? `${(ind.ev_pct * 100).toFixed(2)}%` : "—"}</td>
                          <td className="px-3 py-2 text-[var(--text-secondary)]">{ind.fpr != null ? `${(ind.fpr * 100).toFixed(1)}%` : "—"}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          )}

          {/* ── Sub-tab: Timeline ── */}
          {calSubTab === "timeline" && (
            <div className="card divide-y divide-[var(--border-subtle)] max-h-[600px] overflow-auto">
              {loadingTab ? <TableSkeleton /> : calTimeline.length === 0 ? (
                <div className="p-8 text-center text-[12px] text-[var(--text-tertiary)]">Nenhum evento de calibração nos últimos 7 dias.</div>
              ) : (
                calTimeline.map((ev: any) => {
                  const changes: any[] = Array.isArray(ev.changes) ? ev.changes : [];
                  const hasMeta = ev.shadow_validation_status || ev.mutation_applied != null;
                  return (
                    <div key={ev.id} className="p-3 hover:bg-[var(--bg-elevated)] transition-colors">
                      <div className="flex items-center justify-between gap-2">
                        <div className="flex items-center gap-2">
                          <span className={`w-1.5 h-1.5 rounded-full shrink-0 ${ev.severity === "error" ? "bg-red-400" : ev.severity === "warning" ? "bg-yellow-400" : "bg-green-400"}`} />
                          <span className="font-mono text-[11px] text-[var(--text-primary)]">{ev.event_type}</span>
                          {ev.phase && <span className="badge range text-[9px]">{ev.phase}</span>}
                          {ev.mutation_applied === true && <span className="badge text-[9px] bg-green-500/10 text-green-400 border-green-500/20">aplicado</span>}
                          {ev.mutation_applied === false && <span className="badge text-[9px] bg-yellow-500/10 text-yellow-400 border-yellow-500/20">shadow-only</span>}
                        </div>
                        <span className="text-[10px] text-[var(--text-tertiary)] shrink-0">{fmtDate(ev.created_at)}</span>
                      </div>
                      <div className="text-[11px] text-[var(--text-secondary)] mt-1 ml-3.5">{ev.message}</div>
                      {ev.profile_name && (
                        <div className="text-[10px] text-[var(--text-tertiary)] ml-3.5 mt-0.5">{ev.profile_name}</div>
                      )}
                      {/* Granular diff changes */}
                      {changes.length > 0 && (
                        <div className="ml-3.5 mt-2 space-y-1">
                          {changes.map((c: any, i: number) => (
                            <div key={i} className="flex items-center gap-1 font-mono text-[10px] bg-[var(--bg-input)] rounded px-2 py-1">
                              <span className="text-[var(--text-tertiary)]">{c.section}.{c.field}:</span>
                              <span className="text-red-400 line-through">{String(c.old_value ?? "—")}</span>
                              <span className="text-[var(--text-tertiary)]">→</span>
                              <span className="text-green-400">{String(c.new_value ?? "—")}</span>
                              {c.reason && <span className="text-[var(--text-tertiary)] ml-1 font-sans">· {String(c.reason).replace(/_/g, " ")}</span>}
                            </div>
                          ))}
                        </div>
                      )}
                      {/* Shadow validation state */}
                      {hasMeta && (
                        <div className="ml-3.5 mt-1.5 flex items-center gap-2 text-[10px] text-[var(--text-tertiary)]">
                          {ev.shadow_validation_status && <span>Shadow: <span className="text-[var(--text-secondary)]">{ev.shadow_validation_status}</span></span>}
                        </div>
                      )}
                    </div>
                  );
                })
              )}
            </div>
          )}

          {/* ── Sub-tab: AI Reviews ── */}
          {calSubTab === "ai" && (
            <div className="space-y-3">
              {loadingTab ? <TableSkeleton /> : calAiExplanations.length === 0 ? (
                <div className="card p-8 text-center text-[12px] text-[var(--text-tertiary)]">Nenhum AI Review real disponível.</div>
              ) : (
                calAiExplanations.map((rev: any) => (
                  <div key={rev.id} className="card p-4 space-y-3">
                    <div className="flex items-start justify-between gap-2 flex-wrap">
                      <div>
                        <div className="flex items-center gap-2">
                          <Brain className="w-4 h-4 text-[var(--accent-primary)]" />
                          <span className="text-[13px] font-semibold text-[var(--text-primary)]">{rev.model_name}</span>
                          <span className="badge bullish text-[10px]">{rev.status}</span>
                        </div>
                        <div className="text-[11px] text-[var(--text-tertiary)] mt-0.5">
                          {rev.tokens_input}↑ / {rev.tokens_output}↓ tokens · {fmtDate(rev.completed_at)}
                        </div>
                      </div>
                    </div>
                    {rev.summary && (
                      <div className="text-[12px] text-[var(--text-secondary)] bg-[var(--bg-elevated)] rounded p-3">
                        {rev.summary}
                      </div>
                    )}
                    {rev.findings && Object.keys(rev.findings).length > 0 && (
                      <div>
                        <div className="text-[10px] uppercase font-semibold text-[var(--text-tertiary)] mb-1">Findings</div>
                        <pre className="text-[10px] text-[var(--text-secondary)] bg-[var(--bg-input)] rounded p-2 overflow-auto max-h-[150px]">
                          {JSON.stringify(rev.findings, null, 2)}
                        </pre>
                      </div>
                    )}
                    {rev.recommendations?.length > 0 && (
                      <div>
                        <div className="text-[10px] uppercase font-semibold text-[var(--text-tertiary)] mb-1">Recomendações</div>
                        <ul className="space-y-1">
                          {rev.recommendations.map((rec: string, i: number) => (
                            <li key={i} className="text-[11px] text-[var(--text-secondary)] flex gap-1.5">
                              <span className="text-[var(--accent-primary)] shrink-0">→</span>
                              {rec}
                            </li>
                          ))}
                        </ul>
                      </div>
                    )}
                    {rev.risk_flags?.length > 0 && (
                      <div className="flex gap-2 flex-wrap">
                        {rev.risk_flags.map((flag: string, i: number) => (
                          <span key={i} className="badge bearish text-[10px]">{flag}</span>
                        ))}
                      </div>
                    )}
                  </div>
                ))
              )}
            </div>
          )}
        </div>
      )}

      {/* ── Calibration Adjustment Drawer ───────────────────────────────────── */}
      {selectedCalAdjustment && (
        <Drawer
          title={`Ajuste · ${selectedCalAdjustment.profile_name || selectedCalAdjustment.suggestion_id?.slice(0, 8)}`}
          onClose={() => { setSelectedCalAdjustment(null); setCalDetail(null); }}
        >
          {calDetailLoading ? (
            <div className="text-center py-6 text-[var(--text-secondary)] text-[12px]">
              <RefreshCw className="w-5 h-5 animate-spin mx-auto mb-2 text-[var(--accent-primary)]" />
              Carregando detalhe...
            </div>
          ) : calDetail ? (
            <div className="space-y-4 text-[12px]">
              <div className="grid grid-cols-2 gap-2">
                {[
                  ["Profile", calDetail.profile_name],
                  ["Tipo", calDetail.suggestion_type],
                  ["Seção", calDetail.target_section],
                  ["Campo", calDetail.target_field || "—"],
                  ["Confiança", calDetail.confidence != null ? calDetail.confidence.toFixed(2) : "—"],
                  ["Status", calDetail.suggestion_status],
                  ["Mutação aplicada", calDetail.mutation_applied ? "Sim" : "Não"],
                  ["Criado por", calDetail.created_by],
                ].map(([label, value]) => (
                  <div key={String(label)} className="bg-[var(--bg-elevated)] rounded p-2">
                    <div className="text-[10px] text-[var(--text-tertiary)]">{label}</div>
                    <div className="text-[var(--text-primary)] truncate" title={String(value)}>{String(value)}</div>
                  </div>
                ))}
              </div>

              <div>
                <div className="text-[10px] uppercase font-semibold text-[var(--text-tertiary)] mb-1">Motivo</div>
                <p className="text-[var(--text-secondary)]">{calDetail.reason}</p>
              </div>

              {calDetail.evidence && (
                <div>
                  <div className="text-[10px] uppercase font-semibold text-[var(--text-tertiary)] mb-1">Evidência</div>
                  <pre className="text-[10px] text-[var(--text-secondary)] bg-[var(--bg-input)] rounded p-2 overflow-auto max-h-[200px]">
                    {JSON.stringify(calDetail.evidence, null, 2)}
                  </pre>
                </div>
              )}

              {(calDetail.current_value != null || calDetail.suggested_value != null) && (
                <div className="grid grid-cols-2 gap-2">
                  <div className="bg-[var(--bg-elevated)] rounded p-2">
                    <div className="text-[10px] text-[var(--text-tertiary)] mb-1">Valor atual</div>
                    <pre className="text-[10px] text-[var(--text-secondary)] overflow-auto max-h-[120px]">
                      {JSON.stringify(calDetail.current_value, null, 2)}
                    </pre>
                  </div>
                  <div className="bg-[var(--bg-elevated)] rounded p-2 border border-[var(--accent-primary)]/20">
                    <div className="text-[10px] text-[var(--accent-primary)] mb-1">Valor sugerido</div>
                    <pre className="text-[10px] text-[var(--text-secondary)] overflow-auto max-h-[120px]">
                      {JSON.stringify(calDetail.suggested_value, null, 2)}
                    </pre>
                  </div>
                </div>
              )}

              {calDetail.version && (
                <div>
                  <div className="text-[10px] uppercase font-semibold text-[var(--text-tertiary)] mb-1">Versão</div>
                  <div className="grid grid-cols-2 gap-2">
                    {[
                      ["Status versão", calDetail.version.version_status],
                      ["Shadow validation", calDetail.version.shadow_validation_status],
                      ["Rollback", calDetail.version.rollback_available ? "Disponível" : "Ausente"],
                      ["Aplicado em", fmtDate(calDetail.version.applied_at)],
                    ].map(([l, v]) => (
                      <div key={String(l)} className="bg-[var(--bg-elevated)] rounded p-2">
                        <div className="text-[10px] text-[var(--text-tertiary)]">{l}</div>
                        <div className="text-[var(--text-primary)]">{String(v)}</div>
                      </div>
                    ))}
                  </div>
                  {calDetail.version.shadow_validation_status === "VALIDATED" && !calDetail.version.mutation_applied && (
                    <div className="mt-3 rounded border border-amber-500/25 bg-amber-500/5 p-3">
                      <p className="text-[11px] font-medium text-amber-300">Aplicação direta desativada</p>
                      <p className="mt-1 text-[10px] text-[var(--text-tertiary)]">
                        Reemita como Recommendation V2 para gerar um Challenger Shadow versionado sem alterar o campeão.
                      </p>
                    </div>
                  )}
                  {calDetail.version.diff && (
                    <div className="mt-2">
                      <div className="text-[10px] uppercase font-semibold text-[var(--text-tertiary)] mb-1">Diff</div>
                      <pre className="text-[10px] text-[var(--text-secondary)] bg-[var(--bg-input)] rounded p-2 overflow-auto max-h-[150px]">
                        {JSON.stringify(calDetail.version.diff, null, 2)}
                      </pre>
                    </div>
                  )}
                </div>
              )}

              {!calDetail.version && (
                <div className="card p-3 border-yellow-500/20 bg-yellow-500/5 text-[11px] text-yellow-400">
                  Nenhuma versão registrada — sugestão aguarda aprovação para aplicação.
                </div>
              )}

              {calDetail.indicator_performance?.length > 0 && (
                <div>
                  <div className="text-[10px] uppercase font-semibold text-[var(--text-tertiary)] mb-1">Performance de Indicadores (top 10)</div>
                  <div className="space-y-1">
                    {calDetail.indicator_performance.slice(0, 10).map((ind: any, i: number) => (
                      <div key={i} className="flex items-center gap-2 text-[11px] text-[var(--text-secondary)]">
                        <span className="font-mono text-[var(--text-primary)] w-36 truncate">{ind.indicator_name}</span>
                        <span className={winRateColor(ind.win_rate)}>{ind.win_rate != null ? `WR ${(ind.win_rate * 100).toFixed(0)}%` : "—"}</span>
                        <span className={pnlColor(ind.avg_pnl_pct)}>{ind.avg_pnl_pct != null ? `P&L ${(ind.avg_pnl_pct * 100).toFixed(2)}%` : "—"}</span>
                        {ind.lift_vs_profile != null && (
                          <span className={`text-[10px] ${ind.lift_vs_profile > 0 ? "text-green-400" : "text-red-400"}`}>
                            lift {ind.lift_vs_profile > 0 ? "+" : ""}{(ind.lift_vs_profile * 100).toFixed(1)}%
                          </span>
                        )}
                        <span className="text-[10px] text-[var(--text-tertiary)]">{ind.sample_count} amostras</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          ) : (
            <div className="text-center py-6 text-[12px] text-[var(--text-tertiary)]">Erro ao carregar detalhe.</div>
          )}
        </Drawer>
      )}

      {activeTab === "Auto-Pilot" && (
        <div className="space-y-5">
          <div className="card p-4">
            <div className="flex items-start justify-between gap-4 flex-wrap">
              <div>
                <div className="flex items-center gap-2">
                  <Power className={`w-5 h-5 ${autopilot?.enabled ? "text-green-400" : "text-[var(--text-tertiary)]"}`} />
                  <h2 className="text-[15px] font-semibold text-[var(--text-primary)]">
                    Auto-Pilot global {autopilot?.enabled ? "ligado" : "desligado"}
                  </h2>
                </div>
                <p className="text-[12px] text-[var(--text-secondary)] mt-1 max-w-3xl">
                  Calibra clones versionados, testa candidatos em Shadow e prepara recomendações.
                  Promoção live automática está bloqueada; aprovação e ativação são ações humanas separadas.
                </p>
                <p className="text-[11px] text-[var(--text-tertiary)] mt-2">
                  Último ciclo: {fmtDate(autopilot?.last_cycle_at)}
                  {autopilot?.latest_cycle?.status ? ` · ${autopilot.latest_cycle.status}` : ""}
                </p>
              </div>
              <div className="flex gap-2">
                <button
                  className="btn btn-secondary text-[12px] flex items-center gap-1.5"
                  onClick={handleRunAutopilot}
                  disabled={!autopilot?.enabled || runningAutopilot}
                  title={!autopilot?.enabled ? "Ligue o Auto-Pilot para executar um ciclo" : "Executar ciclo agora"}
                >
                  <RotateCcw className={`w-3.5 h-3.5 ${runningAutopilot ? "animate-spin" : ""}`} />
                  Executar ciclo
                </button>
                <button
                  className={`btn text-[12px] ${autopilot?.enabled ? "btn-secondary" : "btn-primary"}`}
                  onClick={handleToggleAutopilot}
                  disabled={togglingAutopilot}
                >
                  {autopilot?.enabled ? "Desligar" : "Ligar"}
                </button>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
            {[
              ["Coletando", autopilot?.candidate_counts?.SHADOW_COLLECTING ?? 0],
              ["Prontos", autopilot?.candidate_counts?.SHADOW_READY ?? 0],
              ["Aguardando aprovação", autopilot?.candidate_counts?.PENDING_HUMAN_APPROVAL ?? 0],
              ["Aprovados", autopilot?.candidate_counts?.APPROVED_FOR_LIVE ?? 0],
              ["Live", autopilot?.candidate_counts?.LIVE_ACTIVATED ?? 0],
              ["Rollbacks", autopilot?.candidate_counts?.ROLLED_BACK ?? 0],
            ].map(([label, value]) => (
              <div className="card p-3" key={String(label)}>
                <div className="text-[10px] uppercase tracking-wider text-[var(--text-tertiary)]">{label}</div>
                <div className="text-xl font-bold text-[var(--text-primary)] mt-1">{value}</div>
              </div>
            ))}
          </div>

          <div className="card">
            <div className="p-4 border-b border-[var(--border-default)]">
              <h2 className="text-[14px] font-semibold text-[var(--text-primary)]">Candidatos e versões</h2>
              <p className="text-[11px] text-[var(--text-tertiary)] mt-0.5">
                Win Rate inclui a contagem de trades; P&amp;L usa representação decimal canônica.
              </p>
            </div>
            {loadingTab ? <TableSkeleton /> : autopilotCandidates.length === 0 ? (
              <div className="p-8 text-center text-[12px] text-[var(--text-tertiary)]">Nenhum candidato criado.</div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-[12px]">
                  <thead>
                    <tr className="border-b border-[var(--border-subtle)]">
                      {["Profile", "Versão", "Estado", "Trades", "Win Rate", "P&L médio", "Rollback", "Atualizado", "Ações"].map(h => (
                        <th key={h} className="px-4 py-2 text-left text-[10px] uppercase tracking-wider text-[var(--text-tertiary)] whitespace-nowrap">{h}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[var(--border-subtle)]">
                    {autopilotCandidates.map(candidate => (
                      <tr key={candidate.id}>
                        <td className="px-4 py-2.5 text-[var(--text-primary)]">{candidate.profile_name}</td>
                        <td className="px-4 py-2.5 font-mono">v{candidate.version_number}</td>
                        <td className="px-4 py-2.5">{statusBadge(candidate.state)}</td>
                        <td className="px-4 py-2.5">{candidate.observed_trades}</td>
                        <td className={`px-4 py-2.5 ${winRateColor(candidate.observed_win_rate)}`}>
                          {candidate.observed_win_rate == null ? "—" : `${(candidate.observed_win_rate * 100).toFixed(1)}%`}
                        </td>
                        <td className={`px-4 py-2.5 ${pnlColor(candidate.observed_avg_pnl_pct)}`}>
                          {fmtPct(candidate.observed_avg_pnl_pct, 2)}
                        </td>
                        <td className="px-4 py-2.5">
                          <span className={candidate.rollback_available ? "text-green-400" : "text-red-400"}>
                            {candidate.rollback_available ? "Disponível" : "Ausente"}
                          </span>
                        </td>
                        <td className="px-4 py-2.5 whitespace-nowrap">{fmtDate(candidate.updated_at)}</td>
                        <td className="px-4 py-2.5">
                          <div className="flex gap-1.5 flex-wrap min-w-[250px]">
                            <button className="btn btn-secondary text-[10px]" onClick={() => setSelectedAutopilotCandidate(candidate)}>
                              Ver detalhes
                            </button>
                            {candidate.state === "PENDING_HUMAN_APPROVAL" && (
                              <>
                                <button
                                  className="btn btn-primary text-[10px]"
                                  disabled={candidateActionId === candidate.id || !candidate.rollback_available}
                                  onClick={() => handleApproveCandidate(candidate)}
                                >
                                  Aprovar
                                </button>
                                <button
                                  className="btn btn-secondary text-[10px] text-red-400"
                                  disabled={candidateActionId === candidate.id}
                                  onClick={() => handleRejectCandidate(candidate)}
                                >
                                  Rejeitar
                                </button>
                              </>
                            )}
                            {candidate.state === "APPROVED_FOR_LIVE" && (
                              <button
                                className="btn btn-primary text-[10px]"
                                disabled={candidateActionId === candidate.id}
                                onClick={() => handleActivateCandidate(candidate)}
                              >
                                Ativar live
                              </button>
                            )}
                            {candidate.state === "LIVE_ACTIVATED" && (
                              <button
                                className="btn btn-secondary text-[10px]"
                                disabled={candidateActionId === candidate.id}
                                onClick={() => handleRollbackCandidate(candidate)}
                              >
                                Rollback
                              </button>
                            )}
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          <div className="card">
            <div className="p-4 border-b border-[var(--border-default)]">
              <h2 className="text-[14px] font-semibold text-[var(--text-primary)]">Relatório Executivo</h2>
            </div>
            <pre className="p-4 text-[11px] text-[var(--text-secondary)] overflow-auto max-h-[420px]">
              {autopilot?.latest_report
                ? JSON.stringify(autopilot.latest_report, null, 2)
                : "Nenhum relatório diário disponível."}
            </pre>
          </div>

          <div className="card">
            <div className="p-4 border-b border-[var(--border-default)]">
              <h2 className="text-[14px] font-semibold text-[var(--text-primary)]">Auditoria imutável</h2>
            </div>
            <div className="divide-y divide-[var(--border-subtle)] max-h-[420px] overflow-auto">
              {autopilotAudit.map(event => (
                <div key={event.id} className="p-3">
                  <div className="flex items-center justify-between gap-3">
                    <span className="font-mono text-[11px] text-[var(--text-primary)]">{event.event_type}</span>
                    <span className="text-[10px] text-[var(--text-tertiary)]">{fmtDate(event.created_at)}</span>
                  </div>
                  <div className="text-[11px] text-[var(--text-secondary)] mt-1">
                    {event.decision || "—"} · {event.reason || "Sem motivo informado"}
                  </div>
                </div>
              ))}
              {!autopilotAudit.length && <div className="p-6 text-center text-[12px] text-[var(--text-tertiary)]">Sem eventos.</div>}
            </div>
          </div>
        </div>
      )}

      {/* ── TAB: Profiles ──────────────────────────────────────────────────────── */}
      {selectedAutopilotCandidate && (
        <Modal
          title={`Candidato · ${selectedAutopilotCandidate.profile_name}`}
          onClose={() => setSelectedAutopilotCandidate(null)}
        >
          <div className="space-y-3 text-[12px]">
            <div className="grid grid-cols-2 gap-2">
              {[
                ["Estado", selectedAutopilotCandidate.state],
                ["Trades", selectedAutopilotCandidate.observed_trades],
                ["Win Rate", selectedAutopilotCandidate.observed_win_rate == null ? "—" : `${(selectedAutopilotCandidate.observed_win_rate * 100).toFixed(1)}%`],
                ["P&L médio", fmtPct(selectedAutopilotCandidate.observed_avg_pnl_pct, 2)],
                ["Aprovação", selectedAutopilotCandidate.approval_status],
                ["Rollback", selectedAutopilotCandidate.rollback_available ? "Disponível" : "Ausente"],
              ].map(([label, value]) => (
                <div key={String(label)} className="bg-[var(--bg-elevated)] rounded p-2">
                  <div className="text-[10px] text-[var(--text-tertiary)]">{label}</div>
                  <div className="text-[var(--text-primary)]">{String(value)}</div>
                </div>
              ))}
            </div>
            <div>
              <div className="text-[10px] uppercase text-[var(--text-tertiary)]">Motivo</div>
              <div className="text-[var(--text-secondary)]">{selectedAutopilotCandidate.reason || "—"}</div>
            </div>
            <div>
              <div className="text-[10px] uppercase text-[var(--text-tertiary)]">Evidências e riscos</div>
              <pre className="mt-1 p-3 rounded bg-[var(--bg-elevated)] overflow-auto max-h-[320px] text-[10px]">
                {JSON.stringify(selectedAutopilotCandidate.evidence || {}, null, 2)}
              </pre>
            </div>
          </div>
        </Modal>
      )}

      {activeTab === "Profiles" && (
        <div className="card">
          <div className="p-4 border-b border-[var(--border-default)]">
            <h2 className="text-[14px] font-semibold text-[var(--text-primary)]">Ranking de Profiles</h2>
            <p className="text-[11px] text-[var(--text-tertiary)] mt-0.5">Performance baseada em shadow trades fechados. Clique nas colunas para ordenar.</p>
          </div>
          {loadingTab ? <TableSkeleton /> : profiles.length === 0 ? (
            <EmptyState message="Nenhum profile com dados suficientes. Execute uma análise primeiro." onRun={() => setShowRunModal(true)} />
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-[12px]">
                <thead>
                  <tr className="border-b border-[var(--border-subtle)]">
                    {[
                      ["profile_name", "Profile"],
                      ["closed_trades", "Fechados"],
                      ["open_trades", "Abertos"],
                      ["wins", "Wins"],
                      ["losses", "Losses"],
                      ["win_rate", "Win Rate"],
                      ["avg_pnl_pct", "Avg P&L"],
                      ["tp_30m_rate", "TP ≤30m"],
                      ["avg_mae_pct", "Avg MAE"],
                      ["confidence_level", "Confidence"],
                      ["", "Ações"],
                    ].map(([col, label]) => (
                      <th
                        key={col}
                        className={`px-4 py-2 text-left text-[10px] font-semibold text-[var(--text-tertiary)] uppercase tracking-wider whitespace-nowrap ${col ? "cursor-pointer hover:text-[var(--text-primary)]" : ""}`}
                        onClick={() => col && toggleProfileSort(col)}
                      >
                        {label}
                        {profileSort.col === col && (
                          <span className="ml-1">{profileSort.asc ? "↑" : "↓"}</span>
                        )}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-[var(--border-subtle)]">
                  {profileGroups.map(group => {
                    const isDuplicate = group.length > 1;
                    const agg = isDuplicate ? aggregateGroup(group) : { ...group[0], _count: 1 };
                    return (
                      <tr
                        key={agg.profile_id}
                        className={`hover:bg-[var(--bg-elevated)] transition-colors ${isDuplicate ? "bg-yellow-500/5" : ""}`}
                      >
                        <td className="px-4 py-2.5 font-medium text-[var(--text-primary)] whitespace-nowrap">
                          <div className="flex items-center gap-2">
                            <span>{agg.profile_name}</span>
                            {isDuplicate && (
                              <span
                                className="badge text-[9px] px-1.5 py-0.5 flex items-center gap-1 cursor-pointer hover:opacity-80"
                                style={{ background: "rgba(234,179,8,0.15)", color: "#eab308", border: "1px solid rgba(234,179,8,0.3)" }}
                                onClick={() => setSelectedDuplicateGroup(group)}
                                title="Profiles com nome duplicado"
                              >
                                <Users className="w-2.5 h-2.5" />
                                {group.length} IDs
                              </span>
                            )}
                          </div>
                        </td>
                        <td className="px-4 py-2.5 text-[var(--text-secondary)]">{agg.closed_trades ?? "—"}</td>
                        <td className="px-4 py-2.5 text-[var(--text-secondary)]">{agg.open_trades ?? "—"}</td>
                        <td className="px-4 py-2.5 text-green-400">{agg.wins ?? "—"}</td>
                        <td className="px-4 py-2.5 text-red-400">{agg.losses ?? "—"}</td>
                        <td className={`px-4 py-2.5 font-semibold ${winRateColor(agg.win_rate)}`}>{fmtPct(agg.win_rate)}</td>
                        <td className={`px-4 py-2.5 font-medium ${pnlColor(agg.avg_pnl_pct)}`}>{fmtPctRaw(agg.avg_pnl_pct, 2)}</td>
                        <td className="px-4 py-2.5 text-[var(--text-primary)]">{fmtPct(agg.tp_30m_rate)}</td>
                        <td className={`px-4 py-2.5 ${pnlColor(agg.avg_mae_pct)}`}>{fmtPctRaw(agg.avg_mae_pct, 2)}</td>
                        <td className="px-4 py-2.5">{confidenceBadge(agg.confidence_level)}</td>
                        <td className="px-4 py-2.5">
                          <div className="flex items-center gap-1.5">
                            {isDuplicate ? (
                              <button
                                className="btn btn-secondary text-[10px] px-2 py-1 flex items-center gap-1 whitespace-nowrap"
                                onClick={() => setSelectedDuplicateGroup(group)}
                              >
                                <Users className="w-3 h-3" />
                                Ver {group.length} IDs
                              </button>
                            ) : (
                              <a href="/profiles" className="btn btn-secondary text-[10px] px-2 py-1 flex items-center gap-1 whitespace-nowrap w-fit">
                                <ExternalLink className="w-3 h-3" />
                                Profiles
                              </a>
                            )}
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {/* ── TAB: Indicators ────────────────────────────────────────────────────── */}
      {activeTab === "Indicators" && (
        <div className="space-y-4">
          <div className="flex gap-2">
            {(["winners", "losers"] as const).map(sub => (
              <button
                key={sub}
                onClick={() => setIndicatorSubTab(sub)}
                className={`px-4 py-2 rounded-lg text-[12px] font-medium border transition-colors ${
                  indicatorSubTab === sub
                    ? "bg-blue-600 border-blue-500 text-white"
                    : "bg-[var(--bg-elevated)] border-[var(--border-default)] text-[var(--text-secondary)] hover:border-[var(--border-strong)]"
                }`}
              >
                {sub === "winners" ? <span className="flex items-center gap-1.5"><TrendingUp className="w-3.5 h-3.5" /> Top Winners</span> : <span className="flex items-center gap-1.5"><TrendingDown className="w-3.5 h-3.5" /> Top Losers</span>}
              </button>
            ))}
          </div>

          <div className="card">
            <div className="p-4 border-b border-[var(--border-default)]">
              <h2 className="text-[14px] font-semibold text-[var(--text-primary)]">
                {indicatorSubTab === "winners" ? "Indicadores com Melhor Performance" : "Indicadores com Pior Performance"}
              </h2>
              <p className="text-[11px] text-[var(--text-tertiary)] mt-0.5">
                {indicatorSubTab === "winners" ? "Candidatos a Signal ou Scoring Rule" : "Candidatos a Score Penalty (−10 pts) — não viram Block Rule diretamente"}
              </p>
            </div>
            {loadingTab ? <TableSkeleton /> : (
              <div className="overflow-x-auto">
                <table className="w-full text-[12px]">
                  <thead>
                    <tr className="border-b border-[var(--border-subtle)]">
                      {indicatorSubTab === "winners"
                        ? ["Indicador / Bucket", "Profiles associados", "Cases", "W/L", "Win Rate", "Lift vs Base", "Avg P&L", "TP ≤30m", "Avg MAE", "Confidence", "Role", "", "Ajuste"].map(h => (
                          <th key={h} className="px-4 py-2 text-left text-[10px] font-semibold text-[var(--text-tertiary)] uppercase tracking-wider whitespace-nowrap">{h}</th>
                        ))
                        : ["Indicador / Bucket", "Profiles associados", "Cases", "W/L", "Loss Rate", "Lift", "Avg P&L", "Confidence", "Ação Sugerida", "", "Ajuste"].map(h => (
                          <th key={h} className="px-4 py-2 text-left text-[10px] font-semibold text-[var(--text-tertiary)] uppercase tracking-wider whitespace-nowrap">{h}</th>
                        ))
                      }
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[var(--border-subtle)]">
                    {(indicatorSubTab === "winners" ? winners : losers).map(stat => (
                      <>
                        <tr
                          key={stat.id}
                          className="hover:bg-[var(--bg-elevated)] transition-colors cursor-pointer"
                          onClick={() => setExpandedIndicator(expandedIndicator === stat.id ? null : stat.id)}
                        >
                          <td className="px-4 py-2.5">
                            <div className="font-medium text-[var(--text-primary)] font-mono">{stat.indicator}</div>
                            <div className="text-[10px] text-[var(--text-tertiary)]">{stat.bucket_label}</div>
                          </td>
                          <td className="px-4 py-2.5 min-w-[190px]">
                            <div className="flex flex-wrap gap-1">
                              {(stat.associated_profiles || []).slice(0, 2).map(profile => (
                                <span
                                  key={profile.id}
                                  title={profile.id}
                                  className="inline-flex max-w-[180px] items-center gap-1 rounded border border-cyan-400/20 bg-cyan-400/5 px-1.5 py-0.5 text-[10px] text-cyan-200"
                                >
                                  <Users className="h-3 w-3 shrink-0" />
                                  <span className="truncate">{profile.name}</span>
                                </span>
                              ))}
                              {(stat.associated_profiles || []).length > 2 && (
                                <span className="text-[10px] text-[var(--text-tertiary)]">+{(stat.associated_profiles || []).length - 2}</span>
                              )}
                              {(stat.associated_profiles || []).length === 0 && (
                                <span className="text-[10px] text-yellow-400">Sem associação</span>
                              )}
                            </div>
                          </td>
                          <td className="px-4 py-2.5 text-[var(--text-secondary)]">{stat.total_cases}</td>
                          <td className="px-4 py-2.5">
                            <span className="text-green-400">{stat.wins ?? "—"}</span>
                            <span className="text-[var(--text-tertiary)]">/</span>
                            <span className="text-red-400">{stat.losses ?? "—"}</span>
                          </td>
                          {indicatorSubTab === "winners" ? (
                            <>
                              <td className={`px-4 py-2.5 font-semibold ${winRateColor(stat.win_rate)}`}>{fmtPct(stat.win_rate)}</td>
                              <td className={`px-4 py-2.5 font-medium ${(stat.lift_vs_base ?? 0) >= 1.2 ? "text-green-400" : "text-[var(--text-secondary)]"}`}>
                                {stat.lift_vs_base != null ? `${stat.lift_vs_base.toFixed(2)}x` : "—"}
                              </td>
                              <td className={`px-4 py-2.5 ${pnlColor(stat.avg_pnl_pct)}`}>{fmtPctRaw(stat.avg_pnl_pct, 2)}</td>
                              <td className="px-4 py-2.5 text-[var(--text-primary)]">{fmtPct(stat.tp_30m_rate)}</td>
                              <td className={`px-4 py-2.5 ${pnlColor(stat.avg_mae_pct)}`}>{fmtPctRaw(stat.avg_mae_pct, 2)}</td>
                              <td className="px-4 py-2.5">{confidenceBadge(stat.confidence_level)}</td>
                              <td className="px-4 py-2.5">
                                {stat.role_detected && (
                                  <span className={`badge text-[10px] ${stat.role_detected === "winning_indicator" ? "bullish" : stat.role_detected === "scoring_candidate" ? "range" : "range"}`}>
                                    {stat.role_detected.replace(/_/g, " ")}
                                  </span>
                                )}
                              </td>
                              <td className="px-4 py-2.5">
                                <button className="text-[10px] text-[var(--accent-primary)] hover:underline flex items-center gap-1">
                                  {expandedIndicator === stat.id ? <ChevronDown className="w-3 h-3" /> : <ChevronRight className="w-3 h-3" />}
                                  Evidence
                                </button>
                              </td>
                              <td className="px-4 py-2.5">
                                <button
                                  className="btn btn-secondary h-7 whitespace-nowrap px-2 text-[10px]"
                                  onClick={(event) => { event.stopPropagation(); openIndicatorAdjustment(stat); }}
                                  title={stat.can_apply_shadow_adjustment ? "Preparar challenger shadow" : "Revisar bloqueio de validação"}
                                >
                                  <SlidersHorizontal className="h-3 w-3" />
                                  Ajustar
                                </button>
                              </td>
                            </>
                          ) : (
                            <>
                              <td className="px-4 py-2.5 text-red-400 font-semibold">{fmtPct(stat.loss_rate)}</td>
                              <td className={`px-4 py-2.5 font-medium ${(stat.lift_vs_base ?? 1) < 1 ? "text-red-400" : "text-[var(--text-secondary)]"}`}>
                                {stat.lift_vs_base != null ? `${stat.lift_vs_base.toFixed(2)}x` : "—"}
                              </td>
                              <td className={`px-4 py-2.5 ${pnlColor(stat.avg_pnl_pct)}`}>{fmtPctRaw(stat.avg_pnl_pct, 2)}</td>
                              <td className="px-4 py-2.5">{confidenceBadge(stat.confidence_level)}</td>
                              <td className="px-4 py-2.5">
                                {stat.total_cases < 30
                                  ? <span className="badge range text-[10px]">Low Sample</span>
                                  : stat.role_detected === "losing_indicator"
                                  ? <span className="badge bearish text-[10px]">Score Penalty</span>
                                  : <span className="badge range text-[10px]">Monitor</span>}
                              </td>
                              <td className="px-4 py-2.5">
                                <button className="text-[10px] text-[var(--accent-primary)] hover:underline flex items-center gap-1">
                                  {expandedIndicator === stat.id ? <ChevronDown className="w-3 h-3" /> : <ChevronRight className="w-3 h-3" />}
                                  Evidence
                                </button>
                              </td>
                              <td className="px-4 py-2.5">
                                <button
                                  className="btn btn-secondary h-7 whitespace-nowrap px-2 text-[10px]"
                                  onClick={(event) => { event.stopPropagation(); openIndicatorAdjustment(stat); }}
                                  title={stat.can_apply_shadow_adjustment ? "Preparar challenger shadow" : "Revisar bloqueio de validação"}
                                >
                                  <SlidersHorizontal className="h-3 w-3" />
                                  Ajustar
                                </button>
                              </td>
                            </>
                          )}
                        </tr>
                        {expandedIndicator === stat.id && (
                          <tr key={`${stat.id}-expanded`}>
                            <td colSpan={indicatorSubTab === "winners" ? 13 : 11} className="px-6 pb-4 pt-2 bg-[var(--bg-elevated)]">
                              <div className="text-[11px] text-[var(--text-secondary)] space-y-2">
                                <div className="font-semibold text-[var(--text-primary)] mb-1">Evidence — {stat.bucket_label}</div>
                                <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
                                  {[
                                    ["Cases", stat.total_cases],
                                    ["Win Rate", fmtPct(stat.win_rate)],
                                    ["Lift vs Base", stat.lift_vs_base != null ? `${stat.lift_vs_base.toFixed(2)}x` : "—"],
                                    ["Avg P&L", fmtPctRaw(stat.avg_pnl_pct, 3)],
                                    ["TP ≤30m", fmtPct(stat.tp_30m_rate)],
                                    ["Avg MAE", fmtPctRaw(stat.avg_mae_pct, 3)],
                                    ["Avg MFE", fmtPctRaw(stat.avg_mfe_pct, 3)],
                                    ["Avg Holding", fmtSeconds(stat.avg_holding_seconds)],
                                  ].map(([k, v]) => (
                                    <div key={String(k)} className="bg-[var(--bg-surface)] rounded p-2">
                                      <div className="text-[10px] text-[var(--text-tertiary)]">{k}</div>
                                      <div className="text-[12px] font-medium text-[var(--text-primary)]">{String(v)}</div>
                                    </div>
                                  ))}
                                </div>
                                {stat.source_profiles && (
                                  <div className="text-[10px] text-[var(--text-tertiary)]">
                                    Source profiles: {Array.isArray(stat.source_profiles) ? stat.source_profiles.join(", ") : JSON.stringify(stat.source_profiles)}
                                  </div>
                                )}
                                <div className="text-[10px] text-[var(--text-tertiary)]">
                                  Source: {stat.evidence_json?.source || "—"} · Profile: {stat.evidence_json?.profile_id || "source-level"} · Dataset: {stat.evidence_json?.dataset_version || "unversioned"} · Label: {stat.evidence_json?.label_version || "unversioned"}
                                </div>
                                <div className="text-[10px] text-[var(--text-tertiary)]">
                                  Validation: {stat.validation_status || "exploratory_only"} · Actionability: {stat.actionability_status || "exploratory_only"} · Target: {stat.target_section || "—"}
                                </div>
                                {stat.total_cases < 30 && (
                                  <div className="text-[10px] text-yellow-400">⚠️ Evidência insuficiente — não usar como base de decisão operacional.</div>
                                )}
                              </div>
                            </td>
                          </tr>
                        )}
                      </>
                    ))}
                  </tbody>
                </table>
                {(indicatorSubTab === "winners" ? winners : losers).length === 0 && !loadingTab && (
                  <EmptyState message="Nenhum dado. Execute uma análise para popular os indicadores." onRun={() => setShowRunModal(true)} />
                )}
              </div>
            )}
          </div>
        </div>
      )}

      {/* ── TAB: Combinations ──────────────────────────────────────────────────── */}
      {activeTab === "Combinations" && (
        <div className="space-y-4">
          <div className="card">
            <div className="p-4 border-b border-[var(--border-default)]">
              <div className="flex items-center justify-between gap-4 flex-wrap">
                <div>
                  <h2 className="text-[14px] font-semibold text-[var(--text-primary)]">Combinações Descobertas</h2>
                  <p className="text-[11px] text-[var(--text-tertiary)] mt-0.5">
                    Candidatos — evidência parcial, requerem validação em shadow antes de qualquer uso operacional.
                  </p>
                </div>
                <label className="flex items-center gap-2 text-[12px] cursor-pointer select-none shrink-0">
                  <div
                    className={`relative w-8 h-4 rounded-full transition-colors ${hideComboDuplicates ? "bg-blue-600" : "bg-[var(--bg-hover)]"}`}
                    onClick={() => setHideComboDuplicates(v => !v)}
                  >
                    <div className={`absolute top-0.5 w-3 h-3 rounded-full bg-white transition-transform ${hideComboDuplicates ? "translate-x-4" : "translate-x-0.5"}`} />
                  </div>
                  <span className="text-[var(--text-secondary)]">
                    Ocultar duplicatas
                    {hideComboDuplicates && hiddenComboCount > 0 && (
                      <span className="ml-1 text-[10px] text-[var(--text-tertiary)]">({hiddenComboCount} ocultadas)</span>
                    )}
                  </span>
                </label>
              </div>
            </div>
            {loadingTab ? <TableSkeleton /> : combinations.length === 0 ? (
              <EmptyState message="Nenhuma combinação descoberta. Execute uma análise com lookback maior ou reduza min_closed_trades." onRun={() => setShowRunModal(true)} />
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-[12px]">
                  <thead>
                    <tr className="border-b border-[var(--border-subtle)]">
                      {["Nome / Família", "Tipo", "Decisão Auto-Pilot", "Discovery Trades", "Validation Trades", "Validation Lift", "Champion Score", "Confidence", "Overfit", ""].map(h => (
                        <th key={h} className="px-4 py-2 text-left text-[10px] font-semibold text-[var(--text-tertiary)] uppercase tracking-wider whitespace-nowrap">{h}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[var(--border-subtle)]">
                    {displayedCombinations.map(c => (
                      <tr key={c.id} className="hover:bg-[var(--bg-elevated)] transition-colors">
                        <td className="px-4 py-2.5">
                          <div className="font-medium text-[var(--text-primary)] max-w-[200px] truncate">{c.suggested_name || `combination_${c.id.slice(0, 8)}`}</div>
                          {c.setup_family && <div className="text-[10px] text-[var(--text-tertiary)]">{c.setup_family}</div>}
                        </td>
                        <td className="px-4 py-2.5">{combinationTypeBadge(c.combination_type)}</td>
                        <td className="px-4 py-2.5">{autopilotDecisionBadge(c.autopilot_decision)}</td>
                        <td className="px-4 py-2.5 text-[var(--text-secondary)]">{c.discovery_metrics_json?.total_cases ?? c.total_cases ?? "—"}</td>
                        <td className="px-4 py-2.5 text-[var(--text-secondary)]">{c.validation_metrics_json?.total_cases ?? "—"}</td>
                        <td className="px-4 py-2.5 text-[var(--text-secondary)]">
                          {c.validation_metrics_json?.lift != null ? `${Number(c.validation_metrics_json.lift).toFixed(2)}x` : "—"}
                        </td>
                        <td className="px-4 py-2.5 min-w-[120px]"><ChampionScoreBar score={c.champion_score} /></td>
                        <td className="px-4 py-2.5">{confidenceBadge(c.confidence_level)}</td>
                        <td className="px-4 py-2.5">
                          {c.overfit_risk ? <span className="text-yellow-400 text-[11px]">⚠️ Sim</span> : <span className="text-[var(--text-tertiary)] text-[11px]">—</span>}
                        </td>
                        <td className="px-4 py-2.5">
                          <button
                            className="btn btn-secondary text-[10px] px-2 py-1 whitespace-nowrap"
                            onClick={() => setSelectedCombination(c)}
                          >
                            Detalhes
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      )}

      {/* ── TAB: Suggestions ───────────────────────────────────────────────────── */}
      {activeTab === "Suggestions" && (
        <div className="space-y-4">
          <div className="card p-3 border-yellow-500/20 bg-yellow-500/5">
            <div className="flex items-start gap-2">
              <AlertTriangle className="w-4 h-4 text-yellow-400 mt-0.5 shrink-0" />
              <p className="text-[11px] text-[var(--text-secondary)]">
                Sugestões são hipóteses analíticas geradas com base em shadow trades. Requerem validação antes de qualquer uso operacional. <strong className="text-yellow-400">Live trading permanece desativado.</strong>
              </p>
            </div>
          </div>

          <div className="card">
            <div className="p-4 border-b border-[var(--border-default)]">
              <h2 className="text-[14px] font-semibold text-[var(--text-primary)]">Sugestões de Novos Profiles</h2>
              <p className="text-[11px] text-[var(--text-tertiary)] mt-0.5">Exploratório não é aplicável. Validado ainda exige revisão humana e cria somente profile SHADOW_ONLY.</p>
            </div>
            {loadingTab ? <TableSkeleton /> : suggestions.length === 0 ? (
              <EmptyState message="Nenhuma sugestão disponível. Execute uma análise ou aguarde mais shadow trades fechados." onRun={() => setShowRunModal(true)} />
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-[12px]">
                  <thead>
                    <tr className="border-b border-[var(--border-subtle)]">
                      {["Nome Sugerido", "Origem", "Profile", "Validation", "Risco", "Status", "Ações"].map(h => (
                        <th key={h} className="px-4 py-2 text-left text-[10px] font-semibold text-[var(--text-tertiary)] uppercase tracking-wider whitespace-nowrap">{h}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[var(--border-subtle)]">
                    {suggestions.map(s => (
                      <tr key={s.id} className="hover:bg-[var(--bg-elevated)] transition-colors">
                        <td className="px-4 py-2.5 font-medium text-[var(--text-primary)] max-w-[220px] truncate">{s.suggested_profile_name}</td>
                        <td className="px-4 py-2.5 text-[var(--text-secondary)] font-mono text-[10px]">{s.source_type || "—"}</td>
                        <td className="px-4 py-2.5 text-[var(--text-secondary)]">{s.profile_name || "—"}</td>
                        <td className="px-4 py-2.5">{statusBadge(s.validation_status)}</td>
                        <td className="px-4 py-2.5 text-[var(--text-secondary)]">{s.risk_level || "—"}</td>
                        <td className="px-4 py-2.5">{statusBadge(s.status)}</td>
                        <td className="px-4 py-2.5">
                          <div className="flex items-center gap-1.5 flex-wrap">
                            <button
                              className="btn btn-secondary text-[10px] px-2 py-1 whitespace-nowrap"
                              onClick={() => setSelectedSuggestion(s)}
                            >
                              <Eye className="w-3 h-3" />
                            </button>
                            <button
                              className="btn btn-secondary text-[10px] px-2 py-1 whitespace-nowrap flex items-center gap-1"
                              onClick={() => handleExplain(s.id)}
                              disabled={explainingId === s.id}
                            >
                              <Zap className={`w-3 h-3 ${explainingId === s.id ? "animate-pulse" : ""}`} />
                              {explainingId === s.id ? "..." : "IA"}
                            </button>
                            <button
                              className={`btn text-[10px] px-2 py-1 whitespace-nowrap flex items-center gap-1 ${
                                ["created", "applied"].includes(s.status)
                                  ? "btn-secondary opacity-50 cursor-not-allowed"
                                  : !suggestionIsActionable(s)
                                  ? "btn-secondary opacity-40 cursor-not-allowed"
                                  : "btn-primary"
                              }`}
                              onClick={() => suggestionIsActionable(s) && handleOpenCreateProfile(s)}
                              disabled={["created", "applied"].includes(s.status) || !suggestionIsActionable(s)}
                              title={!suggestionIsActionable(s) ? blockedReasonLabel(s.blocked_reason) : "Criar profile SHADOW_ONLY"}
                            >
                              <BarChart3 className="w-3 h-3" />
                              {["created", "applied"].includes(s.status) ? "Aplicado" : "Criar"}
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      )}

      {/* ── TAB: Audit ─────────────────────────────────────────────────────────── */}
      {activeTab === "Audit" && (
        <div className="card">
          <div className="p-4 border-b border-[var(--border-default)]">
            <h2 className="text-[14px] font-semibold text-[var(--text-primary)]">Audit Trail</h2>
            <p className="text-[11px] text-[var(--text-tertiary)] mt-0.5">Log imutável de eventos do Profile Intelligence Engine — incluindo diffs antes/depois de mutações.</p>
          </div>
          {loadingTab ? <TableSkeleton /> : audit.length === 0 ? (
            <div className="p-8 text-center text-[12px] text-[var(--text-tertiary)]">Nenhum evento registrado ainda.</div>
          ) : (
            <div className="divide-y divide-[var(--border-subtle)]">
              {audit.map(entry => {
                const hasDiff = entry.diff_json || (entry.before_json && entry.after_json);
                const isApplied = entry.mutation_applied === true;
                const isDryRun = entry.dry_run === true;
                const mutStatus = entry.mutation_status;
                const mutStatusColor =
                  mutStatus === "APPLIED_TO_PROFILE_CONFIG" ? "text-green-400" :
                  mutStatus === "APPLIED_TO_SHADOW" ? "text-blue-400" :
                  mutStatus === "DRY_RUN_ONLY" ? "text-yellow-400" :
                  mutStatus?.startsWith("AUTO_REJECTED") ? "text-red-400" :
                  "text-[var(--text-tertiary)]";
                const MUTATION_STATUS_LABELS_FRONTEND: Record<string, string> = {
                  DRY_RUN_ONLY: "Simulação (dry run)",
                  APPLIED_TO_SHADOW: "Aplicado em shadow",
                  APPLIED_TO_PROFILE_CONFIG: "Aplicado no profile",
                  AUTO_REJECTED_INSUFFICIENT_EVIDENCE: "Rejeitado — evidência insuficiente",
                  AUTO_REJECTED_RISK: "Rejeitado — risco elevado",
                  AUTO_REJECTED_PROFILE_CONFLICT: "Rejeitado — conflito com profile",
                  AUTO_REJECTED_DUPLICATE_RULE: "Rejeitado — regra duplicada",
                  AUTO_REJECTED_LOW_SAMPLE: "Rejeitado — amostra insuficiente",
                  AUTO_REJECTED_NEGATIVE_EV: "Rejeitado — EV negativo",
                  AUTO_APPROVED_FOR_SHADOW: "Aprovado para shadow",
                  AUTO_ARCHIVED_HYPOTHESIS: "Hipótese arquivada",
                };
                return (
                  <div key={entry.id}>
                    <button
                      className="w-full flex items-center gap-3 px-4 py-3 text-left hover:bg-[var(--bg-elevated)] transition-colors"
                      onClick={() => setExpandedAudit(expandedAudit === entry.id ? null : entry.id)}
                    >
                      <span className="shrink-0 text-[var(--text-tertiary)]">
                        {expandedAudit === entry.id ? <ChevronDown className="w-3.5 h-3.5" /> : <ChevronRight className="w-3.5 h-3.5" />}
                      </span>
                      <span className="flex-1 flex items-center gap-2 min-w-0 flex-wrap">
                        <span className={`badge text-[10px] ${entry.event_type.includes("error") || entry.event_type.includes("failed") ? "bearish" : entry.event_type.includes("completed") || entry.event_type.includes("finished") || isApplied ? "bullish" : entry.event_type.includes("anthropic") || entry.event_type.includes("ai_") ? "range" : "range"}`}>
                          {entry.event_type}
                        </span>
                        {isDryRun && (
                          <span className="px-1 py-0.5 rounded text-[9px] bg-yellow-500/10 text-yellow-400 border border-yellow-500/20">dry run</span>
                        )}
                        {isApplied && (
                          <span className="px-1 py-0.5 rounded text-[9px] bg-green-500/10 text-green-400 border border-green-500/20">aplicado</span>
                        )}
                        {mutStatus && (
                          <span className={`text-[10px] ${mutStatusColor}`}>{MUTATION_STATUS_LABELS_FRONTEND[mutStatus] || mutStatus}</span>
                        )}
                        {hasDiff && (
                          <span className="px-1 py-0.5 rounded text-[9px] bg-blue-500/10 text-blue-400 border border-blue-500/20">diff</span>
                        )}
                        {entry.event_description && (
                          <span className="text-[11px] text-[var(--text-secondary)] truncate">{entry.event_description}</span>
                        )}
                        {entry.model_provider && (
                          <span className="text-[10px] text-purple-400">{entry.model_provider}/{entry.model_name}</span>
                        )}
                      </span>
                      <span className="text-[10px] text-[var(--text-tertiary)] shrink-0 font-mono">{fmtDate(entry.created_at)}</span>
                    </button>
                    {expandedAudit === entry.id && (
                      <div className="px-10 pb-4 pt-2 space-y-3">
                        {/* Metadata row */}
                        <div className="flex flex-wrap gap-3 text-[10px] text-[var(--text-tertiary)]">
                          {entry.profile_name && <span>Profile: <span className="font-mono text-[var(--accent-primary)]">{entry.profile_name}</span></span>}
                          {entry.run_id && <span>Run: <span className="font-mono">{entry.run_id.slice(0, 8)}</span></span>}
                          {entry.suggestion_id && <span>Suggestion: <span className="font-mono">{entry.suggestion_id.slice(0, 8)}</span></span>}
                          {entry.source_run_id && <span>Source run: <span className="font-mono">{entry.source_run_id.slice(0, 8)}</span></span>}
                        </div>
                        {/* Before / After diff cards */}
                        {hasDiff && (
                          <div className="grid grid-cols-2 gap-3">
                            <div className="space-y-1">
                              <div className="text-[10px] font-semibold text-red-400 uppercase tracking-wide">Antes</div>
                              <pre className="text-[10px] text-red-300/80 bg-red-500/5 border border-red-500/15 rounded p-2 overflow-x-auto max-h-40 whitespace-pre-wrap">
                                {JSON.stringify(entry.before_json || "—", null, 2)}
                              </pre>
                            </div>
                            <div className="space-y-1">
                              <div className="text-[10px] font-semibold text-green-400 uppercase tracking-wide">Depois</div>
                              <pre className="text-[10px] text-green-300/80 bg-green-500/5 border border-green-500/15 rounded p-2 overflow-x-auto max-h-40 whitespace-pre-wrap">
                                {JSON.stringify(entry.after_json || "—", null, 2)}
                              </pre>
                            </div>
                          </div>
                        )}
                        {/* Diff JSON */}
                        {entry.diff_json && (
                          <div>
                            <div className="text-[10px] font-semibold text-[var(--text-tertiary)] uppercase mb-1">Diff</div>
                            <pre className="text-[10px] text-[var(--text-secondary)] bg-[var(--bg-input)] rounded p-2 overflow-x-auto max-h-32 whitespace-pre-wrap">
                              {JSON.stringify(entry.diff_json, null, 2)}
                            </pre>
                          </div>
                        )}
                        {entry.result_json && (
                          <div>
                            <div className="text-[10px] font-semibold text-[var(--text-tertiary)] uppercase mb-1">Result</div>
                            <pre className="text-[10px] text-[var(--text-secondary)] bg-[var(--bg-input)] rounded p-2 overflow-x-auto max-h-40 whitespace-pre-wrap">
                              {JSON.stringify(entry.result_json, null, 2)}
                            </pre>
                          </div>
                        )}
                        {entry.payload_json && !hasDiff && (
                          <div>
                            <div className="text-[10px] font-semibold text-[var(--text-tertiary)] uppercase mb-1">Payload</div>
                            <pre className="text-[10px] text-[var(--text-secondary)] bg-[var(--bg-input)] rounded p-2 overflow-x-auto max-h-40 whitespace-pre-wrap">
                              {JSON.stringify(entry.payload_json, null, 2)}
                            </pre>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {/* ── TAB: Settings ──────────────────────────────────────────────────────── */}
      {activeTab === "Settings" && (
        <div className="space-y-4 max-w-2xl">
          <div className="card p-4 border-blue-500/20 bg-blue-500/5">
            <div className="flex items-start gap-2">
              <CheckCircle className="w-4 h-4 text-blue-400 mt-0.5 shrink-0" />
              <p className="text-[11px] text-[var(--text-secondary)]">
                Configurações afetam os próximos runs. Sugestões geradas são sempre analíticas e não ativam live trading.
              </p>
            </div>
          </div>

          {loadingTab ? (
            <div className="skeleton h-64 rounded-[var(--radius-lg)]" />
          ) : (
            <div className="card p-5 space-y-4">
              <h2 className="text-[14px] font-semibold text-[var(--text-primary)]">Parâmetros do Engine</h2>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {[
                  { key: "min_closed_trades", label: "Min Closed Trades", step: 1 },
                  { key: "min_lift", label: "Min Lift", step: 0.1 },
                  { key: "min_win_rate", label: "Min Win Rate", step: 0.01 },
                  { key: "max_avg_mae", label: "Max Avg MAE", step: 0.1 },
                  { key: "max_avg_holding_seconds", label: "Max Avg Holding (s)", step: 60 },
                  { key: "required_tp_30m_rate", label: "Required TP ≤30m Rate", step: 0.01 },
                  { key: "max_combinations_per_run", label: "Max Combinations per Run", step: 50 },
                  { key: "indicator_winning_lift", label: "Winner Lift", step: 0.01 },
                  { key: "indicator_losing_winrate_ratio", label: "Loser WR Ratio", step: 0.01 },
                  { key: "validation_min_discovery_trades", label: "Discovery Min Trades", step: 1 },
                  { key: "validation_min_trades", label: "Validation Min Trades", step: 1 },
                  { key: "validation_min_lift", label: "Validation Min Lift", step: 0.01 },
                  { key: "validation_min_winrate_delta", label: "Validation WR Delta", step: 0.01 },
                  { key: "validation_max_single_symbol_share", label: "Max Symbol Share", step: 0.01 },
                  { key: "validation_max_single_day_share", label: "Max Day Share", step: 0.01 },
                  { key: "validation_min_distinct_symbols", label: "Min Distinct Symbols", step: 1 },
                  { key: "validation_min_distinct_days", label: "Min Distinct Days", step: 1 },
                  { key: "validation_min_assoc_support", label: "Association Min Support", step: 0.01 },
                  { key: "validation_min_assoc_confidence", label: "Association Min Confidence", step: 0.01 },
                  { key: "validation_min_lift_retention", label: "Min Lift Retention", step: 0.01 },
                  { key: "adjustment_min_profile_trades", label: "Adjustment Min Trades", step: 1 },
                  { key: "adjustment_max_win_rate", label: "Adjustment Max WR", step: 0.01 },
                  { key: "adjustment_score_bump", label: "Score Bump", step: 1 },
                  { key: "adjustment_score_cap", label: "Score Cap", step: 1 },
                ].map(({ key, label, step }) => (
                  <div key={key}>
                    <label className="block text-[11px] font-medium text-[var(--text-tertiary)] uppercase tracking-wider mb-1">{label}</label>
                    <input
                      type="number"
                      step={step}
                      value={(settings as any)[key] ?? ""}
                      onChange={e => setSettings(s => ({ ...s, [key]: parseFloat(e.target.value) || 0 }))}
                      className="w-full bg-[var(--bg-input)] border border-[var(--border-default)] rounded-lg px-3 py-2 text-[13px] text-[var(--text-primary)] focus:outline-none focus:border-[var(--accent-primary)]"
                    />
                  </div>
                ))}
              </div>

              <div className="space-y-2 pt-2 border-t border-[var(--border-subtle)]">
                <h3 className="text-[13px] font-semibold text-[var(--text-primary)]">Sources oficiais</h3>
                <div className="flex flex-wrap gap-3">
                  {(["L1_SPECTRUM", "L3", "L3_LAB"] as const).map(source => {
                    const active = (settings.analysis_sources || []).includes(source);
                    return (
                      <label key={source} className="flex items-center gap-2 text-[12px] text-[var(--text-secondary)]">
                        <input
                          type="checkbox"
                          checked={active}
                          onChange={() => setSettings(current => ({
                            ...current,
                            analysis_sources: active
                              ? (current.analysis_sources || []).filter(item => item !== source)
                              : [...(current.analysis_sources || []), source],
                          }))}
                        />
                        {source}
                      </label>
                    );
                  })}
                </div>
              </div>

              <div className="space-y-3 pt-2 border-t border-[var(--border-subtle)]">
                <h3 className="text-[13px] font-semibold text-[var(--text-primary)]">Features Opcionais</h3>
                {[
                  { key: "enable_dynamic_combinations", label: "Dynamic Combinations", hint: "Gera combinações dinâmicas de buckets top-winners" },
                  { key: "enable_association_rules", label: "Association Rules", hint: "mlxtend apriori para encontrar co-ocorrências" },
                  { key: "enable_anthropic_explanations", label: "Anthropic AI Explanations", hint: "⚠️ Consome tokens da cota Anthropic" },
                  { key: "enable_optuna", label: "Optuna Search", hint: "⚠️ Pesado — aumenta tempo de análise significativamente" },
                ].map(({ key, label, hint }) => (
                  <div key={key} className="flex items-center justify-between">
                    <div>
                      <div className="text-[13px] text-[var(--text-primary)]">{label}</div>
                      <div className="text-[11px] text-[var(--text-tertiary)]">{hint}</div>
                    </div>
                    <button
                      onClick={() => setSettings(s => ({ ...s, [key]: !(s as any)[key] }))}
                      className={`relative w-11 h-6 rounded-full transition-colors ${(settings as any)[key] ? "bg-[var(--accent-primary)]" : "bg-[var(--bg-hover)]"} border border-[var(--border-strong)]`}
                    >
                      <span className={`absolute top-0.5 left-0.5 w-5 h-5 rounded-full bg-white shadow transition-transform ${(settings as any)[key] ? "translate-x-5" : "translate-x-0"}`} />
                    </button>
                  </div>
                ))}

                <div className="grid grid-cols-1 gap-3 pt-2">
                  {(["lightgbm", "catboost"] as const).map(key => {
                    const label = key === "lightgbm" ? "LightGBM" : "CatBoost";
                    const ch = mlChallengers?.[key];
                    const isOp = ch?.operational === true;
                    const statusText = ch == null
                      ? "Verificando…"
                      : isOp
                      ? "Operacional"
                      : ch.installed
                      ? "Instalado — sem modelo ativo"
                      : "Pacote não instalado";
                    const borderCls = isOp
                      ? "border-emerald-500/30 bg-emerald-500/5"
                      : "border-yellow-500/25 bg-yellow-500/5";
                    const statusColor = isOp ? "text-emerald-400" : "text-yellow-400";
                    const flagKey = key === "lightgbm" ? "enable_lightgbm" : "enable_catboost";
                    const enabled = !!(settings as any)[flagKey];
                    const caps: [string, boolean][] = ch ? [
                      ["Treina", ch.can_train],
                      ["Infere", ch.can_infer],
                      ["Sugestões", ch.can_generate_suggestions],
                      ["Auto-Pilot", ch.influences_autopilot],
                    ] : [];
                    return (
                      <div key={key} className={`rounded-lg border ${borderCls} p-3`}>
                        <div className="flex items-center justify-between gap-3">
                          <div>
                            <div className="text-[13px] font-medium text-[var(--text-primary)]">{label}</div>
                            <div className={`text-[11px] ${statusColor}`}>Status: {statusText}</div>
                          </div>
                          <button
                            type="button"
                            onClick={() => setSettings(s => ({ ...s, [flagKey]: !(s as any)[flagKey] }))}
                            aria-label={`${label} ${enabled ? "habilitado" : "desabilitado"}`}
                            className={`relative w-11 h-6 rounded-full transition-colors ${enabled ? "bg-[var(--accent-primary)]" : "bg-[var(--bg-hover)]"} border border-[var(--border-strong)]`}
                          >
                            <span className={`absolute top-0.5 left-0.5 w-5 h-5 rounded-full bg-white shadow transition-transform ${enabled ? "translate-x-5" : "translate-x-0"}`} />
                          </button>
                        </div>
                        {isOp && caps.length > 0 ? (
                          <div className="mt-2 flex flex-wrap gap-x-3 gap-y-1">
                            {caps.map(([lbl, val]) => (
                              <span key={lbl} className={`text-[10px] ${val ? "text-emerald-400" : "text-[var(--text-tertiary)]"}`}>
                                {val ? "✓" : "○"} {lbl}
                              </span>
                            ))}
                          </div>
                        ) : (
                          <div className="mt-2 text-[11px] text-[var(--text-tertiary)]">
                            {ch == null
                              ? "Carregando status do backend…"
                              : !ch.installed
                              ? "Instale o pacote para habilitar."
                              : "Configure o model registry para ativar."}
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              </div>

              <button
                className="btn btn-primary text-[13px] w-full"
                onClick={handleSaveSettings}
                disabled={savingSettings}
              >
                {savingSettings ? "Salvando..." : "Salvar Configurações"}
              </button>
            </div>
          )}
        </div>
      )}

      {/* ── TAB: Live Engine ───────────────────────────────────────────────────── */}
      {activeTab === "Live Engine" && (
        <div className="space-y-4">
          {/* Safety Guard — always first */}
          {liveSafety && (
            <div className={`card p-4 flex items-start gap-3 ${liveSafety.gate === "PASS" ? "border-green-500/30 bg-green-500/5" : "border-yellow-500/30 bg-yellow-500/5"}`}>
              <CheckCircle className={`w-4 h-4 shrink-0 mt-0.5 ${liveSafety.gate === "PASS" ? "text-green-400" : "text-yellow-400"}`} />
              <div className="flex-1 min-w-0">
                <div className={`text-[12px] font-semibold mb-1 ${liveSafety.gate === "PASS" ? "text-green-400" : "text-yellow-400"}`}>
                  Safety Guard — {liveSafety.gate}
                </div>
                <div className="grid grid-cols-2 md:grid-cols-6 gap-2">
                  {[
                    ["ML Gate", liveSafety.ml_gate_enabled ? "ON" : "OFF", !liveSafety.ml_gate_enabled],
                    ["Live Trading", liveSafety.live_trading_enabled ? "ON" : "OFF", !liveSafety.live_trading_enabled],
                    ["Production Mutation", liveSafety.auto_mutation_production ? "ON" : "OFF", !liveSafety.auto_mutation_production],
                    ["Create Profile", liveSafety.create_profile_enabled ? "ON" : "OFF", !liveSafety.create_profile_enabled],
                    ["Shadow Calibration", liveSafety.shadow_calibration_autonomous !== false ? "Autonomous" : "Manual", liveSafety.shadow_calibration_autonomous !== false],
                    ["Production Approval", liveSafety.human_approval_required_for_production !== false ? "Required" : "—", liveSafety.human_approval_required_for_production !== false],
                  ].map(([label, value, isGood]) => (
                    <div key={String(label)} className="text-center">
                      <div className="text-[10px] text-[var(--text-tertiary)] uppercase">{label}</div>
                      <div className={`text-[12px] font-semibold ${isGood ? "text-green-400" : "text-red-400"}`}>{String(value)}</div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {/* Engine Status */}
            <div className="card p-4 space-y-3">
              <div className="flex items-center gap-2">
                <Zap className="w-4 h-4 text-[var(--accent-primary)]" />
                <h3 className="text-[13px] font-semibold text-[var(--text-primary)]">Engine Status</h3>
              </div>
              {loadingTab ? (
                <div className="skeleton h-24 rounded" />
              ) : liveStatus ? (
                <div className="space-y-2">
                  <div className="flex justify-between text-[12px]">
                    <span className="text-[var(--text-tertiary)]">Status</span>
                    <span className={`font-semibold ${liveStatus.engine_status === "RUNNING" ? "text-green-400" : liveStatus.is_stale ? "text-yellow-400" : "text-[var(--text-primary)]"}`}>
                      {liveStatus.is_stale ? "STALE" : liveStatus.engine_status}
                    </span>
                  </div>
                  <div className="flex justify-between text-[12px]">
                    <span className="text-[var(--text-tertiary)]">Fase</span>
                    <span className="text-[var(--text-primary)]">{liveStatus.current_phase}</span>
                  </div>
                  <div className="flex justify-between text-[12px]">
                    <span className="text-[var(--text-tertiary)]">Último heartbeat</span>
                    <span className="text-[var(--text-primary)]">{liveStatus.last_heartbeat_at ? new Date(liveStatus.last_heartbeat_at).toLocaleTimeString() : "—"}</span>
                  </div>
                  <div className="flex justify-between text-[12px]">
                    <span className="text-[var(--text-tertiary)]">Próximo ciclo</span>
                    <span className="text-[var(--text-primary)]">{liveStatus.next_cycle_at ? new Date(liveStatus.next_cycle_at).toLocaleTimeString() : "—"}</span>
                  </div>
                  <div className="flex justify-between text-[12px]">
                    <span className="text-[var(--text-tertiary)]">Worker</span>
                    <span className="text-[var(--text-secondary)] truncate max-w-[60%]">{liveStatus.worker_name || "—"}</span>
                  </div>
                </div>
              ) : (
                <div className="text-[12px] text-[var(--text-tertiary)]">Motor não iniciado. Aguardando primeiro heartbeat.</div>
              )}
            </div>

            {/* Shadow Analyzer */}
            <div className="card p-4 space-y-3">
              <div className="flex items-center gap-2">
                <Eye className="w-4 h-4 text-blue-400" />
                <h3 className="text-[13px] font-semibold text-[var(--text-primary)]">Shadow Analyzer (24h)</h3>
              </div>
              {loadingTab ? <div className="skeleton h-24 rounded" /> : liveShadow ? (
                <div className="space-y-2">
                  {liveShadow.total_trades === 0 && liveShadow.message && (
                    <div className="text-[11px] text-amber-400 bg-amber-400/10 rounded px-3 py-2">
                      {liveShadow.message}
                    </div>
                  )}
                  <div className="grid grid-cols-2 gap-2">
                    {[
                      ["Trades (24h)", liveShadow.total_trades],
                      ["Profiles (24h)", liveShadow.total_profiles],
                      ["Win Rate", liveShadow.win_rate != null && liveShadow.total_trades > 0 ? `${(liveShadow.win_rate * 100).toFixed(1)}%` : "—"],
                      ["Avg PnL", liveShadow.avg_pnl_pct != null && liveShadow.total_trades > 0 ? `${liveShadow.avg_pnl_pct > 0 ? "+" : ""}${liveShadow.avg_pnl_pct.toFixed(3)}%` : "—"],
                      ...(liveShadow.total_trades === 0 && liveShadow.fallback_total_trades != null
                        ? [["Trades (7d)", liveShadow.fallback_total_trades], ["Profiles (7d)", liveShadow.fallback_total_profiles]]
                        : [["Negative Profiles", liveShadow.negative_profiles], ["Hard Negatives", liveShadow.hard_negative_patterns_detected]]
                      ),
                    ].map(([label, value]) => (
                      <div key={String(label)} className="bg-[var(--bg-input)] rounded px-3 py-2">
                        <div className="text-[10px] text-[var(--text-tertiary)] uppercase">{label}</div>
                        <div className="text-[13px] font-semibold text-[var(--text-primary)]">{String(value ?? "—")}</div>
                      </div>
                    ))}
                  </div>
                </div>
              ) : <div className="text-[12px] text-[var(--text-tertiary)]">Sem dados de shadow disponíveis.</div>}
            </div>

            {/* AI Critic */}
            <div className="card p-4 space-y-3">
              <div className="flex items-center gap-2">
                <Brain className="w-4 h-4 text-purple-400" />
                <h3 className="text-[13px] font-semibold text-[var(--text-primary)]">AI Critic (4h)</h3>
              </div>
              {loadingTab ? <div className="skeleton h-24 rounded" /> : liveAiReview ? (
                <div className="space-y-2">
                  <div className="flex justify-between text-[12px]">
                    <span className="text-[var(--text-tertiary)]">Status</span>
                    <span className={`font-semibold ${liveAiReview.status === "COMPLETED" ? "text-green-400" : liveAiReview.status === "SCHEDULED" ? "text-blue-400" : "text-[var(--text-secondary)]"}`}>{liveAiReview.status}</span>
                  </div>
                  {liveAiReview.next_review_at && (
                    <div className="flex justify-between text-[12px]">
                      <span className="text-[var(--text-tertiary)]">Próxima revisão</span>
                      <span className="text-[var(--text-primary)]">{new Date(liveAiReview.next_review_at).toLocaleTimeString()}</span>
                    </div>
                  )}

                  {/* Auditable context block — shown before diagnosis */}
                  {liveAiReview.analysis_context_available && liveAiReview.analysis_context ? (
                    <div className="bg-purple-500/5 border border-purple-500/20 rounded p-2 space-y-1 text-[10px]">
                      <div className="text-purple-400 font-semibold uppercase tracking-wide">Contexto auditável ✓</div>
                      {[
                        ["Fonte", liveAiReview.analysis_context.dataset?.table],
                        ["Aba/visão", liveAiReview.analysis_context.dataset?.portfolio_view],
                        ["Sources", liveAiReview.analysis_context.dataset?.sources?.join(", ")],
                        ["Janela", `${liveAiReview.analysis_context.window?.window_hours}h`],
                        ["Período", `${liveAiReview.analysis_context.window?.window_start ? new Date(liveAiReview.analysis_context.window.window_start).toLocaleString() : "—"} → ${liveAiReview.analysis_context.window?.window_end ? new Date(liveAiReview.analysis_context.window.window_end).toLocaleString() : "—"}`],
                        ["Filtro", "COMPLETED + pnl_pct IS NOT NULL + profile_id IS NOT NULL"],
                        ["Trades analisados", liveAiReview.analysis_context.sample?.trades_count],
                        ["Profiles", liveAiReview.analysis_context.sample?.profiles_count],
                        ["Symbols", liveAiReview.analysis_context.sample?.symbols_count],
                        ["Review ID", liveAiReview.review_id ? `${liveAiReview.review_id.slice(0, 8)}…` : "—"],
                        ["Context hash", liveAiReview.context_payload_hash ? `${liveAiReview.context_payload_hash.slice(0, 12)}…` : "—"],
                      ].map(([label, value]) => (
                        <div key={String(label)} className="flex gap-1">
                          <span className="text-[var(--text-tertiary)] min-w-[90px]">{label}</span>
                          <span className="text-[var(--text-secondary)]">{String(value ?? "—")}</span>
                        </div>
                      ))}
                      {liveAiReview.analysis_context.sample?.source_breakdown && Object.keys(liveAiReview.analysis_context.sample.source_breakdown).length > 0 && (
                        <div className="pt-1 border-t border-purple-500/10">
                          <div className="text-purple-400 font-semibold mb-0.5">Source breakdown</div>
                          {Object.entries(liveAiReview.analysis_context.sample.source_breakdown).map(([src, val]: [string, any]) => (
                            <div key={src} className="flex gap-1">
                              <span className="text-[var(--text-tertiary)] min-w-[90px]">{src}</span>
                              <span className="text-[var(--text-secondary)]">{val?.trades ?? val} trades</span>
                            </div>
                          ))}
                        </div>
                      )}
                    </div>
                  ) : liveAiReview.analysis_context_legacy ? (
                    <div className="bg-yellow-500/5 border border-yellow-500/20 rounded p-2 text-[10px] text-yellow-300">
                      Diagnóstico legado sem contexto auditável. Reprocessar review para obter rastreabilidade.
                    </div>
                  ) : liveAiReview.status === "COMPLETED" ? (
                    <div className="bg-yellow-500/5 border border-yellow-500/20 rounded p-2 text-[10px] text-yellow-300">
                      AI Critic executado, mas sem contexto de fonte/período. Reprocessar review.
                    </div>
                  ) : null}

                  {liveAiReview.summary && (
                    <div className="text-[11px] text-[var(--text-secondary)] bg-[var(--bg-input)] rounded p-2">{liveAiReview.summary}</div>
                  )}
                  {liveAiReview.risk_flags?.length > 0 && (
                    <div className="space-y-1">
                      <div className="text-[10px] font-semibold text-yellow-400 uppercase">Risk Flags</div>
                      {liveAiReview.risk_flags.map((f: any, i: number) => (
                        <div key={i} className="text-[11px] text-yellow-300 bg-yellow-500/5 rounded px-2 py-1">
                          {typeof f === "string" ? f : f.flag || JSON.stringify(f)}
                        </div>
                      ))}
                    </div>
                  )}
                  {liveAiReview.tokens_input && (
                    <div className="text-[10px] text-[var(--text-tertiary)]">{liveAiReview.tokens_input} in / {liveAiReview.tokens_output} out tokens</div>
                  )}
                </div>
              ) : <div className="text-[12px] text-[var(--text-tertiary)]">AI Critic ainda não executou.</div>}
            </div>

            {/* Auto-Pilot Calibration */}
            <div className="card p-4 space-y-3">
              <div className="flex items-center gap-2">
                <Settings className="w-4 h-4 text-orange-400" />
                <h3 className="text-[13px] font-semibold text-[var(--text-primary)]">Auto-Pilot Calibration</h3>
              </div>
              <div className="text-[11px] text-[var(--text-secondary)] bg-orange-500/5 border border-orange-500/20 rounded p-2">
                Modo: Calibração-only. Criação de profiles: <span className="text-red-400 font-semibold">OFF</span>. Shadow-only: <span className="text-green-400 font-semibold">ON</span>.
              </div>
              <div className="space-y-1">
                {[
                  ["Em validação Shadow", liveAdjustments.filter(s => s.status === "PENDING_SHADOW_VALIDATION" || s.status === "SHADOW_APPLIED").length],
                  ["Aguardando Aprovação", liveAdjustments.filter(s => s.status === "VALIDATED" || (s.requires_human_approval && !s.mutation_applied)).length],
                  ["Total sugestões", liveAdjustments.length],
                  ["Mutations aplicadas", liveAdjustments.filter(s => s.mutation_applied).length],
                ].map(([label, value]) => (
                  <div key={String(label)} className="flex justify-between text-[12px]">
                    <span className="text-[var(--text-tertiary)]">{label}</span>
                    <span className={`font-semibold ${String(label).includes("Mutations") && Number(value) > 0 ? "text-red-400" : "text-[var(--text-primary)]"}`}>{String(value)}</span>
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Indicator Performance */}
          {liveIndicators && (
            <div className="card p-4 space-y-3">
              <div className="flex flex-wrap items-center justify-between gap-2">
                <div className="flex items-center gap-2">
                  <BarChart3 className="w-4 h-4 text-teal-400" />
                  <h3 className="text-[13px] font-semibold text-[var(--text-primary)]">Indicator Calibration</h3>
                </div>
                <div className="font-mono text-[9px] text-[var(--text-tertiary)]">
                  run {liveIndicators.run_id ? `${liveIndicators.run_id.slice(0, 8)}…` : "—"} · min N {liveIndicators.minimum_cases ?? "—"}
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <div className="text-[11px] font-semibold text-green-400 uppercase mb-2">Top Win Indicators</div>
                  {liveIndicators.top_winners?.slice(0, 5).map((r: LiveIndicatorRow, i: number) => (
                    <div key={`${r.profile_id}-${r.indicator_name}-${r.bucket}-${i}`} className="grid grid-cols-[minmax(0,1fr)_auto] gap-3 border-b border-[var(--border-subtle)] py-1.5 text-[11px]">
                      <div className="min-w-0">
                        <div className="truncate font-mono text-[var(--text-secondary)]">{r.indicator_name}/{r.bucket}</div>
                        <div className="truncate text-[9px] text-cyan-300/80" title={r.profile_id}>{r.profile_name}</div>
                      </div>
                      <div className="text-right">
                        <div className="font-medium text-green-400">{r.win_rate != null ? `${(r.win_rate * 100).toFixed(1)}% WR` : "—"}</div>
                        <div className="font-mono text-[9px] text-[var(--text-tertiary)]">N {r.sample_count} · {r.win_count}/{r.loss_count}</div>
                      </div>
                    </div>
                  ))}
                  {!liveIndicators.top_winners?.length && <div className="py-3 text-[10px] text-[var(--text-tertiary)]">Nenhum bucket positivo no ciclo atual.</div>}
                </div>
                <div>
                  <div className="text-[11px] font-semibold text-red-400 uppercase mb-2">Top Loss Indicators</div>
                  {liveIndicators.top_losers?.slice(0, 5).map((r: LiveIndicatorRow, i: number) => (
                    <div key={`${r.profile_id}-${r.indicator_name}-${r.bucket}-${i}`} className="grid grid-cols-[minmax(0,1fr)_auto] gap-3 border-b border-[var(--border-subtle)] py-1.5 text-[11px]">
                      <div className="min-w-0">
                        <div className="truncate font-mono text-[var(--text-secondary)]">{r.indicator_name}/{r.bucket}</div>
                        <div className="truncate text-[9px] text-cyan-300/80" title={r.profile_id}>{r.profile_name}</div>
                      </div>
                      <div className="text-right">
                        <div className="font-medium text-red-400">{r.win_rate != null ? `${(r.win_rate * 100).toFixed(1)}% WR` : "—"}</div>
                        <div className="font-mono text-[9px] text-[var(--text-tertiary)]">N {r.sample_count} · {r.win_count}/{r.loss_count}</div>
                      </div>
                    </div>
                  ))}
                  {!liveIndicators.top_losers?.length && <div className="py-3 text-[10px] text-[var(--text-tertiary)]">Nenhum bucket negativo no ciclo atual.</div>}
                </div>
              </div>
            </div>
          )}

          {/* Adjustment Suggestions */}
          {liveAdjustments.length > 0 && (
            <div className="card p-4 space-y-3">
              <div className="flex items-center gap-2">
                <TrendingUp className="w-4 h-4 text-amber-400" />
                <h3 className="text-[13px] font-semibold text-[var(--text-primary)]">Calibration Suggestions ({liveAdjustments.length})</h3>
              </div>
              <div className="overflow-x-auto">
                <table className="w-full text-[11px]">
                  <thead>
                    <tr className="text-[var(--text-tertiary)] uppercase border-b border-[var(--border-subtle)]">
                      <th className="text-left pb-2 font-medium">Profile</th>
                      <th className="text-left pb-2 font-medium">Type</th>
                      <th className="text-left pb-2 font-medium">Section</th>
                      <th className="text-right pb-2 font-medium">Status</th>
                      <th className="text-right pb-2 font-medium">Mutation</th>
                    </tr>
                  </thead>
                  <tbody>
                    {liveAdjustments.slice(0, 10).map(s => (
                      <tr key={s.id} className="border-b border-[var(--border-subtle)] hover:bg-[var(--bg-hover)]">
                        <td className="py-2 text-[var(--text-primary)] max-w-[120px] truncate">{s.profile_name || s.profile_id?.slice(0, 8)}</td>
                        <td className="py-2 text-[var(--text-secondary)]">{s.suggestion_type}</td>
                        <td className="py-2 text-[var(--text-tertiary)]">{s.target_section}</td>
                        <td className="py-2 text-right">
                          <span className="px-1.5 py-0.5 rounded text-[10px] bg-blue-500/10 text-blue-400">{s.status}</span>
                        </td>
                        <td className="py-2 text-right">
                          <span className={`font-semibold ${s.mutation_applied ? "text-red-400" : "text-green-400"}`}>{s.mutation_applied ? "APPLIED" : "SAFE"}</span>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* Activity Timeline */}
          <div className="card p-4 space-y-3">
            <div className="flex items-center gap-2">
              <RotateCcw className="w-4 h-4 text-[var(--text-tertiary)]" />
              <h3 className="text-[13px] font-semibold text-[var(--text-primary)]">Activity Timeline</h3>
            </div>
            {loadingTab ? (
              <TableSkeleton />
            ) : liveActivity.length === 0 ? (
              <div className="text-[12px] text-[var(--text-tertiary)] py-4 text-center">Nenhuma atividade registrada ainda. O motor iniciará no próximo ciclo.</div>
            ) : (
              <div className="space-y-1 max-h-72 overflow-y-auto custom-scrollbar">
                {liveActivity.map((ev, i) => (
                  <div key={i} className="flex items-start gap-2 text-[11px] py-1.5 border-b border-[var(--border-subtle)]">
                    <span className={`shrink-0 font-mono w-16 truncate ${ev.severity === "error" ? "text-red-400" : ev.severity === "warn" ? "text-yellow-400" : "text-[var(--text-tertiary)]"}`}>
                      {ev.created_at ? new Date(ev.created_at).toLocaleTimeString() : "—"}
                    </span>
                    <span className="px-1 py-0.5 rounded text-[10px] bg-[var(--bg-input)] text-[var(--text-secondary)] shrink-0">{ev.event_type}</span>
                    <span className="text-[var(--text-primary)] truncate">{ev.message}</span>
                    {ev.profile_name && <span className="text-[var(--accent-primary)] shrink-0">{ev.profile_name}</span>}
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      )}

      {/* ── Combination Detail Drawer ─────────────────────────────────────────── */}
      {selectedCombination && (
        <Drawer title={selectedCombination.suggested_name || "Detalhe da Combinação"} onClose={() => { setSelectedCombination(null); setLastGeneratedSuggestionId(null); }}>
          <div className="space-y-4">
            {/* Alerts */}
            {selectedCombination.overfit_risk && (
              <div className="card p-3 border-yellow-500/30 bg-yellow-500/5 text-[11px] text-yellow-400 flex items-start gap-2">
                <AlertTriangle className="w-4 h-4 shrink-0" /> <span>⚠️ Risco de overfitting detectado. Resultados de discovery podem não generalizar.</span>
              </div>
            )}
            {selectedCombination.confidence_level === "LOW" && (
              <div className="card p-3 border-red-500/30 bg-red-500/5 text-[11px] text-red-400 flex items-start gap-2">
                <AlertTriangle className="w-4 h-4 shrink-0" /> <span>Evidência insuficiente — não usar como base de decisão operacional (LOW confidence).</span>
              </div>
            )}
            {/* Autopilot decision banner — always shown when combination has a decision */}
            {selectedCombination.autopilot_decision && (() => {
              const decision = selectedCombination.autopilot_decision!;
              const d = AUTOPILOT_DECISION_LABELS[decision];
              const isRejected = decision.startsWith("AUTO_REJECTED");
              const isApproved = decision === "AUTO_APPROVED_FOR_SHADOW" || decision === "APPLIED_TO_SHADOW" || decision === "APPLIED_TO_PROFILE_CONFIG";
              const reason = selectedCombination.validation_metrics_json?.blocked_reason
                || selectedCombination.validation_metrics_json?.actionability_status;
              const nextAction = isRejected ? blockedNextAction(reason) : null;
              return (
                <div className={`card p-3 space-y-1.5 ${isRejected ? "border-red-500/30 bg-red-500/5" : isApproved ? "border-green-500/30 bg-green-500/5" : "border-[var(--border-default)]"}`}>
                  <div className={`flex items-start gap-2 text-[11px] ${isRejected ? "text-red-400" : isApproved ? "text-green-400" : "text-[var(--text-tertiary)]"}`}>
                    {isRejected ? <AlertTriangle className="w-4 h-4 shrink-0 mt-px" /> : <CheckCircle className="w-4 h-4 shrink-0 mt-px" />}
                    <div>
                      <span className="font-medium">{d?.label || decision.replace(/_/g, " ")}</span>
                      {reason && (
                        <span className="ml-2 text-[10px] opacity-60 font-mono">{reason}</span>
                      )}
                    </div>
                  </div>
                  {nextAction && (
                    <div className="text-[10px] text-[var(--text-tertiary)] ml-6 flex items-start gap-1">
                      <span className="shrink-0">→</span>
                      <span>{nextAction}</span>
                    </div>
                  )}
                </div>
              );
            })()}

            {selectedCombination.source_profiles?.length ? (
              <div className="text-[11px] text-[var(--text-secondary)]">
                <div className="text-[10px] uppercase text-[var(--text-tertiary)]">Source profiles</div>
                {selectedCombination.source_profiles.join(", ")}
              </div>
            ) : null}

            {/* Discovery vs Validation */}
            <div className="grid grid-cols-2 gap-3">
              {[
                ["Discovery", selectedCombination.discovery_metrics_json],
                ["Validation", selectedCombination.validation_metrics_json],
              ].map(([label, metrics]) => (
                <div key={String(label)} className="card p-3">
                  <div className="text-[10px] font-semibold text-[var(--text-tertiary)] uppercase mb-2">{String(label)}</div>
                  {metrics ? (
                    <div className="space-y-1">
                      {Object.entries(metrics as Record<string, unknown>).map(([k, v]) => (
                        <div key={k} className="flex justify-between text-[11px]">
                          <span className="text-[var(--text-tertiary)]">{k}</span>
                          <span className="text-[var(--text-primary)] font-medium">
                            {typeof v === "number"
                              ? (k.includes("rate") ? fmtPct(v, 2) : k.includes("pnl") || k.includes("mae") || k.includes("mfe") ? fmtPctRaw(v, 2) : v.toFixed(3))
                              : safeVal(v)}
                          </span>
                        </div>
                      ))}
                    </div>
                  ) : <div className="text-[11px] text-[var(--text-tertiary)]">—</div>}
                </div>
              ))}
            </div>

            {/* Degradation */}
            {selectedCombination.degradation_pct != null && (
              <div className="flex justify-between text-[12px]">
                <span className="text-[var(--text-secondary)]">Degradação discovery → validation</span>
                <span className={`font-semibold ${Math.abs(selectedCombination.degradation_pct) > 20 ? "text-red-400" : "text-green-400"}`}>
                  {selectedCombination.degradation_pct.toFixed(1)}%
                </span>
              </div>
            )}

            {/* Rules */}
            {selectedCombination.rules_json && selectedCombination.rules_json.length > 0 && (
              <div>
                <div className="text-[11px] font-semibold text-[var(--text-tertiary)] uppercase mb-2">Regras ({selectedCombination.rules_json.length})</div>
                <div className="space-y-1">
                  {selectedCombination.rules_json.map((r: any, i: number) => (
                    <div key={i} className="font-mono text-[11px] bg-[var(--bg-input)] rounded px-3 py-1.5 text-[var(--text-primary)]">
                      {r.indicator || r.field} {r.operator} {r.value ?? `[${r.range_min}, ${r.range_max}]`}
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Generate Suggestion */}
            <div className="pt-2 border-t border-[var(--border-subtle)] space-y-2">
              <p className="text-[11px] text-[var(--text-tertiary)]">
                Esta é uma hipótese analítica. Gere uma Suggestion para validar em shadow antes de ativar.
              </p>
              <button
                onClick={() => handleGenerateSuggestion(selectedCombination.id)}
                disabled={generatingSuggestion || !combinationIsActionable(selectedCombination)}
                className="btn btn-secondary text-[12px] w-full"
              >
                {generatingSuggestion
                  ? "Gerando..."
                  : combinationIsActionable(selectedCombination)
                    ? "Generate Suggestion"
                    : (() => {
                        const decision = selectedCombination.autopilot_decision;
                        const d = decision ? AUTOPILOT_DECISION_LABELS[decision] : null;
                        const label = d?.label ?? blockedReasonLabel(
                          selectedCombination.validation_metrics_json?.blocked_reason
                          || selectedCombination.validation_metrics_json?.actionability_status
                        );
                        return label.length > 42 ? label.slice(0, 39) + "…" : label;
                      })()}
              </button>
              {lastGeneratedSuggestionId && (
                <button
                  onClick={() => { setActiveTab("Suggestions"); setSelectedCombination(null); setLastGeneratedSuggestionId(null); }}
                  className="btn btn-primary text-[12px] w-full"
                >
                  Open Suggestion →
                </button>
              )}
            </div>
          </div>
        </Drawer>
      )}

      {/* ── Suggestion Detail Drawer ──────────────────────────────────────────── */}
      {selectedSuggestion && (
        <Drawer title={selectedSuggestion.suggested_profile_name} onClose={() => setSelectedSuggestion(null)}>
          <div className="space-y-4">
            {/* Safety */}
            <div className="card p-3 border-yellow-500/20 bg-yellow-500/5 text-[11px] text-yellow-400 flex items-start gap-2">
              <AlertTriangle className="w-3.5 h-3.5 shrink-0 mt-0.5" />
              <span>Perfis gerados por inteligência devem nascer como SHADOW_ONLY. Live trading permanece desativado.</span>
            </div>

            {/* Meta */}
            <div className="grid grid-cols-2 gap-2 text-[11px]">
              {[
                ["Família", selectedSuggestion.suggested_profile_family || "—"],
                ["Origem", selectedSuggestion.source_type || "—"],
                ["Run", selectedSuggestion.source_run_id || "—"],
                ["Profile", selectedSuggestion.profile_name || "—"],
                ["Validation", selectedSuggestion.validation_status || "—"],
                ["Actionability", selectedSuggestion.actionability_status || "—"],
                ["Risco", selectedSuggestion.risk_level || "—"],
                ["Status", selectedSuggestion.status],
                ["Rollback", selectedSuggestion.rollback_available ? "Disponível" : "Ausente"],
              ].map(([k, v]) => (
                <div key={k} className="bg-[var(--bg-elevated)] rounded p-2">
                  <div className="text-[10px] text-[var(--text-tertiary)]">{k}</div>
                  <div className="text-[var(--text-primary)] font-medium">{v}</div>
                </div>
              ))}
            </div>

            {selectedSuggestion.blocked_reason && (
              <div className="card p-3 border-red-500/30 bg-red-500/5 text-[11px] text-red-400">
                Bloqueado: {selectedSuggestion.blocked_reason}
              </div>
            )}

            {selectedSuggestion.source_profiles?.length ? (
              <div className="text-[11px] text-[var(--text-secondary)]">
                <div className="text-[10px] uppercase text-[var(--text-tertiary)]">Source profiles</div>
                {selectedSuggestion.source_profiles.join(", ")}
              </div>
            ) : null}

            {/* Evidence */}
            {selectedSuggestion.evidence_summary_json && (
              <div>
                <div className="text-[11px] font-semibold text-[var(--text-tertiary)] uppercase mb-2">Evidence Summary</div>
                <div className="grid grid-cols-2 gap-2">
                  {Object.entries(selectedSuggestion.evidence_summary_json as Record<string, unknown>).map(([k, v]) => (
                    <div key={k} className="bg-[var(--bg-elevated)] rounded p-2 text-[11px]">
                      <div className="text-[10px] text-[var(--text-tertiary)]">{k}</div>
                      <div className="text-[var(--text-primary)] font-medium">
                        {typeof v === "number"
                          ? (k.includes("rate") || k.includes("win") ? fmtPct(v, 3) : k.includes("pnl") || k.includes("mae") || k.includes("mfe") ? fmtPctRaw(v, 3) : v.toFixed(3))
                          : safeVal(v)}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Quantitative explanation */}
            {selectedSuggestion.quantitative_explanation && (
              <div>
                <div className="text-[11px] font-semibold text-[var(--text-tertiary)] uppercase mb-1">Explicação Quantitativa</div>
                <p className="text-[12px] text-[var(--text-secondary)] leading-relaxed">{selectedSuggestion.quantitative_explanation}</p>
              </div>
            )}

            {/* AI explanation */}
            {selectedSuggestion.ai_explanation ? (
              <div>
                <div className="text-[11px] font-semibold text-blue-400 uppercase mb-1 flex items-center gap-1"><Zap className="w-3 h-3" /> Explicação IA</div>
                <div className="bg-blue-500/5 border border-blue-500/20 rounded-lg p-3 text-[12px] text-[var(--text-secondary)] leading-relaxed whitespace-pre-wrap">
                  {selectedSuggestion.ai_explanation}
                </div>
              </div>
            ) : (
              <div>
                <button
                  className="btn btn-secondary text-[12px] flex items-center gap-1.5 w-full"
                  onClick={() => handleExplain(selectedSuggestion.id)}
                  disabled={explainingId === selectedSuggestion.id}
                >
                  <Zap className={`w-3.5 h-3.5 ${explainingId === selectedSuggestion.id ? "animate-pulse" : ""}`} />
                  {explainingId === selectedSuggestion.id ? "Gerando explicação..." : "Explicar com IA"}
                </button>
                <p className="text-[10px] text-[var(--text-tertiary)] mt-1">Requer chave Anthropic configurada. Usa apenas dados calculados — não inventa métricas.</p>
              </div>
            )}

            {/* Risk notes */}
            {selectedSuggestion.risk_notes && (
              <div className="card p-3 border-yellow-500/20 bg-yellow-500/5">
                <div className="text-[10px] font-semibold text-yellow-400 uppercase mb-1">Notas de Risco</div>
                <p className="text-[11px] text-[var(--text-secondary)]">{selectedSuggestion.risk_notes}</p>
              </div>
            )}

            {/* Config JSON */}
            {selectedSuggestion.suggested_config_json && (
              <div>
                <div className="text-[11px] font-semibold text-[var(--text-tertiary)] uppercase mb-1">Config Sugerida</div>
                <pre className="text-[10px] text-[var(--text-secondary)] bg-[var(--bg-input)] rounded p-3 overflow-x-auto max-h-48">
                  {JSON.stringify(selectedSuggestion.suggested_config_json, null, 2)}
                </pre>
              </div>
            )}

            {/* Actions */}
            <div className="flex gap-2 pt-2 border-t border-[var(--border-subtle)]">
              <button
                className="btn btn-secondary text-[12px] flex items-center gap-1.5 flex-1"
                onClick={() => { navigator.clipboard.writeText(JSON.stringify(selectedSuggestion.suggested_config_json, null, 2)); showToast("JSON copiado!"); }}
              >
                <Copy className="w-3.5 h-3.5" /> Copy JSON
              </button>
              <button
                className={`btn text-[12px] flex items-center gap-1.5 flex-1 ${
                  ["created", "applied"].includes(selectedSuggestion.status) || !suggestionIsActionable(selectedSuggestion)
                    ? "btn-secondary opacity-40 cursor-not-allowed"
                    : "btn-primary"
                }`}
                disabled={["created", "applied"].includes(selectedSuggestion.status) || !suggestionIsActionable(selectedSuggestion)}
                onClick={() => { setSelectedSuggestion(null); handleOpenCreateProfile(selectedSuggestion); }}
              >
                <BarChart3 className="w-3.5 h-3.5" />
                {["created", "applied"].includes(selectedSuggestion.status) ? "Aplicado" : "Criar Profile"}
              </button>
            </div>
          </div>
        </Drawer>
      )}

      {/* ── Create Profile Confirmation Modal ────────────────────────────────── */}
      {createProfileSuggestion && (
        <Modal
          title={createProfileResult ? "Profile Criado" : "Confirmar Criação de Profile"}
          onClose={() => { setCreateProfileSuggestion(null); setCreateDryRunResult(null); setCreateProfileResult(null); }}
        >
          <div className="space-y-4">

            {/* Safety notice — always shown */}
            <div className="card p-3 border-yellow-500/20 bg-yellow-500/5">
              <div className="flex items-start gap-2">
                <AlertTriangle className="w-4 h-4 text-yellow-400 shrink-0 mt-0.5" />
                <div className="text-[11px] text-yellow-400 space-y-0.5">
                  <p><strong>Perfis gerados por inteligência nascem como SHADOW_ONLY.</strong></p>
                  <p>Live trading permanece desativado. Este perfil é uma hipótese analítica.</p>
                </div>
              </div>
            </div>

            {/* Success state */}
            {createProfileResult && (
              <div className="space-y-4">
                <div className="card p-4 border-green-500/30 bg-green-500/5">
                  <div className="flex items-center gap-2 text-green-400 mb-2">
                    <CheckCircle className="w-5 h-5" />
                    <span className="font-semibold text-[13px]">Profile criado com sucesso!</span>
                  </div>
                  <div className="text-[11px] text-[var(--text-secondary)] space-y-1">
                    <div>Nome: <strong className="text-[var(--text-primary)]">{createProfileResult.profile_name}</strong></div>
                    <div>ID: <span className="font-mono text-[10px]">{createProfileResult.profile_id}</span></div>
                    {createProfileResult.audit_id && <div>Audit: <span className="font-mono text-[10px]">{createProfileResult.audit_id}</span></div>}
                    <div className="text-green-400">is_shadow_only: true | live_trading_enabled: false</div>
                  </div>
                </div>
                {createProfileResult.warnings?.length > 0 && (
                  <div className="text-[11px] text-yellow-400 space-y-1">
                    {createProfileResult.warnings.map((w, i) => <div key={i}>⚠️ {w}</div>)}
                  </div>
                )}
                <div className="flex gap-2">
                  <a href="/profiles" className="btn btn-primary text-[12px] flex items-center gap-1.5 flex-1 justify-center">
                    <ExternalLink className="w-3.5 h-3.5" /> Abrir em Profiles
                  </a>
                  <button
                    className="btn btn-secondary text-[12px] flex-1"
                    onClick={() => { setCreateProfileSuggestion(null); setCreateDryRunResult(null); setCreateProfileResult(null); }}
                  >
                    Fechar
                  </button>
                </div>
              </div>
            )}

            {/* Loading dry-run */}
            {!createProfileResult && createDryRunLoading && (
              <div className="text-center py-6 text-[12px] text-[var(--text-secondary)]">
                <RefreshCw className="w-6 h-6 animate-spin mx-auto mb-2 text-[var(--accent-primary)]" />
                Verificando viabilidade da criação...
              </div>
            )}

            {/* Dry-run preview */}
            {!createProfileResult && !createDryRunLoading && createDryRunResult && (
              <div className="space-y-4">
                {/* Profile preview */}
                <div className="grid grid-cols-2 gap-2 text-[11px]">
                  {[
                    ["Nome", createDryRunResult.profile_payload?.name || "—"],
                    ["Tipo", createDryRunResult.profile_payload?.profile_type || "GENERATED"],
                    ["Shadow Only", "true"],
                    ["Live Trading", "DESATIVADO"],
                    ["Confidence", `${createDryRunResult.confidence_level} (${createDryRunResult.confidence_score?.toFixed(1)})`],
                    ["Overfit Risk", createDryRunResult.overfit_risk ? "⚠️ Sim" : "Não"],
                  ].map(([k, v]) => (
                    <div key={k} className="bg-[var(--bg-elevated)] rounded p-2">
                      <div className="text-[10px] text-[var(--text-tertiary)]">{k}</div>
                      <div className={`font-medium ${k === "Live Trading" ? "text-red-400" : "text-[var(--text-primary)]"}`}>{v}</div>
                    </div>
                  ))}
                </div>

                {/* Signals */}
                {(createDryRunResult.profile_payload?.config?.signals?.conditions?.length ?? 0) > 0 && (
                  <div>
                    <div className="text-[11px] font-semibold text-[var(--text-tertiary)] uppercase mb-1">
                      Signals ({createDryRunResult.profile_payload.config.signals?.conditions?.length ?? 0})
                    </div>
                    <div className="space-y-1">
                      {createDryRunResult.profile_payload.config.signals?.conditions?.map((c: any, i: number) => (
                        <div key={i} className="font-mono text-[10px] bg-[var(--bg-input)] rounded px-2 py-1.5 text-[var(--text-primary)]">
                          {c.indicator || c.field} {c.operator} {c.value}
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Block rules */}
                {(createDryRunResult.profile_payload?.config?.block_rules?.blocks?.length ?? 0) > 0 && (
                  <div>
                    <div className="text-[11px] font-semibold text-[var(--text-tertiary)] uppercase mb-1">
                      Block Rules ({createDryRunResult.profile_payload.config.block_rules?.blocks?.length ?? 0})
                    </div>
                    <div className="space-y-1">
                      {createDryRunResult.profile_payload.config.block_rules?.blocks?.map((b: any, i: number) => (
                        <div key={i} className="font-mono text-[10px] bg-[var(--bg-input)] rounded px-2 py-1.5 text-red-400">
                          BLOCK: {b.indicator || b.field} {b.operator} {b.value}
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Master rules */}
                {(createDryRunResult.master_rules_to_create?.length > 0 || createDryRunResult.master_rules_to_reuse?.length > 0) && (
                  <div>
                    <div className="text-[11px] font-semibold text-[var(--text-tertiary)] uppercase mb-1">Scoring Rules Master</div>
                    <div className="space-y-1">
                      {createDryRunResult.master_rules_to_create?.map((r: any) => (
                        <div key={r.id} className="text-[10px] bg-green-500/10 border border-green-500/20 rounded px-2 py-1 text-green-400">
                          + NOVA: {r.name || r.indicator} ({r.points}pts)
                        </div>
                      ))}
                      {createDryRunResult.master_rules_to_reuse?.map((r: any) => (
                        <div key={r.id} className="text-[10px] bg-[var(--bg-elevated)] rounded px-2 py-1 text-[var(--text-secondary)]">
                          ↩ Reutilizar: {r.name || r.indicator}
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Warnings */}
                {createDryRunResult.warnings?.length > 0 && (
                  <div className="space-y-1">
                    {createDryRunResult.warnings.map((w, i) => (
                      <div key={i} className="text-[10px] text-yellow-400 flex items-start gap-1">
                        <AlertTriangle className="w-3 h-3 shrink-0 mt-0.5" />{w}
                      </div>
                    ))}
                  </div>
                )}

                {/* Confirmation toggles for gated cases */}
                {createDryRunResult.confidence_level === "LOW" && (
                  <label className="flex items-center gap-2 text-[12px] cursor-pointer">
                    <input type="checkbox" checked={confirmLowConfidence} onChange={e => setConfirmLowConfidence(e.target.checked)} className="w-4 h-4" />
                    <span className="text-yellow-400">Confirmo: estou ciente de que esta sugestão tem LOW confidence (menos de 30 trades).</span>
                  </label>
                )}
                {createDryRunResult.overfit_risk && (
                  <label className="flex items-center gap-2 text-[12px] cursor-pointer">
                    <input type="checkbox" checked={confirmOverfitRisk} onChange={e => setConfirmOverfitRisk(e.target.checked)} className="w-4 h-4" />
                    <span className="text-yellow-400">Confirmo: estou ciente do risco de overfitting nesta combinação.</span>
                  </label>
                )}

                {/* Final actions */}
                <div className="flex gap-2 pt-1 border-t border-[var(--border-subtle)]">
                  <button
                    className="btn btn-secondary text-[12px] flex-1"
                    onClick={() => { setCreateProfileSuggestion(null); setCreateDryRunResult(null); }}
                  >
                    Cancelar
                  </button>
                  <button
                    className={`btn btn-primary text-[12px] flex-1 flex items-center justify-center gap-1.5 ${
                      createProfileLoading ? "opacity-70" : ""
                    } ${
                      (createDryRunResult.confidence_level === "LOW" && !confirmLowConfidence) ||
                      (createDryRunResult.overfit_risk && !confirmOverfitRisk)
                        ? "opacity-40 cursor-not-allowed" : ""
                    }`}
                    disabled={
                      createProfileLoading ||
                      (createDryRunResult.confidence_level === "LOW" && !confirmLowConfidence) ||
                      (createDryRunResult.overfit_risk && !confirmOverfitRisk)
                    }
                    onClick={handleConfirmCreateProfile}
                  >
                    <BarChart3 className={`w-3.5 h-3.5 ${createProfileLoading ? "animate-pulse" : ""}`} />
                    {createProfileLoading ? "Criando..." : "Criar Profile SHADOW_ONLY"}
                  </button>
                </div>
              </div>
            )}
          </div>
        </Modal>
      )}

      {/* ── Duplicate Profile Group Drawer ───────────────────────────────────── */}
      {selectedDuplicateGroup && (
        <Drawer
          title={`${selectedDuplicateGroup[0].profile_name} — ${selectedDuplicateGroup.length} UUIDs`}
          onClose={() => setSelectedDuplicateGroup(null)}
        >
          <div className="bg-yellow-500/10 border border-yellow-500/30 rounded-lg p-3 text-[12px] text-yellow-400 flex items-start gap-2">
            <AlertTriangle className="w-4 h-4 shrink-0 mt-0.5" />
            <span>
              Existem <strong>{selectedDuplicateGroup.length} profiles com o mesmo nome</strong>.
              As métricas abaixo são individuais por UUID. Considere renomear ou consolidar
              em <a href="/profiles" className="underline hover:opacity-80">/profiles</a>.
            </span>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-[11px]">
              <thead>
                <tr className="border-b border-[var(--border-subtle)]">
                  {["UUID", "Fechados", "Wins", "Loss", "Win Rate", "Avg P&L", "Avg MAE", "Confidence"].map(h => (
                    <th key={h} className="px-3 py-2 text-left text-[10px] font-semibold text-[var(--text-tertiary)] uppercase tracking-wider whitespace-nowrap">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-[var(--border-subtle)]">
                {selectedDuplicateGroup.map(p => (
                  <tr key={p.profile_id} className="hover:bg-[var(--bg-elevated)] transition-colors">
                    <td className="px-3 py-2.5">
                      <div className="flex items-center gap-1.5">
                        <span className="font-mono text-[10px] text-[var(--text-secondary)]">{p.profile_id.slice(0, 8)}…</span>
                        <button
                          className="text-[var(--text-tertiary)] hover:text-[var(--text-primary)] transition-colors"
                          title="Copiar UUID completo"
                          onClick={() => { navigator.clipboard.writeText(p.profile_id); showToast("UUID copiado", true); }}
                        >
                          <Copy className="w-3 h-3" />
                        </button>
                      </div>
                    </td>
                    <td className="px-3 py-2.5 text-[var(--text-secondary)]">{p.closed_trades ?? "—"}</td>
                    <td className="px-3 py-2.5 text-green-400">{p.wins ?? "—"}</td>
                    <td className="px-3 py-2.5 text-red-400">{p.losses ?? "—"}</td>
                    <td className={`px-3 py-2.5 font-semibold ${winRateColor(p.win_rate)}`}>{fmtPct(p.win_rate)}</td>
                    <td className={`px-3 py-2.5 ${pnlColor(p.avg_pnl_pct)}`}>{fmtPctRaw(p.avg_pnl_pct, 2)}</td>
                    <td className={`px-3 py-2.5 ${pnlColor(p.avg_mae_pct)}`}>{fmtPctRaw(p.avg_mae_pct, 2)}</td>
                    <td className="px-3 py-2.5">{confidenceBadge(p.confidence_level)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <div className="pt-2 border-t border-[var(--border-subtle)]">
            <a
              href="/profiles"
              className="btn btn-secondary text-[12px] flex items-center gap-1.5 w-full justify-center"
            >
              <ExternalLink className="w-3.5 h-3.5" />
              Gerenciar em /profiles
            </a>
          </div>
        </Drawer>
      )}

      {selectedIndicatorAdjustment && (
        <Modal
          title="Ajuste de indicador em Shadow"
          onClose={() => {
            setSelectedIndicatorAdjustment(null);
            setIndicatorAdjustmentProfileIds([]);
          }}
        >
          <div className="space-y-4">
            <div className="grid grid-cols-[minmax(0,1fr)_auto] gap-3 border-b border-[var(--border-subtle)] pb-3">
              <div className="min-w-0">
                <div className="font-mono text-[13px] font-semibold text-[var(--text-primary)]">{selectedIndicatorAdjustment.indicator}</div>
                <div className="font-mono text-[10px] text-[var(--text-tertiary)]">{selectedIndicatorAdjustment.bucket_label}</div>
              </div>
              {statusBadge(selectedIndicatorAdjustment.validation_status)}
            </div>

            <div className="grid grid-cols-3 gap-px overflow-hidden rounded border border-[var(--border-default)] bg-[var(--border-default)]">
              {[
                ["Amostra", selectedIndicatorAdjustment.total_cases],
                [selectedIndicatorAdjustment.role_detected === "losing_indicator" ? "Loss rate" : "Win rate", fmtPct(selectedIndicatorAdjustment.role_detected === "losing_indicator" ? selectedIndicatorAdjustment.loss_rate : selectedIndicatorAdjustment.win_rate)],
                ["Lift", selectedIndicatorAdjustment.lift_vs_base != null ? `${selectedIndicatorAdjustment.lift_vs_base.toFixed(2)}x` : "—"],
              ].map(([label, value]) => (
                <div key={String(label)} className="bg-[var(--bg-surface)] px-3 py-2 text-center">
                  <div className="text-[9px] uppercase text-[var(--text-tertiary)]">{label}</div>
                  <div className="font-mono text-[13px] text-[var(--text-primary)]">{String(value)}</div>
                </div>
              ))}
            </div>

            <div>
              <div className="mb-2 text-[10px] font-semibold uppercase text-[var(--text-tertiary)]">Profiles associados</div>
              <div className="space-y-2">
                {(selectedIndicatorAdjustment.associated_profiles || []).map(profile => (
                  <label key={profile.id} className="flex cursor-pointer items-center gap-3 rounded border border-[var(--border-default)] bg-[var(--bg-surface)] px-3 py-2">
                    <input
                      type="checkbox"
                      checked={indicatorAdjustmentProfileIds.includes(profile.id)}
                      onChange={(event) => setIndicatorAdjustmentProfileIds(current => (
                        event.target.checked
                          ? [...new Set([...current, profile.id])]
                          : current.filter(id => id !== profile.id)
                      ))}
                      className="h-4 w-4 rounded"
                    />
                    <Users className="h-4 w-4 text-cyan-300" />
                    <div className="min-w-0">
                      <div className="truncate text-[11px] font-medium text-[var(--text-primary)]">{profile.name}</div>
                      <div className="truncate font-mono text-[9px] text-[var(--text-tertiary)]">{profile.id}</div>
                    </div>
                  </label>
                ))}
              </div>
            </div>

            {!selectedIndicatorAdjustment.can_apply_shadow_adjustment && (
              <div className="flex items-start gap-2 rounded border border-yellow-500/30 bg-yellow-500/5 p-3 text-[11px] text-yellow-300">
                <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" />
                <div>
                  <div className="font-semibold">Aguardando validação temporal</div>
                  <div className="mt-0.5 text-yellow-200/70">{selectedIndicatorAdjustment.adjustment_blocked_reason || "exploratory_only"}</div>
                </div>
              </div>
            )}

            <div className="rounded border border-cyan-400/20 bg-cyan-400/5 p-3 text-[10px] text-cyan-100/80">
              {selectedIndicatorAdjustment.role_detected === "losing_indicator"
                ? "A penalidade será adicionada somente a um challenger shadow versionado."
                : "A condição será substituída somente em um challenger shadow versionado."}
              <span className="ml-1 font-semibold text-cyan-200">O profile incumbent não será alterado.</span>
            </div>

            <div className="flex gap-2 border-t border-[var(--border-subtle)] pt-3">
              <button
                className="btn btn-secondary flex-1 text-[11px]"
                onClick={() => {
                  setSelectedIndicatorAdjustment(null);
                  setIndicatorAdjustmentProfileIds([]);
                }}
              >
                Cancelar
              </button>
              <button
                className="btn btn-primary flex flex-1 items-center justify-center gap-1.5 text-[11px]"
                disabled={
                  indicatorAdjustmentLoading
                  || !selectedIndicatorAdjustment.can_apply_shadow_adjustment
                  || indicatorAdjustmentProfileIds.length === 0
                }
                onClick={handleIndicatorShadowAdjustment}
              >
                <SlidersHorizontal className={`h-3.5 w-3.5 ${indicatorAdjustmentLoading ? "animate-pulse" : ""}`} />
                {indicatorAdjustmentLoading ? "Preparando..." : "Criar challenger shadow"}
              </button>
            </div>
          </div>
        </Modal>
      )}

      {/* ── Run Analysis Modal ────────────────────────────────────────────────── */}
      {showRunModal && (
        <Modal title="Run Analysis" onClose={() => { setShowRunModal(false); setRunResult(null); }}>
          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-3">
              {[
                { key: "lookback_days", label: "Lookback (dias)", step: 1 },
                { key: "min_closed_trades", label: "Min Closed Trades", step: 1 },
                { key: "max_combinations", label: "Max Combinations", step: 50 },
              ].map(({ key, label, step }) => (
                <div key={key}>
                  <label className="block text-[11px] font-medium text-[var(--text-tertiary)] uppercase tracking-wider mb-1">{label}</label>
                  <input
                    type="number"
                    step={step}
                    value={(runPayload as any)[key]}
                    onChange={e => setRunPayload(p => ({ ...p, [key]: parseInt(e.target.value) || 0 }))}
                    className="w-full bg-[var(--bg-input)] border border-[var(--border-default)] rounded-lg px-3 py-2 text-[13px] text-[var(--text-primary)] focus:outline-none focus:border-[var(--accent-primary)]"
                  />
                </div>
              ))}
            </div>

            <div className="space-y-2">
              {[
                { key: "include_counterfactual", label: "Counterfactual Miner" },
                { key: "include_dynamic_combinations", label: "Dynamic Combinations" },
                { key: "include_association_rules", label: "Association Rules" },
                { key: "include_optuna", label: "Optuna Search (pesado)" },
                { key: "include_ai_explanation", label: "AI Explanation (consome tokens)" },
              ].map(({ key, label }) => (
                <label key={key} className="flex items-center justify-between text-[12px] cursor-pointer">
                  <span className="text-[var(--text-secondary)]">{label}</span>
                  <input
                    type="checkbox"
                    checked={(runPayload as any)[key]}
                    onChange={e => setRunPayload(p => ({ ...p, [key]: e.target.checked }))}
                    className="w-4 h-4 rounded"
                  />
                </label>
              ))}
            </div>

            {runResult && (
              <div className={`card p-3 border ${runResult.ok ? "border-green-500/30 bg-green-500/5" : "border-red-500/30 bg-red-500/5"}`}>
                {runResult.ok ? (
                  <div className="flex items-center gap-2 text-[12px] text-green-400">
                    <CheckCircle className="w-4 h-4" />
                    <div>
                      <div>Análise iniciada com sucesso.</div>
                      <div className="text-[10px] font-mono mt-0.5">Run ID: {runResult.run_id}</div>
                      <div className="text-[10px] text-[var(--text-tertiary)] mt-0.5">Resultados disponíveis em alguns minutos. Use Refresh para atualizar.</div>
                    </div>
                  </div>
                ) : (
                  <div className="text-[12px] text-red-400 flex items-start gap-2">
                    <AlertTriangle className="w-4 h-4 shrink-0 mt-0.5" />
                    <span>{runResult.error}</span>
                  </div>
                )}
              </div>
            )}

            <div className="flex gap-2 pt-2">
              <button
                className="btn btn-secondary text-[12px] flex-1"
                onClick={() => { setShowRunModal(false); setRunResult(null); }}
              >
                Fechar
              </button>
              <button
                className="btn btn-primary text-[12px] flex-1 flex items-center justify-center gap-1.5"
                onClick={handleRun}
                disabled={running}
              >
                <Play className={`w-3.5 h-3.5 ${running ? "animate-pulse" : ""}`} />
                {running ? "Iniciando..." : "Iniciar Análise"}
              </button>
            </div>
          </div>
        </Modal>
      )}

      {/* ── Settings Modal (from header button) ──────────────────────────────── */}
      {showSettingsModal && (
        <Modal title="Engine Settings" onClose={() => setShowSettingsModal(false)}>
          <div className="text-[12px] text-[var(--text-secondary)] space-y-2">
            <p>Acesse a aba <strong className="text-[var(--text-primary)]">Settings</strong> para configurar o engine.</p>
            <button
              className="btn btn-primary text-[12px] w-full"
              onClick={() => { setShowSettingsModal(false); setActiveTab("Settings"); }}
            >
              Ir para Settings
            </button>
          </div>
        </Modal>
      )}
    </div>
  );
}

// ── Reusable sub-components (inline) ──────────────────────────────────────────

function EmptyState({ message, onRun }: { message: string; onRun?: () => void }) {
  return (
    <div className="p-10 text-center">
      <Brain className="w-10 h-10 text-[var(--text-tertiary)] opacity-30 mx-auto mb-3" />
      <p className="text-[13px] text-[var(--text-secondary)] max-w-sm mx-auto">{message}</p>
      {onRun && (
        <button className="btn btn-primary mt-4 text-[12px] flex items-center gap-1.5 mx-auto" onClick={onRun}>
          <Play className="w-3.5 h-3.5" /> Executar análise
        </button>
      )}
    </div>
  );
}

function TableSkeleton() {
  return (
    <div className="p-4 space-y-2">
      {[...Array(5)].map((_, i) => <div key={i} className="skeleton h-9 rounded" />)}
    </div>
  );
}

function Drawer({ title, children, onClose }: { title: string; children: React.ReactNode; onClose: () => void }) {
  return (
    <div className="fixed inset-0 z-50 flex">
      <div className="flex-1 bg-black/50" onClick={onClose} />
      <div className="w-full max-w-xl bg-[var(--bg-surface)] border-l border-[var(--border-default)] flex flex-col overflow-hidden">
        <div className="flex items-center justify-between px-5 py-4 border-b border-[var(--border-default)] shrink-0">
          <h2 className="text-[14px] font-semibold text-[var(--text-primary)] truncate pr-4">{title}</h2>
          <button onClick={onClose} className="text-[var(--text-tertiary)] hover:text-[var(--text-primary)] transition-colors">
            <X className="w-5 h-5" />
          </button>
        </div>
        <div className="flex-1 overflow-y-auto p-5 space-y-4 custom-scrollbar">
          {children}
        </div>
      </div>
    </div>
  );
}

function Modal({ title, children, onClose }: { title: string; children: React.ReactNode; onClose: () => void }) {
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/60" onClick={onClose} />
      <div className="relative w-full max-w-lg bg-[var(--bg-elevated)] border border-[var(--border-default)] rounded-[var(--radius-lg)] shadow-2xl flex flex-col max-h-[90vh]">
        <div className="flex items-center justify-between px-5 py-4 border-b border-[var(--border-default)] shrink-0">
          <h2 className="text-[14px] font-semibold text-[var(--text-primary)]">{title}</h2>
          <button onClick={onClose} className="text-[var(--text-tertiary)] hover:text-[var(--text-primary)] transition-colors">
            <X className="w-5 h-5" />
          </button>
        </div>
        <div className="overflow-y-auto p-5 custom-scrollbar">
          {children}
        </div>
      </div>
    </div>
  );
}

'use client'

import { useState, useEffect } from 'react'
import { useParams, useSearchParams, useRouter } from 'next/navigation'
import { ArrowLeft, Save, Play, Settings, Brain, Zap, Filter, Target } from 'lucide-react'
import { apiGet, apiPut } from '@/lib/api'
import { ProfileBuilder } from '@/components/profiles/ProfileBuilder'

interface Profile {
  id: string
  name: string
  description?: string
  is_active: boolean
  profile_role?: string | null
  config?: any
  auto_pilot_enabled?: boolean
  auto_pilot_config?: any
}

export default function ProfileEditPage() {
  const params = useParams()
  const searchParams = useSearchParams()
  const router = useRouter()
  const profileId = params.id as string
  const initialTab = searchParams.get('tab') || 'config'

  const [profile, setProfile] = useState<Profile | null>(null)
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [activeTab, setActiveTab] = useState(initialTab)
  const [autoPilotConfig, setAutoPilotConfig] = useState<any>({
    enabled: false,
    schedules: [],
    event_triggers: {},
  })

  useEffect(() => {
    loadProfile()
  }, [profileId])

  const loadProfile = async () => {
    setLoading(true)
    try {
      const data = await apiGet(`/profiles/${profileId}`)
      setProfile(data)
      if (data.auto_pilot_config) {
        setAutoPilotConfig(data.auto_pilot_config)
      }
    } catch (e) {
      console.error('Failed to load profile:', e)
    } finally {
      setLoading(false)
    }
  }

  const handleSave = async (profileData: any) => {
    setSaving(true)
    try {
      await apiPut(`/profiles/${profileId}`, profileData)
      router.push('/profiles')
    } catch (e: any) {
      alert(`Erro ao salvar: ${e.message}`)
    } finally {
      setSaving(false)
    }
  }

  const handleSaveAutoPilot = async () => {
    setSaving(true)
    try {
      await apiPut(`/profiles/${profileId}/auto-pilot`, autoPilotConfig)
      alert('Auto-Pilot configurado com sucesso!')
    } catch (e: any) {
      alert(`Erro: ${e.message}`)
    } finally {
      setSaving(false)
    }
  }

  if (loading) {
    return (
      <div style={{ padding: 24 }}>
        <div className="skeleton" style={{ height: 40, width: 200, borderRadius: 8, marginBottom: 24 }} />
        <div className="skeleton" style={{ height: 400, borderRadius: 12 }} />
      </div>
    )
  }

  if (!profile) {
    return (
      <div style={{ padding: 24, textAlign: 'center' }}>
        <p style={{ color: 'var(--text-tertiary)' }}>Profile não encontrado.</p>
        <button onClick={() => router.push('/profiles')} style={{ marginTop: 16 }} className="btn btn-secondary">
          Voltar
        </button>
      </div>
    )
  }

  const tabs = [
    { id: 'config', label: 'Configuração', icon: Settings },
    { id: 'auto_pilot', label: 'Auto-Pilot IA', icon: Brain },
  ]

  return (
    <div style={{ padding: 24 }}>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 16, marginBottom: 24 }}>
        <button
          onClick={() => router.push('/profiles')}
          style={{
            background: 'var(--bg-elevated)',
            border: '1px solid var(--border-default)',
            borderRadius: 8,
            padding: 8,
            cursor: 'pointer',
            display: 'flex',
          }}
        >
          <ArrowLeft size={18} color="var(--text-secondary)" />
        </button>
        <div style={{ flex: 1 }}>
          <h1 style={{ fontSize: 20, fontWeight: 700, color: 'var(--text-primary)', margin: 0 }}>
            {profile.name}
          </h1>
          <p style={{ fontSize: 12, color: 'var(--text-tertiary)', margin: '4px 0 0' }}>
            Editar configurações do profile
          </p>
        </div>
      </div>

      {/* Tabs */}
      <div style={{
        display: 'flex',
        gap: 4,
        marginBottom: 24,
        padding: 4,
        background: 'var(--bg-elevated)',
        borderRadius: 10,
        width: 'fit-content',
      }}>
        {tabs.map(tab => {
          const Icon = tab.icon
          const isActive = activeTab === tab.id
          return (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: 6,
                padding: '8px 16px',
                fontSize: 13,
                fontWeight: isActive ? 600 : 500,
                borderRadius: 8,
                border: 'none',
                cursor: 'pointer',
                background: isActive ? 'var(--accent-primary)' : 'transparent',
                color: isActive ? '#fff' : 'var(--text-secondary)',
                transition: 'all 150ms',
              }}
            >
              <Icon size={14} />
              {tab.label}
            </button>
          )
        })}
      </div>

      {/* Tab Content */}
      {activeTab === 'config' && (
        <ProfileBuilder
          profile={profile}
          onSave={handleSave}
          onCancel={() => router.push('/profiles')}
        />
      )}

      {activeTab === 'auto_pilot' && (
        <div className="card">
          <div className="card-body" style={{ padding: 24 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 24 }}>
              <div style={{
                width: 44,
                height: 44,
                borderRadius: 12,
                background: 'rgba(52,211,153,0.1)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
              }}>
                <Brain size={22} color="#34D399" />
              </div>
              <div>
                <h2 style={{ fontSize: 16, fontWeight: 700, color: 'var(--text-primary)', margin: 0 }}>
                  Auto-Pilot IA
                </h2>
                <p style={{ fontSize: 12, color: 'var(--text-secondary)', margin: '4px 0 0' }}>
                  Configure análise automática baseada em IA
                </p>
              </div>
            </div>

            {/* Enable Toggle */}
            <div style={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              padding: '16px 20px',
              background: autoPilotConfig.enabled ? 'rgba(52,211,153,0.06)' : 'var(--bg-secondary)',
              border: `1px solid ${autoPilotConfig.enabled ? 'rgba(52,211,153,0.2)' : 'var(--border-default)'}`,
              borderRadius: 10,
              marginBottom: 20,
            }}>
              <div>
                <div style={{ fontSize: 14, fontWeight: 600, color: 'var(--text-primary)' }}>
                  Habilitar Auto-Pilot
                </div>
                <div style={{ fontSize: 12, color: 'var(--text-secondary)', marginTop: 4 }}>
                  Análise automática será executada nos horários configurados
                </div>
              </div>
              <button
                onClick={() => setAutoPilotConfig({ ...autoPilotConfig, enabled: !autoPilotConfig.enabled })}
                style={{
                  position: 'relative',
                  width: 48,
                  height: 26,
                  borderRadius: 13,
                  border: 'none',
                  cursor: 'pointer',
                  background: autoPilotConfig.enabled ? '#34D399' : 'rgba(255,255,255,0.1)',
                  transition: 'background 200ms',
                }}
              >
                <span style={{
                  position: 'absolute',
                  width: 20,
                  height: 20,
                  borderRadius: '50%',
                  background: '#fff',
                  top: 3,
                  left: autoPilotConfig.enabled ? 25 : 3,
                  transition: 'left 200ms',
                }} />
              </button>
            </div>

            {/* Schedule */}
            <div style={{ marginBottom: 20 }}>
              <label style={{
                display: 'block',
                fontSize: 12,
                fontWeight: 600,
                color: 'var(--text-tertiary)',
                marginBottom: 8,
                textTransform: 'uppercase',
                letterSpacing: '0.04em',
              }}>
                Horários de execução (UTC)
              </label>
              <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                {['00:30', '06:00', '12:00', '18:00'].map(time => {
                  const isSelected = autoPilotConfig.schedules?.includes(time)
                  return (
                    <button
                      key={time}
                      onClick={() => {
                        const schedules = autoPilotConfig.schedules || []
                        if (isSelected) {
                          setAutoPilotConfig({
                            ...autoPilotConfig,
                            schedules: schedules.filter((t: string) => t !== time),
                          })
                        } else {
                          setAutoPilotConfig({
                            ...autoPilotConfig,
                            schedules: [...schedules, time],
                          })
                        }
                      }}
                      style={{
                        padding: '8px 16px',
                        fontSize: 13,
                        fontWeight: 600,
                        fontFamily: 'var(--font-mono)',
                        borderRadius: 8,
                        border: `1px solid ${isSelected ? '#34D399' : 'var(--border-default)'}`,
                        background: isSelected ? 'rgba(52,211,153,0.1)' : 'transparent',
                        color: isSelected ? '#34D399' : 'var(--text-secondary)',
                        cursor: 'pointer',
                      }}
                    >
                      {time}
                    </button>
                  )
                })}
              </div>
            </div>

            {/* Event Triggers */}
            <div style={{ marginBottom: 24 }}>
              <label style={{
                display: 'block',
                fontSize: 12,
                fontWeight: 600,
                color: 'var(--text-tertiary)',
                marginBottom: 8,
                textTransform: 'uppercase',
                letterSpacing: '0.04em',
              }}>
                Gatilhos de evento
              </label>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                {[
                  { key: 'on_regime_change', label: 'Mudança de regime de mercado' },
                  { key: 'on_high_volatility', label: 'Alta volatilidade detectada' },
                  { key: 'on_macro_event', label: 'Evento macro relevante' },
                ].map(trigger => {
                  const isEnabled = autoPilotConfig.event_triggers?.[trigger.key]
                  return (
                    <label
                      key={trigger.key}
                      style={{
                        display: 'flex',
                        alignItems: 'center',
                        gap: 12,
                        padding: '12px 16px',
                        background: 'var(--bg-secondary)',
                        borderRadius: 8,
                        cursor: 'pointer',
                      }}
                    >
                      <input
                        type="checkbox"
                        checked={isEnabled}
                        onChange={(e) => {
                          setAutoPilotConfig({
                            ...autoPilotConfig,
                            event_triggers: {
                              ...autoPilotConfig.event_triggers,
                              [trigger.key]: e.target.checked,
                            },
                          })
                        }}
