                        {trigger.label}
                      </span>
                    </label>
                  )
                })}
              </div>
            </div>

            {/* Save Button */}
            <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
              <button
                onClick={handleSaveAutoPilot}
                disabled={saving}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: 8,
                  padding: '10px 20px',
                  fontSize: 13,
                  fontWeight: 600,
                  borderRadius: 8,
                  border: 'none',
                  background: 'var(--accent-primary)',
                  color: '#fff',
                  cursor: saving ? 'wait' : 'pointer',
                  opacity: saving ? 0.7 : 1,
                }}
              >
                <Save size={14} />
                {saving ? 'Salvando...' : 'Salvar Auto-Pilot'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

