"use client";

import { useEffect, useState } from "react";
import { Plus, Settings2, Trash2, Play, Copy, Layers, ListChecks, FileJson } from "lucide-react";
import { apiGet, apiPost, apiDelete, apiPut } from "@/lib/api";
import { ProfileBuilder } from "@/components/profiles/ProfileBuilder";
import { ProfileCard } from "@/components/profiles/ProfileCard";
import { BulkProfileBuilder } from "@/components/profiles/BulkProfileBuilder";
import { JsonImportBuilder } from "@/components/profiles/JsonImportBuilder";
import { ModuleAIAnalysisAction } from "@/components/ai/ModuleAIAnalysisAction";

interface Profile {
  id: string;
  name: string;
  description: string;
  is_active: boolean;
  config: ProfileConfig;
  created_at: string;
  updated_at: string;
}

interface ProfileConfig {
  filters: {
    logic: string;
    conditions: Condition[];
  };
  scoring: {
    weights: {
      liquidity: number;
      market_structure: number;
      momentum: number;
      signal: number;
    };
  };
  signals: {
    logic: string;
    conditions: Condition[];
  };
}

interface Condition {
  field: string;
  operator: string;
  value: any;
  required?: boolean;
}

export default function ProfilesPage() {
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [loading, setLoading] = useState(true);
  const [showBuilder, setShowBuilder] = useState(false);
  const [showBulkBuilder, setShowBulkBuilder] = useState(false);
  const [showJsonImport, setShowJsonImport] = useState(false);
  const [editingProfile, setEditingProfile] = useState<Profile | null>(null);
  const [testResults, setTestResults] = useState<any>(null);
  const [selectedProfiles, setSelectedProfiles] = useState<Set<string>>(new Set());

  const fetchProfiles = async () => {
    setLoading(true);
    try {
      const data = await apiGet("/profiles");
      setProfiles(data.profiles || []);
    } catch (e) {
      console.error(e);
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchProfiles();
  }, []);

  const handleCreate = () => {
    setEditingProfile(null);
    setShowBuilder(true);
  };

  const handleEdit = (profile: Profile) => {
    setEditingProfile(profile);
    setShowBuilder(true);
  };

  const handleDelete = async (profileId: string) => {
    if (!confirm("Are you sure you want to delete this profile?")) return;
    try {
      await apiDelete(`/profiles/${profileId}`);
      fetchProfiles();
    } catch (e: any) {
      alert(`Failed to delete: ${e.message}`);
    }
  };

  const handleTest = async (profileId: string) => {
    try {
      const result = await apiPost(`/profiles/${profileId}/test`);
      setTestResults(result);
    } catch (e: any) {
      alert(`Test failed: ${e.message}`);
    }
  };

  const handleSave = async (profileData: any) => {
    try {
      if (editingProfile) {
        await apiPut(`/profiles/${editingProfile.id}`, profileData);
      } else {
        await apiPost("/profiles", profileData);
      }
      setShowBuilder(false);
      setEditingProfile(null);
      fetchProfiles();
    } catch (e: any) {
      alert(`Failed to save: ${e.message}`);
    }
  };

  const handleDuplicate = async (profile: Profile) => {
    try {
      await apiPost("/profiles", {
        name: `${profile.name} (Copy)`,
        description: profile.description,
        config: profile.config,
      });
      fetchProfiles();
    } catch (e: any) {
      alert(`Failed to duplicate: ${e.message}`);
    }
  };

  if (showBuilder) {
    return (
      <ProfileBuilder
        profile={editingProfile}
        onSave={handleSave}
        onCancel={() => {
          setShowBuilder(false);
          setEditingProfile(null);
        }}
      />
    );
  }

  if (showBulkBuilder) {
    return (
      <BulkProfileBuilder
        selectedProfiles={profiles.filter(p => selectedProfiles.has(p.id))}
        onClose={() => {
          setShowBulkBuilder(false);
          setSelectedProfiles(new Set());
          fetchProfiles();
        }}
      />
    );
  }

  if (showJsonImport) {
    return (
      <JsonImportBuilder
        onClose={() => {
          setShowJsonImport(false);
          fetchProfiles();
        }}
      />
    );
  }

  const toggleSelectAll = () => {
    if (selectedProfiles.size === profiles.length) {
      setSelectedProfiles(new Set());
    } else {
      setSelectedProfiles(new Set(profiles.map((p) => p.id)));
    }
  };

  const toggleSelectProfile = (id: string) => {
    const next = new Set(selectedProfiles);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedProfiles(next);
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-[var(--text-primary)]">
            Strategy Profiles
          </h1>
          <p className="text-[var(--text-secondary)] mt-1 text-[13px]">
            Define custom filters, scoring weights, and signal conditions.
          </p>
        </div>
        <div className="flex items-center gap-3">
          <ModuleAIAnalysisAction
            originModule="strategy_profiles"
            originView="profiles-list"
            entityIds={Array.from(selectedProfiles)}
            supportsRegenerative
          />
          {selectedProfiles.size > 0 && (
            <div className="flex items-center gap-3 mr-4">
              <span className="text-[13px] text-[var(--text-secondary)] font-medium">
                {selectedProfiles.size} selected
              </span>
              <button
                className="btn btn-secondary text-[12px] px-3 py-1.5"
                onClick={() => setSelectedProfiles(new Set())}
              >
                Clear
              </button>
              <button
                className="btn btn-secondary bg-[var(--accent-primary)]/10 text-[var(--accent-primary)] border-[var(--accent-primary)]/30 text-[12px] px-3 py-1.5"
                onClick={() => setShowBulkBuilder(true)}
              >
                <ListChecks className="w-3.5 h-3.5 mr-1.5" />
                Bulk Edit Indicators
              </button>
            </div>
          )}
          <button
            className="btn btn-secondary"
            onClick={toggleSelectAll}
            title={selectedProfiles.size === profiles.length ? "Deselect All" : "Select All"}
          >
            <ListChecks className="w-4 h-4 mr-2" />
            {selectedProfiles.size === profiles.length ? "Deselect All" : "Select All"}
          </button>
          <button
            className="btn btn-secondary"
            onClick={() => setShowJsonImport(true)}
            title="Criar profiles em massa via JSON"
          >
            <FileJson className="w-4 h-4 mr-2" />
            Import JSON
          </button>
          <button
            className="btn btn-primary"
            onClick={handleCreate}
            data-testid="create-profile-btn"
          >
            <Plus className="w-4 h-4 mr-2" />
            Create Profile
          </button>
        </div>
      </div>

      {/* Test Results Modal */}
      {testResults && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-[var(--bg-card)] rounded-lg p-6 max-w-2xl w-full mx-4 max-h-[80vh] overflow-auto">
            <h3 className="text-lg font-bold mb-4 text-[var(--text-primary)]">
              Test Results: {testResults.profile_name}
            </h3>

            <div className="grid grid-cols-2 gap-4 mb-4">
              <div className="bg-[var(--bg-secondary)] p-4 rounded-lg">
                <div className="text-[var(--text-tertiary)] text-xs mb-1">Assets Analyzed</div>
                <div className="text-2xl font-bold text-[var(--text-primary)]">
                  {testResults.summary?.total_assets || 0}
                </div>
              </div>
              <div className="bg-[var(--bg-secondary)] p-4 rounded-lg">
                <div className="text-[var(--text-tertiary)] text-xs mb-1">Passed Filters</div>
                <div className="text-2xl font-bold text-[var(--color-profit)]">
                  {testResults.summary?.after_filter || 0}
                </div>
              </div>
              <div className="bg-[var(--bg-secondary)] p-4 rounded-lg">
                <div className="text-[var(--text-tertiary)] text-xs mb-1">Filter Rate</div>
                <div className="text-2xl font-bold text-[var(--text-primary)]">
                  {testResults.summary?.filter_rate || "0%"}
                </div>
              </div>
              <div className="bg-[var(--bg-secondary)] p-4 rounded-lg">
                <div className="text-[var(--text-tertiary)] text-xs mb-1">Signals Triggered</div>
                <div className="text-2xl font-bold text-[var(--accent-primary)]">
                  {testResults.summary?.signals_triggered || 0}
                </div>
              </div>
            </div>

            <div className="mb-4">
              <h4 className="font-semibold mb-2 text-[var(--text-primary)]">Score Distribution</h4>
              <div className="flex gap-2">
                <span className="badge bullish">Strong Buy: {testResults.score_distribution?.strong_buy || 0}</span>
                <span className="badge range">Buy: {testResults.score_distribution?.buy || 0}</span>
                <span className="badge">Neutral: {testResults.score_distribution?.neutral || 0}</span>
                <span className="badge bearish">Avoid: {testResults.score_distribution?.avoid || 0}</span>
              </div>
            </div>

            <button
              className="btn btn-secondary w-full mt-4"
              onClick={() => setTestResults(null)}
            >
              Close
            </button>
          </div>
        </div>
      )}

      {/* Profiles Grid */}
      {loading ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {[1, 2, 3].map((i) => (
            <div key={i} className="skeleton h-48 rounded-[var(--radius-lg)]" />
          ))}
        </div>
      ) : profiles.length === 0 ? (
        <div className="card border-dashed border-2 border-[var(--border-subtle)] bg-transparent">
          <div className="card-body text-center py-16">
            <Layers className="w-12 h-12 text-[var(--text-tertiary)] opacity-30 mx-auto mb-4" />
            <h3 className="text-[15px] font-semibold text-[var(--text-primary)] mb-1">
              No Profiles Yet
            </h3>
            <p className="text-[var(--text-secondary)] text-[13px] max-w-sm mx-auto mb-6">
              Profiles define your trading strategy: filters, scoring weights, and signal conditions.
            </p>
            <button className="btn btn-primary" onClick={handleCreate}>
              <Plus className="w-4 h-4 mr-2" />
              Create First Profile
            </button>
          </div>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {profiles.map((profile) => (
            <ProfileCard
              key={profile.id}
              profile={profile}
              selected={selectedProfiles.has(profile.id)}
              onSelectToggle={() => toggleSelectProfile(profile.id)}
              onEdit={() => handleEdit(profile)}
              onDelete={() => handleDelete(profile.id)}
              onTest={() => handleTest(profile.id)}
              onDuplicate={() => handleDuplicate(profile)}
            />
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';

const API_URL = '/api'; // Always use Next.js rewrite proxy to avoid CORS

export default function RegisterPage() {
  const router = useRouter();
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  function validate(): string | null {
    if (!name.trim()) return 'Name is required';
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return 'Enter a valid email address';
    if (password.length < 6) return 'Password must be at least 6 characters';
    if (password !== confirmPassword) return 'Passwords do not match';
    return null;
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError('');
    const validationError = validate();
    if (validationError) {
      setError(validationError);
      return;
    }
    setLoading(true);
    try {
      const res = await fetch(`${API_URL}/auth/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, email, password }),
      });
      if (!res.ok) {
        const data = await res.json().catch(() => ({}));
        throw new Error(data.detail ?? 'Registration failed');
      }
      router.push('/login');
    } catch (err: any) {
      setError(err.message ?? 'Registration failed');
    } finally {
      setLoading(false);
    }
  }

  const inputStyle: React.CSSProperties = {
    width: '100%',
    padding: '10px 12px',
    background: 'var(--bg-input)',
    border: '1px solid var(--border-default)',
    borderRadius: 'var(--radius-md)',
    color: 'var(--text-primary)',
    fontSize: '14px',
    outline: 'none',
    boxSizing: 'border-box',
  };

  const labelStyle: React.CSSProperties = {
    display: 'block',
    marginBottom: '6px',
    fontSize: '13px',
    fontWeight: '500',
    color: 'var(--text-secondary)',
  };

  return (
    <div
      style={{
        minHeight: '100vh',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        background: 'var(--bg-base)',
        padding: '24px',
      }}
    >
      <div
        style={{
          width: '100%',
          maxWidth: '400px',
          background: 'var(--bg-surface)',
          border: '1px solid var(--border-default)',
          borderRadius: 'var(--radius-xl)',
          padding: '40px',
          boxShadow: 'var(--shadow-lg)',
        }}
      >
        <div style={{ textAlign: 'center', marginBottom: '32px' }}>
          <h1
            style={{
              fontSize: '24px',
              fontWeight: '700',
              color: 'var(--text-primary)',
              letterSpacing: '-0.02em',
            }}
          >
            Scalpyn
          </h1>
          <p style={{ marginTop: '8px', color: 'var(--text-secondary)', fontSize: '14px' }}>
            Create your account
          </p>
        </div>

        <form onSubmit={handleSubmit} noValidate>
          <div style={{ marginBottom: '16px' }}>
            <label htmlFor="name" style={labelStyle}>Name</label>
            <input
              id="name"
              type="text"
              required
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="Your name"
              style={inputStyle}
            />
          </div>

          <div style={{ marginBottom: '16px' }}>
            <label htmlFor="email" style={labelStyle}>Email</label>
            <input
              id="email"
              type="email"
              required
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="you@example.com"
              style={inputStyle}
            />
          </div>

          <div style={{ marginBottom: '16px' }}>
            <label htmlFor="password" style={labelStyle}>Password</label>
            <input
              id="password"
              type="password"
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Min. 6 characters"
              style={inputStyle}
            />
          </div>

          <div style={{ marginBottom: '24px' }}>
            <label htmlFor="confirmPassword" style={labelStyle}>Confirm Password</label>
            <input
              id="confirmPassword"
              type="password"
              required
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              placeholder="Repeat password"
              style={inputStyle}
            />
          </div>

          {error && (
            <div
              style={{
                marginBottom: '16px',
                padding: '10px 12px',
                background: 'var(--color-loss-muted)',
                border: '1px solid var(--color-loss-border)',
                borderRadius: 'var(--radius-md)',
                color: 'var(--color-loss)',
                fontSize: '13px',
              }}
            >
              {error}
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            style={{
              width: '100%',
              padding: '11px',
              background: loading ? 'var(--accent-primary-muted)' : 'var(--accent-primary)',
              border: 'none',
              borderRadius: 'var(--radius-md)',
              color: loading ? 'var(--accent-primary)' : '#fff',
              fontSize: '14px',
              fontWeight: '600',
              cursor: loading ? 'not-allowed' : 'pointer',
              transition: 'background 0.15s',
            }}
          >
            {loading ? 'Creating account…' : 'Create Account'}
          </button>
        </form>

        <p
          style={{
            marginTop: '24px',
            textAlign: 'center',
            fontSize: '13px',
            color: 'var(--text-secondary)',
          }}
        >
          Already have an account?{' '}
          <Link
            href="/login"
            style={{ color: 'var(--accent-primary)', textDecoration: 'none', fontWeight: '500' }}
          >
            Sign in
          </Link>
        </p>
      </div>
    </div>
  );
}

