import { AlertCircle, FileJson, Save, RefreshCw, Plus, Trash2, Upload, X } from "lucide-react";
import { useConfig } from "@/hooks/useConfig";
import { ModuleAIAnalysisAction } from "@/components/ai/ModuleAIAnalysisAction";

const INDICATORS = [
