function InfoBanner({
  children,
  variant = 'accent',
}: {
  children: React.ReactNode;
  variant?: 'accent' | 'warning';
}) {
  const isWarning = variant === 'warning';
  return (
    <div
      style={{
        padding: '10px 14px',
