        title="Scanner & 5-Layer Scoring"
        icon={<Layers size={16} />}
        defaultOpen={true}
      >
        <div style={{ display: 'flex', flexDirection: 'column', gap: '24px' }}>
          <SectionGrid>
            <SliderWithValue
              label="Scan Interval"
