                        borderRadius: 'var(--radius-sm)',
                        fontFamily: 'var(--font-mono)',
                        fontSize: '13px',
                        fontWeight: 700,
                        color: 'var(--accent-primary)',
                        textAlign: 'right',
                        outline: 'none',
                        MozAppearance: 'textfield',
