                      e.currentTarget.style.borderColor = 'var(--accent-primary)';
                      e.currentTarget.style.boxShadow = '0 0 0 3px var(--accent-primary-muted)';
                    }}
                    onBlur={(e) => {
                      e.currentTarget.style.borderColor = 'var(--border-default)';
                      e.currentTarget.style.boxShadow = 'none';
                    }}
                  />
                </div>
              ))}
              <div
                style={{
                  padding: '8px 14px',
                  fontSize: '11px',
                  color: 'var(--text-tertiary)',
                  fontStyle: 'italic',
                  borderTop: '1px solid var(--border-subtle)',
                  background: 'var(--bg-hover)',
                }}
              >
                (Below {config?.macro_gate?.thresholds?.risk_off ?? 20} = Strong Risk-Off — trading halted)
              </div>
            </div>
          </Subsection>

          <SectionGrid>
            <SliderWithValue
              label="Neutral Size Reduction %"
              value={config?.macro_gate?.neutral_size_reduction_pct ?? 50}
              onChange={(v) => updateConfig('macro_gate.neutral_size_reduction_pct', v)}
              min={0}
              max={100}
              unit="%"
            />
            <SliderWithValue
              label="Pre-Event Buffer"
              value={config?.macro_gate?.pre_event_buffer_hours ?? 4}
              onChange={(v) => updateConfig('macro_gate.pre_event_buffer_hours', v)}
              min={0}
              max={24}
              unit="h"
            />
            <SliderWithValue
              label="Pre-Event Size Cut %"
              value={config?.macro_gate?.pre_event_size_cut_pct ?? 50}
              onChange={(v) => updateConfig('macro_gate.pre_event_size_cut_pct', v)}
              min={0}
              max={100}
              unit="%"
            />
          </SectionGrid>
        </div>
      </ConfigSection>

      {/* ── SECTION 8: Loss Limits & Circuit Breaker ──────────────────────── */}
      <ConfigSection
        title="Loss Limits & Circuit Breaker"
        icon={<AlertOctagon size={16} />}
        defaultOpen={false}
      >
        <div style={{ display: 'flex', flexDirection: 'column', gap: '24px' }}>
          <SectionGrid>
            <SliderWithValue
              label="Daily Loss Limit %"
              value={config?.loss_limits?.daily_loss_limit_pct ?? 5}
              onChange={(v) => updateConfig('loss_limits.daily_loss_limit_pct', v)}
              min={0.5}
              max={20}
              step={0.5}
              decimals={1}
              unit="%"
              hint={`≈ $${((10000 * (config?.loss_limits?.daily_loss_limit_pct ?? 5)) / 100).toFixed(0)} on $10k capital`}
            />
            <SliderWithValue
              label="Weekly Loss Limit %"
              value={config?.loss_limits?.weekly_loss_limit_pct ?? 10}
              onChange={(v) => updateConfig('loss_limits.weekly_loss_limit_pct', v)}
              min={0.5}
              max={30}
              step={0.5}
              decimals={1}
              unit="%"
              hint={`≈ $${((10000 * (config?.loss_limits?.weekly_loss_limit_pct ?? 10)) / 100).toFixed(0)} on $10k capital`}
            />
            <SliderWithValue
              label="Weekly Loss → Size Cut %"
              value={config?.loss_limits?.weekly_loss_size_cut_pct ?? 50}
              onChange={(v) => updateConfig('loss_limits.weekly_loss_size_cut_pct', v)}
              min={0}
              max={100}
              unit="%"
              hint="Cut position sizes by this % after hitting weekly loss threshold"
            />
          </SectionGrid>

          <SectionGrid>
            <NumberInput
              label="Circuit Breaker After N Losses"
              value={config?.loss_limits?.circuit_breaker_losses ?? 3}
              onChange={(v) => updateConfig('loss_limits.circuit_breaker_losses', v)}
              min={1}
              max={10}
              hint="Consecutive losing trades before pausing engine"
            />
            <NumberInput
              label="Pause Duration (minutes)"
              value={config?.loss_limits?.pause_duration_min ?? 60}
              onChange={(v) => updateConfig('loss_limits.pause_duration_min', v)}
              min={5}
              max={1440}
              step={5}
              width={100}
              hint="Engine pause time after circuit breaker triggers"
            />
          </SectionGrid>

          <RiskPreviewPanel config={config} />
        </div>
      </ConfigSection>

      {/* ── Save Bar ──────────────────────────────────────────────────────── */}
      <SaveConfigBar
        isDirty={isDirty}
        isSaving={isSaving}
        onSave={saveConfig}
        onReset={resetConfig}
      />
      </>)}
    </div>
  );
}

'use client';

import { useState, useEffect, useMemo, useCallback } from 'react';
import { apiGet } from '@/lib/api';

// ─── Types ────────────────────────────────────────────────────────────────────

interface TradeHistoryItem {
  id: string;
  symbol: string;
  profile: string; // "spot" | "futures"
  direction: string; // "long" | "short"
  entry_price: number | string;
  exit_price: number | string;
  quantity: number | string;
  profit_loss: number | string;
  entry_at: string;
  exit_at: string;
  engine_meta?: {
    score_at_entry?: number;
    close_reason?: string;
  };
}

type ProfileFilter = 'all' | 'spot' | 'futures';
type DateRangeFilter = 'last7d' | 'last30d' | 'all';
type SortKey = keyof TradeHistoryItem | 'pnl_pct' | 'hold_time';
type SortDir = 'asc' | 'desc';

// ─── Helper functions ─────────────────────────────────────────────────────────

function toNum(v: number | string | undefined | null): number {
  if (v === undefined || v === null) return 0;
  const n = typeof v === 'string' ? parseFloat(v) : v;
  return isFinite(n) ? n : 0;
}

function formatDuration(start: string, end: string): string {
  if (!start || !end) return '—';
  const diffMs = new Date(end).getTime() - new Date(start).getTime();
  if (diffMs < 0) return '—';
  const totalMins = Math.floor(diffMs / 60_000);
  const mins = totalMins % 60;
  const hours = Math.floor(totalMins / 60) % 24;
  const days = Math.floor(totalMins / 1440);
  if (days > 0) return `${days}d ${hours}h`;
  if (hours > 0) return `${hours}h ${mins}m`;
  return `${mins}m`;
}

function calcPnlPct(
  entry: number | string,
  exit: number | string,
  direction: string
): number {
  const e = toNum(entry);
  const x = toNum(exit);
  if (!e) return 0;
  const raw = ((x - e) / e) * 100;
  return direction?.toLowerCase() === 'short' ? -raw : raw;
}

function formatPrice(price: number): string {
  if (!isFinite(price) || price === 0) return '$0.00';
  const abs = Math.abs(price);
  if (abs < 0.01) return `$${price.toFixed(6)}`;
  if (abs < 1) return `$${price.toFixed(4)}`;
  if (abs < 1000) return `$${price.toFixed(2)}`;
  if (abs < 1_000_000) return `$${(price / 1000).toFixed(2)}K`;
  return `$${(price / 1_000_000).toFixed(2)}M`;
}

function formatPnl(pnl: number): string {
  const abs = Math.abs(pnl);
  const formatted = new Intl.NumberFormat('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(abs);
  return pnl >= 0 ? `+$${formatted}` : `-$${formatted}`;
}

function exportCSV(trades: TradeHistoryItem[]): void {
  const headers = [
    'ID',
    'Profile',
    'Symbol',
    'Direction',
    'Entry Price',
    'Exit Price',
    'Quantity',
    'P&L ($)',
    'P&L (%)',
    'Entry At',
    'Exit At',
    'Hold Time',
    'Score',
    'Close Reason',
  ];

  const rows = trades.map((t) => {
    const pnlPct = calcPnlPct(t.entry_price, t.exit_price, t.direction);
    return [
      t.id,
      t.profile,
      t.symbol,
      t.direction,
      toNum(t.entry_price).toFixed(8),
      toNum(t.exit_price).toFixed(8),
      toNum(t.quantity).toFixed(8),
      toNum(t.profit_loss).toFixed(2),
      pnlPct.toFixed(2),
      t.entry_at,
      t.exit_at,
      formatDuration(t.entry_at, t.exit_at),
      t.engine_meta?.score_at_entry?.toFixed(2) ?? '',
      t.engine_meta?.close_reason ?? '',
    ]
      .map((cell) => `"${String(cell).replace(/"/g, '""')}"`)
      .join(',');
  });

  const csv = [headers.join(','), ...rows].join('\n');
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = `scalpyn_trades_${new Date().toISOString().slice(0, 10)}.csv`;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
}

