    TARGET:    { bg: 'rgba(52, 211, 153, 0.1)',  border: 'rgba(52, 211, 153, 0.25)',  color: 'var(--color-profit)' },
    TRAILING:  { bg: 'rgba(251, 191, 36, 0.1)',  border: 'rgba(251, 191, 36, 0.25)',  color: 'var(--color-warning)' },
