              {filtered.length}
            </span>
          </div>
        </div>

        <div className="card-body" style={{ padding: 0 }}>
          {isLoading ? (
            <div
              style={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                padding: '64px',
                color: 'var(--text-tertiary)',
                fontSize: '13px',
              }}
            >
              Loading trade history…
            </div>
          ) : error ? (
            <div
              style={{
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                padding: '48px',
                gap: '8px',
                color: 'var(--color-loss)',
                fontSize: '13px',
              }}
            >
              <span>Failed to load trade history</span>
              <span style={{ fontSize: '12px', color: 'var(--text-tertiary)' }}>{error}</span>
            </div>
          ) : filtered.length === 0 ? (
            <EmptyState />
          ) : (
            <div style={{ overflowX: 'auto' }}>
              <table className="data-table" style={{ width: '100%', borderCollapse: 'collapse' }}>
                <thead>
                  <tr>
                    <th style={thStyle} onClick={() => handleSort('profile')}>
                      Profile <SortIcon active={sortKey === 'profile'} dir={sortDir} />
                    </th>
                    <th style={thStyle} onClick={() => handleSort('symbol')}>
                      Symbol <SortIcon active={sortKey === 'symbol'} dir={sortDir} />
                    </th>
                    <th style={thStyle} onClick={() => handleSort('direction')}>
                      Dir <SortIcon active={sortKey === 'direction'} dir={sortDir} />
                    </th>
                    <th style={thStyle} onClick={() => handleSort('entry_price')}>
                      Entry <SortIcon active={sortKey === 'entry_price'} dir={sortDir} />
                    </th>
                    <th style={thStyle} onClick={() => handleSort('exit_price')}>
                      Exit <SortIcon active={sortKey === 'exit_price'} dir={sortDir} />
                    </th>
                    <th style={thStyle} onClick={() => handleSort('hold_time')}>
                      Hold Time <SortIcon active={sortKey === 'hold_time'} dir={sortDir} />
                    </th>
                    <th style={thStyle}>
                      Score
                    </th>
                    <th style={thStyle} onClick={() => handleSort('pnl_pct')}>
                      P&L % <SortIcon active={sortKey === 'pnl_pct'} dir={sortDir} />
                    </th>
                    <th style={thStyle} onClick={() => handleSort('profit_loss')}>
                      P&L $ <SortIcon active={sortKey === 'profit_loss'} dir={sortDir} />
                    </th>
                    <th style={thStyle}>Reason</th>
                  </tr>
                </thead>
                <tbody>
                  {filtered.map((trade, i) => {
                    const pnl = toNum(trade.profit_loss);
                    const pnlPct = calcPnlPct(trade.entry_price, trade.exit_price, trade.direction);
                    const score = trade.engine_meta?.score_at_entry;
                    return (
                      <tr
                        key={trade.id ?? i}
                        style={{
                          background: i % 2 === 0 ? 'transparent' : 'rgba(255,255,255,0.01)',
                        }}
                        onMouseEnter={(e) => (e.currentTarget.style.background = 'var(--bg-hover)')}
                        onMouseLeave={(e) =>
                          (e.currentTarget.style.background =
                            i % 2 === 0 ? 'transparent' : 'rgba(255,255,255,0.01)')
                        }
                      >
                        {/* Profile */}
                        <td style={tdStyle}>
                          <ProfileBadge profile={trade.profile} />
                        </td>

                        {/* Symbol */}
                        <td
                          style={{
                            ...tdStyle,
                            fontWeight: 600,
                            fontFamily: 'var(--font-mono)',
                            color: 'var(--text-primary)',
                          }}
                        >
                          {trade.symbol ?? '—'}
                        </td>

                        {/* Direction */}
                        <td style={tdStyle}>
                          <DirectionBadge direction={trade.direction} />
                        </td>

                        {/* Entry */}
                        <td style={{ ...tdStyle, fontFamily: 'var(--font-mono)', color: 'var(--text-secondary)' }}>
                          {formatPrice(toNum(trade.entry_price))}
                        </td>

                        {/* Exit */}
                        <td style={{ ...tdStyle, fontFamily: 'var(--font-mono)', color: 'var(--text-secondary)' }}>
                          {formatPrice(toNum(trade.exit_price))}
                        </td>

                        {/* Hold Time */}
                        <td style={{ ...tdStyle, fontFamily: 'var(--font-mono)', color: 'var(--text-tertiary)' }}>
                          {formatDuration(trade.entry_at, trade.exit_at)}
                        </td>

                        {/* Score */}
                        <td style={{ ...tdStyle, fontFamily: 'var(--font-mono)', color: 'var(--text-secondary)' }}>
                          {score != null ? score.toFixed(2) : '—'}
                        </td>

                        {/* P&L % */}
                        <td style={tdStyle}>
                          <span
                            style={{
                              fontFamily: 'var(--font-mono)',
                              fontSize: '13px',
                              fontWeight: 600,
                              color: pnlPct >= 0 ? 'var(--color-profit)' : 'var(--color-loss)',
                            }}
                          >
                            {pnlPct >= 0 ? '+' : ''}{pnlPct.toFixed(2)}%
                          </span>
                        </td>

                        {/* P&L $ */}
                        <td style={tdStyle}>
                          <span
                            style={{
                              fontFamily: 'var(--font-mono)',
                              fontSize: '13px',
                              fontWeight: 600,
                              color: pnl >= 0 ? 'var(--color-profit)' : 'var(--color-loss)',
                            }}
                          >
                            {formatPnl(pnl)}
                          </span>
                        </td>

                        {/* Reason */}
                        <td style={tdStyle}>
                          <ReasonBadge reason={trade.engine_meta?.close_reason} />
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState, useMemo } from 'react';
import { usePositions, type Position } from '@/hooks/usePositions';

// ─── Helper functions ─────────────────────────────────────────────────────────

function formatAge(dateStr: string): string {
  if (!dateStr) return '—';
  const diffMs = Date.now() - new Date(dateStr).getTime();
  const diffMins = Math.floor(diffMs / 60_000);
  if (diffMins < 60) return `${diffMins}m`;
  const diffHours = Math.floor(diffMins / 60);
  if (diffHours < 24) return `${diffHours}h`;
  const diffDays = Math.floor(diffHours / 24);
  return `${diffDays}d`;
}

function formatPrice(price: number): string {
  if (!isFinite(price)) return '—';
  if (price === 0) return '$0.00';
  const abs = Math.abs(price);
  if (abs < 0.01) return `$${price.toFixed(6)}`;
  if (abs < 1) return `$${price.toFixed(4)}`;
  if (abs < 1000) return `$${price.toFixed(2)}`;
  if (abs < 1_000_000) return `$${(price / 1000).toFixed(2)}K`;
  return `$${(price / 1_000_000).toFixed(2)}M`;
}

function formatPnl(pnl: number): string {
  const abs = Math.abs(pnl);
  const formatted = new Intl.NumberFormat('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(abs);
  return pnl >= 0 ? `+$${formatted}` : `-$${formatted}`;
}

function getLiqDistanceColor(distPct: number): string {
  if (distPct > 10) return 'var(--color-profit)';
  if (distPct >= 5) return 'var(--color-warning)';
  return 'var(--color-loss)';
}

function calcLiqDistance(pos: Position): number | null {
  const price = pos.mark_price ?? pos.current_price ?? 0;
  const liq = pos.liquidation_price;
  if (!liq || !price) return null;
  return (Math.abs(price - liq) / price) * 100;
}

function avgDaysUnderwater(positions: Position[]): number {
  const now = Date.now();
  const total = positions.reduce((sum, p) => {
    const entryMs = p.entry_at ? new Date(p.entry_at).getTime() : now;
    return sum + (now - entryMs) / 86_400_000;
  }, 0);
  return positions.length > 0 ? total / positions.length : 0;
}

// ─── Sub-components ───────────────────────────────────────────────────────────

function PnlCell({ pct, abs }: { pct: number; abs: number }) {
  const isProfit = pct >= 0;
  const color = isProfit ? 'var(--color-profit)' : 'var(--color-loss)';
  return (
    <span style={{ color, fontFamily: 'var(--font-mono)', fontSize: '13px' }}>
      {isProfit ? '+' : ''}{pct.toFixed(2)}%
      <span style={{ display: 'block', fontSize: '11px', opacity: 0.75 }}>{formatPnl(abs)}</span>
    </span>
  );
}

function StatusBadge({ underwater }: { underwater: boolean }) {
  if (underwater) {
    return (
      <span
        style={{
          display: 'inline-flex',
          alignItems: 'center',
          gap: '4px',
          padding: '2px 8px',
          borderRadius: 'var(--radius-sm)',
          background: 'var(--color-loss-muted)',
          border: '1px solid var(--color-loss-border)',
          color: 'var(--color-loss)',
          fontSize: '11px',
          fontWeight: 600,
          letterSpacing: '0.06em',
        }}
      >
        🔴 UNDERWATER
      </span>
    );
  }
  return (
    <span
      style={{
        display: 'inline-flex',
        alignItems: 'center',
        padding: '2px 8px',
        borderRadius: 'var(--radius-sm)',
        background: 'var(--color-profit-muted)',
        border: '1px solid var(--color-profit-border)',
        color: 'var(--color-profit)',
        fontSize: '11px',
        fontWeight: 600,
        letterSpacing: '0.06em',
      }}
    >
      ACTIVE
    </span>
  );
}

function DirectionBadge({ side }: { side: string }) {
  const isLong = side?.toLowerCase() === 'long';
  return (
    <span
      style={{
        display: 'inline-flex',
        padding: '2px 8px',
        borderRadius: 'var(--radius-sm)',
        background: isLong ? 'var(--color-profit-muted)' : 'var(--color-loss-muted)',
        border: `1px solid ${isLong ? 'var(--color-profit-border)' : 'var(--color-loss-border)'}`,
        color: isLong ? 'var(--color-profit)' : 'var(--color-loss)',
        fontSize: '11px',
        fontWeight: 700,
        letterSpacing: '0.06em',
        fontFamily: 'var(--font-mono)',
      }}
    >
      {isLong ? 'LONG' : 'SHORT'}
    </span>
  );
}

function EmptyState({ label }: { label: string }) {
  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        padding: '48px 24px',
        gap: '12px',
        color: 'var(--text-tertiary)',
      }}
    >
      <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
        <path strokeLinecap="round" strokeLinejoin="round" d="M3.75 9.776c.112-.017.227-.026.344-.026h15.812c.117 0 .232.009.344.026m-16.5 0a2.25 2.25 0 00-1.883 2.542l.857 6a2.25 2.25 0 002.227 1.932H19.05a2.25 2.25 0 002.227-1.932l.857-6a2.25 2.25 0 00-1.883-2.542m-16.5 0V6A2.25 2.25 0 016 3.75h3.879a1.5 1.5 0 011.06.44l2.122 2.12a1.5 1.5 0 001.06.44H18A2.25 2.25 0 0120.25 9v.776" />
      </svg>
      <span style={{ fontSize: '13px' }}>No open {label} positions</span>
    </div>
  );
}

// ─── Main Page ────────────────────────────────────────────────────────────────

type ProfileFilter = 'all' | 'spot' | 'futures';
type StatusFilter = 'all' | 'active' | 'underwater';

export default function PositionsPage() {
  const { spotPositions, futuresPositions, underwaterCount, underwaterValue, nearestLiquidation, summary, isLoading } = usePositions();

  const [profileFilter, setProfileFilter] = useState<ProfileFilter>('all');
  const [statusFilter, setStatusFilter] = useState<StatusFilter>('all');
  const [assetSearch, setAssetSearch] = useState('');

  // ── Filtered positions ─────────────────────────────────────────────────────
  const filteredSpot = useMemo(() => {
    if (profileFilter === 'futures') return [];
    return spotPositions.filter((p) => {
      const matchSearch = !assetSearch || p.symbol?.toLowerCase().includes(assetSearch.toLowerCase());
      const isUnder = (p.unrealised_pnl ?? 0) < 0 || p.is_underwater === true;
      const matchStatus =
        statusFilter === 'all' ||
        (statusFilter === 'active' && !isUnder) ||
        (statusFilter === 'underwater' && isUnder);
      return matchSearch && matchStatus;
    });
  }, [spotPositions, profileFilter, statusFilter, assetSearch]);

  const filteredFutures = useMemo(() => {
    if (profileFilter === 'spot') return [];
    return futuresPositions.filter((p) => {
      const matchSearch = !assetSearch || p.symbol?.toLowerCase().includes(assetSearch.toLowerCase());
      const isUnder = (p.unrealised_pnl ?? 0) < 0 || p.is_underwater === true;
      const matchStatus =
        statusFilter === 'all' ||
        (statusFilter === 'active' && !isUnder) ||
        (statusFilter === 'underwater' && isUnder);
      return matchSearch && matchStatus;
    });
  }, [futuresPositions, profileFilter, statusFilter, assetSearch]);

  // ── Derived metrics ────────────────────────────────────────────────────────
  const totalPositionCount = spotPositions.length + futuresPositions.length;
  const freeCapitalPct =
    summary.totalCapital > 0 ? (summary.freeCapital / summary.totalCapital) * 100 : 0;

  const spotUnderwaterPositions = spotPositions.filter(
    (p) => (p.unrealised_pnl ?? 0) < 0 || p.is_underwater === true
  );
  const worstUnderwater = spotUnderwaterPositions.reduce<Position | null>((worst, p) => {
    if (!worst) return p;
    return (p.unrealised_pnl_pct ?? 0) < (worst.unrealised_pnl_pct ?? 0) ? p : worst;
  }, null);

  const totalFuturesPnl = futuresPositions.reduce((sum, p) => sum + (p.unrealised_pnl ?? 0), 0);
  const totalFuturesPnlPct =
    summary.futuresCapital > 0 ? (totalFuturesPnl / summary.futuresCapital) * 100 : 0;

  const nearestLiqDist = nearestLiquidation ? calcLiqDistance(nearestLiquidation) : null;
  const hasLiqWarning = nearestLiqDist !== null && nearestLiqDist < 10;

  // ── Pill button style helper ───────────────────────────────────────────────
  function pillStyle(active: boolean): React.CSSProperties {
    return {
      padding: '5px 14px',
      borderRadius: 'var(--radius-sm)',
      fontSize: '12px',
      fontWeight: 600,
      letterSpacing: '0.05em',
      cursor: 'pointer',
      border: 'none',
      transition: 'background 0.15s, color 0.15s',
      background: active ? 'var(--accent-primary)' : 'transparent',
      color: active ? '#fff' : 'var(--text-secondary)',
    };
  }

  const thStyle: React.CSSProperties = {
    padding: '8px 12px',
    textAlign: 'left',
    fontSize: '11px',
    fontWeight: 600,
    letterSpacing: '0.08em',
    color: 'var(--text-tertiary)',
    borderBottom: '1px solid var(--border-subtle)',
    whiteSpace: 'nowrap',
  };

  const tdStyle: React.CSSProperties = {
    padding: '10px 12px',
    fontSize: '13px',
    color: 'var(--text-primary)',
    borderBottom: '1px solid var(--border-subtle)',
    verticalAlign: 'middle',
  };

  if (isLoading && totalPositionCount === 0) {
    return (
      <div className="space-y-6">
        <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
          <h1 style={{ fontSize: '24px', fontWeight: 700, color: 'var(--text-primary)', letterSpacing: '-0.02em' }}>Positions</h1>
          <p style={{ fontSize: '13px', color: 'var(--text-secondary)' }}>All open positions across spot and futures</p>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '80px', color: 'var(--text-tertiary)', fontSize: '13px' }}>
          Loading positions…
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* ── Page Header ── */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
        <div>
          <h1 style={{ fontSize: '24px', fontWeight: 700, color: 'var(--text-primary)', letterSpacing: '-0.02em', margin: 0 }}>
            Positions
          </h1>
          <p style={{ fontSize: '13px', color: 'var(--text-secondary)', marginTop: '4px' }}>
            All open positions across spot and futures
          </p>
        </div>
        {isLoading && (
          <span style={{ fontSize: '11px', color: 'var(--text-tertiary)', marginTop: '6px' }}>Refreshing…</span>
        )}
      </div>

      {/* ── Filter Bar ── */}
      <div
        style={{
          display: 'flex',
          flexWrap: 'wrap',
          gap: '12px',
          alignItems: 'center',
          padding: '10px 14px',
          background: 'var(--bg-elevated)',
          border: '1px solid var(--border-subtle)',
          borderRadius: 'var(--radius-md)',
        }}
      >
        {/* Profile filter */}
        <div
          style={{
            display: 'flex',
            background: 'var(--bg-hover)',
            borderRadius: 'var(--radius-sm)',
            padding: '2px',
            gap: '2px',
          }}
        >
          {(['all', 'spot', 'futures'] as ProfileFilter[]).map((v) => (
            <button key={v} onClick={() => setProfileFilter(v)} style={pillStyle(profileFilter === v)}>
              {v === 'all' ? 'All' : v === 'spot' ? 'Spot' : 'Futures'}
            </button>
          ))}
        </div>

        {/* Asset search */}
        <input
          type="text"
          placeholder="Search asset…"
          value={assetSearch}
          onChange={(e) => setAssetSearch(e.target.value)}
          style={{
            background: 'var(--bg-input)',
            border: '1px solid var(--border-default)',
            borderRadius: 'var(--radius-sm)',
            padding: '5px 10px',
            color: 'var(--text-primary)',
            fontSize: '13px',
            outline: 'none',
            width: '160px',
            fontFamily: 'inherit',
          }}
        />

        {/* Status filter */}
        <div
          style={{
            display: 'flex',
            background: 'var(--bg-hover)',
            borderRadius: 'var(--radius-sm)',
            padding: '2px',
            gap: '2px',
            marginLeft: 'auto',
          }}
        >
          {(['all', 'active', 'underwater'] as StatusFilter[]).map((v) => (
            <button key={v} onClick={() => setStatusFilter(v)} style={pillStyle(statusFilter === v)}>
              {v === 'all' ? 'All' : v === 'active' ? 'Active' : 'Underwater'}
            </button>
          ))}
        </div>
      </div>

      {/* ── Capital Overview ── */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '12px' }}>
        {/* TOTAL */}
        <div className="metric-card">
          <span className="label">TOTAL CAPITAL</span>
          <span className="value" style={{ fontFamily: 'var(--font-mono)', fontSize: '22px' }}>
            {formatPrice(summary.totalCapital)}
          </span>
          <span className="caption" style={{ color: 'var(--text-tertiary)', fontSize: '12px' }}>
            {totalPositionCount} position{totalPositionCount !== 1 ? 's' : ''}
          </span>
        </div>

        {/* SPOT */}
        <div className="metric-card">
          <span className="label">SPOT DEPLOYED</span>
          <span className="value" style={{ fontFamily: 'var(--font-mono)', fontSize: '22px' }}>
            {formatPrice(summary.spotCapital)}
          </span>
          <span className="caption" style={{ color: 'var(--text-tertiary)', fontSize: '12px' }}>
            {spotPositions.length} position{spotPositions.length !== 1 ? 's' : ''}
          </span>
        </div>

        {/* FUTURES */}
        <div className="metric-card">
          <span className="label">FUTURES MARGIN</span>
          <span className="value" style={{ fontFamily: 'var(--font-mono)', fontSize: '22px' }}>
            {formatPrice(summary.futuresCapital)}
          </span>
          <span className="caption" style={{ color: 'var(--text-tertiary)', fontSize: '12px' }}>
            {futuresPositions.length} position{futuresPositions.length !== 1 ? 's' : ''}
          </span>
        </div>

        {/* FREE */}
        <div className="metric-card">
          <span className="label">FREE CAPITAL</span>
          <span className="value" style={{ fontFamily: 'var(--font-mono)', fontSize: '22px' }}>
            {formatPrice(summary.freeCapital)}
          </span>
          <span
            className="caption"
            style={{
              color: freeCapitalPct > 20 ? 'var(--color-profit)' : freeCapitalPct > 5 ? 'var(--color-warning)' : 'var(--color-loss)',
              fontSize: '12px',
              fontFamily: 'var(--font-mono)',
            }}
          >
            {freeCapitalPct.toFixed(1)}% free
          </span>
        </div>
      </div>

      {/* ── Spot Positions ── */}
      {profileFilter !== 'futures' && (
        <div className="card">
          <div className="card-header" style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
              <h3 style={{ margin: 0, fontSize: '12px', fontWeight: 700, letterSpacing: '0.1em', color: 'var(--text-secondary)' }}>
                SPOT POSITIONS
              </h3>
              <span
                style={{
                  display: 'inline-flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  minWidth: '22px',
                  height: '22px',
                  padding: '0 6px',
                  borderRadius: 'var(--radius-sm)',
                  background: 'var(--bg-hover)',
                  border: '1px solid var(--border-default)',
                  color: 'var(--text-secondary)',
                  fontSize: '11px',
                  fontWeight: 700,
                  fontFamily: 'var(--font-mono)',
                }}
              >
                {filteredSpot.length}
              </span>
            </div>
          </div>

          <div className="card-body" style={{ padding: 0 }}>
            {filteredSpot.length === 0 ? (
              <EmptyState label="spot" />
            ) : (
              <div style={{ overflowX: 'auto' }}>
                <table className="data-table" style={{ width: '100%', borderCollapse: 'collapse' }}>
                  <thead>
                    <tr>
                      {['Symbol', 'Entry', 'Current', 'P&L %', 'P&L $', 'Status', 'Age'].map((col) => (
                        <th key={col} style={thStyle}>{col}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {filteredSpot.map((pos, i) => {
                      const isUnder = (pos.unrealised_pnl ?? 0) < 0 || pos.is_underwater === true;
                      const pnlPct = pos.unrealised_pnl_pct ?? 0;
                      const pnlAbs = pos.unrealised_pnl ?? 0;
                      return (
                        <tr
                          key={pos.id ?? i}
                          style={{ background: i % 2 === 0 ? 'transparent' : 'rgba(255,255,255,0.01)' }}
                          onMouseEnter={(e) => (e.currentTarget.style.background = 'var(--bg-hover)')}
                          onMouseLeave={(e) => (e.currentTarget.style.background = i % 2 === 0 ? 'transparent' : 'rgba(255,255,255,0.01)')}
                        >
                          <td style={{ ...tdStyle, fontWeight: 600, fontFamily: 'var(--font-mono)' }}>
                            {pos.symbol ?? '—'}
                          </td>
                          <td style={{ ...tdStyle, fontFamily: 'var(--font-mono)' }}>
                            {formatPrice(pos.entry_price ?? 0)}
                          </td>
                          <td style={{ ...tdStyle, fontFamily: 'var(--font-mono)' }}>
                            {formatPrice(pos.current_price ?? pos.mark_price ?? 0)}
                          </td>
                          <td style={tdStyle}>
                            <span
                              style={{
                                fontFamily: 'var(--font-mono)',
                                fontSize: '13px',
                                color: pnlPct >= 0 ? 'var(--color-profit)' : 'var(--color-loss)',
                              }}
                            >
                              {pnlPct >= 0 ? '+' : ''}{pnlPct.toFixed(2)}%
                            </span>
                          </td>
                          <td style={tdStyle}>
                            <span
                              style={{
                                fontFamily: 'var(--font-mono)',
                                fontSize: '13px',
                                color: pnlAbs >= 0 ? 'var(--color-profit)' : 'var(--color-loss)',
                              }}
                            >
                              {formatPnl(pnlAbs)}
                            </span>
                          </td>
                          <td style={tdStyle}>
                            <StatusBadge underwater={isUnder} />
                          </td>
                          <td style={{ ...tdStyle, fontFamily: 'var(--font-mono)', color: 'var(--text-secondary)' }}>
                            {formatAge(pos.entry_at ?? '')}
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}

            {/* Underwater summary panel */}
            {underwaterCount > 0 && (
              <div
                style={{
                  margin: '0 16px 16px',
                  padding: '12px 16px',
                  borderRadius: 'var(--radius-md)',
                  background: 'var(--color-loss-muted)',
                  border: '1px solid var(--color-loss-border)',
                  display: 'flex',
                  flexDirection: 'column',
                  gap: '6px',
                }}
              >
                <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                  <span style={{ color: 'var(--color-loss)', fontSize: '12px', fontWeight: 700 }}>
                    {underwaterCount} underwater position{underwaterCount !== 1 ? 's' : ''}
                  </span>
                  <span style={{ color: 'var(--text-tertiary)', fontSize: '11px' }}>·</span>
                  <span style={{ color: 'var(--color-loss)', fontFamily: 'var(--font-mono)', fontSize: '12px' }}>
                    {formatPnl(underwaterValue)} locked
                  </span>
                  <span style={{ color: 'var(--text-tertiary)', fontSize: '11px' }}>·</span>
                  <span style={{ color: 'var(--text-tertiary)', fontFamily: 'var(--font-mono)', fontSize: '11px' }}>
                    {summary.totalCapital > 0
                      ? ((Math.abs(underwaterValue) / summary.totalCapital) * 100).toFixed(1)
                      : '0.0'}%
                  </span>
                </div>
                {worstUnderwater && (
                  <div style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>
                    <span style={{ fontWeight: 600 }}>Worst:</span>{' '}
                    <span style={{ fontFamily: 'var(--font-mono)', color: 'var(--color-loss)' }}>
                      {worstUnderwater.symbol}
                    </span>{' '}
                    <span style={{ fontFamily: 'var(--font-mono)', color: 'var(--color-loss)' }}>
                      {(worstUnderwater.unrealised_pnl_pct ?? 0).toFixed(1)}%
                    </span>
                    {worstUnderwater.entry_price && worstUnderwater.current_price && (
                      <span style={{ color: 'var(--text-tertiary)' }}>
                        {' '}(needs{' '}
                        <span style={{ fontFamily: 'var(--font-mono)', color: 'var(--color-warning)' }}>
                          +{((worstUnderwater.entry_price / (worstUnderwater.current_price ?? worstUnderwater.entry_price) - 1) * 100).toFixed(1)}%
                        </span>
                        {' '}to target)
                      </span>
                    )}
                  </div>
                )}
                <div style={{ fontSize: '11px', color: 'var(--text-tertiary)' }}>
                  Avg time underwater:{' '}
                  <span style={{ fontFamily: 'var(--font-mono)', color: 'var(--text-secondary)' }}>
                    {avgDaysUnderwater(spotUnderwaterPositions).toFixed(1)} days
                  </span>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* ── Futures Positions ── */}
      {profileFilter !== 'spot' && (
        <div className="card">
          <div className="card-header" style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
              <h3 style={{ margin: 0, fontSize: '12px', fontWeight: 700, letterSpacing: '0.1em', color: 'var(--text-secondary)' }}>
                FUTURES POSITIONS
              </h3>
              <span
                style={{
                  display: 'inline-flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  minWidth: '22px',
                  height: '22px',
                  padding: '0 6px',
                  borderRadius: 'var(--radius-sm)',
                  background: 'var(--bg-hover)',
                  border: '1px solid var(--border-default)',
                  color: 'var(--text-secondary)',
                  fontSize: '11px',
                  fontWeight: 700,
                  fontFamily: 'var(--font-mono)',
                }}
              >
                {filteredFutures.length}
              </span>
            </div>
          </div>

          <div className="card-body" style={{ padding: 0 }}>
            {filteredFutures.length === 0 ? (
              <EmptyState label="futures" />
            ) : (
              <div style={{ overflowX: 'auto' }}>
                <table className="data-table" style={{ width: '100%', borderCollapse: 'collapse' }}>
                  <thead>
                    <tr>
                      {['Symbol', 'Dir', 'Entry', 'Current', 'P&L %', 'Lev', 'Liq. Price', 'Dist'].map((col) => (
                        <th key={col} style={thStyle}>{col}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {filteredFutures.map((pos, i) => {
                      const pnlPct = pos.unrealised_pnl_pct ?? 0;
                      const dist = calcLiqDistance(pos);
                      return (
                        <tr
                          key={pos.id ?? i}
                          style={{ background: i % 2 === 0 ? 'transparent' : 'rgba(255,255,255,0.01)' }}
                          onMouseEnter={(e) => (e.currentTarget.style.background = 'var(--bg-hover)')}
                          onMouseLeave={(e) => (e.currentTarget.style.background = i % 2 === 0 ? 'transparent' : 'rgba(255,255,255,0.01)')}
                        >
                          <td style={{ ...tdStyle, fontWeight: 600, fontFamily: 'var(--font-mono)' }}>
                            {pos.symbol ?? '—'}
                          </td>
                          <td style={tdStyle}>
                            <DirectionBadge side={pos.side ?? 'long'} />
                          </td>
                          <td style={{ ...tdStyle, fontFamily: 'var(--font-mono)' }}>
                            {formatPrice(pos.entry_price ?? 0)}
                          </td>
                          <td style={{ ...tdStyle, fontFamily: 'var(--font-mono)' }}>
                            {formatPrice(pos.mark_price ?? pos.current_price ?? 0)}
                          </td>
                          <td style={tdStyle}>
                            <span
                              style={{
                                fontFamily: 'var(--font-mono)',
                                fontSize: '13px',
                                color: pnlPct >= 0 ? 'var(--color-profit)' : 'var(--color-loss)',
                              }}
                            >
                              {pnlPct >= 0 ? '+' : ''}{pnlPct.toFixed(2)}%
                            </span>
                          </td>
                          <td style={{ ...tdStyle, fontFamily: 'var(--font-mono)', color: 'var(--text-secondary)' }}>
                            {pos.leverage != null ? `${pos.leverage}×` : '—'}
                          </td>
                          <td style={{ ...tdStyle, fontFamily: 'var(--font-mono)', color: 'var(--color-warning)' }}>
                            {pos.liquidation_price != null ? formatPrice(pos.liquidation_price) : '—'}
                          </td>
                          <td style={tdStyle}>
                            {dist !== null ? (
                              <span
                                style={{
                                  fontFamily: 'var(--font-mono)',
                                  fontSize: '13px',
                                  fontWeight: 600,
                                  color: getLiqDistanceColor(dist),
                                }}
                              >
                                {dist.toFixed(1)}%
                              </span>
                            ) : (
                              <span style={{ color: 'var(--text-tertiary)' }}>—</span>
                            )}
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}

            {/* Liquidation Monitor panel */}
            <div
              style={{
                margin: '0 16px 16px',
                padding: '12px 16px',
                borderRadius: 'var(--radius-md)',
                background: hasLiqWarning ? 'rgba(248, 113, 113, 0.06)' : 'var(--bg-hover)',
                border: `1px solid ${hasLiqWarning ? 'var(--color-loss-border)' : 'var(--border-subtle)'}`,
                display: 'flex',
                flexDirection: 'column',
                gap: '6px',
              }}
            >
              {/* Header status */}
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <span
                  style={{
                    fontSize: '11px',
                    fontWeight: 700,
                    letterSpacing: '0.08em',
                    color: hasLiqWarning ? 'var(--color-loss)' : 'var(--color-profit)',
                  }}
                >
                  {hasLiqWarning ? '⚠ LIQUIDATION RISK' : '✓ All positions SAFE'}
                </span>
              </div>

              {/* Nearest liquidation */}
              {nearestLiquidation && nearestLiqDist !== null && (
                <div style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>
                  <span style={{ fontWeight: 600 }}>Nearest liquidation:</span>{' '}
                  <span style={{ fontFamily: 'var(--font-mono)', color: 'var(--text-primary)' }}>
                    {nearestLiquidation.symbol}
                  </span>{' '}
                  <DirectionBadge side={nearestLiquidation.side ?? 'long'} />{' '}
                  <span style={{ fontFamily: 'var(--font-mono)', color: getLiqDistanceColor(nearestLiqDist) }}>
                    at {nearestLiqDist.toFixed(1)}% distance
                  </span>
                </div>
              )}

              {/* Margin & P&L row */}
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: '16px', fontSize: '12px', color: 'var(--text-secondary)' }}>
                <span>
                  Total margin:{' '}
                  <span style={{ fontFamily: 'var(--font-mono)', color: 'var(--text-primary)' }}>
                    {formatPrice(summary.futuresCapital)}
                  </span>
                </span>
                <span>
                  Unrealized P&L:{' '}
                  <span
                    style={{
                      fontFamily: 'var(--font-mono)',
                      color: totalFuturesPnl >= 0 ? 'var(--color-profit)' : 'var(--color-loss)',
                    }}
                  >
                    {formatPnl(totalFuturesPnl)}{' '}
                    ({totalFuturesPnlPct >= 0 ? '+' : ''}{totalFuturesPnlPct.toFixed(2)}%)
                  </span>
                </span>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { useTradingConfig } from '@/hooks/useTradingConfig';
import { useEngineStatus } from '@/hooks/useEngineStatus';
import { EngineStatusBar } from '@/components/trading-desk/shared/EngineStatusBar';
import { ConfigSection } from '@/components/trading-desk/shared/ConfigSection';
import { SliderWithValue } from '@/components/trading-desk/shared/SliderWithValue';
import { SaveConfigBar } from '@/components/trading-desk/shared/SaveConfigBar';
import { apiGet } from '@/lib/api';

// ─── Inline Toggle ────────────────────────────────────────────────────────────

interface ToggleProps {
  checked: boolean;
  onChange: (value: boolean) => void;
  disabled?: boolean;
  id?: string;
}

function Toggle({ checked, onChange, disabled = false, id }: ToggleProps) {
  return (
    <button
      id={id}
      type="button"
      role="switch"
      aria-checked={checked}
      disabled={disabled}
      onClick={() => !disabled && onChange(!checked)}
      style={{
        display: 'inline-flex',
        alignItems: 'center',
        width: '36px',
        height: '20px',
        borderRadius: '999px',
        padding: '2px',
        border: 'none',
        cursor: disabled ? 'not-allowed' : 'pointer',
        background: checked ? 'var(--accent-primary)' : 'var(--bg-hover)',
        transition: 'background var(--transition-fast)',
        flexShrink: 0,
        opacity: disabled ? 0.6 : 1,
      }}
    >
      <span
        style={{
          display: 'block',
          width: '16px',
          height: '16px',
          borderRadius: '50%',
          background: '#ffffff',
          transform: checked ? 'translateX(16px)' : 'translateX(0)',
          transition: 'transform var(--transition-fast)',
          flexShrink: 0,
        }}
      />
    </button>
  );
}

// ─── Inline helpers ───────────────────────────────────────────────────────────

const numInputStyle: React.CSSProperties = {
  background: 'var(--bg-input)',
  border: '1px solid var(--border-default)',
  borderRadius: 'var(--radius-sm)',
  padding: '4px 8px',
  color: 'var(--text-primary)',
  fontFamily: 'var(--font-mono)',
  width: '80px',
  fontSize: '13px',
  outline: 'none',
};

function SubHeader({ children }: { children: React.ReactNode }) {
  return (
    <div
      className="label"
      style={{
        marginTop: '20px',
        marginBottom: '10px',
        letterSpacing: '0.08em',
        fontSize: '11px',
        color: 'var(--text-tertiary)',
      }}
    >
      {children}
    </div>
  );
}

interface ToggleRowProps {
  label: string;
  description?: string;
  checked: boolean;
  onChange: (v: boolean) => void;
  disabled?: boolean;
}

function ToggleRow({ label, description, checked, onChange, disabled }: ToggleRowProps) {
  return (
    <div
      style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        gap: '12px',
        padding: '8px 0',
        borderBottom: '1px solid var(--border-subtle)',
      }}
    >
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ color: 'var(--text-primary)', fontSize: '14px', fontWeight: 500 }}>
          {label}
        </div>
        {description && (
          <div style={{ color: 'var(--text-tertiary)', fontSize: '12px', marginTop: '2px' }}>
            {description}
          </div>
        )}
      </div>
      <Toggle checked={checked} onChange={onChange} disabled={disabled} />
    </div>
  );
}

// ─── Page ─────────────────────────────────────────────────────────────────────

type AuditItem = {
  trace_id: string | null;
  symbol: string;
  status: string;
  reason: string | null;
  rule_details: Record<string, unknown> | null;
  score_breakdown: Record<string, unknown> | null;
  trade_id: string | null;
  decided_at: string | null;
};

export default function SpotTradingPage() {
  const { config, updateConfig, saveConfig, resetConfig, isDirty, isSaving } =
    useTradingConfig('spot');

  const [activeTab, setActiveTab] = useState<'config' | 'audit'>('config');
  const [auditItems, setAuditItems] = useState<AuditItem[]>([]);
  const [auditLoading, setAuditLoading] = useState(false);
  const [auditLastUpdated, setAuditLastUpdated] = useState<Date | null>(null);
  const [balance, setBalance] = useState<{
    available_usdt: number;
    in_positions: number;
    total: number;
    source: string;
  } | null>(null);
  const [balanceLoading, setBalanceLoading] = useState(false);

  const fetchBalance = useCallback(async () => {
    setBalanceLoading(true);
    try {
      const data = await apiGet('/live/balance');
      setBalance(data);
    } catch {
      // ignore
    } finally {
      setBalanceLoading(false);
    }
  }, []);

  const fetchAudit = useCallback(async () => {
    setAuditLoading(true);
    try {
      const data = await apiGet('/spot-engine/audit?limit=100');
      setAuditItems(data?.items ?? []);
      setAuditLastUpdated(new Date());
    } catch {
      // ignore
    } finally {
      setAuditLoading(false);
    }
  }, []);

  useEffect(() => {
    if (activeTab === 'audit') {
      fetchAudit();
      fetchBalance();
      // Audit refreshes every 60s; balance only every 5 min (it calls exchange API)
      const auditId = setInterval(fetchAudit, 60_000);
      const balanceId = setInterval(fetchBalance, 5 * 60_000);
      return () => { clearInterval(auditId); clearInterval(balanceId); };
    }
  }, [activeTab, fetchAudit, fetchBalance]);

  const capital: number = config?.account?.capital ?? 10000;

  // ── Derived values (safe access) ─────────────────────────────────────────

  const scanInterval = config?.scanner?.interval ?? 60;
  const buyScoreThreshold = config?.buying?.score_threshold ?? 75;
  const strongBuyScore = config?.buying?.strong_buy_score ?? 85;
  const maxOpportunitiesPerScan = config?.scanner?.max_opportunities ?? 5;

  const perTradePct = config?.buying?.capital_per_trade_pct ?? 10;
  const minPerTrade = config?.buying?.capital_per_trade_min_usdt ?? 20;
  const maxPerTrade = config?.buying?.capital_per_trade_max_usdt ?? 500;
  const capitalReservePct = config?.buying?.capital_reserve_pct ?? 10;
  const maxCapitalInUsePct = config?.buying?.max_capital_in_use_pct ?? 80;

  const maxPositionsTotal = config?.buying?.max_positions_total ?? 20;
  const maxPerAsset = config?.buying?.max_positions_per_asset ?? 5;
  const maxExposurePerAssetPct = config?.buying?.max_exposure_per_asset_pct ?? 25;

  const orderType: 'market' | 'limit' = config?.orders?.type ?? 'market';
  const limitOrderTimeout = config?.orders?.limit_timeout_seconds ?? 30;
  const maxSlippagePct = config?.orders?.max_slippage_pct ?? 0.5;

  // Sell rules
  const takeProfitPct = config?.sell?.take_profit_pct ?? 2.0;
  const minProfitToSellPct = config?.sell?.min_profit_pct ?? 0.5;
  const safetyMarginPct = config?.sell?.safety_margin_pct ?? 0.1;

  const layerRanging = config?.sell?.layers?.ranging ?? true;
  const layerExhaustion = config?.sell?.layers?.exhaustion ?? true;
  const layerAiOpportunity = config?.sell?.layers?.ai_opportunity ?? false;
  const layerTargetHit = config?.sell?.layers?.target_hit ?? true;
  const layerAiTrailing = config?.sell?.layers?.ai_trailing ?? false;

  const showAiConfig = layerAiOpportunity || layerAiTrailing;
  const aiModel = config?.sell?.ai?.model ?? 'google/gemini-2.5-flash';
  const aiRateLimit = config?.sell?.ai?.rate_limit_seconds ?? 60;

  // Holding & Recovery
  const alertAfterUnderwaterHours = config?.holding?.alert_after_hours ?? 24;
  const repeatAlertEveryHours = config?.holding?.repeat_alert_hours ?? 12;
  const showOpportunityCost = config?.holding?.show_opportunity_cost ?? false;
  const showRecoveryPct = config?.holding?.show_recovery_pct ?? true;

  const dcaEnabled = config?.dca?.enabled ?? false;
  const dcaTriggerDropPct = config?.dca?.trigger_drop_pct ?? 5;
  const dcaMinScore = config?.dca?.min_score ?? 60;
  const dcaMaxLayers = config?.dca?.max_layers ?? 3;
  const dcaBaseAmount = config?.dca?.base_amount ?? 100;
  const dcaDecayFactor = config?.dca?.decay_factor ?? 0.7;
  const dcaMaxExposurePct = config?.dca?.max_total_exposure_pct ?? 30;
  const dcaRequireMacroSafe = config?.dca?.require_macro_not_risk_off ?? false;

  // Macro filter
  const macroEnabled = config?.macro?.enabled ?? false;
  const macroBlockOnStrongRiskOff = config?.macro?.block_on_strong_risk_off ?? true;
  const macroReduceBuysPct = config?.macro?.reduce_buys_pct ?? 50;
  const macroBtcGuard = config?.macro?.btc_correlation_guard ?? true;
  const macroBtcDumpThreshold1h = config?.macro?.btc_dump_threshold_1h_pct ?? -3.0;
  const macroBtcGuardAction: 'reduce' | 'alert' = config?.macro?.btc_guard_action ?? 'reduce';

  // Trailing stop
  const trailingMethod: 'fixed' | 'atr' = config?.trailing?.method ?? 'fixed';
  const trailingAtrPeriod = config?.trailing?.atr_period ?? 14;
  const trailingAtrMultiplier = config?.trailing?.atr_multiplier ?? 1.5;
  const trailingMarginFloor = config?.trailing?.margin_floor_pct ?? 0.3;
  const trailingMarginCeiling = config?.trailing?.margin_ceiling_pct ?? 1.5;
  const trailingTightenAbovePct = config?.trailing?.tighten_above_profit_pct ?? 5;
  const trailingTightenFactor = config?.trailing?.tighten_factor ?? 0.7;

  return (
    <div style={{ paddingBottom: '80px' }}>
      {/* Page Header */}
      <div style={{ marginBottom: '24px' }}>
        <h1
          style={{
            fontSize: '24px',
            fontWeight: 700,
            color: 'var(--text-primary)',
            margin: 0,
            fontFamily: 'var(--font-sans)',
          }}
        >
          Spot Trading
        </h1>
        <p
          style={{
            fontSize: '14px',
            color: 'var(--text-secondary)',
            margin: '4px 0 0',
            fontFamily: 'var(--font-sans)',
          }}
        >
          Configure and control the spot trading engine
        </p>
      </div>

      {/* Engine Status Bar */}
      <EngineStatusBar profile="spot" />

      {/* Tab Navigation */}
      <div style={{ display: 'flex', gap: '4px', borderBottom: '1px solid var(--border-default)', marginTop: '16px' }}>
        {(['config', 'audit'] as const).map((tab) => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            style={{
              padding: '8px 16px',
              fontSize: '13px',
              fontWeight: activeTab === tab ? 600 : 400,
              color: activeTab === tab ? 'var(--accent-primary)' : 'var(--text-secondary)',
              background: 'none',
              border: 'none',
              borderBottom: activeTab === tab ? '2px solid var(--accent-primary)' : '2px solid transparent',
              cursor: 'pointer',
              marginBottom: '-1px',
              textTransform: 'capitalize',
            }}
          >
            {tab === 'config' ? 'Configuration' : 'Audit Trail'}
          </button>
        ))}
      </div>

      {/* Audit Tab */}
      {activeTab === 'audit' && (
        <div style={{ marginTop: '16px' }}>

          {/* Capital Total card */}
          <div style={{
            display: 'flex', gap: '12px', marginBottom: '16px', flexWrap: 'wrap',
          }}>
            <div style={{
              flex: 1, minWidth: 160, padding: '12px 16px',
              background: 'var(--bg-elevated)',
              border: '1px solid var(--border-default)',
              borderRadius: 'var(--radius-md)',
            }}>
              <div style={{ fontSize: '10px', color: 'var(--text-tertiary)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: 4 }}>
                Capital Total (USDT)
              </div>
              <div style={{ fontSize: '22px', fontWeight: 700, fontFamily: 'var(--font-mono)', color: 'var(--text-primary)' }}>
                {balanceLoading && !balance ? '…' : balance ? `$${balance.total.toLocaleString(undefined, { maximumFractionDigits: 2 })}` : '—'}
              </div>
              {balance && (
                <div style={{ display: 'flex', gap: '12px', marginTop: '6px' }}>
                  <span style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>
                    Disponível: <strong style={{ color: 'var(--text-primary)' }}>${balance.available_usdt.toFixed(2)}</strong>
                  </span>
                  <span style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>
                    Em posições: <strong style={{ color: 'var(--text-primary)' }}>${balance.in_positions.toFixed(2)}</strong>
                  </span>
                </div>
              )}
              {balance?.source === 'exchange_error' && (
                <div style={{ fontSize: '10px', color: '#ef4444', marginTop: 4 }}>Erro ao buscar saldo da corretora</div>
              )}
              {balance?.source === 'no_connection' && (
                <div style={{ fontSize: '10px', color: 'var(--text-tertiary)', marginTop: 4 }}>Sem conexão com corretora configurada</div>
              )}
            </div>
          </div>

          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
            <p style={{ fontSize: '13px', color: 'var(--text-secondary)', margin: 0 }}>
              Últimas 100 tentativas de compra
              {auditLastUpdated && (
                <span style={{ fontSize: '11px', color: 'var(--text-tertiary)', marginLeft: '8px' }}>
                  · atualizado {auditLastUpdated.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}
                </span>
              )}
            </p>
            <button
              onClick={fetchAudit}
              disabled={auditLoading}
              style={{
                fontSize: '12px',
                padding: '4px 12px',
                background: 'var(--bg-secondary)',
                border: '1px solid var(--border-default)',
                borderRadius: 'var(--radius-sm)',
                color: 'var(--text-primary)',
                cursor: 'pointer',
              }}
            >
              {auditLoading ? 'Loading…' : 'Refresh'}
            </button>
          </div>

          {auditItems.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '40px', color: 'var(--text-tertiary)', fontSize: '13px' }}>
              {auditLoading ? 'Carregando registros…' : 'Nenhuma tentativa registrada. Inicie o engine para ver atividade.'}
            </div>
          ) : (
            <div style={{ overflowX: 'auto' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '12px' }}>
                <thead>
                  <tr style={{ borderBottom: '1px solid var(--border-default)' }}>
                    {['Time', 'Symbol', 'Status', 'Reason', 'Size (USDT)', 'Score', 'Trade ID'].map((h) => (
                      <th
                        key={h}
                        style={{
                          padding: '8px 10px',
                          textAlign: 'left',
                          color: 'var(--text-tertiary)',
                          fontWeight: 500,
                          whiteSpace: 'nowrap',
                        }}
                      >
                        {h}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {auditItems.map((item, i) => {
                    const isApproved = item.status === 'APPROVED';
                    const details = item.rule_details as Record<string, unknown> | null;
                    return (
                      <tr
                        key={item.trace_id ?? i}
                        style={{
                          borderBottom: '1px solid var(--border-subtle)',
                          background: i % 2 === 0 ? 'transparent' : 'var(--bg-hover)',
                        }}
                      >
                        <td style={{ padding: '8px 10px', color: 'var(--text-secondary)', whiteSpace: 'nowrap' }}>
                          {item.decided_at ? new Date(item.decided_at).toLocaleString() : '—'}
                        </td>
                        <td style={{ padding: '8px 10px', color: 'var(--text-primary)', fontWeight: 500 }}>
                          {item.symbol}
                        </td>
                        <td style={{ padding: '8px 10px' }}>
                          <span style={{
                            padding: '2px 8px',
                            borderRadius: '99px',
                            fontSize: '11px',
                            fontWeight: 600,
                            background: isApproved ? 'rgba(34,197,94,0.15)' : 'rgba(239,68,68,0.15)',
                            color: isApproved ? '#22c55e' : '#ef4444',
                          }}>
                            {item.status}
                          </span>
                        </td>
                        <td style={{ padding: '8px 10px', color: 'var(--text-secondary)', maxWidth: '260px', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                          {item.reason ?? '—'}
                        </td>
                        <td style={{ padding: '8px 10px', color: 'var(--text-primary)', fontFamily: 'var(--font-mono)' }}>
                          {details?.trade_size != null ? `$${Number(details.trade_size).toFixed(2)}` : '—'}
                        </td>
                        <td style={{ padding: '8px 10px', color: 'var(--text-primary)', fontFamily: 'var(--font-mono)' }}>
                          {details?.score != null ? Number(details.score).toFixed(1) : '—'}
                        </td>
                        <td style={{ padding: '8px 10px', color: 'var(--text-tertiary)', fontFamily: 'var(--font-mono)', fontSize: '11px' }}>
                          {item.trade_id ? item.trade_id.slice(0, 8) + '…' : '—'}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {/* Config Tab */}
      {activeTab === 'config' && (<>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '12px', marginTop: '16px' }}>

        {/* ── SECTION: Scanner & Buying ───────────────────────────────────── */}
        <ConfigSection title="Scanner & Buying" icon="🔍" defaultOpen={true}>
          <SliderWithValue
            label="Scan Interval"
            value={scanInterval}
            onChange={(v) => updateConfig('scanner.interval', v)}
            min={10}
            max={300}
            step={5}
            unit="s"
            hint="How often to scan for new opportunities"
          />
          <SliderWithValue
            label="Buy Score Threshold"
            value={buyScoreThreshold}
            onChange={(v) => updateConfig('buying.score_threshold', v)}
            min={0}
            max={100}
            hint="Minimum score required to place a buy"
          />
          <SliderWithValue
            label="Strong Buy Score"
            value={strongBuyScore}
            onChange={(v) => updateConfig('buying.strong_buy_score', v)}
            min={0}
            max={100}
            hint="Score considered a strong conviction buy"
          />
          <SliderWithValue
            label="Max Opportunities per Scan"
            value={maxOpportunitiesPerScan}
            onChange={(v) => updateConfig('scanner.max_opportunities', v)}
            min={1}
            max={10}
            hint="Limit how many signals are acted on per scan cycle"
          />

          <SubHeader>CAPITAL ALLOCATION</SubHeader>

          <SliderWithValue
            label="Per Trade %"
            value={perTradePct}
            onChange={(v) => updateConfig('buying.capital_per_trade_pct', v)}
            min={0}
            max={100}
            unit="%"
            hint={`≈ $${((perTradePct / 100) * capital).toFixed(0)} per trade`}
          />

          <div style={{ display: 'flex', gap: '24px', flexWrap: 'wrap', padding: '6px 0' }}>
            <div>
              <div
                style={{
                  fontSize: '13px',
                  color: 'var(--text-secondary)',
                  marginBottom: '6px',
                  fontFamily: 'var(--font-sans)',
                }}
              >
                Min per Trade $
              </div>
              <input
                type="number"
                value={minPerTrade}
                onChange={(e) => updateConfig('buying.capital_per_trade_min_usdt', Number(e.target.value))}
                style={numInputStyle}
                min={1}
              />
            </div>
            <div>
              <div
                style={{
                  fontSize: '13px',
                  color: 'var(--text-secondary)',
                  marginBottom: '6px',
                  fontFamily: 'var(--font-sans)',
                }}
              >
                Max per Trade $
              </div>
              <input
                type="number"
                value={maxPerTrade}
                onChange={(e) => updateConfig('buying.capital_per_trade_max_usdt', Number(e.target.value))}
                style={numInputStyle}
                min={1}
              />
            </div>
          </div>

          <SliderWithValue
            label="Capital Reserve %"
            value={capitalReservePct}
            onChange={(v) => updateConfig('buying.capital_reserve_pct', v)}
            min={0}
            max={100}
            unit="%"
            hint="Always keep this portion of capital unused"
          />
          <SliderWithValue
            label="Max Capital in Use %"
            value={maxCapitalInUsePct}
            onChange={(v) => updateConfig('buying.max_capital_in_use_pct', v)}
            min={0}
            max={100}
            unit="%"
            hint="Hard cap on total deployed capital"
          />

          <SubHeader>POSITION LIMITS</SubHeader>

          <div style={{ display: 'flex', gap: '24px', flexWrap: 'wrap', padding: '6px 0' }}>
            <div>
              <div
                style={{
                  fontSize: '13px',
                  color: 'var(--text-secondary)',
                  marginBottom: '6px',
                  fontFamily: 'var(--font-sans)',
                }}
              >
                Max Positions Total
              </div>
              <input
                type="number"
                value={maxPositionsTotal}
                onChange={(e) =>
                  updateConfig('buying.max_positions_total', Number(e.target.value))
                }
                style={numInputStyle}
                min={1}
              />
            </div>
            <div>
              <div
                style={{
                  fontSize: '13px',
                  color: 'var(--text-secondary)',
                  marginBottom: '6px',
                  fontFamily: 'var(--font-sans)',
                }}
              >
                Max per Asset
              </div>
              <input
                type="number"
                value={maxPerAsset}
                onChange={(e) => updateConfig('buying.max_positions_per_asset', Number(e.target.value))}
                style={numInputStyle}
                min={1}
              />
            </div>
          </div>

          <SliderWithValue
            label="Max Exposure per Asset %"
            value={maxExposurePerAssetPct}
            onChange={(v) => updateConfig('buying.max_exposure_per_asset_pct', v)}
            min={0}
            max={100}
            unit="%"
            hint="Maximum portfolio share for a single asset"
          />

          <SubHeader>ORDER SETTINGS</SubHeader>

          <div style={{ padding: '6px 0' }}>
            <div
              style={{
                fontSize: '13px',
                color: 'var(--text-secondary)',
                marginBottom: '8px',
                fontFamily: 'var(--font-sans)',
              }}
            >
              Order Type
            </div>
            <div style={{ display: 'flex', gap: '8px' }}>
              {(['market', 'limit'] as const).map((type) => (
                <label
                  key={type}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '6px',
                    cursor: 'pointer',
                    fontSize: '14px',
                    color: orderType === type ? 'var(--text-primary)' : 'var(--text-secondary)',
                    fontFamily: 'var(--font-sans)',
                  }}
                >
                  <input
                    type="radio"
                    name="orderType"
                    value={type}
                    checked={orderType === type}
                    onChange={() => updateConfig('orders.type', type)}
                    style={{ accentColor: 'var(--accent-primary)' }}
                  />
                  {type.charAt(0).toUpperCase() + type.slice(1)}
                </label>
              ))}
            </div>
          </div>

          {orderType === 'limit' && (
            <div style={{ padding: '6px 0' }}>
              <div
                style={{
                  fontSize: '13px',
                  color: 'var(--text-secondary)',
                  marginBottom: '6px',
                  fontFamily: 'var(--font-sans)',
                }}
              >
                Limit Order Timeout (seconds)
              </div>
              <input
                type="number"
                value={limitOrderTimeout}
                onChange={(e) =>
                  updateConfig('orders.limit_timeout_seconds', Number(e.target.value))
                }
                style={numInputStyle}
                min={5}
              />
            </div>
          )}

          <SliderWithValue
            label="Max Slippage %"
            value={maxSlippagePct}
            onChange={(v) => updateConfig('orders.max_slippage_pct', v)}
            min={0}
            max={100}
            step={0.01}
            unit="%"
            decimals={2}
            hint="Maximum acceptable slippage when filling orders"
          />
        </ConfigSection>

        {/* ── SECTION: Sell Rules ─────────────────────────────────────────── */}
        <ConfigSection title="Sell Rules" icon="📤" defaultOpen={true}>
          {/* Core Rule Banner */}
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: '12px',
              padding: '12px 14px',
              background: 'var(--color-warning-muted)',
              border: '1px solid var(--color-warning)',
              borderRadius: 'var(--radius-md)',
              marginBottom: '16px',
            }}
          >
            <span style={{ fontSize: '20px', flexShrink: 0 }}>🔒</span>
            <div style={{ flex: 1 }}>
              <div
                style={{
                  fontSize: '13px',
                  fontWeight: 700,
                  color: 'var(--color-warning)',
                  fontFamily: 'var(--font-sans)',
                  letterSpacing: '0.04em',
                  textTransform: 'uppercase',
                }}
              >
                NEVER SELL AT LOSS
              </div>
              <div
                style={{
                  fontSize: '12px',
                  color: 'var(--text-secondary)',
                  marginTop: '2px',
                  fontFamily: 'var(--font-sans)',
                }}
              >
                This rule is permanently enforced and cannot be disabled.
              </div>
            </div>
            <Toggle checked={true} onChange={() => {}} disabled={true} />
          </div>

          <SliderWithValue
            label="Take Profit Target %"
            value={takeProfitPct}
            onChange={(v) => updateConfig('sell.take_profit_pct', v)}
            min={0}
            max={100}
            unit="%"
            decimals={2}
            hint="Target gain to trigger a sell evaluation"
          />
          <SliderWithValue
            label="Min Profit to Sell %"
            value={minProfitToSellPct}
            onChange={(v) => updateConfig('sell.min_profit_pct', v)}
            min={0}
            max={100}
            unit="%"
            decimals={2}
            hint="Absolute floor — position will not sell below this"
          />
          <SliderWithValue
            label="Safety Margin %"
            value={safetyMarginPct}
            onChange={(v) => updateConfig('sell.safety_margin_pct', v)}
            min={0}
            max={100}
            step={0.05}
            unit="%"
            decimals={2}
            hint="Buffer added above min profit to absorb fees"
          />

          <SubHeader>SELL FLOW LAYERS</SubHeader>

          <ToggleRow
            label="Ranging Detection"
            description="Market lateralized → sell if profit ≥ TP"
            checked={layerRanging}
            onChange={(v) => updateConfig('sell.layers.ranging', v)}
          />
          <ToggleRow
            label="Exhaustion Detection"
            description="Trend weakening signals"
            checked={layerExhaustion}
            onChange={(v) => updateConfig('sell.layers.exhaustion', v)}
          />
          <ToggleRow
            label="AI Opportunity"
            description="Consult AI model for EXTEND/SELL decision"
            checked={layerAiOpportunity}
            onChange={(v) => updateConfig('sell.layers.ai_opportunity', v)}
          />
          <ToggleRow
            label="Target Hit"
            description="Direct profit ≥ take profit"
            checked={layerTargetHit}
            onChange={(v) => updateConfig('sell.layers.target_hit', v)}
          />
          <ToggleRow
            label="AI Trailing"
            description="HWM trailing stop after AI Hold"
            checked={layerAiTrailing}
            onChange={(v) => updateConfig('sell.layers.ai_trailing', v)}
          />

          {showAiConfig && (
            <div
              style={{
                marginTop: '16px',
                padding: '14px',
                background: 'var(--bg-elevated)',
                border: '1px solid var(--border-subtle)',
                borderRadius: 'var(--radius-md)',
                display: 'flex',
                flexDirection: 'column',
                gap: '12px',
              }}
            >
              <div
                className="label"
                style={{ fontSize: '11px', color: 'var(--text-tertiary)', letterSpacing: '0.08em' }}
              >
                AI CONFIGURATION
              </div>

              <div>
                <div
                  style={{
                    fontSize: '13px',
                    color: 'var(--text-secondary)',
                    marginBottom: '6px',
                    fontFamily: 'var(--font-sans)',
                  }}
                >
                  AI Model
                </div>
                <select
                  value={aiModel}
                  onChange={(e) => updateConfig('sell.ai.model', e.target.value)}
                  style={{
                    ...numInputStyle,
                    width: 'auto',
                    minWidth: '220px',
                    paddingRight: '12px',
                  }}
                >
                  <option value="google/gemini-2.5-flash">google/gemini-2.5-flash</option>
                  <option value="google/gemini-2.0-flash">google/gemini-2.0-flash</option>
                  <option value="anthropic/claude-3-haiku">anthropic/claude-3-haiku</option>
                </select>
              </div>

              <div>
                <div
                  style={{
                    fontSize: '13px',
                    color: 'var(--text-secondary)',
                    marginBottom: '6px',
                    fontFamily: 'var(--font-sans)',
                  }}
                >
                  AI Rate Limit (seconds)
                </div>
                <input
                  type="number"
                  value={aiRateLimit}
                  onChange={(e) =>
                    updateConfig('sell.ai.rate_limit_seconds', Number(e.target.value))
                  }
                  style={numInputStyle}
                  min={10}
                />
              </div>
            </div>
          )}
        </ConfigSection>

        {/* ── SECTION: Holding & Recovery ────────────────────────────────── */}
        <ConfigSection title="Holding & Recovery" icon="⏳" defaultOpen={false}>
          <div
            style={{
              padding: '10px 14px',
              background: 'var(--bg-elevated)',
              border: '1px solid var(--border-subtle)',
              borderRadius: 'var(--radius-md)',
              marginBottom: '16px',
              fontSize: '13px',
              color: 'var(--text-secondary)',
              fontFamily: 'var(--font-sans)',
              lineHeight: 1.5,
            }}
          >
            Underwater positions are held indefinitely until the minimum profit target is reached.
          </div>

          <div style={{ display: 'flex', gap: '24px', flexWrap: 'wrap', padding: '6px 0' }}>
            <div>
              <div
                style={{
                  fontSize: '13px',
                  color: 'var(--text-secondary)',
                  marginBottom: '6px',
                  fontFamily: 'var(--font-sans)',
                }}
              >
                Alert after underwater (hours)
              </div>
              <input
                type="number"
                value={alertAfterUnderwaterHours}
                onChange={(e) =>
                  updateConfig('holding.alert_after_hours', Number(e.target.value))
                }
                style={numInputStyle}
                min={1}
              />
            </div>
            <div>
              <div
                style={{
                  fontSize: '13px',
                  color: 'var(--text-secondary)',
                  marginBottom: '6px',
                  fontFamily: 'var(--font-sans)',
                }}
              >
                Repeat alert every (hours)
              </div>
              <input
                type="number"
                value={repeatAlertEveryHours}
                onChange={(e) =>
                  updateConfig('holding.repeat_alert_hours', Number(e.target.value))
                }
                style={numInputStyle}
                min={1}
              />
            </div>
          </div>

          <ToggleRow
            label="Show opportunity cost estimate"
            checked={showOpportunityCost}
            onChange={(v) => updateConfig('holding.show_opportunity_cost', v)}
          />
          <ToggleRow
            label="Show recovery % needed"
            checked={showRecoveryPct}
            onChange={(v) => updateConfig('holding.show_recovery_pct', v)}
          />

          <SubHeader>DCA (DOLLAR COST AVERAGE)</SubHeader>

          <ToggleRow
            label="Enable DCA"
            description="Accumulate additional position on significant drops"
            checked={dcaEnabled}
            onChange={(v) => updateConfig('dca.enabled', v)}
          />

          {dcaEnabled && (
            <div
              style={{
                marginTop: '12px',
                paddingLeft: '14px',
                borderLeft: '2px solid var(--accent-primary-border)',
                display: 'flex',
                flexDirection: 'column',
                gap: '4px',
              }}
            >
              <SliderWithValue
                label="Trigger after drop %"
                value={dcaTriggerDropPct}
                onChange={(v) => updateConfig('dca.trigger_drop_pct', v)}
                min={0}
                max={100}
                unit="%"
                hint="DCA kicks in when position drops this much"
              />
              <SliderWithValue
                label="Min score for DCA"
                value={dcaMinScore}
                onChange={(v) => updateConfig('dca.min_score', v)}
                min={0}
                max={100}
                hint="Asset must still score above this to DCA"
              />

              <div style={{ padding: '6px 0' }}>
                <div
                  style={{
                    fontSize: '13px',
                    color: 'var(--text-secondary)',
                    marginBottom: '6px',
