                    fontFamily: 'var(--font-sans)',
                  }}
                >
                  <input
                    type="radio"
                    name="trailingMethod"
                    value={value}
                    checked={trailingMethod === value}
                    onChange={() => updateConfig('trailing.method', value)}
                    style={{ accentColor: 'var(--accent-primary)' }}
                  />
                  {label}
                </label>
              ))}
            </div>
          </div>

          {trailingMethod === 'atr' && (
