}


function PipelineTab() {
  const [watchlists, setWatchlists] = useState<PipelineWatchlist[]>([]);
  const [pools, setPools] = useState<Pool[]>([]);
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [modalWl, setModalWl] = useState<Partial<PipelineWatchlist> | null>(null);
  const [showModal, setShowModal] = useState(false);
  const [refreshTick, setRefreshTick] = useState(0);

  // ── Live level-change highlights (transient, 3s per symbol) ──────────────
  const [liveDirections, setLiveDirections] = useState<Record<string, string>>({});
  const clearTimers = useRef<Record<string, ReturnType<typeof setTimeout>>>({});

  const userId = typeof window !== 'undefined' ? getCurrentUserId() : undefined;
  const { lastMessage } = useWebSocket('alerts', userId);

  useEffect(() => {
    if (!lastMessage || lastMessage.type !== 'level_change') return;
    const { symbol, direction } = lastMessage as { type: string; symbol: string; direction: string };
    if (!symbol || !direction) return;

    // Apply highlight
    setLiveDirections((prev) => ({ ...prev, [symbol]: direction }));

    // Clear after 3 seconds
    if (clearTimers.current[symbol]) clearTimeout(clearTimers.current[symbol]);
    clearTimers.current[symbol] = setTimeout(() => {
      setLiveDirections((prev) => {
        const next = { ...prev };
        delete next[symbol];
        return next;
      });
    }, 3000);
  }, [lastMessage]);

  // Cleanup timers on unmount
  useEffect(() => {
    return () => {
      Object.values(clearTimers.current).forEach(clearTimeout);
    };
  }, []);

  const load = useCallback(async (silent = false) => {
    if (!silent) setLoading(true);
    try {
      // Load each endpoint independently so a single failure (e.g. backend
      // schema drift on /watchlists) does not blank out pools and profiles.
      // The previous Promise.all + empty catch hid the original bug.
      const results = await Promise.allSettled([
        apiFetch<{ watchlists: PipelineWatchlist[] }>('/watchlists?order_by=performance_priority'),
        apiFetch<{ pools: Pool[] }>('/pools'),
        apiFetch<{ profiles: Profile[] }>('/profiles'),
      ]);

      const failures: string[] = [];

      const wlRes = results[0];
      if (wlRes.status === 'fulfilled') {
        setWatchlists(wlRes.value.watchlists ?? []);
      } else {
        console.error('Failed to load watchlists:', wlRes.reason);
        failures.push('watchlists');
      }

      const poolRes = results[1];
      if (poolRes.status === 'fulfilled') {
        setPools(poolRes.value.pools ?? []);
      } else {
        console.error('Failed to load pools:', poolRes.reason);
        failures.push('pools');
      }

      const profRes = results[2];
      if (profRes.status === 'fulfilled') {
        setProfiles(profRes.value.profiles ?? []);
      } else {
        console.error('Failed to load profiles:', profRes.reason);
        failures.push('profiles');
      }

      setLoadError(
        failures.length > 0
          ? `Falha ao carregar: ${failures.join(', ')}. Verifique o backend e recarregue a página.`
          : null,
      );
    } finally {
      if (!silent) setLoading(false);
    }
  }, []);

  const loadSilent = useCallback(() => load(true), [load]);

  useEffect(() => { load(); }, [load]);

  useEffect(() => {
    const interval = window.setInterval(() => {
      setRefreshTick((tick) => tick + 1);
      void loadSilent();
    }, WATCHLIST_POLL_MS);
    return () => window.clearInterval(interval);
  }, [loadSilent]);

  function openCreate() { setModalWl({}); setShowModal(true); }
  function openEdit(wl: PipelineWatchlist) { setModalWl(wl); setShowModal(true); }
  function closeModal() { setShowModal(false); setModalWl(null); }

  async function handleSave(data: Partial<PipelineWatchlist>) {
    if (modalWl?.id) {
      const updated = await apiFetch<PipelineWatchlist>(`/watchlists/${modalWl.id}`, {
        method: 'PUT',
        body: JSON.stringify(data),
      });
      setWatchlists((prev) => prev.map((w) => w.id === updated.id ? updated : w));
    } else {
      const created = await apiFetch<PipelineWatchlist>('/watchlists', {
        method: 'POST',
        body: JSON.stringify(data),
      });
      setWatchlists((prev) => [...prev, created]);
    }
    closeModal();
    await load(true);
  }

  function handleDelete(id: string) {
    setWatchlists((prev) => prev.filter((w) => w.id !== id));
  }

  const byLevel = (level: string) => watchlists.filter((w) => resolveWatchlistLevel(w, profiles) === level);
  const customWls = watchlists.filter((w) => resolveWatchlistLevel(w, profiles) === 'custom');

  return (
    <div className="space-y-6">
      {/* Error banner — surface load failures instead of hiding them */}
      {loadError && (
        <div className="rounded-lg border border-[#7F1D1D] bg-[#1F0A0A] px-4 py-3 text-sm text-[#FCA5A5]">
          {loadError}
        </div>
      )}

      {/* Toolbar */}
      <div className="flex items-center justify-between">
        <p className="text-sm text-[#64748B]">
          {watchlists.length === 0
            ? 'No pipeline watchlists yet. Create one to start filtering assets.'
            : `${watchlists.length} watchlist${watchlists.length !== 1 ? 's' : ''}`}
        </p>
        <button
          onClick={openCreate}
          className="flex items-center gap-2 px-4 py-2 rounded-lg bg-[#3B82F6] text-sm font-medium text-white hover:bg-[#2563EB] transition-colors"
        >
          <Plus size={14} />
          New Watchlist
        </button>
      </div>

      {loading ? (
        <div className="space-y-3">
          {[1, 2, 3].map((i) => (
            <div key={i} className="h-12 rounded-xl bg-[#0F1117] border border-[#1E2433] animate-pulse" />
          ))}
        </div>
      ) : watchlists.length === 0 ? (
        <div className="space-y-6">
          <div>
            <div className="mb-3 flex items-center gap-2">
              <LevelBadge level="L3" />
              <span className="text-xs text-[#4B5563]">visão virtual</span>
            </div>
            <L3ConsolidatedCard refreshTick={refreshTick} />
          </div>
          <div className="rounded-xl border border-dashed border-[#1E2433] py-16 text-center">
            <Layers size={40} className="mx-auto mb-4 text-[#1E2433]" />
            <p className="mb-4 text-sm text-[#4B5563]">Build your institutional asset funnel</p>
            <button
              onClick={openCreate}
              className="rounded-lg bg-[#1E2433] px-6 py-2.5 text-sm text-[#94A3B8] transition-colors hover:bg-[#263048] hover:text-[#E2E8F0]"
            >
              Create first watchlist
            </button>
          </div>
        </div>
      ) : (
        <div className="space-y-6">
          {(['POOL', 'L1', 'L2', 'L3'] as const).map((lvl) => {
            const lvlWls = byLevel(lvl);
            if (lvlWls.length === 0 && lvl !== 'L3') return null;
            const totalAssets = lvlWls.reduce((sum, w) => sum + (w.asset_count ?? 0), 0);
            return (
              <div key={lvl}>
                <div className="flex items-center gap-2 mb-3">
                  <LevelBadge level={lvl} />
                  <span className="text-xs text-[#4B5563]">{lvlWls.length} watchlist{lvlWls.length !== 1 ? 's' : ''}</span>
                  {totalAssets > 0 && (
                    <span
                      className="ml-1 inline-flex items-center gap-1 rounded-full border border-[#2A3448] bg-[#1E2433] px-2 py-0.5 text-xs font-medium text-[#94A3B8] tabular-nums"
                      title={`Total consolidado de ativos aprovados nas ${lvlWls.length} watchlists ${lvl}`}
                    >
                      <Layers size={10} />
                      {totalAssets} ativo{totalAssets !== 1 ? 's' : ''} aprovado{totalAssets !== 1 ? 's' : ''}
                    </span>
                  )}
                </div>
                <div className="space-y-2">
                  {lvl === 'L3' && <L3ConsolidatedCard refreshTick={refreshTick} />}
                  {lvlWls.map((wl) => (
                    <WatchlistRow
                      key={wl.id}
                      wl={wl}
                      pools={pools}
                      allWatchlists={watchlists}
                      profiles={profiles}
                      onEdit={openEdit}
                      onDelete={handleDelete}
                      onRefreshed={loadSilent}
                      refreshTick={refreshTick}
                      liveDirections={liveDirections}
                    />
                  ))}
                </div>
              </div>
            );
          })}
          {customWls.length > 0 && (
            <div>
              <div className="flex items-center gap-2 mb-3">
                <LevelBadge level="custom" />
                <span className="text-xs text-[#4B5563]">{customWls.length} watchlist{customWls.length !== 1 ? 's' : ''}</span>
              </div>
              <div className="space-y-2">
                {customWls.map((wl) => (
                  <WatchlistRow
                    key={wl.id}
                    wl={wl}
                    pools={pools}
                    allWatchlists={watchlists}
                    profiles={profiles}
                    onEdit={openEdit}
                    onDelete={handleDelete}
                    onRefreshed={loadSilent}
                    refreshTick={refreshTick}
                  />
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {showModal && (
        <WatchlistModal
          wl={modalWl}
          pools={pools}
          watchlists={watchlists}
          profiles={profiles}
          onClose={closeModal}
          onSave={handleSave}
        />
      )}
    </div>
  );
}

// ── Page ──────────────────────────────────────────────────────────────────────

type Tab = 'scanner' | 'pipeline';

export default function WatchlistPage() {
  const [activeTab, setActiveTab] = useState<Tab>('scanner');

  return (
    <div className="space-y-6">
      {/* Page header */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-[#E2E8F0]">Watchlist</h1>
          <p className="text-[#94A3B8] mt-1 text-sm">
            {activeTab === 'scanner'
              ? 'Real-time Alpha Score rankings and technical indicators.'
              : '4-level institutional asset funnel — Pool → L1 → L2 → L3.'}
          </p>
        </div>
      </div>

      {/* Tabs */}
      <div className="page-tabs">
        <button
          className={`page-tab${activeTab === 'scanner' ? ' active' : ''}`}
          onClick={() => setActiveTab('scanner')}
        >
          Market Scanner
        </button>
        <button
          className={`page-tab${activeTab === 'pipeline' ? ' active' : ''}`}
          onClick={() => setActiveTab('pipeline')}
        >
          Pipeline
        </button>
      </div>

      {/* Tab content */}
      {activeTab === 'scanner' && <WatchlistTable />}
      {activeTab === 'pipeline' && <PipelineTab />}
    </div>
  );
}

