"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import useSWR from "swr";
import { CheckCircle2, Inbox, WalletCards } from "lucide-react";
import { apiGet } from "@/lib/api";

/**
 * One row from ``GET /api/diagnostics/l3-queue`` — the L3-approved
 * snapshot the pipeline scan keeps in ``pipeline_watchlist_assets``.
 *
 * This is the same source the ``/watchlist`` page L3 tab reads, so
 * the card always reflects "what passed L3 in the latest scan",
 * independent of whether ``execute_buy`` has fired or whether the
 * caller has any USDT to spend.
 */
interface L3QueueRow {
  symbol: string;
  score: number | null;
  score_long: number | null;
  score_short: number | null;
  confidence_score: number | null;
  futures_direction: string | null;
  market_type: string;
  approved_at: string | null;
  pool_id: string | null;
  watchlist_id: string;
  watchlist_name: string;
}

interface L3QueueResponse {
  items: L3QueueRow[];
  count: number;
  /** ``buying.capital_per_trade_min_usdt`` from the user's spot_engine
   * config, or ``10.0`` when no config row exists. Drives the
   * "aguardando saldo" badge below. */
  min_trade_usdt: number;
}

interface BalanceResponse {
  available_usdt: number;
  in_positions: number;
  total: number;
  source: string;
}

const ENDPOINT = "/api/diagnostics/l3-queue?limit=50";
const BALANCE_ENDPOINT = "/api/live/balance";


/**
 * Left-column card showing the L3-approved assets currently sitting
 * in the active-pool pipeline. Source: the same
 * ``pipeline_watchlist_assets`` table the watchlist page L3 tab reads.
 *
 * Pulse animation fires on the *first render that contains a symbol
 * we haven't seen before* — we keep the seen-set in a ref so the
 * effect doesn't fire on every poll for the same row. Avoids the
 * page being a constant disco of pulses while the user is scrolling.
 */
export function L3ApprovedList() {
  const { data, isLoading } = useSWR<L3QueueResponse>(
    ENDPOINT,
    (url: string) => apiGet<L3QueueResponse>(url),
    {
      refreshInterval: 8_000,
      revalidateOnFocus: true,
      dedupingInterval: 3_000,
      keepPreviousData: true,
    }
  );

  // Balance is fetched separately so the L3 list keeps rendering
  // even if the exchange call fails (no_connection / exchange_error
  // both surface as available_usdt=0, which is the conservative
  // assumption — every row gets the "aguardando saldo" badge until
  // the user wires credentials).
  const { data: balance } = useSWR<BalanceResponse>(
    BALANCE_ENDPOINT,
    (url: string) => apiGet<BalanceResponse>(url),
    {
      refreshInterval: 15_000,
      revalidateOnFocus: true,
      dedupingInterval: 5_000,
      keepPreviousData: true,
    }
  );

  const items = data?.items ?? [];
  const minTradeUsdt = data?.min_trade_usdt ?? 10;
  const availableUsdt = balance?.available_usdt ?? 0;
  const awaitingBalance = availableUsdt < minTradeUsdt;

  const seenRef = useRef<Set<string>>(new Set());
  const [recentlyAdded, setRecentlyAdded] = useState<Set<string>>(new Set());

  useEffect(() => {
    const fresh: string[] = [];
    for (const row of items) {
      const key = rowKey(row);
      if (!seenRef.current.has(key)) {
        seenRef.current.add(key);
        fresh.push(key);
      }
    }
    if (fresh.length > 0 && seenRef.current.size > fresh.length) {
      // Only animate when there were already-seen rows (i.e. this is
      // a delta, not the initial mount). Prevents a pulse storm on
      // page load when the buffer fills with N rows at once.
      setRecentlyAdded(new Set(fresh));
      const t = setTimeout(() => setRecentlyAdded(new Set()), 1_500);
      return () => clearTimeout(t);
    }
    return undefined;
  }, [items]);

  return (
    <div className="card fade-in-up">
      <div className="card-header">
        <h3 style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <CheckCircle2 size={16} style={{ color: "var(--color-profit)" }} />
          L3 aprovados — pool ativo
        </h3>
        <span
          style={{
            fontFamily: "var(--font-mono)",
            fontSize: 12,
            color: "var(--text-tertiary)",
          }}
        >
          {items.length}
        </span>
      </div>
      <div
        style={{
          padding: 12,
          display: "flex",
          flexDirection: "column",
          gap: 8,
          maxHeight: 420,
          overflowY: "auto",
        }}
        className="custom-scrollbar"
      >
        {isLoading && items.length === 0 ? (
          <SkeletonList />
        ) : items.length === 0 ? (
          <EmptyState
            icon={<Inbox size={24} />}
            title="Nada aprovado ainda"
            subtitle="Ativos que passarem pelos filtros L3 do pipeline aparecem aqui."
          />
        ) : (
          items.map((row) => (
            <ApprovedCard
              key={rowKey(row)}
              row={row}
              pulse={recentlyAdded.has(rowKey(row))}
              awaitingBalance={awaitingBalance}
              minTradeUsdt={minTradeUsdt}
            />
          ))
        )}
      </div>
    </div>
  );
}

// ── Internal ────────────────────────────────────────────────────────


function ApprovedCard({
  row,
  pulse,
  awaitingBalance,
  minTradeUsdt,
}: {
  row: L3QueueRow;
  pulse: boolean;
  awaitingBalance: boolean;
  minTradeUsdt: number;
}) {
  const score = useMemo(() => extractScore(row), [row]);
  const scoreColor = score == null
    ? "var(--text-tertiary)"
    : score >= 80
    ? "var(--color-profit)"
    : score >= 60
    ? "var(--color-warning)"
    : "var(--color-loss)";

  return (
    <div
      style={{
        background: "var(--bg-elevated)",
        border: "1px solid var(--border-default)",
        borderLeft: "2px solid var(--color-profit)",
        borderRadius: "var(--radius-md)",
        padding: "12px 14px",
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        gap: 12,
        animation: pulse
          ? "pulseGlow 1.5s ease-out, fadeInUp 220ms ease-out"
          : "fadeInUp 220ms ease-out",
      }}
    >
      <div style={{ display: "flex", flexDirection: "column", gap: 2, minWidth: 0 }}>
        <div
          style={{
            fontFamily: "var(--font-mono)",
            fontSize: 14,
            fontWeight: 600,
            color: "var(--text-primary)",
            letterSpacing: "-0.01em",
          }}
        >
          {row.symbol}
        </div>
        <div
          style={{
            fontSize: 11,
            color: "var(--text-tertiary)",
            display: "flex",
            gap: 8,
            alignItems: "center",
            flexWrap: "wrap",
          }}
        >
          <span
            style={{
              padding: "1px 6px",
              border: "1px solid var(--border-default)",
              borderRadius: 4,
              textTransform: "uppercase",
              letterSpacing: "0.04em",
              fontWeight: 600,
            }}
          >
            {row.market_type}
          </span>
          {row.futures_direction && (
            <span
              style={{
                padding: "1px 6px",
                border: "1px solid var(--border-default)",
                borderRadius: 4,
                textTransform: "uppercase",
                letterSpacing: "0.04em",
                fontWeight: 600,
              }}
            >
              {row.futures_direction}
            </span>
          )}
          <span style={{ fontFamily: "var(--font-mono)" }}>
            {fmtTime(row.approved_at)}
          </span>
          {awaitingBalance && (
            <span
              title={`Saldo disponível abaixo do mínimo (${minTradeUsdt.toFixed(2)} USDT)`}
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: 4,
                padding: "1px 6px",
                borderRadius: 4,
                background: "color-mix(in srgb, var(--color-warning) 14%, transparent)",
                border: "1px solid color-mix(in srgb, var(--color-warning) 35%, transparent)",
                color: "var(--color-warning)",
                fontWeight: 600,
                textTransform: "uppercase",
                letterSpacing: "0.04em",
              }}
            >
              <WalletCards size={11} />
              aguardando saldo
            </span>
          )}
        </div>
      </div>
      {score != null && (
        <span
          style={{
            fontFamily: "var(--font-mono)",
            fontSize: 13,
            fontWeight: 600,
            color: scoreColor,
            background: `color-mix(in srgb, ${scoreColor} 12%, transparent)`,
            border: `1px solid color-mix(in srgb, ${scoreColor} 28%, transparent)`,
            padding: "2px 10px",
            borderRadius: 999,
            fontVariantNumeric: "tabular-nums",
          }}
        >
          {score.toFixed(0)}
        </span>
      )}
    </div>
  );
}

function SkeletonList() {
  return (
    <>
      {[0, 1, 2, 3].map((i) => (
        <div
          key={i}
          style={{
            height: 56,
            borderRadius: 8,
            background:
              "linear-gradient(90deg, var(--bg-hover) 0%, var(--bg-active) 50%, var(--bg-hover) 100%)",
            backgroundSize: "200% 100%",
            animation: "shimmer 1.4s ease-in-out infinite",
          }}
        />
      ))}
    </>
  );
}

function EmptyState({
  icon,
  title,
  subtitle,
}: {
  icon: React.ReactNode;
  title: string;
  subtitle: string;
}) {
  return (
    <div
      style={{
        textAlign: "center",
        padding: "32px 16px",
        color: "var(--text-tertiary)",
      }}
    >
      <div style={{ display: "flex", justifyContent: "center", marginBottom: 8, opacity: 0.7 }}>
        {icon}
      </div>
      <div style={{ color: "var(--text-secondary)", fontSize: 13, fontWeight: 600 }}>
        {title}
      </div>
      <div style={{ fontSize: 12, marginTop: 4 }}>{subtitle}</div>
    </div>
  );
}

// ── Helpers ─────────────────────────────────────────────────────────


/**
 * Stable identity for an L3-queue row across polls. ``watchlist_id``
 * is needed because the same symbol can legitimately exist on both
 * a spot and a futures L3 watchlist for the same user — keying by
 * symbol alone would collapse them and break the pulse-on-new
 * heuristic.
 */
function rowKey(row: L3QueueRow): string {
  return `${row.watchlist_id}:${row.symbol}`;
}

/**
 * Pulls a numeric "score" from the row using a small waterfall:
 * spot ``alpha_score`` → futures ``confidence_score`` →
 * max(score_long, score_short). Returns ``null`` when nothing is
 * usable so the card renders without a pill rather than ``"NaN"``.
 */
function extractScore(row: L3QueueRow): number | null {
  if (typeof row.score === "number" && isFinite(row.score)) return clamp(row.score);
  if (typeof row.confidence_score === "number" && isFinite(row.confidence_score)) {
    return clamp(row.confidence_score);
  }
  const longS = typeof row.score_long === "number" && isFinite(row.score_long) ? row.score_long : null;
  const shortS = typeof row.score_short === "number" && isFinite(row.score_short) ? row.score_short : null;
  if (longS != null || shortS != null) {
    return clamp(Math.max(longS ?? 0, shortS ?? 0));
  }
  return null;
}

function clamp(n: number): number {
  return Math.max(0, Math.min(100, n));
}

function fmtTime(iso?: string | null): string {
  if (!iso) return "—";
  try {
    return new Date(iso).toLocaleTimeString();
  } catch {
    return "—";
  }
}

"use client";

import { useMemo, useState } from "react";
import useSWR from "swr";
import { ChevronDown, ChevronRight, ShieldOff } from "lucide-react";
import { apiGet } from "@/lib/api";

interface RejectionGroup {
  rule_key: string;
  status: string;
  hits: number;
  distinct_symbols: number;
  sample_symbols: string[] | null;
}

interface RejectionsResponse {
  since: string;
  window_seconds: number;
  cutoff: string;
  groups: RejectionGroup[];
  count: number;
}

const ENDPOINT = "/api/diagnostics/rejections/summary?since=24h";


/**
 * Section 4: collapsible rejection summary.
 *
 * Default-closed per spec. We DON'T paginate — the backend caps at
 * 200 groups already, and rendering 200 short rows is cheaper than
 * adding a paginator that hides aggregate insight.
 *
 * The progress bar is normalised against the *largest* hit count in
 * the response so the operator instantly sees the dominant blocker
 * even when total volume varies wildly between days.
 */
export function RejectionSummary() {
  const [open, setOpen] = useState(false);

  // SWR pause: only fetch when expanded. Until then the network is
  // entirely idle for this section.
  const { data, isLoading } = useSWR<RejectionsResponse>(
    open ? ENDPOINT : null,
    (url: string) => apiGet<RejectionsResponse>(url),
    {
      refreshInterval: open ? 60_000 : 0,
      revalidateOnFocus: false,
      dedupingInterval: 30_000,
      keepPreviousData: true,
    }
  );

  const groups = data?.groups ?? [];
  const maxHits = useMemo(
    () => groups.reduce((m, g) => Math.max(m, g.hits), 0),
    [groups]
  );

  return (
    <div className="card fade-in-up">
      <button
        onClick={() => setOpen((v) => !v)}
        style={{
          width: "100%",
          background: "transparent",
          border: 0,
          padding: 0,
          cursor: "pointer",
        }}
      >
        <div
          className="card-header"
          style={{
            cursor: "pointer",
            transition: "background var(--transition-fast)",
          }}
        >
          <h3 style={{ display: "flex", alignItems: "center", gap: 8 }}>
            {open ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
            <ShieldOff size={16} style={{ color: "var(--color-warning)" }} />
            Top regras que mais bloquearam — últimas 24h
          </h3>
          {open && (
            <span
              style={{
                fontFamily: "var(--font-mono)",
                fontSize: 12,
                color: "var(--text-tertiary)",
              }}
            >
              {groups.length} grupos
            </span>
          )}
        </div>
      </button>

      {open && (
        <div style={{ padding: 12, maxHeight: 480, overflowY: "auto" }} className="custom-scrollbar">
          {isLoading && groups.length === 0 ? (
            <SkeletonRows />
          ) : groups.length === 0 ? (
            <div
              style={{
                padding: "32px 16px",
                textAlign: "center",
                color: "var(--text-tertiary)",
              }}
            >
              <div style={{ color: "var(--text-secondary)", fontSize: 13, fontWeight: 600 }}>
                Nenhuma reprovação na janela
              </div>
              <div style={{ fontSize: 12, marginTop: 4 }}>
                As últimas 24h estão limpas — nenhum gate bloqueou trades.
              </div>
            </div>
          ) : (
            <table className="data-table">
              <thead>
                <tr>
                  <th style={{ minWidth: 240 }}>Regra</th>
                  <th style={{ textAlign: "right" }}>Bloqueios</th>
                  <th style={{ textAlign: "right" }}>Símbolos</th>
                  <th style={{ minWidth: 200 }}>Distribuição</th>
                </tr>
              </thead>
              <tbody>
                {groups.map((g, i) => (
                  <tr key={`${g.rule_key}-${g.status}-${i}`}>
                    <td>
                      <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
                        <span
                          style={{
                            fontFamily: "var(--font-mono)",
                            fontSize: 13,
                            color: "var(--text-primary)",
                          }}
                        >
                          {g.rule_key}
                        </span>
                        <span
                          style={{
                            fontSize: 10,
                            color: "var(--text-tertiary)",
                            textTransform: "uppercase",
                            letterSpacing: "0.06em",
                          }}
                        >
                          {g.status}
                        </span>
                      </div>
                    </td>
                    <td className="numeric" style={{ fontWeight: 600 }}>
                      {g.hits.toLocaleString()}
                    </td>
                    <td className="numeric">{g.distinct_symbols}</td>
                    <td>
                      <div
                        style={{
                          height: 6,
                          background: "var(--bg-hover)",
                          borderRadius: 3,
                          overflow: "hidden",
                        }}
                      >
                        <div
                          style={{
                            width: `${maxHits ? (g.hits / maxHits) * 100 : 0}%`,
                            height: "100%",
                            background: "var(--color-warning)",
                            transition: "width var(--transition-base)",
                          }}
                        />
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}
    </div>
  );
}

function SkeletonRows() {
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
      {[0, 1, 2, 3, 4].map((i) => (
        <div
          key={i}
          style={{
            height: 36,
            borderRadius: 6,
            background:
              "linear-gradient(90deg, var(--bg-hover) 0%, var(--bg-active) 50%, var(--bg-hover) 100%)",
            backgroundSize: "200% 100%",
            animation: "shimmer 1.4s ease-in-out infinite",
          }}
        />
      ))}
    </div>
  );
}

"use client";

import { useAppStore } from '@/stores/useAppStore';
import { useAuthStore } from '@/stores/useAuthStore';
import { getToken } from '@/lib/auth';
import { Bell, ChevronRight, LogOut, Menu } from 'lucide-react';
import { usePathname, useRouter } from 'next/navigation';
import { useEffect, useRef, useState } from 'react';

export function Header() {
  const mode = useAppStore((state) => state.mode);
  const openMobileNav = useAppStore((state) => state.openMobileNav);
  const { user, logout, setUser } = useAuthStore();
  const pathname = usePathname();
  const router = useRouter();
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Hydrate auth store from localStorage on mount
  useEffect(() => {
    if (!user && typeof window !== 'undefined') {
      const stored = localStorage.getItem('user');
      const token = getToken();
      if (stored && token) {
        try {
          setUser(JSON.parse(stored), token);
        } catch {
          localStorage.removeItem('user');
        }
      }
    }
  }, [user, setUser]);

  // Close dropdown on outside click
  useEffect(() => {
    function handleClick(e: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
        setDropdownOpen(false);
      }
    }
    document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, []);

  // Format pathname as breadcrumb style
  const pathParts = pathname.split('/').filter(Boolean);
  const pageTitle =
    pathParts.length > 0
      ? pathParts[pathParts.length - 1].charAt(0).toUpperCase() +
        pathParts[pathParts.length - 1].slice(1)
      : 'Dashboard';

  // Derive user initials
  const initials = user?.name
    ? user.name
        .split(' ')
        .slice(0, 2)
        .map((w) => w[0].toUpperCase())
        .join('')
    : '?';

  function handleLogout() {
    logout();
    router.push('/login');
  }

  return (
    <header className="fixed top-0 left-[240px] max-lg:left-[64px] max-md:left-0 right-0 h-[56px] border-b border-[var(--border-subtle)] flex items-center justify-between px-6 z-40 backdrop-blur-md bg-[#0C0D12D9] transition-all duration-350 ease-out">

      {/* Hamburger — mobile only */}
      <button
        onClick={openMobileNav}
        className="md:hidden btn-icon mr-2 shrink-0"
        aria-label="Open navigation menu"
      >
        <Menu className="w-5 h-5" />
      </button>

      {/* Left side: Page Title & Breadcrumb */}
      <div className="flex flex-col justify-center flex-1 min-w-0">
        <div className="flex items-center gap-2 text-[11px] text-[var(--text-tertiary)] uppercase tracking-[0.05em] font-medium mb-0.5">
          <span>Scalpyn</span>
          <ChevronRight className="w-3 h-3" />
          {pathParts.length > 1 && (
            <>
              <span>{pathParts[0]}</span>
              <ChevronRight className="w-3 h-3" />
            </>
          )}
          <span className="text-[var(--text-secondary)]">{pageTitle}</span>
        </div>
      </div>

      {/* Right side controls */}
      <div className="flex items-center gap-4">

        {/* Mode Indicator */}
        <div className="flex items-center gap-2 px-3 py-1.5 bg-[var(--color-profit-muted)] border border-[var(--color-profit-border)] rounded-full text-[var(--color-profit)] text-[11px] font-semibold tracking-[0.05em] uppercase">
          <span className="live-dot bg-[var(--color-profit)]" /> LIVE TRADING
        </div>

        {/* Notifications */}
        <button className="btn-icon relative ml-2">
          <Bell className="w-4 h-4" />
          <span className="absolute top-2 right-2.5 w-1.5 h-1.5 bg-[var(--color-loss)] rounded-full border border-[var(--bg-surface)]" />
        </button>

        {/* User Avatar with dropdown */}
        <div className="relative" ref={dropdownRef}>
          <button
            onClick={() => setDropdownOpen((v) => !v)}
            className="w-8 h-8 rounded-full bg-[var(--accent-primary-muted)] border border-[var(--accent-primary-border)] flex items-center justify-center cursor-pointer hover:border-[var(--border-strong)] transition-colors text-[var(--accent-primary)] text-[11px] font-bold"
            title={user?.name ?? 'User'}
          >
            {initials}
          </button>

          {dropdownOpen && (
            <div
              style={{
                position: 'absolute',
                right: 0,
                top: 'calc(100% + 8px)',
                minWidth: '180px',
                background: 'var(--bg-elevated)',
                border: '1px solid var(--border-default)',
                borderRadius: 'var(--radius-md)',
                boxShadow: 'var(--shadow-md)',
                zIndex: 50,
                overflow: 'hidden',
              }}
            >
              {user && (
                <div
                  style={{
                    padding: '12px 14px',
                    borderBottom: '1px solid var(--border-subtle)',
                  }}
                >
                  <p style={{ fontSize: '13px', fontWeight: '600', color: 'var(--text-primary)', margin: 0 }}>
                    {user.name}
                  </p>
                  <p style={{ fontSize: '11px', color: 'var(--text-tertiary)', margin: '2px 0 0' }}>
                    {user.email}
                  </p>
                </div>
              )}
              <button
                onClick={handleLogout}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '8px',
                  width: '100%',
                  padding: '10px 14px',
                  background: 'none',
                  border: 'none',
                  cursor: 'pointer',
                  color: 'var(--color-loss)',
                  fontSize: '13px',
                  fontWeight: '500',
                  textAlign: 'left',
                }}
              >
                <LogOut className="w-4 h-4" />
                Sign out
              </button>
            </div>
          )}
        </div>
      </div>
    </header>
  );
}

