              <div className="text-[13px] font-semibold text-[var(--text-primary)] truncate">Ricardo T.</div>
              <div className="text-[11px] text-[var(--text-secondary)] bg-[var(--bg-active)] px-2 py-0.5 rounded-full inline-block mt-0.5">Admin</div>
            </div>
          )}
        </div>
        
        <button 
          onClick={() => {
            localStorage.removeItem('token');
            window.location.href = '/';
          }}
          className={`flex items-center justify-center gap-2 w-full py-2 rounded-md text-[var(--color-loss)] hover:bg-[var(--color-loss-muted)] hover:border-[var(--color-loss-border)] border border-transparent transition-colors ${collapsed ? '' : 'px-3'}`}
          title="Log Out"
        >
          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"></path><polyline points="16 17 21 12 16 7"></polyline><line x1="21" y1="12" x2="9" y2="12"></line></svg>
          {!collapsed && <span className="text-[13px] font-medium tracking-wide">Log Out</span>}
        </button>
      </div>
    </aside>
  );
}

"use client";

import React, { useState, useEffect, useRef, useMemo, useCallback } from "react";
import {
  X,
  Search,
  Plus,
  TrendingUp,
  TrendingDown,
  CheckSquare,
  Square,
  Loader2,
  ChevronLeft,
  ChevronRight,
  EyeOff,
  Eye,
} from "lucide-react";
import { apiGet, apiPost } from "@/lib/api";

// ── Types ────────────────────────────────────────────────────────────────────

export interface AssetSearchResult {
  symbol: string;
  name: string;
  price: number;
  market_cap: number;
  volume_24h: number;
  change_24h: number;
  type: "spot" | "futures" | "tradfi";
  already_in_pool: boolean;
}

type MarketType = "spot" | "futures" | "tradfi";

interface AddCryptosModalProps {
  poolId: string;
  poolMarketType: string;
  onClose: () => void;
  onAdded: () => void;
  existingSymbols: string[];
}

// ── Helpers ──────────────────────────────────────────────────────────────────

function formatValue(value: number | null | undefined): string {
  if (value == null || value <= 0) return "—";
  if (value >= 1_000_000_000_000) return `$${(value / 1_000_000_000_000).toFixed(2)}T`;
  if (value >= 1_000_000_000) return `$${(value / 1_000_000_000).toFixed(2)}B`;
  if (value >= 1_000_000) return `$${(value / 1_000_000).toFixed(2)}M`;
  if (value >= 1_000) return `$${(value / 1_000).toFixed(2)}K`;
  return `$${value.toFixed(2)}`;
}

function formatPrice(price: number): string {
  if (price <= 0) return "—";
  return `$${price.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 6 })}`;
}

// ── Component ────────────────────────────────────────────────────────────────

export default function AddCryptosModal({
  poolId,
  poolMarketType,
  onClose,
  onAdded,
  existingSymbols,
}: AddCryptosModalProps) {
  // State per tab — persist selections across tab switches
  const [marketType, setMarketType] = useState<MarketType>(
    (poolMarketType as MarketType) || "spot"
  );

  const [results, setResults] = useState<AssetSearchResult[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState("");
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(0);
  const [total, setTotal] = useState(0);
  const [hideExisting, setHideExisting] = useState(false);
  const [adding, setAdding] = useState(false);

  // Selection state persisted per tab
  const [selectionsByTab, setSelectionsByTab] = useState<Record<MarketType, Set<string>>>({
    spot: new Set(),
    futures: new Set(),
    tradfi: new Set(),
  });

  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const searchRef = useRef<HTMLInputElement>(null);
  const PER_PAGE = 50;

  const selected = selectionsByTab[marketType];

  // ── Fetch assets from backend ──────────────────────────────────────────────

  const fetchAssets = useCallback(
    async (query: string, pageNum: number, mType: MarketType) => {
      if (mType === "tradfi") {
        setResults([]);
        setTotal(0);
        setTotalPages(0);
        setLoading(false);
        return;
      }

      setLoading(true);
      setError(null);
      try {
        const params = new URLSearchParams({
          query,
          type: mType,
          pool_id: poolId,
          page: String(pageNum),
          per_page: String(PER_PAGE),
        });
        const data = await apiGet(`/assets/search?${params.toString()}`);
        setResults(data.results ?? []);
        setTotal(data.total ?? 0);
        setTotalPages(data.total_pages ?? 0);
      } catch (err: any) {
        setError(err.message ?? "Failed to search assets");
        setResults([]);
      } finally {
        setLoading(false);
      }
    },
    [poolId]
  );

  // Initial load when tab changes
  useEffect(() => {
    setSearch("");
    setPage(1);
    fetchAssets("", 1, marketType);
    setTimeout(() => searchRef.current?.focus(), 100);
  }, [marketType, fetchAssets]);

  // Debounced search
  const handleSearchChange = (value: string) => {
    setSearch(value);
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => {
      setPage(1);
      fetchAssets(value.trim(), 1, marketType);
    }, 400);
  };

  // Pagination
  const handlePageChange = (newPage: number) => {
    setPage(newPage);
    fetchAssets(search.trim(), newPage, marketType);
  };

  // ── Selection ──────────────────────────────────────────────────────────────

  const toggleSelect = (symbol: string, alreadyAdded: boolean) => {
    if (alreadyAdded) return;
    setSelectionsByTab((prev) => {
      const next = new Set(prev[marketType]);
      if (next.has(symbol)) {
        next.delete(symbol);
      } else {
        next.add(symbol);
      }
      return { ...prev, [marketType]: next };
    });
  };

  // Filter displayed results
  const displayResults = useMemo(() => {
    if (!hideExisting) return results;
    return results.filter((r) => !r.already_in_pool);
  }, [results, hideExisting]);

  const selectableInView = useMemo(
    () => displayResults.filter((r) => !r.already_in_pool),
    [displayResults]
  );

  const allVisibleSelected =
    selectableInView.length > 0 &&
    selectableInView.every((r) => selected.has(r.symbol));

  const toggleSelectAll = () => {
    const symbols = selectableInView.map((r) => r.symbol);
    setSelectionsByTab((prev) => {
      const next = new Set(prev[marketType]);
      if (allVisibleSelected) {
        symbols.forEach((s) => next.delete(s));
      } else {
        symbols.forEach((s) => next.add(s));
      }
      return { ...prev, [marketType]: next };
    });
  };

  // Total selections across all tabs
  const totalSelected =
    selectionsByTab.spot.size + selectionsByTab.futures.size + selectionsByTab.tradfi.size;

  // ── Confirm: bulk add ──────────────────────────────────────────────────────

  const handleConfirm = async () => {
    const assets = Object.entries(selectionsByTab).flatMap(([mType, syms]) =>
      Array.from(syms).map((sym) => ({ symbol: sym, market_type: mType }))
    );

    if (assets.length === 0) {
      onClose();
      return;
    }

    setAdding(true);
    setError(null);
    try {
      await apiPost(`/pools/${poolId}/coins/bulk`, { assets });
      onAdded();
      onClose();
    } catch (err: any) {
      setError(err.message ?? "Failed to add assets");
    } finally {
      setAdding(false);
    }
  };

  // ── Backdrop close ─────────────────────────────────────────────────────────

  const handleBackdropClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (e.target === e.currentTarget) onClose();
  };

  // ── Tab config ─────────────────────────────────────────────────────────────

  const marketTabs: { id: MarketType; label: string }[] = [
    { id: "spot", label: "Spot" },
    { id: "futures", label: "Futures" },
    { id: "tradfi", label: "TradFi" },
  ];

  // ── Render ─────────────────────────────────────────────────────────────────

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm"
      onClick={handleBackdropClick}
    >
      <div className="relative w-full max-w-3xl max-h-[90vh] flex flex-col bg-[var(--bg-card)] border border-[var(--border-default)] rounded-[var(--radius-lg)] shadow-2xl overflow-hidden">
        {/* ── Header ── */}
        <div className="flex items-center justify-between px-5 py-4 border-b border-[var(--border-subtle)]">
          <div>
            <h2 className="text-[16px] font-semibold text-[var(--text-primary)]">
              Adicionar Criptos Manualmente
            </h2>
            <p className="text-[12px] text-[var(--text-secondary)] mt-0.5">
              Busque e selecione ativos para adicionar ao pool
            </p>
          </div>
          <button
            className="btn-icon w-8 h-8 flex items-center justify-center hover:text-[var(--text-primary)]"
            onClick={onClose}
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* ── Market Tabs ── */}
        <div className="flex items-center justify-between px-5 pt-3 pb-2 border-b border-[var(--border-subtle)]">
          <div className="flex gap-1">
            {marketTabs.map((tab) => (
              <button
                key={tab.id}
                className={`px-4 py-1.5 text-[12px] font-medium rounded-[var(--radius-sm)] transition-colors ${
                  marketType === tab.id
                    ? "bg-[var(--accent-primary)] text-white"
                    : "text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-hover)]"
                }`}
                onClick={() => setMarketType(tab.id)}
              >
                {tab.label}
                {selectionsByTab[tab.id].size > 0 && (
                  <span className="ml-1.5 px-1.5 py-0.5 text-[10px] rounded-full bg-white/20">
                    {selectionsByTab[tab.id].size}
                  </span>
                )}
              </button>
            ))}
          </div>

          {/* Hide existing toggle */}
          <label className="flex items-center gap-2 cursor-pointer text-[12px] text-[var(--text-secondary)]">
            <input
              type="checkbox"
              checked={hideExisting}
              onChange={(e) => setHideExisting(e.target.checked)}
              style={{ accentColor: "var(--accent-primary)" }}
            />
            {hideExisting ? (
              <EyeOff className="w-3.5 h-3.5" />
            ) : (
              <Eye className="w-3.5 h-3.5" />
            )}
            Ocultar já adicionados
          </label>
        </div>

        {/* ── Search ── */}
        <div className="px-5 py-3 border-b border-[var(--border-subtle)]">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[var(--text-tertiary)]" />
            <input
              ref={searchRef}
              type="text"
              className="input pl-9 w-full text-[13px]"
              placeholder="Buscar por símbolo (BTC, ETH, SOL…)"
              value={search}
              onChange={(e) => handleSearchChange(e.target.value)}
              disabled={marketType === "tradfi"}
            />
            {loading && (
              <Loader2 className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 animate-spin text-[var(--text-tertiary)]" />
            )}
          </div>
        </div>

        {/* ── Error ── */}
        {error && (
          <div
            className="mx-5 mt-3 px-3 py-2 text-[13px] rounded-[var(--radius-md)]"
            style={{
              background: "var(--color-loss-muted)",
              color: "var(--color-loss)",
              border: "1px solid var(--color-loss-border)",
            }}
          >
            {error}
          </div>
        )}

        {/* ── Table ── */}
        <div className="flex-1 overflow-y-auto">
          {loading && results.length === 0 && (
            <div className="flex items-center justify-center py-16 text-[var(--text-secondary)] text-[14px]">
              <Loader2 className="w-5 h-5 animate-spin mr-2" />
              <span>Carregando ativos…</span>
            </div>
          )}

          {!loading && marketType === "tradfi" && (
            <div className="flex flex-col items-center justify-center py-16 text-[var(--text-secondary)] text-[14px] gap-2">
              <span className="text-3xl">🏦</span>
              <span>Ativos TradFi em breve</span>
              <span className="text-[12px] text-[var(--text-tertiary)]">
                Ações, ETFs e outros ativos tradicionais serão adicionados em futuras versões.
              </span>
            </div>
          )}

          {!loading && !error && marketType !== "tradfi" && displayResults.length === 0 && (
            <div className="flex items-center justify-center py-16 text-[var(--text-tertiary)] text-[13px]">
              {search
                ? `Nenhum ativo encontrado para "${search}"`
                : "Nenhum ativo disponível"}
            </div>
          )}

          {marketType !== "tradfi" && displayResults.length > 0 && (
            <table className="data-table w-full">
              <thead className="sticky top-0 bg-[var(--bg-card)] z-10">
                <tr>
                  <th className="w-10 text-center">
                    <button
                      className="btn-icon w-6 h-6 flex items-center justify-center mx-auto"
                      title="Selecionar todos visíveis"
                      onClick={toggleSelectAll}
                    >
                      {allVisibleSelected ? (
                        <CheckSquare className="w-3.5 h-3.5 text-[var(--accent-primary)]" />
                      ) : (
                        <Square className="w-3.5 h-3.5" />
                      )}
                    </button>
                  </th>
                  <th>Symbol</th>
                  <th className="text-right">Preço</th>
                  <th className="text-right">24h %</th>
                  <th className="text-right">Market Cap</th>
                  <th className="text-right" title="Volume 24h em USDT (ticker spot Gate.io). Não inclui futuros perpétuos nem outras exchanges.">Vol 24h (Gate Spot)</th>
                </tr>
              </thead>
              <tbody>
                {displayResults.map((asset) => {
                  const alreadyAdded =
                    asset.already_in_pool || existingSymbols.includes(asset.symbol);
                  const isSelected = selected.has(asset.symbol);
                  return (
                    <tr
                      key={asset.symbol}
                      className={`cursor-pointer ${
                        alreadyAdded
                          ? "opacity-40"
                          : isSelected
                          ? "bg-[var(--accent-primary)]/10"
                          : "hover:bg-[var(--bg-hover)]"
                      }`}
                      onClick={() => toggleSelect(asset.symbol, alreadyAdded)}
                    >
                      <td className="text-center" onClick={(e) => e.stopPropagation()}>
                        <button
                          disabled={alreadyAdded}
                          className="btn-icon w-6 h-6 flex items-center justify-center mx-auto"
                          onClick={() => toggleSelect(asset.symbol, alreadyAdded)}
                        >
                          {alreadyAdded ? (
                            <CheckSquare className="w-3.5 h-3.5 text-[var(--text-tertiary)]" />
                          ) : isSelected ? (
                            <CheckSquare className="w-3.5 h-3.5 text-[var(--accent-primary)]" />
                          ) : (
                            <Square className="w-3.5 h-3.5 text-[var(--text-tertiary)]" />
                          )}
                        </button>
                      </td>
                      <td>
                        <div className="flex items-center gap-2">
                          <span className="font-semibold text-[13px] text-[var(--text-primary)] font-mono">
                            {asset.name}
                          </span>
                          <span className="text-[11px] text-[var(--text-tertiary)]">
                            /USDT{asset.type === "futures" ? " Perp" : ""}
                          </span>
                          {alreadyAdded && (
                            <span className="text-[10px] px-1.5 py-0.5 rounded bg-[var(--bg-hover)] text-[var(--text-tertiary)]">
                              No pool
                            </span>
                          )}
                        </div>
                      </td>
                      <td className="numeric price text-right text-[13px]">
                        {formatPrice(asset.price)}
                      </td>
                      <td
                        className={`numeric text-right text-[13px] ${
                          asset.change_24h >= 0 ? "profit" : "loss"
                        }`}
                      >
                        <span className="inline-flex items-center gap-1">
                          {asset.change_24h >= 0 ? (
                            <TrendingUp className="w-3 h-3" />
                          ) : (
                            <TrendingDown className="w-3 h-3" />
                          )}
                          {asset.change_24h >= 0 ? "+" : ""}
                          {asset.change_24h.toFixed(2)}%
                        </span>
                      </td>
                      <td className="numeric text-right text-[var(--text-secondary)] text-[12px]">
                        {formatValue(asset.market_cap)}
                      </td>
                      <td className="numeric text-right text-[var(--text-secondary)] text-[12px]">
                        {formatValue(asset.volume_24h)}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          )}
        </div>

        {/* ── Pagination ── */}
        {!loading && marketType !== "tradfi" && totalPages > 1 && (
          <div className="flex items-center justify-center gap-2 px-5 py-2 border-t border-[var(--border-subtle)]">
            <button
              className="btn btn-ghost text-[12px] px-2 py-1"
              disabled={page <= 1}
              onClick={() => handlePageChange(page - 1)}
            >
              <ChevronLeft className="w-3.5 h-3.5" />
            </button>
            <span className="text-[12px] text-[var(--text-secondary)]">
              Página {page} de {totalPages}
              <span className="text-[var(--text-tertiary)] ml-1">({total} ativos)</span>
            </span>
            <button
              className="btn btn-ghost text-[12px] px-2 py-1"
              disabled={page >= totalPages}
              onClick={() => handlePageChange(page + 1)}
            >
              <ChevronRight className="w-3.5 h-3.5" />
            </button>
          </div>
        )}

        {/* ── Footer ── */}
        {marketType !== "tradfi" && (
          <div className="px-5 py-3 border-t border-[var(--border-subtle)] flex items-center justify-between gap-3">
            <span className="text-[11px] text-[var(--text-tertiary)]">
              {displayResults.length} ativos exibidos
              {totalSelected > 0 &&
                ` · ${totalSelected} selecionado${totalSelected !== 1 ? "s" : ""}`}
            </span>
            <div className="flex gap-2">
              <button className="btn text-[13px] px-4 py-1.5" onClick={onClose}>
                Cancelar
              </button>
              <button
                className="btn btn-primary text-[13px] px-4 py-1.5"
                disabled={totalSelected === 0 || adding}
                onClick={handleConfirm}
              >
                {adding ? (
                  <Loader2 className="w-3.5 h-3.5 mr-1 animate-spin" />
                ) : (
                  <Plus className="w-3.5 h-3.5 mr-1" />
                )}
                {adding
                  ? "Adicionando…"
                  : `Adicionar ao Pool${totalSelected > 0 ? ` (${totalSelected})` : ""}`}
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Bot, Zap } from "lucide-react";

interface Props {
  poolId: string;
  autopilotEnabled: boolean;
  onToggle?: (enabled: boolean) => void;
}

export default function PoolAutoPilotSection({ poolId, autopilotEnabled, onToggle }: Props) {
  const [enabled, setEnabled] = useState(autopilotEnabled);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const toggle = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch(`/api/pools/${poolId}/autopilot/toggle`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ enabled: !enabled }),
      });
      const data = await res.json();
      if (!res.ok) {
        setError(data.detail || "Erro ao alterar AutoPilot");
        return;
      }
      setEnabled(data.autopilot_enabled);
      onToggle?.(data.autopilot_enabled);
    } catch (e: any) {
      setError(`Erro de conexão: ${e.message}`);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: 8,
        padding: "12px 14px",
        borderRadius: 10,
        background: enabled
          ? "linear-gradient(135deg,rgba(59,130,246,0.1),rgba(37,99,235,0.06))"
          : "var(--bg-elevated, #1a1a2e)",
        border: `1px solid ${enabled ? "rgba(59,130,246,0.3)" : "rgba(255,255,255,0.07)"}`,
      }}
    >
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <Bot size={16} color={enabled ? "#3B82F6" : "#6B7280"} />
          <div>
            <div style={{ fontSize: 13, fontWeight: 700, color: enabled ? "#93C5FD" : "#9CA3AF" }}>
              Auto-Pilot
            </div>
            <div style={{ fontSize: 11, color: "#6B7280" }}>
              {enabled
                ? "Ativo — pool atualiza automaticamente"
                : "Inativo — pool requer atualização manual"}
            </div>
          </div>
        </div>
        <button
          onClick={toggle}
          disabled={loading}
          style={{
            display: "flex",
            alignItems: "center",
            gap: 6,
            padding: "6px 12px",
            fontSize: 12,
            fontWeight: 700,
            borderRadius: 6,
            border: "none",
            cursor: loading ? "not-allowed" : "pointer",
            background: enabled ? "#3B82F6" : "rgba(255,255,255,0.08)",
            color: enabled ? "#fff" : "#9CA3AF",
            transition: "all 200ms",
          }}
        >
          <Zap size={12} />
          {loading ? "..." : enabled ? "Desativar" : "Ativar"}
        </button>
      </div>
      {error && (
        <div style={{ fontSize: 11, color: "#F87171", paddingTop: 4 }}>{error}</div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { Sparkles, CheckCircle2, XCircle, ChevronDown, ChevronUp } from "lucide-react";

interface PoolPresetIAResult {
  status: string;
  pool_id: string;
  regime: string;
  macro_risk: string;
  analysis_summary: string;
  recommendations: {
    min_volume_24h?: number | null;
    min_market_cap?: number | null;
    max_assets?: number | null;
    remove_symbols?: string[];
    add_symbols?: string[];
  };
  executed_at: string;
}

interface Props {
  poolId: string;
  onSuccess?: (result: PoolPresetIAResult) => void;
}

const RISK_COLOR: Record<string, string> = {
  LOW: "#34D399",
  MEDIUM: "#FBBF24",
  HIGH: "#F97316",
  EXTREME: "#F87171",
};

export default function PoolConfigureButton({ poolId, onSuccess }: Props) {
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<PoolPresetIAResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [showDetail, setShowDetail] = useState(false);
  const [applying, setApplying] = useState(false);

  const handleRun = async () => {
    setLoading(true);
    setError(null);
    setResult(null);
    try {
      const res = await fetch(`/api/pools/${poolId}/preset-ia`, { method: "POST" });
      const data = await res.json();
      if (!res.ok) {
        setError(data.detail || `Erro ${res.status}`);
        return;
      }
      setResult(data);
      onSuccess?.(data);
    } catch (e: any) {
      setError(`Erro de conexão: ${e.message}`);
    } finally {
      setLoading(false);
    }
  };

  const handleApply = async () => {
    if (!result) return;
    setApplying(true);
    try {
      const res = await fetch(`/api/pools/${poolId}/preset-ia/apply`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ recommendations: result.recommendations }),
      });
      const data = await res.json();
      if (!res.ok) {
        setError(data.detail || `Erro ao aplicar: ${res.status}`);
        return;
      }
      onSuccess?.(result);
      setResult(null);
    } catch (e: any) {
      setError(`Erro ao aplicar: ${e.message}`);
    } finally {
      setApplying(false);
    }
  };

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
      <button
        onClick={handleRun}
        disabled={loading}
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          gap: 6,
          padding: "9px 14px",
          fontSize: 13,
          fontWeight: 700,
          borderRadius: 8,
          border: "none",
          cursor: loading ? "not-allowed" : "pointer",
          background: loading
            ? "linear-gradient(135deg,#6B3FA0,#4F7BF7)"
            : "linear-gradient(135deg,#8B5CF6,#4F7BF7)",
          color: "#fff",
          transition: "all 200ms",
          boxShadow: !loading ? "0 2px 16px rgba(139,92,246,0.25)" : "none",
          width: "100%",
        }}
      >
        <Sparkles size={14} style={loading ? { animation: "spin 1s linear infinite" } : {}} />
        {loading ? "Analisando pool..." : "✨ Configurar com IA"}
      </button>

      {error && (
        <div
          style={{
            display: "flex",
            alignItems: "flex-start",
            gap: 8,
            padding: "10px 12px",
            borderRadius: 8,
            fontSize: 12,
            background: "rgba(248,113,113,0.1)",
            border: "1px solid rgba(248,113,113,0.3)",
            color: "#F87171",
          }}
        >
          <XCircle size={13} style={{ flexShrink: 0, marginTop: 1 }} />
          <span>{error}</span>
        </div>
      )}

      {result && (
        <div
          style={{
            background: "var(--bg-elevated, #1a1a2e)",
            border: "1px solid rgba(139,92,246,0.25)",
            borderRadius: 10,
            overflow: "hidden",
          }}
        >
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 8,
              padding: "10px 14px",
              background: "linear-gradient(135deg,rgba(139,92,246,0.1),rgba(79,123,247,0.06))",
              borderBottom: "1px solid rgba(255,255,255,0.05)",
            }}
          >
            <CheckCircle2 size={14} color="#8B5CF6" />
            <span style={{ fontSize: 12, fontWeight: 700, flex: 1 }}>
              Análise concluída — {result.regime}
            </span>
            <span
              style={{
                fontSize: 10,
                fontWeight: 700,
                color: RISK_COLOR[result.macro_risk] || "#8B92A5",
              }}
            >
              {result.macro_risk}
            </span>
            <button
              onClick={() => setShowDetail((v) => !v)}
              style={{ background: "none", border: "none", cursor: "pointer", color: "#8B92A5" }}
            >
              {showDetail ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
            </button>
          </div>

          {showDetail && (
            <div style={{ padding: "10px 14px", fontSize: 12, color: "#8B92A5", lineHeight: 1.6 }}>
              <p style={{ marginBottom: 8 }}>{result.analysis_summary}</p>
              <pre
                style={{
                  background: "rgba(0,0,0,0.2)",
                  borderRadius: 6,
                  padding: 8,
                  fontSize: 11,
                  overflowX: "auto",
                }}
              >
                {JSON.stringify(result.recommendations, null, 2)}
              </pre>
            </div>
          )}

          <div
            style={{
              display: "flex",
              gap: 8,
              padding: "10px 14px",
              borderTop: "1px solid rgba(255,255,255,0.05)",
            }}
          >
            <button
              onClick={() => setResult(null)}
              style={{
                flex: 1,
                padding: "7px 12px",
                fontSize: 12,
                borderRadius: 6,
                border: "1px solid rgba(255,255,255,0.1)",
                background: "transparent",
                color: "#8B92A5",
                cursor: "pointer",
              }}
            >
              Descartar
            </button>
            <button
              onClick={handleApply}
              disabled={applying}
              style={{
                flex: 2,
                padding: "7px 12px",
                fontSize: 12,
                fontWeight: 700,
                borderRadius: 6,
                border: "none",
                background: "#8B5CF6",
                color: "#fff",
                cursor: applying ? "not-allowed" : "pointer",
              }}
            >
              {applying ? "Aplicando..." : "Aplicar Recomendações"}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { ArrowLeft, Save, Plus, Trash2, Check, AlertTriangle, Play } from "lucide-react";
import { apiPut } from "@/lib/api";
import { ConditionBuilder, NumericInput } from "./ConditionBuilder";

// ── Shared types (mirrors ProfileBuilder) ─────────────────────────────────────
type RuleConditionType = "threshold" | "comparison" | "boolean";

interface RuleCondition {
  id: string;
  type: RuleConditionType;
  indicator?: string;
  left?: string;
  right?: string;
  operator: string;
  value?: any;
  min?: number;
  max?: number;
  period?: number;
}

interface BlockRule {
  id: string;
  name: string;
  enabled: boolean;
  logic: "AND" | "OR";
  reason?: string;
  timeframe?: string;
  conditions: RuleCondition[];
}

interface EntryTrigger extends RuleCondition {
  required: boolean;
  enabled: boolean;
  timeframe?: string;
}

interface Profile {
  id: string;
  name: string;
  config: any;
}

interface BulkProfileBuilderProps {
  selectedProfiles: Profile[];
  onClose: () => void;
}

type ActiveTab = "filters" | "scoring" | "signals" | "block_rules" | "entry_triggers";

// ── Constants (mirrors ProfileBuilder) ───────────────────────────────────────
const RULE_INDICATORS = [
  { value: "rsi",                    label: "RSI",                               kind: "number" },
  { value: "adx",                    label: "ADX",                               kind: "number" },
