export function ProfileBuilder({ profile, onSave, onCancel }: ProfileBuilderProps) {
  const { config: globalScoreConfig } = useConfig("score");
  const [name, setName]                     = useState(profile?.name || "");
  const [description, setDescription]       = useState(profile?.description || "");
  const [config, setConfig]                 = useState<any>(() => normalizeProfileConfig(profile?.config));
  const [profileRole, setProfileRole]       = useState<ProfileRole | null>(profile?.profile_role || null);
  const [activeTab, setActiveTab]           = useState<ActiveTab>("filters");
  const [testResult, setTestResult]         = useState<any>(null);
  const [testing, setTesting]               = useState(false);
  const [saving, setSaving]                 = useState(false);
  const [scoringEnabled, setScoringEnabled] = useState(
    profile?.config?.scoring?.enabled !== false
  );
  const [signalsScoringEnabled, setSignalsScoringEnabled] = useState(
    profile?.config?.signals?.scoring?.enabled !== false
  );
  const [entryTriggersScoringEnabled, setEntryTriggersScoringEnabled] = useState(
    profile?.config?.entry_triggers?.scoring?.enabled !== false
  );
  const scoreRules = useMemo<ScoreRule[]>(
    () => ((globalScoreConfig?.scoring_rules as ScoreRule[] | undefined) || []).map((rule) => ({
      ...rule,
      category: rule.category || "",
      points: Number(rule.points ?? 0),
    })),
    [globalScoreConfig]
  );

  const handleSave = async () => {
    if (!name.trim()) { alert("Profile name is required"); return; }
    setSaving(true);
    const profileData = {
      name,
      description,
      config,
      is_active: true,
      profile_role: profileRole,
      pipeline_order: profileRole
        ? { universe_filter: 0, primary_filter: 1, score_engine: 2, acquisition_queue: 3 }[profileRole] ?? 99
        : 99,
    };
    onSave(profileData);
    setSaving(false);
  };

  const handleTest = async () => {
    setTesting(true);
    try {
      const result = await apiPost("/profiles/test-config", { config });
      setTestResult(result);
    } catch (e: any) {
      alert(`Test failed: ${e.message}`);
    }
    setTesting(false);
  };

  // ── Update helpers ──────────────────────────────────────────────────────────
  const updateFilters  = (conditions: Condition[], logic: string) =>
    setConfig((c: any) => ({ ...c, filters: { logic, conditions } }));

  const updateSignals  = (conditions: Condition[], logic: string) =>
    setConfig((c: any) => ({ ...c, signals: { ...c.signals, logic, conditions } }));

  const updateWeights  = (weights: any) =>
    setConfig((c: any) => ({ ...c, scoring: { ...c.scoring, weights } }));

  const toggleScoringRuleId = (ruleId: string) =>
    setConfig((c: any) => {
      const current: string[] = c.scoring?.selected_rule_ids ?? [];
      const next = current.includes(ruleId)
        ? current.filter((id: string) => id !== ruleId)
        : [...current, ruleId];
      return { ...c, scoring: { ...c.scoring, selected_rule_ids: next } };
    });

  const toggleScoringEnabled = (enabled: boolean) => {
    setScoringEnabled(enabled);
    setConfig((c: any) => ({ ...c, scoring: { ...c.scoring, enabled } }));
  };

  const toggleSignalsScoringRuleId = (ruleId: string) =>
    setConfig((c: any) => {
      const current: string[] = c.signals?.scoring?.selected_rule_ids ?? [];
      const next = current.includes(ruleId)
        ? current.filter((id: string) => id !== ruleId)
        : [...current, ruleId];
      return { ...c, signals: { ...c.signals, scoring: { ...c.signals?.scoring, selected_rule_ids: next } } };
    });

  const updateSignalsWeights = (weights: any) =>
    setConfig((c: any) => ({ ...c, signals: { ...c.signals, scoring: { ...c.signals?.scoring, weights } } }));

  const toggleSignalsScoringEnabled = (enabled: boolean) => {
    setSignalsScoringEnabled(enabled);
    setConfig((c: any) => ({ ...c, signals: { ...c.signals, scoring: { ...c.signals?.scoring, enabled } } }));
  };

  const toggleEntryTriggersScoringRuleId = (ruleId: string) =>
    setConfig((c: any) => {
      const current: string[] = c.entry_triggers?.scoring?.selected_rule_ids ?? [];
      const next = current.includes(ruleId)
        ? current.filter((id: string) => id !== ruleId)
        : [...current, ruleId];
      return { ...c, entry_triggers: { ...c.entry_triggers, scoring: { ...c.entry_triggers?.scoring, selected_rule_ids: next } } };
    });

  const updateEntryTriggersWeights = (weights: any) =>
    setConfig((c: any) => ({ ...c, entry_triggers: { ...c.entry_triggers, scoring: { ...c.entry_triggers?.scoring, weights } } }));

  const toggleEntryTriggersScoringEnabled = (enabled: boolean) => {
    setEntryTriggersScoringEnabled(enabled);
    setConfig((c: any) => ({ ...c, entry_triggers: { ...c.entry_triggers, scoring: { ...c.entry_triggers?.scoring, enabled } } }));
  };

  // ── Block Rules helpers ─────────────────────────────────────────────────────
  const addBlock = () =>
    setConfig((c: any) => ({
      ...c,
      block_rules: {
        ...c.block_rules,
        blocks: [
          ...(c.block_rules?.blocks || []),
          {
            id: `block_${Date.now()}`,
            name: "New Block",
            enabled: true,
            logic: "AND",
            conditions: [createRuleCondition("comparison")],
            reason: "",
          },
        ],
      },
    }));

  const removeBlock = (id: string) =>
    setConfig((c: any) => ({
      ...c,
      block_rules: { ...c.block_rules, blocks: (c.block_rules?.blocks || []).filter((b: BlockRule) => b.id !== id) },
    }));

  const updateBlock = (id: string, field: string, value: any) =>
    setConfig((c: any) => ({
      ...c,
      block_rules: {
        ...c.block_rules,
        blocks: (c.block_rules?.blocks || []).map((b: BlockRule) => b.id === id ? { ...b, [field]: value } : b),
      },
    }));

  const addBlockCondition = (blockId: string) =>
    setConfig((c: any) => ({
      ...c,
      block_rules: {
        ...c.block_rules,
        blocks: (c.block_rules?.blocks || []).map((block: BlockRule) => (
          block.id === blockId
            ? { ...block, conditions: [...(block.conditions || []), createRuleCondition("comparison")] }
            : block
        )),
      },
    }));

  const updateBlockCondition = (blockId: string, conditionId: string, updates: Partial<RuleCondition>) =>
    setConfig((c: any) => ({
      ...c,
      block_rules: {
        ...c.block_rules,
        blocks: (c.block_rules?.blocks || []).map((block: BlockRule) => (
          block.id === blockId
            ? {
                ...block,
                conditions: (block.conditions || []).map((condition) => (
                  condition.id === conditionId ? { ...condition, ...updates } : condition
                )),
              }
            : block
        )),
      },
    }));

  const removeBlockCondition = (blockId: string, conditionId: string) =>
    setConfig((c: any) => ({
      ...c,
      block_rules: {
        ...c.block_rules,
        blocks: (c.block_rules?.blocks || []).map((block: BlockRule) => (
          block.id === blockId
            ? {
                ...block,
                conditions: (block.conditions || []).filter((condition) => condition.id !== conditionId),
              }
            : block
        )),
      },
    }));

  // ── Entry Trigger helpers ───────────────────────────────────────────────────
  const addTrigger = () =>
    setConfig((c: any) => ({
      ...c,
      entry_triggers: {
        ...c.entry_triggers,
        conditions: [
          ...(c.entry_triggers?.conditions || []),
          {
            ...createRuleCondition("comparison"),
            id: `entry_${Date.now()}`,
            required: false,
            enabled: true,
          },
        ],
      },
    }));

  const removeTrigger = (id: string) =>
    setConfig((c: any) => ({
      ...c,
      entry_triggers: {
        ...c.entry_triggers,
        conditions: (c.entry_triggers?.conditions || []).filter((t: EntryTrigger) => t.id !== id),
      },
    }));

  const updateTrigger = (id: string, field: string, value: any) =>
    setConfig((c: any) => ({
      ...c,
      entry_triggers: {
        ...c.entry_triggers,
        conditions: (c.entry_triggers?.conditions || []).map((t: EntryTrigger) =>
          t.id === id ? { ...t, [field]: value } : t
        ),
      },
    }));

  const updateEntryLogic = (logic: string) =>
    setConfig((c: any) => ({ ...c, entry_triggers: { ...c.entry_triggers, logic } }));

  const buildEntryLogicPreview = (
    conditions: EntryTrigger[],
    defaultTimeframe: string,
    logic: string,
  ) => {
    const describe = (trigger: EntryTrigger, requiredLabel = false) => {
      const referenceIndicator = trigger.type === "comparison" ? trigger.left : trigger.indicator;
      const tf = referenceIndicator && NO_TF_INDICATORS.has(referenceIndicator)
        ? ""
        : ` (${trigger.timeframe || defaultTimeframe}${trigger.period ? `, P:${trigger.period}` : ""})`;
      let conditionText = "";

      if (trigger.type === "comparison") {
        conditionText = `${trigger.left} ${trigger.operator} ${trigger.right}`;
      } else if (trigger.type === "boolean") {
        const booleanValue =
          trigger.operator === "is_false" || trigger.value === false
            ? "False"
            : trigger.operator === "is_true" || trigger.value === true
              ? "True"
              : String(trigger.value ?? trigger.operator ?? "True");
        conditionText = `${trigger.indicator}${tf} = ${booleanValue}`;
      } else if (trigger.operator === "between") {
        conditionText = `between ${trigger.min} and ${trigger.max}`;
      } else {
        conditionText = `${trigger.operator} ${trigger.value}`;
      }

      if (trigger.type === "comparison") {
        return `  ${requiredLabel ? "[REQUIRED] " : ""}${conditionText}${tf}`.trimEnd();
      }

      return `  ${requiredLabel ? "[REQUIRED] " : ""}${trigger.indicator}${tf} ${conditionText}`.trimEnd();
    };

    const required = conditions.filter((t) => t.enabled && t.required);
    const optional = conditions.filter((t) => t.enabled && !t.required);
    const lines: string[] = ["IF ("];

    if (required.length > 0) {
      lines.push(required.map((trigger) => describe(trigger, true)).join("\n  AND\n"));
    }

    if (optional.length > 0) {
      if (required.length > 0) lines.push("  AND");
      lines.push("  (");
      lines.push(optional.map((trigger) => describe(trigger)).join(`\n    ${logic}\n`));
      lines.push("  )");
    }

    if (required.length === 0 && optional.length === 0) {
      lines.push("  No active entry triggers");
    }

    lines.push(") → ALLOW TRADE ENTRY");
    return lines.join("\n");
  };

  // ── Normalização safety-net (frontend) ─────────────────────────────────────
  const normalizePresetConfig = (incoming: any): any => {
    const FIELD_ALIASES: Record<string, string> = {
      "change_24h_pct":   "change_24h",
      "price_change_24h": "change_24h",
      "change_pct_24h":   "change_24h",
      "atr_pct":          "atr_percent",
      "atr_percentage":   "atr_percent",
      "bollinger_width":  "bb_width",
      "stochastic_k":     "stoch_k",
      "stochastic_d":     "stoch_d",
      "z_score":          "zscore",
    };

    const fixConditions = (conditions: any[]): any[] => {
      if (!Array.isArray(conditions)) return conditions;
      return conditions.map((cond) => {
        let field = cond.field || cond.indicator || "";
        let value = cond.value;
        if (FIELD_ALIASES[field]) field = FIELD_ALIASES[field];
        if (typeof value === "string") {
          const parsed = parseFloat(value.replace(",", "."));
          if (!isNaN(parsed)) value = parsed;
        }
        if (field === "volume_24h" && typeof value === "number") {
          const abs = Math.abs(value);
          if (value < 0)       field = "change_24h";
          else if (abs <= 5)   field = "atr_percent";
          else if (abs <= 100) field = "change_24h";
        }
        return { ...cond, field, value };
      });
    };

    const fixBlocks = (blocks: any[]): any[] => {
      if (!Array.isArray(blocks)) return [];
      return blocks.map((block) => normalizeBlockRule({
        ...block,
        indicator: FIELD_ALIASES[block.indicator || ""] || block.indicator,
      }));
    };

    return {
      ...incoming,
      filters: incoming.filters ? {
        ...incoming.filters,
        conditions: fixConditions(incoming.filters.conditions ?? []),
      } : incoming.filters,
      signals: incoming.signals ? {
        ...incoming.signals,
        conditions: fixConditions(incoming.signals.conditions ?? []),
        scoring: incoming.signals.scoring ?? { ...DEFAULT_SCORING_CONFIG },
      } : { logic: "AND", conditions: [], scoring: { ...DEFAULT_SCORING_CONFIG } },
      block_rules: incoming.block_rules ? {
        ...incoming.block_rules,
        blocks: fixBlocks(incoming.block_rules.blocks ?? []),
      } : { blocks: [] },
      entry_triggers: incoming.entry_triggers ? {
        logic: incoming.entry_triggers.logic || "AND",
        logic_preview_text: incoming.entry_triggers.logic_preview_text,
        conditions: fixConditions(incoming.entry_triggers.conditions ?? []).map((c: any) => normalizeEntryTrigger({
          ...c,
          indicator: c.field || c.indicator || "rsi",
          enabled: c.enabled !== false,
          required: c.required || false,
        })),
        scoring: incoming.entry_triggers.scoring ?? { ...DEFAULT_SCORING_CONFIG },
      } : { logic: "AND", conditions: [], scoring: { ...DEFAULT_SCORING_CONFIG } },
    };
  };

  const handlePresetIASuccess = (result: any) => {
    if (result?.config) {
      const normalized = normalizePresetConfig(result.config);
      setConfig(normalized);
      if (normalized.scoring?.enabled !== undefined) {
        setScoringEnabled(normalized.scoring.enabled !== false);
      }
      if (normalized.signals?.scoring?.enabled !== undefined) {
        setSignalsScoringEnabled(normalized.signals.scoring.enabled !== false);
      }
      if (normalized.entry_triggers?.scoring?.enabled !== undefined) {
        setEntryTriggersScoringEnabled(normalized.entry_triggers.scoring.enabled !== false);
      }
    }
  };

  const blocks: BlockRule[]           = config.block_rules?.blocks || [];
  const entryConditions: EntryTrigger[] = config.entry_triggers?.conditions || [];
  const entryLogic: string            = config.entry_triggers?.logic || "AND";
  const autoEntryLogicPreview = useMemo(
    () => buildEntryLogicPreview(entryConditions, config.default_timeframe || "5m", entryLogic),
    [entryConditions, config.default_timeframe, entryLogic]
  );

  const TABS: { key: ActiveTab; label: string; count?: number; icon?: React.ReactNode }[] = [
    { key: "filters",       label: "Filters",       count: config.filters?.conditions?.length ?? 0 },
    { key: "scoring",       label: "Scoring" },
    { key: "signals",       label: "Signals",       count: config.signals?.conditions?.length ?? 0 },
    { key: "block_rules",   label: "Block Rules",   count: blocks.filter(b => b.enabled).length,   icon: <ShieldOff className="w-3.5 h-3.5" /> },
    { key: "entry_triggers",label: "Entry Triggers",count: entryConditions.filter(t => t.enabled).length, icon: <Zap className="w-3.5 h-3.5" /> },
  ];

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center gap-4">
        <button className="btn btn-secondary p-2" onClick={onCancel} data-testid="back-btn">
          <ArrowLeft className="w-4 h-4" />
        </button>
        <div className="flex-1">
          <h1 className="text-2xl font-bold tracking-tight text-[var(--text-primary)]">
            {profile ? "Edit Profile" : "Create Profile"}
          </h1>
          <p className="text-[var(--text-secondary)] text-[13px]">Define your strategy configuration</p>
        </div>
        {profile?.id && (
          <PresetIAButton
            profileId={profile.id}
            profileRole={profileRole ?? profile.profile_role}
            size="sm"
            onSuccess={handlePresetIASuccess}
          />
        )}
        <button className="btn btn-secondary" onClick={handleTest} disabled={testing} data-testid="test-config-btn">
          <Play className="w-4 h-4 mr-2" />
          {testing ? "Testing..." : "Test Config"}
        </button>
        <button className="btn btn-primary" onClick={handleSave} disabled={saving} data-testid="save-profile-btn">
          <Save className="w-4 h-4 mr-2" />
          {saving ? "Saving..." : "Save Profile"}
        </button>
      </div>

      {/* Basic Info + Watchlist */}
      <div className="card">
        <div className="card-body p-6 space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="label">Profile Name</label>
              <input
                className="input"
                placeholder="e.g., High Volume Momentum"
                value={name}
                onChange={(e) => setName(e.target.value)}
                data-testid="profile-name-input"
              />
            </div>
            <div className="space-y-2">
              <label className="label">Default Timeframe</label>
              <select
                className="input"
                value={config.default_timeframe || "5m"}
                onChange={(e) => setConfig((c: any) => ({ ...c, default_timeframe: e.target.value }))}
                data-testid="default-timeframe-select"
              >
                {TIMEFRAME_OPTIONS.map((tf) => (
                  <option key={tf.value} value={tf.value}>{tf.label}</option>
                ))}
              </select>
              <p className="text-[11px] text-[var(--text-tertiary)]">
                Indicators inherit this timeframe unless overridden
              </p>
            </div>
          </div>

          <div className="space-y-2">
            <label className="label">Description</label>
            <textarea
              className="input min-h-[80px]"
              placeholder="Describe your strategy..."
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              data-testid="profile-description-input"
            />
          </div>

          <div className="pt-2">
            <ProfileRoleSelector value={profileRole} onChange={(role) => setProfileRole(role)} />
          </div>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-[var(--border-default)] overflow-x-auto">
        {TABS.map(({ key, label, count, icon }) => (
          <button
            key={key}
            className={`flex items-center gap-1.5 px-4 py-2 text-sm font-medium transition-colors whitespace-nowrap ${
              activeTab === key
                ? "text-[var(--accent-primary)] border-b-2 border-[var(--accent-primary)]"
                : "text-[var(--text-secondary)] hover:text-[var(--text-primary)]"
            }`}
            onClick={() => setActiveTab(key)}
            data-testid={`tab-${key}`}
          >
            {icon}
            {label}
            {count !== undefined && (
              <span className="ml-1 px-1.5 py-0.5 rounded-full bg-[var(--bg-hover)] text-[11px]">
                {count}
              </span>
            )}
          </button>
        ))}
      </div>

      {/* Tab Content */}
      <div className="card">
        <div className="card-body p-6">

          {/* ── FILTERS ── */}
          {activeTab === "filters" && (
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <div>
                  <h3 className="font-semibold text-[var(--text-primary)]">Filter Conditions</h3>
                  <p className="text-[12px] text-[var(--text-secondary)]">Assets must pass these binary conditions to be included. Scoring rules are configured in the Scoring tab.</p>
                </div>
                <select
                  className="input w-24"
                  value={config.filters?.logic ?? "AND"}
                  onChange={(e) => updateFilters(config.filters?.conditions ?? [], e.target.value)}
                  data-testid="filter-logic-select"
                >
                  <option value="AND">AND</option>
                  <option value="OR">OR</option>
                </select>
              </div>
              <ConditionBuilder
                conditions={config.filters?.conditions ?? []}
                onChange={(conditions) => updateFilters(conditions, config.filters?.logic ?? "AND")}
                showRequired={false}
                defaultTimeframe={config.default_timeframe || "5m"}
                scoreRules={scoreRules}
              />
            </div>
          )}

          {/* ── SCORING ── */}
          {activeTab === "scoring" && (
            <ScoreEngineConfigPanel
              scoreRules={scoreRules}
              selectedIds={config.scoring?.selected_rule_ids ?? []}
              onToggleRuleId={toggleScoringRuleId}
              onClearSelection={() => setConfig((c: any) => ({ ...c, scoring: { ...c.scoring, selected_rule_ids: [] } }))}
              isEnabled={scoringEnabled}
              weights={config.scoring?.weights ?? { liquidity: 25, market_structure: 25, momentum: 25, signal: 25 }}
              onUpdateWeights={updateWeights}
              onToggleEnabled={toggleScoringEnabled}
              testid="scoring"
            />
          )}

          {/* ── SIGNALS ── */}
          {activeTab === "signals" && (
            <div className="space-y-6">
              <ScoreEngineConfigPanel
                scoreRules={scoreRules}
                selectedIds={config.signals?.scoring?.selected_rule_ids ?? []}
                onToggleRuleId={toggleSignalsScoringRuleId}
                onClearSelection={() => setConfig((c: any) => ({ ...c, signals: { ...c.signals, scoring: { ...c.signals?.scoring, selected_rule_ids: [] } } }))}
                isEnabled={signalsScoringEnabled}
                weights={config.signals?.scoring?.weights ?? { liquidity: 25, market_structure: 25, momentum: 25, signal: 25 }}
                onUpdateWeights={updateSignalsWeights}
                onToggleEnabled={toggleSignalsScoringEnabled}
                testid="signals-scoring"
              />
              <div className="space-y-4 pt-4 border-t border-[var(--border-subtle)]">
                <div className="flex items-center justify-between">
                  <div>
                    <h3 className="font-semibold text-[var(--text-primary)]">Signal Entry Conditions</h3>
                    <p className="text-[12px] text-[var(--text-secondary)]">Define when a trading signal should be triggered</p>
                  </div>
                  <select
                    className="input w-24"
                    value={config.signals?.logic ?? "AND"}
                    onChange={(e) => updateSignals(config.signals?.conditions ?? [], e.target.value)}
                    data-testid="signal-logic-select"
                  >
                    <option value="AND">AND</option>
                    <option value="OR">OR</option>
                  </select>
                </div>
                <ConditionBuilder
                  conditions={config.signals?.conditions ?? []}
                  onChange={(conditions) => updateSignals(conditions, config.signals?.logic ?? "AND")}
                  showRequired={true}
                  defaultTimeframe={config.default_timeframe || "5m"}
                />
              </div>
            </div>
          )}

          {/* ── BLOCK RULES ── */}
          {activeTab === "block_rules" && (
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <div>
                  <h3 className="font-semibold text-[var(--text-primary)]">Block Rules</h3>
                  <p className="text-[12px] text-[var(--text-secondary)]">
                    Hard veto conditions — assets matching any rule are immediately blocked from the watchlist
                  </p>
                </div>
                <button onClick={addBlock} className="btn btn-secondary text-[12px] px-3 py-1.5">
                  <Plus className="w-3.5 h-3.5 mr-1" />
                  Add Block
                </button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {blocks.map((block) => (
                  <div
                    key={block.id}
                    className={`card ${block.enabled ? "border-l-4 border-l-[var(--color-loss)]" : "opacity-60"}`}
                  >
                    <div className="p-4 space-y-3">
                      <div className="flex items-center justify-between gap-2">
                        <input
                          type="text"
                          className="input h-8 text-[13px] font-semibold flex-1"
                          value={block.name}
                          onChange={(e) => updateBlock(block.id, "name", e.target.value)}
                          placeholder="Block name"
                        />
                        <div className="flex items-center gap-2 shrink-0">
                          <div
                            className={`toggle ${block.enabled ? "active" : ""}`}
                            onClick={() => updateBlock(block.id, "enabled", !block.enabled)}
                          >
                            <div className="knob" />
                          </div>
                          <button
                            onClick={() => removeBlock(block.id)}
                            className="btn-icon w-7 h-7 flex items-center justify-center hover:text-[var(--color-loss)]"
                          >
                            <Trash2 className="w-3.5 h-3.5" />
                          </button>
                        </div>
                      </div>

                      <div className="flex items-center justify-between gap-2">
                        <div className="flex items-center gap-2">
                          <span className="text-[11px] text-[var(--text-secondary)]">Logic</span>
                          <select
                            className="input h-8 w-20 text-[12px]"
                            value={block.logic || "AND"}
                            onChange={(e) => updateBlock(block.id, "logic", e.target.value)}
                          >
                            <option value="AND">AND</option>
                            <option value="OR">OR</option>
                          </select>
                        </div>
                        <button
                          type="button"
                          className="btn btn-secondary text-[11px] px-2.5 py-1"
                          onClick={() => addBlockCondition(block.id)}
                        >
                          <Plus className="w-3.5 h-3.5 mr-1" />
                          Condition
                        </button>
                      </div>

                      {/* Timeframe / Period overrides */}
                      {block.conditions.some((condition) => {
                        const reference = condition.type === "comparison" ? condition.left : condition.indicator;
                        return reference ? !NO_TF_INDICATORS.has(reference) : false;
                      }) && (
                        <div className="grid grid-cols-2 gap-2">
                          <div className="space-y-1">
                            <label className="label text-[11px]">Timeframe</label>
                            <select
                              className="input h-8 text-[12px]"
                              value={block.timeframe || ""}
                              onChange={(e) => updateBlock(block.id, "timeframe", e.target.value || undefined)}
                            >
                              <option value="">{config.default_timeframe || "5m"} (default)</option>
                              {TIMEFRAME_OPTIONS.map((tf) => (
                                <option key={tf.value} value={tf.value}>{tf.label}</option>
                              ))}
                            </select>
                          </div>
                          <div className="text-[11px] text-[var(--text-tertiary)] flex items-end pb-2">
                            Shared across this block rule
                          </div>
                        </div>
                      )}

                      <div className="space-y-2">
                        {block.conditions.map((condition) => (
                          <div key={condition.id} className="flex items-center gap-2 flex-wrap rounded-md border border-[var(--border-subtle)] p-2">
                            <select
                              className="input h-8 text-[12px] min-w-[120px]"
                              value={condition.type}
                              onChange={(e) => {
                                const nextCondition = createRuleCondition(e.target.value as RuleConditionType);
                                updateBlockCondition(block.id, condition.id, {
                                  type: nextCondition.type,
                                  indicator: nextCondition.indicator,
                                  left: nextCondition.left,
                                  right: nextCondition.right,
                                  operator: nextCondition.operator,
                                  value: nextCondition.value,
                                  min: nextCondition.min,
                                  max: nextCondition.max,
                                });
                              }}
                            >
                              {RULE_TYPE_OPTIONS.map((option) => (
                                <option key={option.value} value={option.value}>{option.label}</option>
                              ))}
                            </select>

                            {condition.type === "comparison" ? (
                              <>
                                <select
                                  className="input h-8 text-[12px] min-w-[120px]"
                                  value={condition.left || "price"}
                                  onChange={(e) => updateBlockCondition(block.id, condition.id, { left: e.target.value })}
                                >
                                  {NUMERIC_RULE_INDICATORS.map((indicator) => (
                                    <option key={indicator.value} value={indicator.value}>{indicator.label}</option>
                                  ))}
                                </select>
                                {PERIOD_DEFAULTS[condition.left || ""] !== undefined && (
                                  <input
                                    type="number"
                                    className="input h-8 w-20 text-[12px] font-mono text-center"
                                    value={condition.period ?? ""}
                                    onChange={(e) => {
                                      const v = parseInt(e.target.value, 10);
                                      updateBlockCondition(block.id, condition.id, { period: isNaN(v) ? undefined : v });
                                    }}
                                    placeholder={`P:${PERIOD_DEFAULTS[condition.left || ""]}`}
                                    title={`Period (default: ${PERIOD_DEFAULTS[condition.left || ""]})`}
                                  />
                                )}
                                <select
                                  className="input h-8 text-[12px] w-20"
                                  value={condition.operator}
                                  onChange={(e) => updateBlockCondition(block.id, condition.id, { operator: e.target.value })}
                                >
                                  {COMPARISON_OPERATORS.map((operator) => (
                                    <option key={operator} value={operator}>{operator}</option>
                                  ))}
                                </select>
                                <select
                                  className="input h-8 text-[12px] min-w-[120px]"
                                  value={condition.right || "ema9"}
                                  onChange={(e) => updateBlockCondition(block.id, condition.id, { right: e.target.value })}
                                >
                                  {NUMERIC_RULE_INDICATORS.map((indicator) => (
                                    <option key={indicator.value} value={indicator.value}>{indicator.label}</option>
                                  ))}
                                </select>
                              </>
                            ) : condition.type === "boolean" ? (
                              <>
                                <select
                                  className="input h-8 text-[12px] min-w-[140px]"
                                  value={condition.indicator || "ema9_gt_ema21"}
                                  onChange={(e) => updateBlockCondition(block.id, condition.id, { indicator: e.target.value })}
                                >
                                  {BOOLEAN_RULE_INDICATORS.map((indicator) => (
                                    <option key={indicator.value} value={indicator.value}>{indicator.label}</option>
                                  ))}
                                </select>
                                {PERIOD_DEFAULTS[condition.indicator || ""] !== undefined && (
                                  <input
                                    type="number"
                                    className="input h-8 w-20 text-[12px] font-mono text-center"
                                    value={condition.period ?? ""}
                                    onChange={(e) => {
                                      const v = parseInt(e.target.value, 10);
                                      updateBlockCondition(block.id, condition.id, { period: isNaN(v) ? undefined : v });
                                    }}
                                    placeholder={`P:${PERIOD_DEFAULTS[condition.indicator || ""]}`}
                                    title={`Period (default: ${PERIOD_DEFAULTS[condition.indicator || ""]})`}
                                  />
                                )}
                                <select
                                  className="input h-8 text-[12px] w-24"
                                  value={condition.operator === "is_false" ? "false" : "true"}
                                  onChange={(e) => {
                                    const booleanValue = e.target.value === "true";
                                    updateBlockCondition(block.id, condition.id, {
                                      operator: booleanValue ? "is_true" : "is_false",
                                      value: booleanValue,
                                    });
                                  }}
                                >
                                  <option value="true">True</option>
                                  <option value="false">False</option>
                                </select>
                              </>
                            ) : (
                              <>
                                <select
                                  className="input h-8 text-[12px] min-w-[140px]"
                                  value={condition.indicator || "rsi"}
                                  onChange={(e) => updateBlockCondition(block.id, condition.id, { indicator: e.target.value })}
                                >
                                  {NUMERIC_RULE_INDICATORS.map((indicator) => (
                                    <option key={indicator.value} value={indicator.value}>{indicator.label}</option>
                                  ))}
                                </select>
                                {PERIOD_DEFAULTS[condition.indicator || ""] !== undefined && (
                                  <input
                                    type="number"
                                    className="input h-8 w-20 text-[12px] font-mono text-center"
                                    value={condition.period ?? ""}
                                    onChange={(e) => {
                                      const v = parseInt(e.target.value, 10);
                                      updateBlockCondition(block.id, condition.id, { period: isNaN(v) ? undefined : v });
                                    }}
                                    placeholder={`P:${PERIOD_DEFAULTS[condition.indicator || ""]}`}
                                    title={`Period (default: ${PERIOD_DEFAULTS[condition.indicator || ""]})`}
                                  />
                                )}
                                <select
                                  className="input h-8 text-[12px] w-24"
                                  value={condition.operator}
                                  onChange={(e) => {
                                    const operator = e.target.value;
                                    updateBlockCondition(block.id, condition.id, {
                                      operator,
                                      value: operator === "between" ? undefined : condition.value ?? 0,
                                      min: operator === "between" ? Number(condition.value ?? condition.min ?? 0) : undefined,
                                      max: operator === "between" ? Number(condition.max ?? 100) : undefined,
                                    });
                                  }}
                                >
                                  {THRESHOLD_OPERATORS.map((operator) => (
                                    <option key={operator} value={operator}>{operator === "between" ? "between" : operator}</option>
                                  ))}
                                </select>
                                {condition.operator === "between" ? (
                                  <>
                                    <input
                                      type="number"
                                      className="input h-8 w-20 text-[12px] font-mono"
                                      value={condition.min ?? 0}
                                      onChange={(e) => updateBlockCondition(block.id, condition.id, { min: parseFloat(e.target.value) || 0 })}
                                      placeholder="Min"
                                    />
                                    <input
                                      type="number"
                                      className="input h-8 w-20 text-[12px] font-mono"
                                      value={condition.max ?? 100}
                                      onChange={(e) => updateBlockCondition(block.id, condition.id, { max: parseFloat(e.target.value) || 0 })}
                                      placeholder="Max"
                                    />
                                  </>
                                ) : (
                                  <input
                                    type="number"
                                    className="input h-8 w-24 text-[12px] font-mono"
                                    value={typeof condition.value === "number" ? condition.value : Number(condition.value ?? 0)}
                                    onChange={(e) => updateBlockCondition(block.id, condition.id, { value: parseFloat(e.target.value) || 0 })}
                                  />
                                )}
                              </>
                            )}

                            <button
                              type="button"
                              onClick={() => removeBlockCondition(block.id, condition.id)}
                              className="btn-icon w-7 h-7 flex items-center justify-center hover:text-[var(--color-loss)] ml-auto"
                            >
                              <Trash2 className="w-3.5 h-3.5" />
                            </button>
                          </div>
                        ))}
                      </div>

                      <input
                        type="text"
                        className="input h-8 text-[12px]"
                        value={block.reason || ""}
                        onChange={(e) => updateBlock(block.id, "reason", e.target.value)}
                        placeholder="Reason (e.g. Overbought extreme)"
                      />
                    </div>
                  </div>
                ))}
              </div>

              {blocks.length === 0 && (
                <div className="text-center py-12 text-[var(--text-tertiary)] text-[13px]">
                  No block rules defined. All assets will pass the block check for this profile.
                </div>
              )}
            </div>
          )}

          {/* ── ENTRY TRIGGERS ── */}
          {activeTab === "entry_triggers" && (
            <div className="space-y-6">
              <ScoreEngineConfigPanel
                scoreRules={scoreRules}
                selectedIds={config.entry_triggers?.scoring?.selected_rule_ids ?? []}
                onToggleRuleId={toggleEntryTriggersScoringRuleId}
                onClearSelection={() => setConfig((c: any) => ({ ...c, entry_triggers: { ...c.entry_triggers, scoring: { ...c.entry_triggers?.scoring, selected_rule_ids: [] } } }))}
                isEnabled={entryTriggersScoringEnabled}
                weights={config.entry_triggers?.scoring?.weights ?? { liquidity: 25, market_structure: 25, momentum: 25, signal: 25 }}
                onUpdateWeights={updateEntryTriggersWeights}
                onToggleEnabled={toggleEntryTriggersScoringEnabled}
                testid="entry-triggers-scoring"
              />
              <div className="space-y-4 pt-4 border-t border-[var(--border-subtle)]">
              <div className="flex items-center justify-between">
                <div>
                  <h3 className="font-semibold text-[var(--text-primary)]">Entry Triggers</h3>
                  <p className="text-[12px] text-[var(--text-secondary)]">
                    Conditions that must be met to allow trade execution (L3 only)
                  </p>
                </div>
                <div className="flex items-center gap-3">
                  <div className="flex items-center gap-2">
                    <span className="text-[12px] text-[var(--text-secondary)]">Logic:</span>
                    <select
                      className="input h-8 w-20 text-[12px]"
                      value={entryLogic}
                      onChange={(e) => updateEntryLogic(e.target.value)}
                    >
                      <option value="AND">AND</option>
                      <option value="OR">OR</option>
                    </select>
                  </div>
                  <button onClick={addTrigger} className="btn btn-secondary text-[12px] px-3 py-1.5">
                    <Plus className="w-3.5 h-3.5 mr-1" />
                    Add Trigger
                  </button>
                </div>
              </div>

              <div className="space-y-2">
                {entryConditions.map((trig) => (
                  <div
                    key={trig.id}
                    className={`flex items-center gap-3 p-3 rounded-[var(--radius-md)] border ${
                      trig.enabled
                        ? "border-[var(--border-default)] bg-[var(--bg-surface)]"
                        : "border-[var(--border-subtle)] bg-[var(--bg-base)] opacity-60"
                    }`}
                    >
                      <div
                        className={`toggle ${trig.enabled ? "active" : ""}`}
                        onClick={() => updateTrigger(trig.id, "enabled", !trig.enabled)}
                      >
                        <div className="knob" />
                      </div>
                    <select
                      className="input h-8 text-[12px] w-32"
                      value={trig.type}
                      onChange={(e) => {
                        const nextCondition = createRuleCondition(e.target.value as RuleConditionType);
                        updateTrigger(trig.id, "type", nextCondition.type);
                        updateTrigger(trig.id, "indicator", nextCondition.indicator);
                        updateTrigger(trig.id, "left", nextCondition.left);
                        updateTrigger(trig.id, "right", nextCondition.right);
                        updateTrigger(trig.id, "operator", nextCondition.operator);
                        updateTrigger(trig.id, "value", nextCondition.value);
                        updateTrigger(trig.id, "min", nextCondition.min);
                        updateTrigger(trig.id, "max", nextCondition.max);
                      }}
                    >
                      {RULE_TYPE_OPTIONS.map((option) => (
                        <option key={option.value} value={option.value}>{option.label}</option>
                      ))}
                    </select>
                    {trig.type === "comparison" ? (
                      <>
                        <select
                          className="input h-8 text-[12px] w-36"
                          value={trig.left || "price"}
                          onChange={(e) => updateTrigger(trig.id, "left", e.target.value)}
                        >
                          {NUMERIC_RULE_INDICATORS.map((indicator) => (
                            <option key={indicator.value} value={indicator.value}>{indicator.label}</option>
                          ))}
                        </select>
                        <select
                          className="input h-8 text-[12px] w-20"
                          value={trig.operator}
                          onChange={(e) => updateTrigger(trig.id, "operator", e.target.value)}
                        >
                          {COMPARISON_OPERATORS.map((operator) => (
                            <option key={operator} value={operator}>{operator}</option>
                          ))}
                        </select>
                        <select
                          className="input h-8 text-[12px] w-36"
                          value={trig.right || "ema9"}
                          onChange={(e) => updateTrigger(trig.id, "right", e.target.value)}
                        >
                          {NUMERIC_RULE_INDICATORS.map((indicator) => (
                            <option key={indicator.value} value={indicator.value}>{indicator.label}</option>
                          ))}
                        </select>
                      </>
                    ) : trig.type === "boolean" ? (
                      <>
                        <select
                          className="input h-8 text-[12px] w-36"
                          value={trig.indicator || "ema9_gt_ema21"}
                          onChange={(e) => updateTrigger(trig.id, "indicator", e.target.value)}
                        >
                          {BOOLEAN_RULE_INDICATORS.map((indicator) => (
                            <option key={indicator.value} value={indicator.value}>{indicator.label}</option>
                          ))}
                        </select>
                        <select
                          className="input h-8 text-[12px] w-24"
                          value={trig.operator === "is_false" ? "false" : "true"}
                          onChange={(e) => {
                            const booleanValue = e.target.value === "true";
                            updateTrigger(trig.id, "operator", booleanValue ? "is_true" : "is_false");
                            updateTrigger(trig.id, "value", booleanValue);
                          }}
                        >
                          <option value="true">True</option>
                          <option value="false">False</option>
                        </select>
                      </>
                    ) : (
                      <>
                        <select
                          className="input h-8 text-[12px] w-36"
                          value={trig.indicator || "rsi"}
                          onChange={(e) => updateTrigger(trig.id, "indicator", e.target.value)}
                        >
                          {NUMERIC_RULE_INDICATORS.map((indicator) => (
                            <option key={indicator.value} value={indicator.value}>{indicator.label}</option>
                          ))}
                        </select>
                        <select
                          className="input h-8 text-[12px] w-20"
                          value={trig.operator}
                          onChange={(e) => {
                            const op = e.target.value;
                            if (op === "between") {
                              const minVal = typeof trig.value === "number" ? trig.value : (parseFloat(String(trig.value ?? 0)) || 0);
                              updateTrigger(trig.id, "operator", op);
                              updateTrigger(trig.id, "min", minVal);
                              updateTrigger(trig.id, "max", 100);
                              updateTrigger(trig.id, "value", undefined);
                            } else if (trig.operator === "between") {
                              updateTrigger(trig.id, "operator", op);
                              updateTrigger(trig.id, "value", trig.min ?? 0);
                              updateTrigger(trig.id, "min", undefined);
                              updateTrigger(trig.id, "max", undefined);
                            } else {
                              updateTrigger(trig.id, "operator", op);
                            }
                          }}
                        >
                          {THRESHOLD_OPERATORS.map((operator) => (
                            <option key={operator} value={operator}>{operator === "between" ? "entre" : operator}</option>
                          ))}
                        </select>
                        {trig.operator === "between" ? (
                          <>
                            <NumericInput
                              className="input h-8 text-[12px] w-20 font-mono"
                              value={typeof trig.min === "number" ? trig.min : 0}
                              onChange={(v) => updateTrigger(trig.id, "min", v)}
                              placeholder="Min"
                            />
                            <span className="text-[11px] text-[var(--text-secondary)] font-medium">e</span>
                            <NumericInput
                              className="input h-8 text-[12px] w-20 font-mono"
                              value={typeof trig.max === "number" ? trig.max : 100}
                              onChange={(v) => updateTrigger(trig.id, "max", v)}
                              placeholder="Max"
                            />
                          </>
                        ) : (
                          <NumericInput
                            className="input h-8 text-[12px] w-20 font-mono"
                            value={typeof trig.value === "number" ? trig.value : null}
                            onChange={(v) => updateTrigger(trig.id, "value", v)}
                          />
                        )}
                      </>
                    )}
                    {/* Timeframe override */}
                    {!NO_TF_INDICATORS.has((trig.type === "comparison" ? trig.left : trig.indicator) || "") && (
                      <select
                        className="input h-8 text-[11px] w-[68px]"
                        value={trig.timeframe || ""}
                        onChange={(e) => updateTrigger(trig.id, "timeframe", e.target.value || undefined)}
                        title={`Timeframe (default: ${config.default_timeframe || "5m"})`}
                      >
                        <option value="">{config.default_timeframe || "5m"}</option>
                        {TIMEFRAME_OPTIONS.map((tf) => (
                          <option key={tf.value} value={tf.value}>{tf.label}</option>
                        ))}
                      </select>
                    )}
                    {/* Period override */}
                    {trig.type !== "comparison" && PERIOD_DEFAULTS[trig.indicator || ""] !== undefined && (
                      <input
                        type="number"
                        min={1}
                        className="input h-8 text-[11px] w-14 font-mono"
                        value={trig.period ?? ""}
                        onChange={(e) => {
                          const v = parseInt(e.target.value, 10);
                          updateTrigger(trig.id, "period", isNaN(v) ? undefined : v);
                        }}
                        placeholder={`P:${PERIOD_DEFAULTS[trig.indicator || ""]}`}
                        title={`Period (default: ${PERIOD_DEFAULTS[trig.indicator || ""]})`}
                      />
                    )}
                    <label className="flex items-center gap-1.5 text-[12px] cursor-pointer">
                      <input
                        type="checkbox"
                        checked={trig.required}
                        onChange={(e) => updateTrigger(trig.id, "required", e.target.checked)}
                        className="accent-[var(--accent-primary)]"
                      />
                      <span className={trig.required ? "text-[var(--color-warning)] font-semibold" : "text-[var(--text-secondary)]"}>
                        Required
                      </span>
                    </label>
                    <button
                      onClick={() => removeTrigger(trig.id)}
                      className="btn-icon w-7 h-7 flex items-center justify-center hover:text-[var(--color-loss)] ml-auto"
                    >
                      <Trash2 className="w-3.5 h-3.5" />
                    </button>
                  </div>
                ))}
              </div>

              {entryConditions.length === 0 && (
                <div className="text-center py-12 text-[var(--text-tertiary)] text-[13px]">
                  No entry triggers defined. Trades will be allowed by default.
                </div>
              )}

              {entryConditions.length > 0 && (
                <div className="card bg-[var(--bg-base)]">
                  <div className="p-4">
                    <div className="flex items-center justify-between gap-3 mb-2">
                      <p className="text-[11px] text-[var(--text-tertiary)] font-semibold uppercase tracking-wider">
                        Logic Preview <span className="text-[10px] normal-case font-normal text-[var(--text-tertiary)]">(somente leitura — edite os campos acima)</span>
                      </p>
                    </div>
                    <textarea
                      readOnly
                      tabIndex={-1}
                      className="input min-h-[220px] text-[12px] font-mono text-[var(--text-secondary)] cursor-default select-text"
                      value={autoEntryLogicPreview}
                    />
                  </div>
                </div>
              )}
              </div>
            </div>
          )}

        </div>
      </div>

      {/* Test Results */}
      {testResult && (
        <div className="card border-l-4 border-l-[var(--accent-primary)]">
          <div className="card-body p-6">
            <h3 className="font-semibold text-[var(--text-primary)] mb-4">Test Results</h3>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              {[
                { label: "Total Assets",  value: testResult.summary?.total_assets || 0,       color: "var(--text-primary)" },
                { label: "After Filter",  value: testResult.summary?.after_filter || 0,        color: "var(--color-profit)" },
                { label: "Filter Rate",   value: testResult.summary?.filter_rate || "0%",      color: "var(--text-primary)" },
                { label: "Signals",       value: testResult.summary?.signals_triggered || 0,   color: "var(--accent-primary)" },
              ].map(({ label, value, color }) => (
                <div key={label}>
                  <div className="text-[var(--text-tertiary)] text-xs">{label}</div>
                  <div className="text-xl font-bold" style={{ color }}>{value}</div>
                </div>
              ))}
            </div>
            {testResult.sample_assets?.length > 0 && (
              <div className="mt-4">
                <div className="text-[var(--text-tertiary)] text-xs mb-2">Top Matched Assets</div>
                <div className="flex flex-wrap gap-2">
                  {testResult.sample_assets.slice(0, 5).map((asset: any) => (
                    <span key={asset.symbol} className="px-2 py-1 rounded bg-[var(--bg-secondary)] text-[var(--text-primary)] text-xs">
                      {asset.symbol} ({asset.score?.total_score?.toFixed(1) || 0})
                    </span>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { Settings2, Trash2, Play, Copy, Bot } from "lucide-react";

interface ProfileCardProps {
  profile: {
    id: string;
    name: string;
    description: string;
    is_active: boolean;
    config: any;
    created_at: string;
    updated_at: string;
    autopilot_enabled?: boolean;
  };
  onEdit: () => void;
  onDelete: () => void;
  onTest: () => void;
  onDuplicate: () => void;
  onUpdate?: () => void;
  selected?: boolean;
  onSelectToggle?: () => void;
}

export function ProfileCard({
  profile,
  onEdit,
  onDelete,
  onTest,
  onDuplicate,
  onUpdate,
  selected,
  onSelectToggle,
}: ProfileCardProps) {
  const [isTogglingAutoPilot, setIsTogglingAutoPilot] = useState(false);
  const filterCount = profile.config?.filters?.conditions?.length || 0;

  const toggleAutoPilot = async () => {
    setIsTogglingAutoPilot(true);
    try {
      const token = typeof window !== "undefined" ? localStorage.getItem("token") : null;
      const res = await fetch(`/api/profiles/${profile.id}/autopilot/toggle`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          ...(token ? { Authorization: `Bearer ${token}` } : {}),
        },
        body: JSON.stringify({ enabled: !profile.autopilot_enabled }),
      });
      if (!res.ok) console.error("Auto-Pilot toggle failed:", res.status, await res.text());
      onUpdate?.();
    } catch (error) {
      console.error("Erro ao alternar Auto-Pilot:", error);
    } finally {
      setIsTogglingAutoPilot(false);
    }
  };
  const signalCount = profile.config?.signals?.conditions?.length || 0;
  const weights = profile.config?.scoring?.weights || {};

  return (
    <div className="card flex flex-col" data-testid={`profile-card-${profile.id}`}>
      <div className="card-body flex-1 p-6 relative">
        {onSelectToggle && (
          <div className="absolute top-4 left-4 z-10">
            <input
              type="checkbox"
              className="w-5 h-5 rounded border-zinc-600 bg-zinc-800 checked:bg-[var(--accent-primary)] checked:border-[var(--accent-primary)] focus:ring-1 focus:ring-[var(--accent-primary)] focus:ring-offset-1 focus:ring-offset-zinc-900 cursor-pointer"
              checked={selected}
              onChange={onSelectToggle}
            />
          </div>
        )}
        <div className={`flex justify-between items-start mb-4 ${onSelectToggle ? "pl-8" : ""}`}>
          <div>
            <h3 className="text-lg font-bold text-[var(--text-primary)] tracking-tight">
              {profile.name}
            </h3>
            <div className="flex items-center gap-2 mt-2">
              <span
                className={`badge ${profile.is_active ? "bullish" : "range"}`}
              >
                {profile.is_active ? "ACTIVE" : "INACTIVE"}
              </span>
            </div>
          </div>
          <button
            onClick={toggleAutoPilot}
            disabled={isTogglingAutoPilot}
            className={`p-2 rounded-lg transition-colors ${
              profile.autopilot_enabled
                ? "bg-blue-600 text-white hover:bg-blue-700"
                : "bg-zinc-800 text-zinc-400 hover:bg-zinc-700"
            }`}
            title={profile.autopilot_enabled ? "Auto-Pilot ativo" : "Ativar Auto-Pilot"}
          >
            <Bot className="h-4 w-4" />
          </button>
        </div>

        {profile.description && (
          <p className="text-[13px] text-[var(--text-secondary)] mb-4 line-clamp-2">
            {profile.description}
          </p>
        )}

        {/* Config Summary */}
        <div className="space-y-3">
          <div className="flex items-center justify-between text-[12px]">
            <span className="text-[var(--text-tertiary)]">Filters</span>
            <span className="text-[var(--text-primary)] font-medium">
              {filterCount} conditions
            </span>
          </div>
          <div className="flex items-center justify-between text-[12px]">
            <span className="text-[var(--text-tertiary)]">Signals</span>
            <span className="text-[var(--text-primary)] font-medium">
              {signalCount} conditions
            </span>
          </div>
          <div className="flex items-center justify-between text-[12px]">
            <span className="text-[var(--text-tertiary)]">Weights</span>
            <div className="flex gap-1">
              <span className="text-[10px] px-1.5 py-0.5 rounded bg-blue-500/20 text-blue-400">
                L:{weights.liquidity || 25}
              </span>
              <span className="text-[10px] px-1.5 py-0.5 rounded bg-purple-500/20 text-purple-400">
                M:{weights.market_structure || 25}
              </span>
              <span className="text-[10px] px-1.5 py-0.5 rounded bg-green-500/20 text-green-400">
                Mo:{weights.momentum || 25}
              </span>
              <span className="text-[10px] px-1.5 py-0.5 rounded bg-orange-500/20 text-orange-400">
                S:{weights.signal || 25}
              </span>
            </div>
          </div>
        </div>

        <div className="text-[11px] text-[var(--text-tertiary)] mt-4">
          Updated{" "}
          {profile.updated_at
            ? new Date(profile.updated_at).toLocaleDateString()
            : "—"}
        </div>
      </div>

      {/* Actions */}
      <div className="border-t border-[var(--border-default)] p-3 flex justify-between">
        <div className="flex gap-1">
          <button
            className="btn btn-secondary text-[12px] px-2 py-1.5 text-red-500 hover:bg-red-500/10"
            onClick={onDelete}
            title="Delete"
            data-testid={`delete-profile-${profile.id}`}
          >
            <Trash2 className="w-3.5 h-3.5" />
          </button>
          <button
            className="btn btn-secondary text-[12px] px-2 py-1.5"
            onClick={onDuplicate}
            title="Duplicate"
          >
            <Copy className="w-3.5 h-3.5" />
          </button>
        </div>
        <div className="flex gap-1">
          <button
            className="btn btn-secondary text-[12px] px-2 py-1.5 text-[var(--accent-primary)]"
            onClick={onTest}
            title="Test Profile"
            data-testid={`test-profile-${profile.id}`}
          >
            <Play className="w-3.5 h-3.5" />
          </button>
          <button
            className="btn btn-primary text-[12px] px-3 py-1.5"
            onClick={onEdit}
            data-testid={`edit-profile-${profile.id}`}
          >
            <Settings2 className="w-3.5 h-3.5 mr-1" />
            Configure
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

interface WeightSlidersProps {
  weights: {
    liquidity: number;
    market_structure: number;
    momentum: number;
    signal: number;
  };
  onChange: (weights: any) => void;
}

export function WeightSliders({ weights, onChange }: WeightSlidersProps) {
  const total =
    weights.liquidity +
    weights.market_structure +
    weights.momentum +
    weights.signal;

  const updateWeight = (key: string, value: number) => {
    onChange({ ...weights, [key]: value });
  };

  const sliders = [
    {
      key: "liquidity",
      label: "Liquidity",
      description: "Volume, spread, order book depth",
      color: "bg-blue-500",
    },
    {
      key: "market_structure",
      label: "Market Structure",
      description: "ADX, EMA alignment, ATR, trend strength",
      color: "bg-purple-500",
    },
    {
      key: "momentum",
      label: "Momentum",
      description: "RSI, MACD, Stochastic, Z-Score",
      color: "bg-green-500",
    },
    {
      key: "signal",
      label: "Signal",
      description: "Entry conditions, volume delta, funding",
      color: "bg-orange-500",
    },
  ];

  return (
    <div className="space-y-6">
      {/* Total indicator */}
      <div className="flex items-center justify-between p-3 bg-[var(--bg-secondary)] rounded-lg">
        <span className="text-[var(--text-secondary)] text-sm">Total Weight</span>
        <span
          className={`font-mono font-bold ${
            total === 100
              ? "text-[var(--color-profit)]"
              : "text-[var(--color-loss)]"
          }`}
        >
          {total}%
        </span>
      </div>

      {/* Weight sliders */}
      {sliders.map((slider) => (
        <div key={slider.key} className="space-y-2">
          <div className="flex items-center justify-between">
            <div>
              <label className="font-medium text-[var(--text-primary)] text-sm">
                {slider.label}
              </label>
              <p className="text-[11px] text-[var(--text-tertiary)]">
                {slider.description}
              </p>
            </div>
            <div className="flex items-center gap-2">
              <input
                type="number"
                min="0"
                max="100"
                value={weights[slider.key as keyof typeof weights]}
                onChange={(e) =>
                  updateWeight(slider.key, parseInt(e.target.value) || 0)
                }
                className="input w-16 text-center text-sm"
                data-testid={`weight-input-${slider.key}`}
              />
              <span className="text-[var(--text-tertiary)] text-sm">%</span>
            </div>
          </div>

          <div className="relative">
            <input
              type="range"
              min="0"
              max="100"
              value={weights[slider.key as keyof typeof weights]}
              onChange={(e) =>
                updateWeight(slider.key, parseInt(e.target.value) || 0)
              }
              className="w-full h-2 rounded-lg appearance-none cursor-pointer"
              style={{
                background: `linear-gradient(to right, ${
                  slider.key === "liquidity"
                    ? "#3b82f6"
                    : slider.key === "market_structure"
                    ? "#a855f7"
                    : slider.key === "momentum"
                    ? "#22c55e"
                    : "#f97316"
                } ${weights[slider.key as keyof typeof weights]}%, var(--bg-secondary) ${
                  weights[slider.key as keyof typeof weights]
                }%)`,
              }}
              data-testid={`weight-slider-${slider.key}`}
            />
          </div>
        </div>
      ))}

      {/* Visual weight distribution */}
      <div className="mt-6">
        <label className="text-[var(--text-tertiary)] text-xs mb-2 block">
          Weight Distribution
        </label>
        <div className="h-4 rounded-full overflow-hidden flex">
          <div
            className="bg-blue-500 transition-all"
            style={{ width: `${(weights.liquidity / total) * 100 || 0}%` }}
          />
          <div
            className="bg-purple-500 transition-all"
            style={{ width: `${(weights.market_structure / total) * 100 || 0}%` }}
          />
          <div
            className="bg-green-500 transition-all"
            style={{ width: `${(weights.momentum / total) * 100 || 0}%` }}
          />
          <div
            className="bg-orange-500 transition-all"
            style={{ width: `${(weights.signal / total) * 100 || 0}%` }}
          />
        </div>
        <div className="flex justify-between mt-1 text-[10px] text-[var(--text-tertiary)]">
          <span>L: {weights.liquidity}%</span>
          <span>MS: {weights.market_structure}%</span>
          <span>Mo: {weights.momentum}%</span>
          <span>S: {weights.signal}%</span>
        </div>
      </div>

      {/* Presets */}
      <div className="pt-4 border-t border-[var(--border-default)]">
        <label className="text-[var(--text-tertiary)] text-xs mb-2 block">
          Quick Presets
        </label>
        <div className="flex flex-wrap gap-2">
          <button
            className="btn btn-secondary text-xs px-3 py-1"
            onClick={() =>
              onChange({
                liquidity: 25,
                market_structure: 25,
                momentum: 25,
                signal: 25,
              })
            }
          >
            Balanced
          </button>
          <button
            className="btn btn-secondary text-xs px-3 py-1"
            onClick={() =>
              onChange({
                liquidity: 30,
                market_structure: 15,
                momentum: 40,
                signal: 15,
              })
            }
          >
            Momentum Focus
          </button>
          <button
            className="btn btn-secondary text-xs px-3 py-1"
            onClick={() =>
              onChange({
                liquidity: 20,
                market_structure: 35,
                momentum: 30,
                signal: 15,
              })
            }
          >
            Trend Focus
          </button>
          <button
            className="btn btn-secondary text-xs px-3 py-1"
            onClick={() =>
              onChange({
                liquidity: 40,
                market_structure: 20,
                momentum: 25,
                signal: 15,
              })
            }
          >
            Liquidity Focus
          </button>
        </div>
      </div>
    </div>
  );
}

'use client'
/**
 * AIProviderSection.tsx
 * Section of /settings/general for AI API key configuration.
 * Keys are NEVER returned by the backend — only key_hint is exposed.
 */
import { useState, useEffect } from 'react'
import {
  Brain, ExternalLink, Eye, EyeOff,
  CheckCircle2, XCircle, AlertCircle,
  RefreshCw, Trash2, Plus, Zap,
} from 'lucide-react'

interface ProviderStatus {
  provider: string
  name?: string
  key_hint: string | null
  label: string | null
  is_configured: boolean
  is_validated: boolean
  test_status: 'ok' | 'error' | 'pending' | null
  test_error: string | null
  last_tested_at: string | null
  tokens_used_month: number | null
  monthly_token_limit: number | null
  docs_url: string
}

const MAX_TOKEN_LIMIT = 100_000_000

/** Formata tokens: 5000000 → "5.0M" · 500000 → "500k" · 999 → "999" */
function fmtTokens(n: number | null | undefined): string {
  if (n == null) return '0'
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`
  if (n >= 1_000)     return `${(n / 1_000).toFixed(0)}k`
  return String(n)
}

/** Converte string de input em número de tokens, retorna null se inválido */
function parseTokenLimit(s: string): number | null {
  if (!s.trim()) return null
  const n = parseInt(s.replace(/\D/g, ''), 10)
  if (isNaN(n) || n < 1_000) return null
  return Math.min(n, MAX_TOKEN_LIMIT)
}

const PMETA: Record<string, {
  icon: string; color: string; bg: string; border: string
  desc: string; usedBy: string[]; placeholder: string
}> = {
  anthropic: {
    icon: '◆', color: '#CC785C',
    bg: 'rgba(204,120,92,0.07)', border: 'rgba(204,120,92,0.2)',
    desc: 'Motor do Auto-Pilot IA, Preset IA e análises de regime.',
    usedBy: ['Auto-Pilot IA', 'Preset IA', 'Análise de regime'],
    placeholder: 'sk-ant-api03-...',
  },
  openai: {
    icon: '⬡', color: '#10A37F',
    bg: 'rgba(16,163,127,0.07)', border: 'rgba(16,163,127,0.2)',
    desc: 'Alternativa ao Anthropic. Fallback automático.',
    usedBy: ['Fallback IA'],
    placeholder: 'sk-proj-...',
  },
  gemini: {
    icon: '✦', color: '#4285F4',
    bg: 'rgba(66,133,244,0.07)', border: 'rgba(66,133,244,0.2)',
    desc: 'Google Gemini para análises complementares.',
    usedBy: ['Análises complementares'],
    placeholder: 'AIzaSy...',
  },
}

function authHeaders(): HeadersInit {
  const token = typeof window !== 'undefined' ? localStorage.getItem('token') : null
  return token
    ? { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }
    : { 'Content-Type': 'application/json' }
}

function Badge({ status }: { status: ProviderStatus }) {
  if (!status.is_configured)
    return <span style={{ fontSize: 11, padding: '3px 8px', borderRadius: 20, fontWeight: 600, background: 'rgba(255,255,255,0.04)', color: 'var(--text-tertiary)' }}>Não configurado</span>
  if (status.test_status === 'ok')
    return <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4, fontSize: 11, padding: '3px 8px', borderRadius: 20, fontWeight: 600, background: 'var(--color-profit-muted)', color: 'var(--color-profit)' }}><CheckCircle2 size={10} />Conectado</span>
  if (status.test_status === 'error')
    return <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4, fontSize: 11, padding: '3px 8px', borderRadius: 20, fontWeight: 600, background: 'var(--color-loss-muted)', color: 'var(--color-loss)' }}><XCircle size={10} />Erro</span>
  return <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4, fontSize: 11, padding: '3px 8px', borderRadius: 20, fontWeight: 600, background: 'var(--color-warning-muted)', color: 'var(--color-warning)' }}><AlertCircle size={10} />Não testado</span>
}

function ProviderCard({ status, onRefresh }: { status: ProviderStatus; onRefresh: () => void }) {
  const meta = PMETA[status.provider] ?? PMETA.anthropic
  const isMain = status.provider === 'anthropic'
  const [apiKey, setApiKey] = useState('')
  const [label, setLabel] = useState(status.label ?? '')
  const [limit, setLimit] = useState(status.monthly_token_limit?.toString() ?? '')
  const [showKey, setShowKey] = useState(false)
  const [editing, setEditing] = useState(!status.is_configured)
  const [saving, setSaving] = useState(false)
  const [testing, setTesting] = useState(false)
  const [testResult, setTestResult] = useState<{ success: boolean; message: string } | null>(null)
  const [error, setError] = useState<string | null>(null)

  const inputStyle: React.CSSProperties = {
    width: '100%', fontSize: 13, fontFamily: 'var(--font-mono)',
    background: 'var(--bg-input)', border: '1px solid var(--border-default)',
    borderRadius: 8, padding: '9px 40px 9px 12px',
    color: 'var(--text-primary)', outline: 'none', boxSizing: 'border-box',
  }

  const handleSave = async () => {
    if (!apiKey.trim()) { setError('Insira a API key.'); return }
    const tokenLimit = parseTokenLimit(limit)
    if (limit.trim() && tokenLimit === null) {
      setError('Limite de tokens inválido. Mínimo: 1.000. Máximo: 100.000.000.')
      return
    }
    setSaving(true); setError(null); setTestResult(null)
    try {
      const res = await fetch(`/api/ai-keys/${status.provider}`, {
        method: 'POST',
        headers: authHeaders(),
        body: JSON.stringify({
          api_key: apiKey.trim(),
          label: label || null,
          monthly_token_limit: tokenLimit,
        }),
      })
      if (!res.ok) {
        const e = await res.json()
        setError(e.detail ?? 'Erro ao salvar.')
        setSaving(false); return
      }
      setEditing(false); setApiKey(''); setSaving(false); onRefresh()
    } catch {
      setError('Erro de conexão.')
      setSaving(false)
    }
  }

  const handleTest = async () => {
    setTesting(true); setTestResult(null)
    try {
      const res = await fetch(`/api/ai-keys/${status.provider}/test`, {
        method: 'POST',
        headers: authHeaders(),
      })
      const data = await res.json()
      if (!res.ok) {
        const errMsg = typeof data.detail === 'string'
          ? data.detail
          : Array.isArray(data.detail)
            ? data.detail.map((e: { msg: string }) => e.msg).join(', ')
            : `Erro HTTP ${res.status}`
        setTesting(false)
        setTestResult({ success: false, message: errMsg })
        return
      }
      const msg = data.message || (data.success ? 'Conectado.' : 'Sem resposta do servidor.')
      setTesting(false)
      setTestResult({ success: !!data.success, message: msg })
      if (data.success) onRefresh()
    } catch {
      setTesting(false)
      setTestResult({ success: false, message: 'Erro de conexão.' })
    }
  }

  const handleDelete = async () => {
    if (!confirm(`Remover a chave ${status.name ?? status.provider}?`)) return
    await fetch(`/api/ai-keys/${status.provider}`, { method: 'DELETE', headers: authHeaders() })
    onRefresh()
  }

  return (
    <div style={{ background: status.is_configured ? meta.bg : 'var(--bg-elevated)', border: `1px solid ${status.is_configured ? meta.border : 'var(--border-default)'}`, borderRadius: 12, overflow: 'hidden', transition: 'all 200ms' }}>
      {/* Header row */}
      <div style={{ display: 'flex', alignItems: 'flex-start', gap: 14, padding: '16px 20px', borderBottom: (editing || status.is_configured) ? '1px solid var(--border-subtle)' : 'none' }}>
        <div style={{ width: 40, height: 40, borderRadius: 10, flexShrink: 0, background: `${meta.color}18`, border: `1px solid ${meta.color}30`, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 18, color: meta.color }}>{meta.icon}</div>
        <div style={{ flex: 1 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 4 }}>
            <span style={{ fontSize: 14, fontWeight: 700, color: 'var(--text-primary)' }}>{status.name ?? status.provider}</span>
            {isMain && <span style={{ fontSize: 10, padding: '2px 7px', borderRadius: 20, fontWeight: 700, background: `${meta.color}18`, color: meta.color, letterSpacing: '0.04em' }}>PRINCIPAL</span>}
            <Badge status={status} />
          </div>
          <p style={{ fontSize: 12, color: 'var(--text-secondary)', margin: 0, lineHeight: 1.5 }}>{meta.desc}</p>
          <div style={{ display: 'flex', gap: 6, marginTop: 8, flexWrap: 'wrap' }}>
            {meta.usedBy.map(tag => (
              <span key={tag} style={{ fontSize: 10, padding: '2px 7px', borderRadius: 20, background: 'rgba(255,255,255,0.04)', border: '1px solid var(--border-subtle)', color: 'var(--text-tertiary)' }}>{tag}</span>
            ))}
          </div>
        </div>
        <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexShrink: 0 }}>
          <a href={status.docs_url} target="_blank" rel="noopener noreferrer" style={{ display: 'flex', alignItems: 'center', gap: 4, fontSize: 11, color: 'var(--text-tertiary)', textDecoration: 'none' }}>
            <ExternalLink size={12} />Docs
          </a>
          {status.is_configured && !editing && (
            <>
              <button onClick={() => setEditing(true)} style={{ fontSize: 11, padding: '5px 10px', borderRadius: 6, background: 'transparent', border: '1px solid var(--border-default)', cursor: 'pointer', color: 'var(--text-secondary)' }}>Editar</button>
              <button onClick={handleDelete} style={{ background: 'none', border: 'none', cursor: 'pointer', padding: 4 }}><Trash2 size={13} color="var(--text-tertiary)" /></button>
            </>
          )}
          {!status.is_configured && !editing && (
            <button onClick={() => setEditing(true)} style={{ display: 'flex', alignItems: 'center', gap: 5, fontSize: 12, fontWeight: 600, padding: '7px 12px', borderRadius: 7, background: 'var(--accent-primary-muted)', border: '1px solid var(--accent-primary-border)', cursor: 'pointer', color: 'var(--accent-primary)' }}>
              <Plus size={12} />Configurar
            </button>
          )}
        </div>
      </div>

      {/* Connected state */}
      {status.is_configured && !editing && (
        <div style={{ padding: '12px 20px' }}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: 12 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
              <span style={{ fontSize: 11, color: 'var(--text-tertiary)' }}>API Key</span>
              <code style={{ fontSize: 12, fontFamily: 'var(--font-mono)', background: 'var(--bg-input)', border: '1px solid var(--border-default)', borderRadius: 6, padding: '4px 10px', color: 'var(--text-secondary)' }}>{status.key_hint ?? '••••••••••••'}</code>
              {status.last_tested_at && (
                <span style={{ fontSize: 11, color: 'var(--text-tertiary)' }}>
                  testado {new Date(status.last_tested_at).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' })}
                </span>
              )}
            </div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
              <Zap size={12} color="var(--text-tertiary)" />
              <span style={{ fontSize: 11, color: 'var(--text-tertiary)', fontFamily: 'var(--font-mono)' }}>
                {fmtTokens(status.tokens_used_month)} tokens este mês
                {status.monthly_token_limit != null && ` / ${fmtTokens(status.monthly_token_limit)} limite`}
              </span>
            </div>
            <button onClick={handleTest} disabled={testing} style={{ display: 'flex', alignItems: 'center', gap: 5, fontSize: 11, fontWeight: 600, padding: '6px 12px', borderRadius: 6, background: 'transparent', border: '1px solid var(--border-default)', cursor: testing ? 'wait' : 'pointer', color: 'var(--text-secondary)' }}>
              <RefreshCw size={11} style={testing ? { animation: 'spin 1s linear infinite' } : {}} />
              {testing ? 'Testando...' : 'Testar conexão'}
            </button>
          </div>
          {testResult && (
            <div style={{ marginTop: 10, padding: '8px 12px', borderRadius: 7, fontSize: 12, background: testResult.success ? 'var(--color-profit-muted)' : 'var(--color-loss-muted)', border: `1px solid ${testResult.success ? 'var(--color-profit-border)' : 'var(--color-loss-border)'}`, color: testResult.success ? 'var(--color-profit)' : 'var(--color-loss)', display: 'flex', alignItems: 'center', gap: 7 }}>
              {testResult.success ? <CheckCircle2 size={13} /> : <XCircle size={13} />}
              {testResult.message}
            </div>
          )}
          {status.test_status === 'error' && !testResult && status.test_error && (
            <div style={{ marginTop: 10, padding: '8px 12px', borderRadius: 7, fontSize: 12, background: 'var(--color-loss-muted)', border: '1px solid var(--color-loss-border)', color: 'var(--color-loss)' }}>{status.test_error}</div>
          )}
        </div>
      )}

      {/* Edit / add key form */}
      {editing && (
        <div style={{ padding: '16px 20px', display: 'flex', flexDirection: 'column', gap: 12 }}>
          <div>
            <label style={{ display: 'block', fontSize: 11, fontWeight: 600, color: 'var(--text-tertiary)', marginBottom: 6, textTransform: 'uppercase', letterSpacing: '0.04em' }}>API Key</label>
            <div style={{ position: 'relative' }}>
              <input
                type={showKey ? 'text' : 'password'}
                value={apiKey}
                onChange={e => setApiKey(e.target.value)}
                placeholder={meta.placeholder}
                autoComplete="off"
                style={{ ...inputStyle, borderColor: error ? 'var(--color-loss-border)' : 'var(--border-default)' }}
              />
              <button onClick={() => setShowKey(!showKey)} style={{ position: 'absolute', right: 10, top: '50%', transform: 'translateY(-50%)', background: 'none', border: 'none', cursor: 'pointer', padding: 0, display: 'flex' }}>
                {showKey ? <EyeOff size={15} color="var(--text-tertiary)" /> : <Eye size={15} color="var(--text-tertiary)" />}
              </button>
            </div>
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
            <div>
              <label style={{ display: 'block', fontSize: 11, fontWeight: 600, color: 'var(--text-tertiary)', marginBottom: 6, textTransform: 'uppercase', letterSpacing: '0.04em' }}>Label (opcional)</label>
              <input type="text" value={label} onChange={e => setLabel(e.target.value)} placeholder="Ex: Produção" style={{ ...inputStyle, padding: '9px 12px', fontFamily: 'var(--font-sans,sans-serif)' }} />
            </div>
            <div>
              <label style={{ display: 'block', fontSize: 11, fontWeight: 600, color: 'var(--text-tertiary)', marginBottom: 6, textTransform: 'uppercase', letterSpacing: '0.04em' }}>Limite mensal (tokens)</label>
              <input type="number" value={limit} onChange={e => setLimit(e.target.value)} placeholder="Ex: 5000000 (= 5M)" min={1000} max={MAX_TOKEN_LIMIT} style={{ ...inputStyle, padding: '9px 12px' }} />
              {limit && parseTokenLimit(limit) != null && (
                <p style={{ fontSize: 11, color: 'var(--text-tertiary)', margin: '4px 0 0' }}>
                  = {fmtTokens(parseTokenLimit(limit))} tokens/mês
                </p>
              )}
            </div>
          </div>
          {error && (
            <div style={{ fontSize: 12, padding: '8px 12px', borderRadius: 7, background: 'var(--color-loss-muted)', border: '1px solid var(--color-loss-border)', color: 'var(--color-loss)' }}>{error}</div>
          )}
          <div style={{ display: 'flex', gap: 8, justifyContent: 'flex-end', marginTop: 4 }}>
            {status.is_configured && (
              <button onClick={() => { setEditing(false); setApiKey(''); setError(null) }} style={{ padding: '8px 16px', fontSize: 12, borderRadius: 7, background: 'transparent', border: '1px solid var(--border-default)', cursor: 'pointer', color: 'var(--text-secondary)' }}>
                Cancelar
              </button>
            )}
            <button onClick={handleSave} disabled={saving || !apiKey.trim()} style={{ display: 'flex', alignItems: 'center', gap: 6, padding: '8px 18px', fontSize: 12, fontWeight: 600, borderRadius: 7, background: 'var(--accent-primary)', border: 'none', cursor: saving ? 'wait' : 'pointer', color: '#fff', opacity: saving || !apiKey.trim() ? 0.6 : 1 }}>
              {saving ? <><RefreshCw size={12} style={{ animation: 'spin 1s linear infinite' }} />Salvando...</> : 'Salvar e conectar'}
            </button>
          </div>
        </div>
      )}
    </div>
  )
}

const DEFAULT_PROVIDERS: ProviderStatus[] = [
  {
    provider: 'anthropic', name: 'Anthropic',
    key_hint: null, label: null,
    is_configured: false, is_validated: false,
    test_status: null, test_error: null, last_tested_at: null,
    tokens_used_month: null, monthly_token_limit: null,
    docs_url: 'https://console.anthropic.com/settings/keys',
  },
  {
