"use client";

import { useState, useEffect } from "react";
import { Save, RefreshCw } from "lucide-react";
import { useConfig } from "@/hooks/useConfig";

export function RiskConfigForm() {
  const { config, updateConfig, isLoading } = useConfig("risk");
  const [local, setLocal] = useState<Record<string, any>>({});
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (config && Object.keys(config).length > 0) setLocal(config);
  }, [config]);

  const set = (key: string, value: any) => setLocal((p) => ({ ...p, [key]: value }));

  const handleSave = async () => {
    setSaving(true);
    try { await updateConfig(local); } catch (e) { console.error(e); }
    setSaving(false);
  };

  if (isLoading) return <div className="card"><div className="card-body"><div className="skeleton h-64 w-full" /></div></div>;

  const tp = local.take_profit_pct ?? 1.5;
  const sl = local.stop_loss_atr_multiplier ?? 1.5;
  const maxPos = local.max_positions ?? 5;
  const dailyLoss = local.daily_loss_limit_pct ?? 3;
  const capPer = local.capital_per_trade_pct ?? 10;
  const maxCap = local.max_capital_in_use_pct ?? 80;
  const maxExp = local.max_exposure_per_asset_pct ?? 20;
  const cbLosses = local.circuit_breaker_consecutive_losses ?? 3;

  const sliders = [
    { label: "Default Take Profit", key: "take_profit_pct", value: tp, min: 0.1, max: 10, step: 0.1, suffix: "%" },
    { label: "Dynamic Stop Loss (ATR)", key: "stop_loss_atr_multiplier", value: sl, min: 0.5, max: 5, step: 0.1, suffix: "x" },
    { label: "Max Concurrent Positions", key: "max_positions", value: maxPos, min: 1, max: 20, step: 1, suffix: "POS" },
    { label: "Capital Per Trade", key: "capital_per_trade_pct", value: capPer, min: 1, max: 50, step: 1, suffix: "%" },
    { label: "Max Capital In Use", key: "max_capital_in_use_pct", value: maxCap, min: 10, max: 100, step: 5, suffix: "%" },
    { label: "Max Exposure Per Asset", key: "max_exposure_per_asset_pct", value: maxExp, min: 5, max: 50, step: 1, suffix: "%" },
  ];

  return (
    <div className="card">
      <div className="card-header pb-4 border-b border-[var(--border-subtle)]">
        <div>
          <h2 className="text-[18px] font-bold tracking-tight">Risk Management Parameters</h2>
          <p className="text-[13px] text-[var(--text-secondary)] mt-1">ZERO HARDCODE — saved to database, controls execution engine in real-time.</p>
        </div>
        <button onClick={handleSave} disabled={saving} className="btn btn-primary">
          {saving ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
          {saving ? "Saving..." : "Save Configuration"}
        </button>
      </div>

      <div className="card-body p-6">
        <div className="grid grid-cols-1 md:grid-cols-5 gap-8">
          <div className="md:col-span-3 space-y-6">
            {/* Circuit Breaker */}
            <div className="flex items-center justify-between p-4 bg-[var(--bg-elevated)] border border-[var(--border-default)] rounded-[var(--radius-md)]">
              <div>
                <h4 className="font-semibold text-[14px] text-[var(--text-primary)]">Circuit Breaker</h4>
                <p className="text-[12px] text-[var(--text-secondary)] mt-0.5">Halt after {cbLosses} consecutive losses</p>
              </div>
              <input type="number" className="input numeric w-16 h-8 text-[13px]" value={cbLosses} min={1} max={20} onChange={(e) => set("circuit_breaker_consecutive_losses", parseInt(e.target.value) || 3)} />
            </div>

            {/* Sliders */}
            {sliders.map((s) => (
              <div key={s.key} className="space-y-2 pt-3 border-t border-[var(--border-subtle)]">
                <div className="flex justify-between items-center">
                  <label className={`text-[13px] font-semibold ${s.key === "daily_loss_limit_pct" ? "text-[var(--color-loss)]" : "text-[var(--text-primary)]"}`}>{s.label}</label>
                  <div className="input-group w-[100px]">
                    <input type="number" value={s.value} onChange={(e) => set(s.key, parseFloat(e.target.value) || 0)} className="input numeric" step={s.step} />
                    <span className="suffix">{s.suffix}</span>
                  </div>
                </div>
                <input type="range" min={s.min} max={s.max} step={s.step} value={s.value} onChange={(e) => set(s.key, parseFloat(e.target.value))} className="slider w-full" style={{ "--progress": `${((s.value - s.min) / (s.max - s.min)) * 100}%` } as any} />
              </div>
            ))}

            {/* Daily Loss */}
            <div className="space-y-2 pt-3 border-t border-[var(--border-subtle)]">
              <div className="flex justify-between items-center">
                <label className="text-[13px] font-semibold text-[var(--color-loss)]">Daily Loss Limit</label>
                <div className="input-group w-[100px]">
                  <input type="number" value={dailyLoss} onChange={(e) => set("daily_loss_limit_pct", parseFloat(e.target.value) || 0)} className="input numeric text-[var(--color-loss)]" step={0.5} />
                  <span className="suffix">%</span>
                </div>
              </div>
              <input type="range" min={0.5} max={15} step={0.5} value={dailyLoss} onChange={(e) => set("daily_loss_limit_pct", parseFloat(e.target.value))} className="slider w-full" style={{ "--progress": `${(dailyLoss / 15) * 100}%` } as any} />
            </div>

            {/* Trailing Stop */}
            <div className="flex items-center justify-between p-4 bg-[var(--bg-elevated)] border border-[var(--border-default)] rounded-[var(--radius-md)]">
              <div>
                <h4 className="font-semibold text-[14px] text-[var(--text-primary)]">Trailing Stop</h4>
                <p className="text-[12px] text-[var(--text-secondary)]">Distance: {local.trailing_stop_distance_pct ?? 0.5}%</p>
              </div>
              <div className={`toggle ${local.trailing_stop_enabled ? "active" : ""}`} onClick={() => set("trailing_stop_enabled", !local.trailing_stop_enabled)}>
                <div className="knob" />
              </div>
            </div>

            {/* Order Type */}
            <div className="flex items-center justify-between pt-3 border-t border-[var(--border-subtle)]">
              <label className="text-[13px] font-semibold text-[var(--text-primary)]">Default Order Type</label>
              <select className="input w-32 h-9 text-[13px]" value={local.default_order_type ?? "limit"} onChange={(e) => set("default_order_type", e.target.value)}>
                <option value="limit">Limit</option>
                <option value="market">Market</option>
              </select>
            </div>
          </div>

          {/* Preview */}
          <div className="md:col-span-2">
            <div className="bg-[var(--bg-elevated)] border border-[var(--border-strong)] rounded-[var(--radius-lg)] p-5 sticky top-24">
              <h3 className="text-[14px] font-semibold text-[var(--text-primary)] mb-4 pb-3 border-b border-[var(--border-subtle)]">Risk Exposure Preview</h3>
              <div className="space-y-4">
                {[
                  { l: "Capital (assumed)", v: "$100,000" },
                  { l: "Per Trade", v: `$${(100000 * capPer / 100).toLocaleString()}`, s: `${capPer}%` },
                  { l: "Max Deployed", v: `$${(100000 * maxCap / 100).toLocaleString()}`, s: `${maxPos} pos` },
                  { l: "Max Per Asset", v: `$${(100000 * maxExp / 100).toLocaleString()}`, s: `${maxExp}%` },
                ].map((r, i) => (
                  <div key={i} className="flex justify-between items-end border-b border-[var(--border-subtle)] pb-2">
                    <div><span className="text-[12px] text-[var(--text-secondary)]">{r.l}</span>{r.s && <span className="caption block">{r.s}</span>}</div>
                    <span className="data-value text-[15px]">{r.v}</span>
                  </div>
                ))}
                <div className="flex justify-between items-end pt-2">
                  <div className="border-l-2 border-[var(--color-loss)] pl-3">
                    <span className="text-[12px] font-bold text-[var(--color-loss)]">Circuit Breaker</span>
                    <span className="caption block">HALT TRADING AT</span>
                  </div>
                  <span className="data-value text-[18px] font-bold text-[var(--color-loss)]">-${(100000 * dailyLoss / 100).toLocaleString()}</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";

interface Pool {
  id: string;
  name: string;
  description?: string;
  is_active: boolean;
  mode: string;
  asset_count: number;
  autopilot_enabled: boolean;
}

interface Props {
  value?: string | null;
  onChange: (poolId: string | null) => void;
  placeholder?: string;
  disabled?: boolean;
}

export default function PoolSelector({ value, onChange, placeholder = "Selecionar pool...", disabled }: Props) {
  const [pools, setPools] = useState<Pool[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchPools = async () => {
      setLoading(true);
      try {
        const res = await fetch("/api/pools/");
        const data = await res.json();
        setPools(data.pools || []);
      } catch (e: any) {
        setError("Erro ao carregar pools");
      } finally {
        setLoading(false);
      }
    };
    fetchPools();
  }, []);

  if (loading) {
    return (
      <select disabled style={{ width: "100%", padding: "8px 12px", borderRadius: 8, fontSize: 13 }}>
        <option>Carregando pools...</option>
      </select>
    );
  }

  if (error) {
    return (
      <select disabled style={{ width: "100%", padding: "8px 12px", borderRadius: 8, fontSize: 13 }}>
        <option>{error}</option>
      </select>
    );
  }

  return (
    <select
      value={value ?? ""}
      onChange={(e) => onChange(e.target.value || null)}
      disabled={disabled}
      style={{
        width: "100%",
        padding: "8px 12px",
        borderRadius: 8,
        fontSize: 13,
        background: "var(--bg-elevated, #1a1a2e)",
        border: "1px solid rgba(255,255,255,0.1)",
        color: "var(--text-primary, #fff)",
        cursor: disabled ? "not-allowed" : "pointer",
      }}
    >
      <option value="">{placeholder}</option>
      {pools.map((pool) => (
        <option key={pool.id} value={pool.id}>
          {pool.name}
          {pool.asset_count > 0 ? ` (${pool.asset_count} ativos)` : ""}
          {pool.autopilot_enabled ? " 🤖" : ""}
        </option>
      ))}
    </select>
  );
}

'use client';

import Link from 'next/link';
import { Pause, Play, BarChart3, AlertTriangle, TrendingUp, TrendingDown } from 'lucide-react';
import { useEngineStatus, type TradingProfile } from '@/hooks/useEngineStatus';
import { ApiError } from '@/lib/api';
import { pickActivePositionsCount, pickUnderwaterCount } from '@/lib/engineStatus';
import { useState } from 'react';

function formatActionError(err: unknown): string {
  if (err instanceof ApiError) return err.toDescriptiveString();
  if (err instanceof Error) return err.message;
  return String(err);
}

// ── Types ────────────────────────────────────────────────────────────────────

interface EngineStatusBarProps {
  profile: TradingProfile;
}

type EngineState = 'running' | 'paused' | 'stopped';

type MacroRegime =
  | 'STRONG_RISK_ON'
  | 'RISK_ON'
  | 'NEUTRAL'
  | 'RISK_OFF'
  | 'STRONG_RISK_OFF';

// ── Helpers ──────────────────────────────────────────────────────────────────

function resolveEngineState(isRunning: boolean, isPaused: boolean): EngineState {
  if (isPaused) return 'paused';
  if (isRunning) return 'running';
  return 'stopped';
}

const STATE_CONFIG: Record<
  EngineState,
  { label: string; dotColor: string; borderColor: string; textColor: string }
> = {
  running: {
    label: 'RUNNING',
    dotColor: 'var(--color-profit)',
    borderColor: 'var(--color-profit)',
    textColor: 'var(--color-profit)',
  },
  paused: {
    label: 'PAUSED',
    dotColor: 'var(--color-warning)',
    borderColor: 'var(--color-warning)',
    textColor: 'var(--color-warning)',
  },
  stopped: {
    label: 'STOPPED',
    dotColor: 'var(--text-tertiary)',
    borderColor: 'var(--border-default)',
    textColor: 'var(--text-tertiary)',
  },
};

const REGIME_CONFIG: Record<MacroRegime, { color: string; bg: string; border: string }> = {
  STRONG_RISK_ON: {
    color: 'var(--color-profit)',
    bg: 'var(--color-profit-muted)',
    border: 'var(--color-profit-border)',
  },
  RISK_ON: {
    color: '#6EE7B7',
    bg: 'rgba(110, 231, 183, 0.10)',
    border: 'rgba(110, 231, 183, 0.25)',
  },
  NEUTRAL: {
    color: 'var(--text-secondary)',
    bg: 'var(--bg-active)',
    border: 'var(--border-default)',
  },
  RISK_OFF: {
    color: 'var(--color-warning)',
    bg: 'var(--color-warning-muted)',
    border: 'rgba(251, 191, 36, 0.25)',
  },
  STRONG_RISK_OFF: {
    color: 'var(--color-loss)',
    bg: 'var(--color-loss-muted)',
    border: 'var(--color-loss-border)',
  },
};

function fmt(n: number | null | undefined, decimals = 2): string {
  if (n == null || isNaN(n)) return '—';
  return n.toLocaleString('en-US', {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  });
}

function fmtPct(n: number | null | undefined): string {
  if (n == null || isNaN(n)) return '—';
  return `${n.toFixed(1)}%`;
}

// ── Sub-components ────────────────────────────────────────────────────────────

function StatusDot({ state }: { state: EngineState }) {
  const cfg = STATE_CONFIG[state];
  return (
    <span
      style={{
        display: 'inline-block',
        width: '8px',
        height: '8px',
        borderRadius: '50%',
        background: cfg.dotColor,
        flexShrink: 0,
        animation: state === 'running' ? 'pulse 2s ease-in-out infinite' : 'none',
      }}
      aria-hidden="true"
    />
  );
}

function Metric({
  label,
  value,
  color,
}: {
  label: string;
  value: React.ReactNode;
  color?: string;
}) {
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '3px' }}>
      <span className="label">{label}</span>
      <span
        style={{
          fontFamily: 'var(--font-mono)',
          fontSize: '13px',
          fontWeight: 600,
          letterSpacing: '-0.02em',
          color: color ?? 'var(--text-primary)',
        }}
      >
        {value}
      </span>
    </div>
  );
}

function Divider() {
  return (
    <div
      style={{
        width: '1px',
        height: '32px',
        background: 'var(--border-subtle)',
        alignSelf: 'center',
        flexShrink: 0,
      }}
    />
  );
}

function MacroRegimeBadge({ regime }: { regime: string }) {
  const key = regime as MacroRegime;
  const cfg = REGIME_CONFIG[key] ?? REGIME_CONFIG['NEUTRAL'];

  return (
    <span
      style={{
        display: 'inline-flex',
        alignItems: 'center',
        gap: '5px',
        padding: '3px 10px',
        borderRadius: '100px',
        fontSize: '10px',
        fontWeight: 700,
        letterSpacing: '0.06em',
        textTransform: 'uppercase',
        color: cfg.color,
        background: cfg.bg,
        border: `1px solid ${cfg.border}`,
        whiteSpace: 'nowrap',
      }}
    >
      {regime.replace(/_/g, ' ')}
    </span>
  );
}

// ── Spot body ────────────────────────────────────────────────────────────────

function SpotBody({
  positions,
  positionsSummary,
  capital,
}: {
  positions: Record<string, any>[];
  positionsSummary: Record<string, any> | null;
  capital: { total: number; used: number; free: number } | null;
}) {
  const safePositions = Array.isArray(positions) ? positions : [];
  const activeCount = pickActivePositionsCount(positionsSummary, safePositions);
  const underwaterCount = pickUnderwaterCount(positionsSummary, safePositions);

  const deployedPct =
    capital && capital.total > 0 ? (capital.used / capital.total) * 100 : null;

  return (
    <>
      <Metric label="Active Positions" value={activeCount} />
      <Divider />
      {underwaterCount > 0 ? (
        <Metric
          label="Underwater"
          value={
            <span style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
              <AlertTriangle size={12} />
              {underwaterCount}
            </span>
          }
          color="var(--color-warning)"
        />
      ) : (
        <Metric label="Underwater" value={underwaterCount} color="var(--text-secondary)" />
      )}
      <Divider />
      <Metric
        label="Capital Free"
        value={capital ? `$${fmt(capital.free)}` : '—'}
        color="var(--color-profit)"
      />
      <Metric
        label="Capital Total"
        value={capital ? `$${fmt(capital.total)}` : '—'}
      />
      {deployedPct != null && (
        <Metric
          label="Deployed"
          value={fmtPct(deployedPct)}
          color={deployedPct > 85 ? 'var(--color-warning)' : 'var(--text-secondary)'}
        />
      )}
    </>
  );
}

// ── Futures body ─────────────────────────────────────────────────────────────

function FuturesBody({
  positions,
  positionsSummary,
  capital,
  balance,
}: {
  positions: Record<string, any>[];
  positionsSummary: Record<string, any> | null;
  capital: { total: number; used: number; free: number } | null;
  balance: Record<string, any> | null;
}) {
  const safePositions = Array.isArray(positions) ? positions : [];
  const openCount = pickActivePositionsCount(positionsSummary, safePositions);
  const longs = safePositions.filter((p) => p && (p.side === 'long' || p.direction === 'long')).length;
  const shorts = safePositions.filter((p) => p && (p.side === 'short' || p.direction === 'short')).length;

  const unrealizedPnl: number | null = balance?.unrealized_pnl ?? null;
  const pnlPositive = unrealizedPnl != null && unrealizedPnl >= 0;

  const marginUsed = capital?.used ?? null;
  const marginTotal = capital?.total ?? null;
  const marginPct =
    marginUsed != null && marginTotal != null && marginTotal > 0
      ? (marginUsed / marginTotal) * 100
      : null;

  const macroRegime: string | null = balance?.macro_regime ?? balance?.regime ?? null;

  return (
    <>
      <Metric label="Open Positions" value={openCount} />
      <Divider />
      <Metric
        label="Longs"
        value={
          <span style={{ display: 'inline-flex', alignItems: 'center', gap: '4px' }}>
            <TrendingUp size={12} />
            {longs}
          </span>
        }
        color="var(--color-profit)"
      />
      <Metric
        label="Shorts"
        value={
          <span style={{ display: 'inline-flex', alignItems: 'center', gap: '4px' }}>
            <TrendingDown size={12} />
            {shorts}
          </span>
        }
        color="var(--color-loss)"
      />
      <Divider />
      <Metric
        label="P&L Today"
        value={unrealizedPnl != null ? `${pnlPositive ? '+' : ''}$${fmt(unrealizedPnl)}` : '—'}
        color={
          unrealizedPnl == null
            ? 'var(--text-secondary)'
            : pnlPositive
            ? 'var(--color-profit)'
            : 'var(--color-loss)'
        }
      />
      <Divider />
      <Metric
        label="Margin Used"
        value={marginUsed != null ? `$${fmt(marginUsed)}` : '—'}
      />
      <Metric
        label="Margin Total"
        value={marginTotal != null ? `$${fmt(marginTotal)}` : '—'}
      />
      {marginPct != null && (
        <Metric
          label="Margin %"
          value={fmtPct(marginPct)}
          color={
            marginPct > 80
              ? 'var(--color-loss)'
              : marginPct > 60
              ? 'var(--color-warning)'
              : 'var(--text-secondary)'
          }
        />
      )}
      {macroRegime && (
        <>
          <Divider />
          <div style={{ display: 'flex', flexDirection: 'column', gap: '3px' }}>
            <span className="label">Macro Regime</span>
            <MacroRegimeBadge regime={macroRegime} />
          </div>
        </>
      )}
    </>
  );
}

// ── Skeleton loader ───────────────────────────────────────────────────────────

function SkeletonBar() {
