// ── Main component ────────────────────────────────────────────────────────────

export function EngineStatusBar({ profile }: EngineStatusBarProps) {
  const {
    isRunning,
    isPaused,
    positions,
    positionsSummary,
    capital,
    balance,
    isLoading,
    startEngine,
    pauseEngine,
    resumeEngine,
  } = useEngineStatus(profile);

  const [actionLoading, setActionLoading] = useState<'start' | 'pause' | 'resume' | null>(null);
  const [error, setError] = useState<string | null>(null);

  const engineState = resolveEngineState(isRunning, isPaused);
  const stateCfg = STATE_CONFIG[engineState];

  if (isLoading) return <SkeletonBar />;

  async function handleStart() {
    setActionLoading('start');
    setError(null);
    try {
      await startEngine();
    } catch (err) {
      const message = formatActionError(err);
      setError(message);
      console.error('Failed to start engine:', err);
    } finally {
      setActionLoading(null);
    }
  }

  async function handlePause() {
    setActionLoading('pause');
    setError(null);
    try {
      await pauseEngine();
    } catch (err) {
      const message = formatActionError(err);
      setError(message);
      console.error('Failed to pause engine:', err);
    } finally {
      setActionLoading(null);
    }
  }

  async function handleResume() {
    setActionLoading('resume');
    setError(null);
    try {
      await resumeEngine();
    } catch (err) {
      const message = formatActionError(err);
      setError(message);
      console.error('Failed to resume engine:', err);
    } finally {
      setActionLoading(null);
    }
  }

  return (
    <>
      {error && (
        <div
          style={{
            padding: '12px 16px',
            background: 'var(--color-loss-muted)',
            border: '1px solid var(--color-loss-border)',
            borderRadius: 'var(--radius-lg)',
            marginBottom: '12px',
            display: 'flex',
            alignItems: 'flex-start',
            gap: '12px',
          }}
          role="alert"
        >
          <AlertTriangle size={16} style={{ color: 'var(--color-loss)', flexShrink: 0, marginTop: '2px' }} />
          <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: '4px' }}>
            <span style={{ fontWeight: 600, fontSize: '13px', color: 'var(--text-primary)' }}>
              Failed to start {profile} engine
            </span>
            <span
              style={{
                fontSize: '12px',
                color: 'var(--text-secondary)',
                lineHeight: 1.5,
                fontFamily: 'var(--font-mono)',
                wordBreak: 'break-word',
              }}
            >
              {error}
            </span>
            {(error.includes('config') || error.includes('connection')) && (
              <span style={{ fontSize: '11px', color: 'var(--text-tertiary)', marginTop: '4px' }}>
                Make sure you have configured your {profile === 'spot' ? 'Spot' : 'Futures'} Engine settings and connected your Gate.io API keys.
              </span>
            )}
            {/^404\b/.test(error) && (
              <span style={{ fontSize: '11px', color: 'var(--text-tertiary)', marginTop: '4px' }}>
                The upstream API returned 404 for this route. If the issue persists, try a hard refresh (Cmd/Ctrl+Shift+R) and contact support with the path shown above.
              </span>
            )}
            {/^5\d\d\b/.test(error) && (
              <span style={{ fontSize: '11px', color: 'var(--text-tertiary)', marginTop: '4px' }}>
                The backend returned a server error. Server logs will have full details — please retry in a moment.
              </span>
            )}
          </div>
          <button
            type="button"
            onClick={() => setError(null)}
            style={{
              background: 'transparent',
              border: 'none',
              color: 'var(--text-tertiary)',
              cursor: 'pointer',
              padding: '4px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              borderRadius: 'var(--radius-sm)',
              flexShrink: 0,
            }}
            aria-label="Dismiss error"
          >
            ×
          </button>
        </div>
      )}
      <div
        style={{
        display: 'flex',
        alignItems: 'center',
        gap: '0',
        background: 'var(--bg-elevated)',
        border: '1px solid var(--border-default)',
        borderLeft: `3px solid ${stateCfg.borderColor}`,
        borderRadius: 'var(--radius-lg)',
        overflow: 'hidden',
        flexWrap: 'wrap',
      }}
      role="status"
      aria-label={`${profile} engine status: ${engineState}`}
    >
      {/* Left: status indicator */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: '10px',
          padding: '14px 20px',
          borderRight: '1px solid var(--border-subtle)',
          flexShrink: 0,
        }}
      >
        <StatusDot state={engineState} />
        <div style={{ display: 'flex', flexDirection: 'column', gap: '1px' }}>
          <span
            className="label"
            style={{ color: 'var(--text-tertiary)' }}
          >
            {profile === 'spot' ? 'SPOT ENGINE' : 'FUTURES ENGINE'}
          </span>
          <span
            style={{
              fontFamily: 'var(--font-mono)',
              fontSize: '11px',
              fontWeight: 700,
              letterSpacing: '0.08em',
              textTransform: 'uppercase',
              color: stateCfg.textColor,
            }}
          >
            {stateCfg.label}
          </span>
        </div>
      </div>

      {/* Middle: metrics */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: '20px',
          padding: '14px 20px',
          flex: 1,
          flexWrap: 'wrap',
          minWidth: 0,
        }}
      >
        {profile === 'spot' ? (
          <SpotBody
            positions={positions}
            positionsSummary={positionsSummary}
            capital={capital}
          />
        ) : (
          <FuturesBody
            positions={positions}
            positionsSummary={positionsSummary}
            capital={capital}
            balance={balance}
          />
        )}
      </div>

      {/* Right: action buttons */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: '8px',
          padding: '14px 16px',
          borderLeft: '1px solid var(--border-subtle)',
          flexShrink: 0,
        }}
      >
        {/* Pause / Resume / Start toggle */}
        {engineState === 'running' ? (
          <button
            type="button"
            className="btn btn-secondary"
            onClick={handlePause}
            disabled={actionLoading !== null}
            style={{ gap: '6px', fontSize: '12px', padding: '6px 12px', height: '32px' }}
            aria-label="Pause engine"
          >
            <Pause size={13} />
            {actionLoading === 'pause' ? 'Pausing…' : 'Pause Engine'}
          </button>
        ) : engineState === 'paused' ? (
          <button
            type="button"
            className="btn btn-secondary"
            onClick={handleResume}
            disabled={actionLoading !== null}
            style={{
              gap: '6px',
              fontSize: '12px',
              padding: '6px 12px',
              height: '32px',
              color: 'var(--color-warning)',
              borderColor: 'rgba(251, 191, 36, 0.25)',
            }}
            aria-label="Resume engine"
          >
            <Play size={13} />
            {actionLoading === 'resume' ? 'Resuming…' : 'Resume'}
          </button>
        ) : (
          <button
            type="button"
            className="btn btn-primary"
            onClick={handleStart}
            disabled={actionLoading !== null}
            style={{ gap: '6px', fontSize: '12px', padding: '6px 12px', height: '32px' }}
            aria-label="Start engine"
          >
            <Play size={13} />
            {actionLoading === 'start' ? 'Starting…' : 'Start Engine'}
          </button>
        )}

        {/* View positions link */}
        <Link
          href="/trading-desk/positions"
          className="btn btn-secondary"
          style={{ gap: '6px', fontSize: '12px', padding: '6px 12px', height: '32px', textDecoration: 'none' }}
        >
          <BarChart3 size={13} />
          View Positions
        </Link>
      </div>
    </div>
    </>
  );
}

'use client';

import { Fragment, useState } from 'react';
import { ChevronDown, ChevronRight, CheckCircle2, XCircle, RefreshCw } from 'lucide-react';
import { EvaluationTraceBreakdown, type EvaluationTraceItem } from './EvaluationTraceBreakdown';
import { scoreBand, scorePct, SCORE_TOOLTIP, RULES_TOOLTIP } from '@/lib/scoreBand';
import { summarizeScoreRules, fmtConfidence } from '@/lib/scoreRulesSummary';

// ── Types ─────────────────────────────────────────────────────────────────────

export interface ScoreRule {
  id: string;
  indicator: string;
  label: string;
  operator: string;
  target_value: number | string | null;
  min: number | null;
  max: number | null;
  actual_value: number | boolean | string | null;
  passed: boolean;
  points_awarded: number;
  points_possible: number;
  type?: "positive" | "penalty" | "neutral";
  condition_text: string;
  category: string;
  scheduler_group?: string | null;
  indicator_age_seconds?: number | null;
  /**
   * Task #211 — deterministic awarded points for this matched rule.
   * Equals the full configured points (no confidence weighting).
   * Present only on matched rules when the engine produced a score.
   * Absent ⇒ render falls back to `points_awarded` and the panel
   * shows a "(legacy)" marker on the Regras line.
   */
  awarded_points?: number;
  /** Confidence for this rule's indicator (0–1). Metadata only — does NOT reduce awarded_points. */
  indicator_confidence?: number;
  /** Whether the indicator data was available for evaluation. */
  data_available?: boolean;
}

// ── Shared score-rule colour tokens ──────────────────────────────────────────
export const RULE_COLORS = {
  positiveMatched:   { text: 'text-[#34D399]', bg: 'bg-[#061E14] border-[#14532D]/40' },
  penaltyFired:      { text: 'text-[#F87171]', bg: 'bg-[#1C0808] border-[#7F1D1D]/60' },
  positiveUnmatched: { text: 'text-[#4B5563]', bg: 'bg-[#0A0C14] border-[#1A2035]/50' },
  penaltyIdle:       { text: 'text-[#4B5563]', bg: 'bg-[#0A0C14] border-[#1A2035]/30' },
} as const;

/** Format a points value for display in score badges.
 *  - Avoids "-0" by checking Math.abs < 0.5 before rounding.
 *  - Badge uses integer; tooltip should use .toFixed(2) for precision. */
export function fmtPts(v: number): string {
  if (Math.abs(v) < 0.5) return '0';
  const r = Math.round(v);
  return r > 0 ? `+${r}` : `${r}`;
}

/** Sort score rules: positive first (descending), neutral in the middle,
 *  penalty rules last (ascending by magnitude — most negative first). */
export function sortScoreRules(rules: ScoreRule[]): ScoreRule[] {
  const pos = rules.filter(r => r.type === 'positive' || (!r.type && r.points_possible > 0));
  const neu = rules.filter(r => r.type === 'neutral' || (!r.type && r.points_possible === 0));
  const pen = rules.filter(r => r.type === 'penalty' || (!r.type && r.points_possible < 0));
  pos.sort((a, b) => b.points_possible - a.points_possible);
  pen.sort((a, b) => a.points_possible - b.points_possible);
  return [...pos, ...neu, ...pen];
}

type IndicatorValue = number | boolean | string | null | undefined;

export interface PipelineAssetWithScore {
  id: string;
  symbol: string;
  current_price: number | null;
  price_change_24h: number | null;
  volume_24h: number | null;
