  level_direction: string | null;
  blocked: boolean;
  block_reasons: string[];
  indicators: Record<string, IndicatorValue>;
  score_rules: ScoreRule[];
  score_classification?: string | null;
  evaluation_trace?: EvaluationTraceItem[];
  /** Robust Indicators Phase 2 — "robust" when the symbol's score
   *  was produced by the rollout pipeline, "legacy" when the legacy
   *  ScoreEngine produced it. ``null`` for rows persisted before the
   *  rollout columns were added (Migration 028). */
  engine_tag?: 'robust' | 'legacy' | string | null;
  /** ML model outputs — populated when ml_enabled + use_ml_ranking are active. */
  ml_probability?: number | null;
  ml_final_score?: number | null;
  blocked_by_ml?: boolean | null;
  crypto_ev?: CryptoEVSummary | null;
}

export interface IndicatorColumn {
  key: string;
  label: string;
  field: string;
}

interface CryptoEVSummary {
  score: number | null;
  state: string;
  n_trades: number;
  n_excluded_unreplayable?: number | null;
  w?: number | null;
  computed_at?: string | null;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function fmtMarketCap(val: number | null | undefined): string {
  if (val == null || val === 0) return '—';
  if (val >= 1_000_000_000) return `$${(val / 1_000_000_000).toFixed(1)}B`;
  if (val >= 1_000_000)     return `$${(val / 1_000_000).toFixed(0)}M`;
  if (val >= 1_000)         return `$${(val / 1_000).toFixed(0)}K`;
  return `$${val.toFixed(0)}`;
}

function marketCapColor(val: number | null | undefined): string {
  if (val == null || val === 0) return 'text-[#4B5563]';
  if (val < 50_000_000)  return 'text-[#F87171]';  // microcap red
  if (val <= 500_000_000) return 'text-[#FBBF24]';  // yellow
  return 'text-[#34D399]';  // green
}

function fmtDepth(val: number | null | undefined): string {
  if (val == null) return '—';
  if (val >= 1_000_000) return `${(val / 1_000_000).toFixed(1)}M`;
  if (val >= 1_000) return `${(val / 1_000).toFixed(0)}k`;
  return val.toFixed(0);
}

function fmtVolume(val: number | null | undefined): string {
  if (val == null || val === 0) return '—';
  if (val >= 1_000_000_000) return `$${(val / 1_000_000_000).toFixed(1)}B`;
  if (val >= 1_000_000) return `$${(val / 1_000_000).toFixed(1)}M`;
  if (val >= 1_000) return `$${(val / 1_000).toFixed(1)}K`;
  return `$${val.toFixed(0)}`;
}

// Backend sends market metadata columns with an "_meta:" prefix so they can share
// one table schema with computed indicators without colliding with raw field names.
function normalizeIndicatorKey(key: string): string {
  return key.startsWith('_meta:') ? key.slice(6) : key;
}

/** Color-coded indicator cell value + emoji dot */
function getIndicatorColor(key: string, value: IndicatorValue): { text: string; cls: string; dot: string } {
  if (value == null) return { text: '—', cls: 'text-[#4B5563]', dot: '' };
  const normalizedKey = normalizeIndicatorKey(key);

  if (typeof value === 'boolean') {
    if (normalizedKey === 'di_trend') {
      return {
        text: value ? '▲ DI+' : '▼ DI-',
        cls: value ? 'text-[#34D399]' : 'text-[#F87171]',
        dot: '',
      };
    }
    if (normalizedKey === 'ema_full_alignment') {
      return {
        text: value ? '9>50>200' : '—',
        cls: value ? 'text-[#34D399]' : 'text-[#4B5563]',
        dot: '',
      };
    }
    return {
      text: value ? '✓' : '✗',
      cls: value ? 'text-[#34D399]' : 'text-[#F87171]',
      dot: '',
    };
  }

  if (typeof value === 'string') {
    if (value === '9>50>200') return { text: '9›50›200', cls: 'text-[#34D399]', dot: '' };
    if (value === '9>50') return { text: '9›50', cls: 'text-[#FBBF24]', dot: '' };
    if (value === '9<50<200') return { text: '9‹50‹200', cls: 'text-[#F87171]', dot: '' };
    if (value === 'mix') return { text: 'mix', cls: 'text-[#94A3B8]', dot: '' };
    if (value === 'positive') return { text: value, cls: 'text-[#34D399]', dot: '' };
    if (value === 'negative') return { text: value, cls: 'text-[#F87171]', dot: '' };
    return { text: value, cls: 'text-[#CBD5E1]', dot: '' };
  }

  const n = Number(value);
  if (isNaN(n)) return { text: String(value), cls: 'text-[#4B5563]', dot: '' };

  switch (normalizedKey) {
    case 'market_cap':
      return {
        text: fmtMarketCap(n),
        cls: marketCapColor(n),
        dot: '',
      };
    case 'volume_24h':
      return {
        text: fmtVolume(n),
        cls: 'text-[#E2E8F0]',
        dot: '',
      };
    case 'price_change_24h':
    case 'change_24h':
      return {
        text: `${n >= 0 ? '+' : ''}${n.toFixed(2)}%`,
        cls: n >= 0 ? 'text-[#34D399]' : 'text-[#F87171]',
        dot: n >= 0 ? '🟢' : '🔴',
      };
    case 'rsi':
      return {
        text: n.toFixed(1),
        cls: (n >= 45 && n <= 65) ? 'text-[#34D399]' : (n > 75 || n < 35) ? 'text-[#F87171]' : 'text-[#E2E8F0]',
        dot: (n >= 45 && n <= 65) ? '🟢' : (n > 75 || n < 35) ? '🔴' : '',
      };
    case 'volume_spike':
      return {
        text: n.toFixed(1),
        cls: n > 2.0 ? 'text-[#34D399]' : n >= 1.3 ? 'text-[#FBBF24]' : 'text-[#F87171]',
        dot: n > 2.0 ? '🟢' : n >= 1.3 ? '🟡' : '🔴',
      };
    case 'taker_ratio':
      // Canonical scale since #82: buy/(buy+sell) ∈ [0, 1]. Equilibrium = 0.5.
      // 3-decimal display so 0.512 vs 0.498 is distinguishable next to thresholds.
      return {
        text: n.toFixed(3),
        cls: n > 0.6 ? 'text-[#34D399]' : n < 0.4 ? 'text-[#F87171]' : 'text-[#94A3B8]',
        dot: n > 0.6 ? '🟢' : n < 0.4 ? '🔴' : '⚪',
      };
    case 'spread_pct':
      return {
        text: n.toFixed(2) + '%',
        cls: n <= 0.8 ? 'text-[#34D399]' : n <= 1.5 ? 'text-[#FBBF24]' : 'text-[#F87171]',
        dot: n <= 0.8 ? '🟢' : n <= 1.5 ? '🟡' : '🔴',
      };
    case 'orderbook_depth_usdt':
      return {
        text: fmtDepth(n),
        cls: n >= 5000 ? 'text-[#E2E8F0]' : 'text-[#F87171]',
        dot: n < 5000 ? '🔴' : '',
      };
    case 'ema9_distance_pct':
      return {
        text: (n >= 0 ? '+' : '') + n.toFixed(2) + '%',
        cls: Math.abs(n) > 3 ? 'text-[#FBBF24]' : 'text-[#E2E8F0]',
        dot: '',
      };
    default:
      return {
        text: Math.abs(n) >= 100 ? n.toFixed(1) : Math.abs(n) >= 1 ? n.toFixed(2) : n.toFixed(4),
        cls: 'text-[#E2E8F0]',
        dot: '',
      };
  }
}

function fmtIndValue(key: string, value: IndicatorValue): string {
  if (value == null) return '—';
  const normalizedKey = normalizeIndicatorKey(key);
  if (typeof value === 'boolean') {
    if (normalizedKey === 'ema9_gt_ema50' || normalizedKey === 'ema_trend') return value ? '9>50' : '9<50';
    if (normalizedKey === 'ema_full_alignment') return value ? '9>50>200' : '—';
    if (normalizedKey === 'di_trend') return value ? '▲ DI+' : '▼ DI-';
    return value ? '✓' : '✗';
  }
  if (normalizedKey === 'macd_histogram') {
    const n = Number(value);
    return (n >= 0 ? '+' : '') + n.toFixed(4);
  }
  const n = Number(value);
  if (isNaN(n)) return String(value);
  if (normalizedKey === 'market_cap') return fmtMarketCap(n);
  if (normalizedKey === 'volume_24h') return fmtVolume(n);
  if (normalizedKey === 'price_change_24h' || normalizedKey === 'change_24h') return `${n >= 0 ? '+' : ''}${n.toFixed(2)}%`;
  if (normalizedKey === 'orderbook_depth_usdt') return fmtDepth(n);
  if (normalizedKey === 'spread_pct' || normalizedKey === 'ema9_distance_pct') return `${n >= 0 ? '+' : ''}${n.toFixed(2)}%`;
  if (Math.abs(n) >= 100) return n.toFixed(1);
  if (Math.abs(n) >= 1)   return n.toFixed(2);
  return n.toFixed(4);
}

function getRuleForIndicator(keys: string[], rules: ScoreRule[]): ScoreRule | undefined {
  let r = rules.find((rule) => keys.includes(rule.indicator));
  if (!r && keys.includes('price_change_24h')) r = rules.find((rule) => rule.indicator === 'change_24h');
  if (!r && keys.includes('change_24h')) r = rules.find((rule) => rule.indicator === 'price_change_24h');
  if (!r && keys.includes('ema9_gt_ema50')) {
    r = rules.find((rule) => rule.operator === 'ema9>ema50' || rule.operator === 'ema9>ema50>ema200');
  }
  return r;
}

function getStatus(score: number, classification?: string | null, blocked: boolean = false) {
  if (blocked) return { label: 'BLOCKED', cls: 'text-[#F87171]', dot: 'bg-[#F87171]' };
  if (classification === 'strong_buy') return { label: 'STRONG', cls: 'text-[#34D399]', dot: 'bg-[#34D399]' };
  if (classification === 'buy') return { label: 'GOOD', cls: 'text-[#4ADE80]', dot: 'bg-[#4ADE80]' };
  if (classification === 'neutral') return { label: 'MIXED', cls: 'text-[#FBBF24]', dot: 'bg-[#FBBF24]' };
  if (classification === 'avoid' || classification === 'no_data') {
    return { label: 'WEAK', cls: 'text-[#F87171]', dot: 'bg-[#F87171]' };
  }
  return { label: score > 0 ? 'SCORED' : 'WEAK', cls: 'text-[#94A3B8]', dot: 'bg-[#94A3B8]' };
}

function fmtAge(seconds: number | null | undefined): string {
  if (seconds == null) return '';
  if (seconds < 60) return `${Math.round(seconds)}s`;
  if (seconds < 3600) return `${Math.round(seconds / 60)}m`;
  return `${(seconds / 3600).toFixed(1)}h`;
}

const GROUP_LABEL: Record<string, string> = {
  structural: 'struct',
  microstructure: 'micro',
  combined: 'cmbd',
};

const GROUP_COLOR: Record<string, string> = {
  structural: 'text-[#60A5FA]',
  microstructure: 'text-[#34D399]',
  combined: 'text-[#94A3B8]',
};

const BOOLEAN_INDICATOR_KEYS = new Set([
  'ema_trend', 'ema9_gt_ema50', 'ema_full_alignment', 'di_trend',
]);

function getWeaknesses(rules: ScoreRule[]): string {
  const failed = rules
    .filter(r => !r.passed && r.points_possible > 0)
    .sort((a, b) => b.points_possible - a.points_possible)
    .slice(0, 2);
  return failed.map(r => r.label).join(' · ');
}

function scoreBarColor(score: number, classification?: string | null, blocked: boolean = false) {
  const status = getStatus(score, classification, blocked);
  if (status.label === 'STRONG') return '#34D399';
  if (status.label === 'GOOD') return '#4ADE80';
  if (status.label === 'MIXED') return '#FBBF24';
  if (status.label === 'SCORED') return '#94A3B8';
  return '#F87171';
}

// ── Sub-components ────────────────────────────────────────────────────────────

function IndicatorCell({ column, value, rules }: { column: IndicatorColumn; value: IndicatorValue; rules: ScoreRule[] }) {
  const { text, cls, dot } = getIndicatorColor(column.key, value);
  const normalizedKey = normalizeIndicatorKey(column.key);
  // Deduplicate alias candidates because meta columns may resolve to the same rule key.
  const rule = getRuleForIndicator(
    Array.from(new Set([column.field, column.key, normalizedKey])),
    rules,
  );
  const tip = rule
    ? `${rule.condition_text}  →  ${rule.passed ? fmtPts(rule.points_awarded) + ' pts (' + rule.points_awarded.toFixed(2) + ')' : 'falhou'}`
    : undefined;

  return (
    <div className="flex items-center justify-end gap-1" title={tip}>
      {dot && <span className="text-[10px]">{dot}</span>}
      <span className={`font-mono text-xs ${cls}`}>{text}</span>
    </div>
  );
}

function ScoreBar({
  score,
  classification,
  blocked = false,
}: {
  score: number;
  classification?: string | null;
  blocked?: boolean;
}) {
  const color = scoreBarColor(score, classification, blocked);
  return (
    <div className="flex items-center gap-2 min-w-[110px]">
      <div className="relative flex-1 h-1.5 bg-[#1A2035] rounded-full overflow-hidden">
        <div
          className="h-full rounded-full transition-all duration-700"
          style={{ width: `${Math.min(100, score)}%`, backgroundColor: color }}
        />
      </div>
      <span className="text-sm font-bold text-[#E2E8F0] tabular-nums w-7 text-right"
            style={{ color }}>
        {Math.round(score)}
      </span>
    </div>
  );
}

function cryptoEvClass(state: string | null | undefined): string {
  if (state === 'FAVORABLE') return 'bg-[#34D399]/10 text-[#34D399] border-[#34D399]/20';
  if (state === 'RISKY') return 'bg-[#FBBF24]/10 text-[#FBBF24] border-[#FBBF24]/20';
  if (state === 'AVOID') return 'bg-[#F87171]/10 text-[#F87171] border-[#F87171]/20';
  if (state === 'NEUTRAL') return 'bg-[#1E2433] text-[#94A3B8] border-[#334155]';
  return 'bg-[#0A0C14] text-[#4B5563] border-[#1A2035]';
}

function CryptoEVBadge({ value }: { value?: CryptoEVSummary | null }) {
  if (!value || value.score == null) return <span className="text-[#4B5563]">-</span>;
  const tip = [
    `Crypto EV: ${Number(value.score).toFixed(1)}`,
    value.state ? `state ${value.state}` : null,
    `N=${value.n_trades ?? 0}`,
    value.n_excluded_unreplayable != null ? `unreplayable=${value.n_excluded_unreplayable}` : null,
    value.w != null ? `w=${Number(value.w).toFixed(2)}` : null,
    value.computed_at ? `as of ${value.computed_at}` : null,
  ].filter(Boolean).join(' | ');
  return (
    <span
      className={`text-[10px] font-semibold px-1.5 py-0.5 rounded border tabular-nums ${cryptoEvClass(value.state)}`}
      title={tip}
    >
      {Number(value.score).toFixed(0)}
    </span>
  );
}

// ── Drilldown Panel ───────────────────────────────────────────────────────────

const CATEGORY_ORDER = ['momentum', 'market_structure', 'liquidity', 'signal', 'other'];
const CATEGORY_LABELS: Record<string, string> = {
  momentum: 'Momentum', market_structure: 'Estrutura de Mercado',
  liquidity: 'Liquidez', signal: 'Sinal', other: 'Outros',
};

function DrilldownPanel({
  rules,
  score,
  classification,
  blocked = false,
  evaluationTrace = [],
}: {
  rules: ScoreRule[];
  score: number;
  classification?: string | null;
  blocked?: boolean;
  evaluationTrace?: EvaluationTraceItem[];
}) {
  const summary = summarizeScoreRules(rules);
  const {
    matchedCount,
    positiveCount,
    totalPossible,
    nominalEarned,
    awardedEarned,
    hasEnriched,
    totalPenalties,
  } = summary;
  const earnedDisplay = hasEnriched ? awardedEarned : nominalEarned;

  // Group by category; within each category sort positive-first then penalties.
  const byCategory = CATEGORY_ORDER.reduce<Record<string, ScoreRule[]>>((acc, cat) => {
    const items = sortScoreRules(rules.filter(r => r.category === cat));
    if (items.length) acc[cat] = items;
    return acc;
  }, {});

  // Single source of truth for both label and color (Task #187 review fix).
  // Previously getStatus + scoreBarColor could disagree at the boundaries
  // because they encoded thresholds independently.
  const band = scoreBand(score, blocked);
  const pct = scorePct(score);

  return (
    <div className="px-4 pt-3 pb-4 bg-[#06080E] border-t border-[#1A2035]">
      {/* Score row — robust 0–100 metric (drives entries) */}
      <div className="flex items-center gap-3">
        <span className="text-[10px] font-semibold text-[#4B5563] uppercase tracking-wider w-[110px] shrink-0">
          Score
        </span>
        <div
          className="flex-1 h-1.5 bg-[#1A2035] rounded-full overflow-hidden"
          title={SCORE_TOOLTIP}
        >
          <div
            className="h-full rounded-full transition-all duration-700"
            style={{ width: `${pct}%`, backgroundColor: band.color }}
          />
        </div>
        <span
          className="text-sm font-bold tabular-nums w-16 text-right"
          style={{ color: band.color }}
          title={SCORE_TOOLTIP}
        >
          {score.toFixed(1)}/100
        </span>
        <span
          className="text-[10px] font-semibold uppercase tracking-wider w-14 text-right"
          style={{ color: band.color }}
          title={SCORE_TOOLTIP}
          data-testid="score-band-label"
        >
          {band.label}
        </span>
      </div>

      {/* Rules row — secondary counter, distinct visual (no bar) */}
      <div className="flex items-center gap-3 mt-1.5 mb-3">
        <span className="text-[10px] font-semibold text-[#4B5563] uppercase tracking-wider w-[110px] shrink-0">
          Regras
        </span>
        <span
          className="text-[11px] text-[#64748B] flex-1"
          title={RULES_TOOLTIP}
        >
          {matchedCount}/{positiveCount} matched ·{' '}
          {`+${earnedDisplay.toFixed(0)}`}
          /{totalPossible.toFixed(0)} pts
          {!hasEnriched && matchedCount > 0 && (
            <span className="ml-1.5 text-[9px] text-[#475569] uppercase tracking-wider">
              (legacy)
            </span>
          )}
        </span>
        {totalPenalties !== 0 && (
          <span className="text-[10px] text-[#F87171] shrink-0">
            Penalty: {fmtPts(totalPenalties)}
          </span>
        )}
      </div>

      {/* Rules by category */}
      <div className="space-y-3">
        {Object.entries(byCategory).map(([cat, catRules]) => (
          <div key={cat}>
            <div className="text-[10px] font-medium text-[#334155] uppercase tracking-wider mb-1.5">
              {CATEGORY_LABELS[cat]}
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-1">
              {catRules.map((rule) => {
                const isPenalty = rule.type === 'penalty';
                const isNeutral = rule.type === 'neutral';
                const isFired   = rule.passed;
                const isGood    = !isPenalty && !isNeutral && isFired;
                const colors    = isNeutral
                  ? RULE_COLORS.positiveUnmatched
                  : isPenalty
                    ? (isFired ? RULE_COLORS.penaltyFired : RULE_COLORS.penaltyIdle)
                    : (isFired ? RULE_COLORS.positiveMatched : RULE_COLORS.positiveUnmatched);

                const grpKey = rule.scheduler_group ?? '';
                const grpLabel = GROUP_LABEL[grpKey] ?? grpKey;
                const grpColor = GROUP_COLOR[grpKey] ?? 'text-[#4B5563]';
                const ageStr = fmtAge(rule.indicator_age_seconds);

                const hasAwarded =
                  rule.passed &&
                  typeof rule.awarded_points === 'number' &&
                  Number.isFinite(rule.awarded_points);
                const awardedDisplay = rule.passed
                  ? hasAwarded
                    ? `+${(rule.awarded_points as number).toFixed(0)}`
                    : fmtPts(rule.points_awarded)
                  : '0';
                const possibleDisplay = fmtPts(rule.points_possible);
                const ptsTooltip = hasAwarded
                  ? `${(rule.awarded_points as number).toFixed(0)}` +
                    ` / ${rule.points_possible.toFixed(0)} pts` +
                    ` (conf ${fmtConfidence(rule.indicator_confidence)})`
                  : `${rule.passed ? rule.points_awarded.toFixed(2) : '0'} /` +
                    ` ${rule.points_possible.toFixed(2)} pts`;

                return (
                  <div
                    key={rule.id}
                    className={`flex items-center gap-2 px-3 py-2 rounded-lg text-xs border ${colors.bg}`}
                    data-testid={`drilldown-rule-${rule.indicator}`}
                  >
                    {isGood || (isPenalty && !isFired) || (isNeutral && isFired)
                      ? <CheckCircle2 size={11} className={`${isGood ? 'text-[#34D399]' : 'text-[#4B5563]'} shrink-0`} />
                      : <XCircle size={11} className={`${isNeutral ? 'text-[#4B5563]' : 'text-[#F87171]'} shrink-0`} />
                    }
                    <span className={`flex-1 truncate ${isGood ? 'text-[#94A3B8]' : isPenalty && isFired ? 'text-[#F87171]' : 'text-[#4B5563]'}`}>
                      {rule.condition_text}
                    </span>
                    <span className={`font-mono text-[10px] shrink-0 ${
                      rule.actual_value != null
                        ? isGood ? 'text-[#CBD5E1]' : isPenalty && isFired ? 'text-[#FCA5A5]' : 'text-[#64748B]'
                        : 'text-[#334155]'
                    }`}>
                      {rule.actual_value != null ? fmtIndValue(rule.indicator, rule.actual_value) : '—'}
                    </span>
                    {grpLabel && (
                      <span className={`font-mono text-[9px] shrink-0 ${grpColor} opacity-70`}
                            title={`${rule.scheduler_group ?? ''}${ageStr ? ` · ${ageStr} ago` : ''}`}>
                        {grpLabel}{ageStr ? `·${ageStr}` : ''}
                      </span>
                    )}
                    <span
                      className={`font-mono text-[10px] shrink-0 w-20 text-right ${colors.text}`}
                      title={ptsTooltip}
                    >
                      {awardedDisplay}/{possibleDisplay}
                    </span>
                  </div>
                );
              })}
            </div>
          </div>
        ))}
      </div>

      {rules.length === 0 && (
        <p className="text-xs text-[#334155] text-center py-2">
          Sem regras de scoring configuradas — configure em Settings → Score.
        </p>
      )}

      {evaluationTrace.length > 0 && (
        <div className="mt-4 space-y-3">
          <div className="text-[10px] font-semibold text-[#4B5563] uppercase tracking-wider">
            Profile Evaluation
          </div>
          <EvaluationTraceBreakdown items={evaluationTrace} />
        </div>
      )}
    </div>
  );
}

// ── Main component ─────────────────────────────────────────────────────────────

export function PipelineAssetTable({
  assets,
  indicatorCols = [],
  onRefresh,
  refreshing,
  liveDirections = {},
  showScore = true,
}: {
  assets: PipelineAssetWithScore[];
  indicatorCols?: IndicatorColumn[];
  onRefresh: () => void;
  refreshing: boolean;
  liveDirections?: Record<string, string>;
  showScore?: boolean;
}) {
  const [expandedRow, setExpandedRow] = useState<string | null>(null);
  const [sortKey, setSortKey] = useState<string | null>(null);
  const [sortDir, setSortDir] = useState<'asc' | 'desc'>('desc');

  if (assets.length === 0) {
    return (
      <div className="px-4 py-8 text-center">
        <p className="text-sm text-[#4B5563]">No assets. Click refresh to resolve the pipeline.</p>
        <button
          onClick={onRefresh}
          disabled={refreshing}
          className="mt-3 px-4 py-1.5 text-xs rounded-lg bg-[#1E2433] text-[#94A3B8] hover:bg-[#263048] transition-colors disabled:opacity-40"
          data-testid="pipeline-refresh-btn"
        >
          {refreshing ? <span className="flex items-center gap-1.5"><RefreshCw size={11} className="animate-spin" />Refreshing…</span> : 'Refresh Now'}
        </button>
      </div>
    );
  }

  const toggleSort = (key: string) => {
    if (sortKey === key) {
      setSortDir(d => d === 'desc' ? 'asc' : 'desc');
    } else {
      setSortKey(key);
      setSortDir('desc');
    }
  };

  const visibleColumns = indicatorCols;

  const getAssetColumnValue = (asset: PipelineAssetWithScore, column: IndicatorColumn): IndicatorValue => {
    const topLevelValue = (asset as unknown as Record<string, unknown>)[column.field] as IndicatorValue;
    return asset.indicators?.[column.key]
      ?? asset.indicators?.[normalizeIndicatorKey(column.key)]
      ?? asset.indicators?.[column.field]
      ?? topLevelValue
      ?? null;
  };

  const sortNum = (a: number, b: number) => sortDir === 'desc' ? b - a : a - b;
  const sortedAssets = sortKey
    ? [...assets].sort((a, b) => {
        if (sortKey === 'score') return sortNum(a.alpha_score ?? -Infinity, b.alpha_score ?? -Infinity);
        if (sortKey === 'ml') return sortNum(a.ml_probability ?? -Infinity, b.ml_probability ?? -Infinity);
        if (sortKey === 'crypto_ev') return sortNum(a.crypto_ev?.score ?? -Infinity, b.crypto_ev?.score ?? -Infinity);
        const col = visibleColumns.find(c => c.key === sortKey);
        if (!col) return 0;
        const av = getAssetColumnValue(a, col);
        const bv = getAssetColumnValue(b, col);
        const an = typeof av === 'number' ? av : av == null ? -Infinity : Number(av);
        const bn = typeof bv === 'number' ? bv : bv == null ? -Infinity : Number(bv);
        return sortNum(isNaN(an) ? -Infinity : an, isNaN(bn) ? -Infinity : bn);
      })
    : assets;

  const totalPts  = (rules: ScoreRule[]) =>
    rules.filter(r => (r.type ?? 'positive') !== 'penalty').reduce((s, r) => s + r.points_possible, 0);
  const earnedPts = (rules: ScoreRule[]) =>
    rules.filter(r => (r.type ?? 'positive') !== 'penalty').reduce((s, r) => s + r.points_awarded, 0);

  return (
    <div className="overflow-x-auto">
      <table className="w-full text-xs min-w-[1040px]">
        <thead>
          <tr className="border-b border-[#1A2035] bg-[#060810] sticky top-0">
            <th className="w-8 px-2 py-2.5" />
            <th className="px-3 py-2.5 text-left text-[#4B5563] font-medium">Symbol</th>
            {showScore && (
              <th className="px-3 py-2.5 text-left text-[#4B5563] font-medium min-w-[130px]">
                <button onClick={() => toggleSort('score')} className="flex items-center gap-1 hover:text-[#94A3B8] transition-colors">
                  Score
                  <span className={`text-[9px] ${sortKey === 'score' ? 'text-[#60A5FA]' : 'opacity-30'}`}>
                    {sortKey === 'score' ? (sortDir === 'desc' ? '▼' : '▲') : '⇅'}
                  </span>
                </button>
              </th>
            )}
            <th className="px-3 py-2.5 text-center text-[#4B5563] font-medium whitespace-nowrap">
              <button onClick={() => toggleSort('ml')} className="flex items-center gap-1 justify-center hover:text-[#94A3B8] transition-colors w-full">
                ML
                <span className={`text-[9px] ${sortKey === 'ml' ? 'text-[#60A5FA]' : 'opacity-30'}`}>
                  {sortKey === 'ml' ? (sortDir === 'desc' ? '▼' : '▲') : '⇅'}
                </span>
              </button>
            </th>
            <th className="px-3 py-2.5 text-center text-[#4B5563] font-medium whitespace-nowrap">
              <button onClick={() => toggleSort('crypto_ev')} className="flex items-center gap-1 justify-center hover:text-[#94A3B8] transition-colors w-full">
                EV
                <span className={`text-[9px] ${sortKey === 'crypto_ev' ? 'text-[#60A5FA]' : 'opacity-30'}`}>
                  {sortKey === 'crypto_ev' ? (sortDir === 'desc' ? '▼' : '▲') : '⇅'}
                </span>
              </button>
            </th>
            {visibleColumns.map((col) => {
              const isNumeric = !BOOLEAN_INDICATOR_KEYS.has(col.key) && !BOOLEAN_INDICATOR_KEYS.has(normalizeIndicatorKey(col.key));
              return (
                <th key={col.key} className="px-3 py-2.5 text-right text-[#4B5563] font-medium whitespace-nowrap">
                  {isNumeric ? (
                    <button onClick={() => toggleSort(col.key)} className="flex items-center gap-1 justify-end hover:text-[#94A3B8] transition-colors w-full">
                      {col.label}
                      <span className={`text-[9px] ${sortKey === col.key ? 'text-[#60A5FA]' : 'opacity-30'}`}>
                        {sortKey === col.key ? (sortDir === 'desc' ? '▼' : '▲') : '⇅'}
                      </span>
                    </button>
                  ) : (
                    col.label
                  )}
                </th>
              );
            })}
            <th className="px-3 py-2.5 text-center text-[#4B5563] font-medium">Status</th>
          </tr>
        </thead>
        <tbody>
          {sortedAssets.map((asset) => {
            const score     = asset.alpha_score ?? 0;
            const rules     = asset.score_rules ?? [];
            const isBlocked = asset.blocked ?? false;
            const blockReasons = asset.block_reasons ?? [];
            const classification = asset.score_classification;
            const status    = getStatus(score, classification, isBlocked);
            const weakness  = getWeaknesses(rules);
            const isExpanded = expandedRow === asset.symbol;
            const effectiveDir = liveDirections[asset.symbol] ?? asset.level_direction;

            const hasDivergence =
              rules.some(r => r.indicator === 'macd_histogram' && !r.passed) && score >= 65;
            const hasVolSpike =
              Number(asset.indicators?.['volume_spike'] ?? 0) > 2.5;
            const hasHighADX =
              Number(asset.indicators?.['adx'] ?? 0) > 40;

            const rowAlert = isBlocked        ? 'border-l-2 border-l-[#F87171]/60'
                           : hasDivergence    ? 'border-l-2 border-l-[#FBBF24]/60'
                           : hasVolSpike      ? 'border-l-2 border-l-[#60A5FA]/60'
                           : hasHighADX       ? 'border-l-2 border-l-[#A78BFA]/60'
                           : '';

            const getColumnValue = (column: IndicatorColumn) => getAssetColumnValue(asset, column);

            return (
              <Fragment key={asset.symbol}>
                <tr
                  className={`border-b border-[#1A2035]/60 cursor-pointer transition-colors ${rowAlert} ${
                    isExpanded ? 'bg-[#0C1020]' : 'hover:bg-[#0D1118]'
                  } ${effectiveDir === 'up' ? 'row-level-up' : effectiveDir === 'down' ? 'row-level-down' : ''}`}
                  onClick={() => setExpandedRow(isExpanded ? null : asset.symbol)}
                  data-testid={`pipeline-asset-row-${asset.symbol}`}
                >
                  {/* Expander */}
                  <td className="px-2 py-2.5 text-[#334155]">
                    {isExpanded
                      ? <ChevronDown  size={13} className="text-[#60A5FA]" />
                      : <ChevronRight size={13} />
                    }
                  </td>

                  {/* Symbol */}
                  <td className="px-3 py-2.5">
                    <div className="flex items-center gap-1.5">
                      <span className="font-semibold text-[#E2E8F0] tracking-wide">{asset.symbol}</span>
                      {isBlocked && (
                        <span className="text-[9px] px-1 py-0.5 rounded bg-[#F87171]/10 text-[#F87171] border border-[#F87171]/20" title={`Bloqueado: ${blockReasons.join(', ')}`}>
                          🚨
                        </span>
                      )}
                      {hasDivergence && !isBlocked && (
                        <span className="text-[9px] px-1 py-0.5 rounded bg-[#FBBF24]/10 text-[#FBBF24] border border-[#FBBF24]/20" title="Score alto mas MACD negativo">
                          DIV
                        </span>
                      )}
                      {hasHighADX && !isBlocked && (
                        <span className="text-[9px] px-1 py-0.5 rounded bg-[#A78BFA]/10 text-[#A78BFA] border border-[#A78BFA]/20" title="ADX alto — possível breakout">
                          ADX
                        </span>
                      )}
                    </div>
                    {showScore && rules.length > 0 && (
                      <div className="mt-0.5 text-[10px] text-[#334155] flex items-center gap-1.5">
                        <span>
                          {earnedPts(rules).toFixed(0)}/{totalPts(rules).toFixed(0)} pts
                          {weakness ? ` · ${weakness}` : ''}
                        </span>
                        {asset.engine_tag === 'robust' && (
                          <span
                            className="text-[9px] px-1 py-0.5 rounded bg-[#34D399]/10 text-[#34D399] border border-[#34D399]/20 font-semibold tracking-wide"
                            title="Score produzido pelo Robust Indicator Pipeline (Phase 2)"
                            data-testid={`engine-badge-robust-${asset.symbol}`}
                          >
                            ROBUST
                          </span>
                        )}
                        {asset.engine_tag === 'legacy' && (
                          <span
                            className="text-[9px] px-1 py-0.5 rounded bg-[#1A2035] text-[#94A3B8] border border-[#1A2035] font-semibold tracking-wide"
                            title="Score produzido pelo motor legado (não bucketed no rollout)"
                            data-testid={`engine-badge-legacy-${asset.symbol}`}
                          >
                            LEGACY
                          </span>
                        )}
                      </div>
                    )}
                  </td>

                   {/* Score bar — hidden for Stage 0 (POOL/custom) and Stage 1 (L1) */}
                  {showScore && (
                    <td className="px-3 py-2.5">
                      <ScoreBar score={score} classification={classification} blocked={isBlocked} />
                    </td>
                  )}

                  {/* ML probability column */}
                  <td className="px-3 py-2.5 text-center">
                    {asset.ml_probability != null ? (
                      <span
                        className={`text-[10px] font-semibold px-1.5 py-0.5 rounded ${
                          asset.blocked_by_ml
                            ? 'bg-[#F87171]/10 text-[#F87171] border border-[#F87171]/20'
                            : asset.ml_probability >= 0.6
                            ? 'bg-[#34D399]/10 text-[#34D399] border border-[#34D399]/20'
                            : asset.ml_probability >= 0.4
                            ? 'bg-[#FBBF24]/10 text-[#FBBF24] border border-[#FBBF24]/20'
                            : 'bg-[#F87171]/10 text-[#F87171] border border-[#F87171]/20'
                        }`}
                        title={`ML win probability: ${(asset.ml_probability * 100).toFixed(1)}%${asset.blocked_by_ml ? ' (blocked by ML)' : ''}`}
                      >
                        {(asset.ml_probability * 100).toFixed(0)}%
                      </span>
                    ) : (
                      <span className="text-[#4B5563]">—</span>
                    )}
                  </td>

                  {/* Crypto EV operational score */}
                  <td className="px-3 py-2.5 text-center">
                    <CryptoEVBadge value={asset.crypto_ev} />
                  </td>

                  {/* Dynamic indicator columns from the profile */}
                  {visibleColumns.map((col) => (
                    <td key={col.key} className="px-3 py-2.5 text-right">
                      <IndicatorCell
                        column={col}
                        value={getColumnValue(col)}
                        rules={rules}
                      />
                    </td>
                  ))}

                  {/* Status */}
                  <td className="px-3 py-2.5 text-center">
                    <div className="inline-flex items-center gap-1.5" title={isBlocked ? blockReasons.join(', ') : ''}>
                      <div className={`w-1.5 h-1.5 rounded-full ${status.dot} shrink-0`} />
                      <span className={`font-semibold text-[10px] tracking-wide ${status.cls}`}>
                        {status.label}
                      </span>
                      {isBlocked && <span className="text-[9px]">🚨</span>}
                    </div>
                  </td>
                </tr>

                {/* Drilldown row */}
                {isExpanded && (
                  <tr className="border-b border-[#1A2035]">
                    <td colSpan={2 + (showScore ? 1 : 0) + 1 + 1 + 1 + visibleColumns.length} className="p-0">
                      <DrilldownPanel
                        rules={rules}
                        score={score}
                        classification={classification}
                        blocked={isBlocked}
                        evaluationTrace={asset.evaluation_trace ?? []}
                      />
                    </td>
                  </tr>
                )}
              </Fragment>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

"use client";

import { Fragment, useMemo, useState } from "react";
import { ChevronDown, ChevronRight, CheckCircle2, XCircle } from "lucide-react";
import {
  EvaluationTraceBreakdown,
  blockRuleOutcome,
  classifySkip,
  formatEvaluationTraceValue,
  type EvaluationTraceItem,
} from "./EvaluationTraceBreakdown";
import type { ScoreRule } from "./PipelineAssetTable";
import { RULE_COLORS, fmtPts, sortScoreRules } from "./PipelineAssetTable";
import { scoreBand, scorePct, SCORE_TOOLTIP, RULES_TOOLTIP } from "@/lib/scoreBand";
import { summarizeScoreRules, fmtConfidence } from "@/lib/scoreRulesSummary";

const DECISION_SUMMARY_INDICATOR_LIMIT = 3;

export interface DecisionTraceItem {
  type: "filter" | "block_rule" | "entry_trigger" | "signal";
  indicator: string;
  condition: string;
  expected?: string | null;
  current_value?: unknown;
  status: "PASS" | "FAIL" | "SKIPPED";
  reason?: string | null;
  outcome?: "OK" | "TRIPPED" | "SKIPPED";
  condition_matched?: boolean | null;
}

export interface DecisionDetails {
  filters: DecisionTraceItem[];
  indicators: string[];
  conditions: string[];
  current_values: Record<string, unknown>;
  expected_values: Record<string, string | null>;
  evaluation_trace: DecisionTraceItem[];
}

export interface WatchlistDecisionItem {
  symbol: string;
  status: "approved" | "rejected";
  stage?: string | null;
  profile_id?: string | null;
  timestamp?: string | null;
  alpha_score?: number | null;
  technical_score?: number | null;
  final_score?: number | null;
  social_score?: SocialScoreSummary | null;
  score_rules?: ScoreRule[];
  failed_indicators: string[];
  conditions: string[];
  current_values: Record<string, unknown>;
  expected_values: Record<string, string | null>;
  details: DecisionDetails;
  /** ML model outputs — populated when ml_enabled + use_ml_ranking are active. */
  ml_probability?: number | null;
  ml_final_score?: number | null;
  blocked_by_ml?: boolean | null;
  crypto_ev?: CryptoEVSummary | null;
}

export interface SocialScoreSummary {
  run_id?: string;
  sentiment_score?: number;
  attention_score?: number;
  confidence?: number;
  sentiment_adjusted?: number;
  sentiment_label?: string;
  recommendation?: string;
  summary?: string;
  narratives?: string[];
  anomalies?: string[];
  sources?: Array<{ platform?: string; url?: string; title?: string }>;
  age_seconds?: number;
  eligible?: boolean;
  enabled?: boolean;
  applied?: boolean;
  fallback_reason?: string | null;
  technical_score?: number;
  final_score?: number;
}

export type RejectedTraceItem = DecisionTraceItem;
export type RejectedAssetItem = WatchlistDecisionItem;

interface CryptoEVSummary {
  score: number | null;
  state: string;
  n_trades: number;
  n_excluded_unreplayable?: number | null;
  w?: number | null;
  computed_at?: string | null;
}

function fmtValue(value: unknown): string {
  return formatEvaluationTraceValue(value);
}

function scoreColor(pct: number | null): string {
  if (pct == null) return "#64748B";
  if (pct >= 70) return "#34D399";
  if (pct >= 45) return "#FBBF24";
  return "#F87171";
}

function ScoreBar({ value, technical }: { value?: number | null; technical?: number | null }) {
  if (value == null) return <span className="text-[#334155] text-xs">—</span>;
  const pct = Math.min(100, Math.max(0, value));
  const color = scoreColor(pct);
  return (
    <div className="min-w-[120px]">
      <div className="flex items-center gap-2">
      <div className="relative flex-1 h-1.5 bg-[#1A2035] rounded-full overflow-hidden">
        <div
          className="h-full rounded-full transition-all duration-700"
          style={{ width: `${pct}%`, backgroundColor: color }}
        />
      </div>
      <span className="text-sm font-bold tabular-nums w-7 text-right" style={{ color }}>
        {Math.round(value)}
      </span>
      </div>
      {technical != null && Math.abs(technical - value) >= 0.05 && (
        <div className="mt-1 text-[9px] font-mono text-[#64748B]">T {technical.toFixed(1)} → F {value.toFixed(1)}</div>
      )}
    </div>
  );
}

function SocialScoreCell({ value }: { value?: SocialScoreSummary | null }) {
  if (!value || value.sentiment_score == null) return <span className="text-[#334155]">—</span>;
  const ageHours = value.age_seconds == null ? null : value.age_seconds / 3600;
  const live = value.eligible === true;
  const sentiment = Number(value.sentiment_score);
  const color = sentiment >= 60 ? "text-[#50D5A8]" : sentiment <= 40 ? "text-[#F87171]" : "text-[#FBBF24]";
  const title = [
    `Sentimento ${sentiment.toFixed(1)}`,
    value.attention_score != null ? `Atenção ${Number(value.attention_score).toFixed(1)}` : null,
    value.confidence != null ? `Confiança ${(Number(value.confidence) * 100).toFixed(0)}%` : null,
    ageHours != null ? `Idade ${ageHours.toFixed(1)}h` : null,
    value.applied ? "Aplicado ao score" : `Fallback: ${value.fallback_reason ?? "não aplicado"}`,
  ].filter(Boolean).join(" | ");
  return (
    <div className="min-w-[145px]" title={title}>
      <div className="flex items-center gap-1.5">
        <span className={`font-mono text-xs font-bold ${color}`}>S {sentiment.toFixed(0)}</span>
        <span className={`rounded border px-1 py-0.5 text-[8px] font-semibold ${live ? "border-[#2EC99A]/25 bg-[#2EC99A]/10 text-[#62DDB7]" : "border-[#475569]/30 bg-[#1E293B]/40 text-[#64748B]"}`}>
          {live ? (value.applied ? "LIVE" : "FRESH") : "STALE"}
        </span>
      </div>
      <div className="mt-1 font-mono text-[9px] text-[#64748B]">
        A {value.attention_score == null ? "—" : Number(value.attention_score).toFixed(0)} · C {value.confidence == null ? "—" : `${(Number(value.confidence) * 100).toFixed(0)}%`} · {ageHours == null ? "—" : `${ageHours.toFixed(1)}h`}
      </div>
    </div>
  );
}

function cryptoEvClass(state: string | null | undefined): string {
  if (state === "FAVORABLE") return "bg-[#34D399]/10 text-[#34D399] border-[#34D399]/20";
  if (state === "RISKY") return "bg-[#FBBF24]/10 text-[#FBBF24] border-[#FBBF24]/20";
  if (state === "AVOID") return "bg-[#F87171]/10 text-[#F87171] border-[#F87171]/20";
  if (state === "NEUTRAL") return "bg-[#1E2433] text-[#94A3B8] border-[#334155]";
  return "bg-[#0A0C14] text-[#4B5563] border-[#1A2035]";
}

function CryptoEVBadge({ value }: { value?: CryptoEVSummary | null }) {
  if (!value || value.score == null) return <span className="text-[#4B5563]">-</span>;
  const tip = [
    `Crypto EV: ${Number(value.score).toFixed(1)}`,
    value.state ? `state ${value.state}` : null,
    `N=${value.n_trades ?? 0}`,
    value.n_excluded_unreplayable != null ? `unreplayable=${value.n_excluded_unreplayable}` : null,
    value.w != null ? `w=${Number(value.w).toFixed(2)}` : null,
    value.computed_at ? `as of ${value.computed_at}` : null,
  ].filter(Boolean).join(" | ");
  return (
    <span
      className={`text-[10px] font-semibold px-1.5 py-0.5 rounded border tabular-nums ${cryptoEvClass(value.state)}`}
      title={tip}
    >
      {Number(value.score).toFixed(0)}
    </span>
  );
}

function itemPalette(status: "approved" | "rejected") {
  return status === "approved"
    ? {
        badge: "bg-[#34D399]/10 text-[#86EFAC] border border-[#34D399]/25",
        row: "border-l-2 border-l-[#34D399]/60",
        accent: "text-[#86EFAC]",
      }
    : {
        badge: "bg-[#F87171]/10 text-[#FCA5A5] border border-[#F87171]/25",
        row: "border-l-2 border-l-[#F87171]/60",
        accent: "text-[#FCA5A5]",
      };
}

function summarizeIndicators(item: WatchlistDecisionItem): string {
  if (item.failed_indicators.length > 0) return item.failed_indicators.join(", ");
  return item.details.indicators.slice(0, DECISION_SUMMARY_INDICATOR_LIMIT).join(", ") || "—";
}

function summarizeConditions(item: WatchlistDecisionItem): string {
  if (item.details.conditions.length === 0) return "—";
  if (item.details.conditions.length === 1) return item.details.conditions[0];
  return `${item.details.conditions[0]} +${item.details.conditions.length - 1}`;
}

export interface IndicatorColumnSpec {
  /** Storage key inside `current_values` (e.g. `_meta:price`, `adx`). */
  key: string;
  /** Header label rendered to the user. */
  label: string;
  /** Original profile field name (e.g. `price`, `taker_ratio`). */
  field: string;
}

/** Render a per-row indicator value for the dynamic column set. */
function fmtIndicatorCell(key: string, raw: unknown): string {
  if (raw == null) return "—";
  if (typeof raw === "boolean") return raw ? "✓" : "✗";
  const num = typeof raw === "number" ? raw : Number(raw);
  if (!Number.isFinite(num)) return String(raw);
  if (key === "_meta:price") {
    if (num >= 1) return `$${num.toFixed(2)}`;
    if (num >= 0.01) return `$${num.toFixed(4)}`;
    return `$${num.toPrecision(4)}`;
  }
  if (key === "_meta:volume_24h" || key === "_meta:market_cap") {
    if (num >= 1e9) return `$${(num / 1e9).toFixed(1)}B`;
    if (num >= 1e6) return `$${(num / 1e6).toFixed(1)}M`;
    if (num >= 1e3) return `$${(num / 1e3).toFixed(0)}K`;
    return `$${num.toFixed(0)}`;
  }
  if (key === "_meta:price_change_24h") {
    return `${num >= 0 ? "+" : ""}${num.toFixed(2)}%`;
  }
  if (Math.abs(num) >= 1_000_000_000) return `${(num / 1e9).toFixed(1)}B`;
  if (Math.abs(num) >= 1_000_000)     return `${(num / 1e6).toFixed(1)}M`;
  if (Math.abs(num) >= 1_000)         return `${(num / 1e3).toFixed(1)}K`;
  if (Math.abs(num) >= 100)           return num.toFixed(1);
  if (Math.abs(num) >= 1)             return num.toFixed(2);
  return num.toFixed(4);
}

function metricTopIndicator(items: WatchlistDecisionItem[]): string {
  const counts = new Map<string, number>();
  for (const item of items) {
    const indicators = item.failed_indicators.length > 0 ? item.failed_indicators : item.details.indicators;
    for (const indicator of indicators) {
      counts.set(indicator, (counts.get(indicator) ?? 0) + 1);
    }
  }
  return [...counts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))[0]?.[0] ?? "—";
}

export function WatchlistDecisionTable({
  items,
  loading,
  emptyMessage,
  indicatorCols,
  showScore = true,
}: {
  items: WatchlistDecisionItem[];
  loading: boolean;
  emptyMessage?: string;
  /**
   * Dynamic indicator columns derived from the watchlist's profile (Score
   * tab + filters). When provided, replaces the legacy "Indicators" /
   * "Conditions" summary columns with one column per indicator. ``price``
   * is always the first column. When omitted (or empty), falls back to
   * the legacy summary view.
   */
  indicatorCols?: IndicatorColumnSpec[];
  /** Hide the Score column (e.g. for L1 where scoring is not yet applied). */
  showScore?: boolean;
}) {
  const [expandedRow, setExpandedRow] = useState<string | null>(null);
  const [search, setSearch] = useState("");
  const [stage, setStage] = useState("all");
  const [status, setStatus] = useState<"all" | "approved" | "rejected">("all");
  const [indicator, setIndicator] = useState("all");
  const [sortKey, setSortKey] = useState<string | null>(null);
  const [sortDir, setSortDir] = useState<"asc" | "desc">("desc");

  const metrics = useMemo(() => {
    const approved = items.filter((item) => item.status === "approved").length;
    const rejected = items.length - approved;
    const stages = [...new Set(items.map((item) => item.stage).filter(Boolean))] as string[];
    const availableIndicators = [...new Set(items.flatMap((item) => item.details.indicators))].sort();
    return {
      total: items.length,
      approved,
      rejected,
      topIndicator: metricTopIndicator(items),
      stages,
      availableIndicators,
    };
  }, [items]);

  const filtered = useMemo(() => {
    return items.filter((item) => {
      if (stage !== "all" && item.stage !== stage) return false;
      if (status !== "all" && item.status !== status) return false;
      if (indicator !== "all" && !item.details.indicators.includes(indicator)) return false;
      if (search && !item.symbol.toLowerCase().includes(search.toLowerCase())) return false;
      return true;
    });
  }, [indicator, items, search, stage, status]);

  const BOOLEAN_DECISION_KEYS = new Set([
    "ema_trend", "ema9_gt_ema50", "ema9_gt_ema21", "ema_full_alignment", "di_trend",
  ]);

  const toggleSort = (key: string) => {
    if (sortKey === key) {
      setSortDir((d) => (d === "desc" ? "asc" : "desc"));
    } else {
      setSortKey(key);
      setSortDir("desc");
    }
  };

  const sortedFiltered = sortKey
    ? [...filtered].sort((a, b) => {
        let aVal: number, bVal: number;
        if (sortKey === "score") {
          aVal = a.alpha_score ?? -Infinity;
          bVal = b.alpha_score ?? -Infinity;
        } else if (sortKey === "ml") {
          aVal = a.ml_probability ?? -Infinity;
          bVal = b.ml_probability ?? -Infinity;
        } else if (sortKey === "crypto_ev") {
          aVal = a.crypto_ev?.score ?? -Infinity;
          bVal = b.crypto_ev?.score ?? -Infinity;
        } else {
          const av = a.current_values?.[sortKey];
          const bv = b.current_values?.[sortKey];
          aVal = typeof av === "number" ? av : av == null ? -Infinity : Number(av);
          bVal = typeof bv === "number" ? bv : bv == null ? -Infinity : Number(bv);
          if (isNaN(aVal)) aVal = -Infinity;
          if (isNaN(bVal)) bVal = -Infinity;
        }
        return sortDir === "desc" ? bVal - aVal : aVal - bVal;
      })
    : filtered;

  if (loading) {
    return <div className="px-4 py-6 text-sm text-[#4B5563]">Loading decision snapshot…</div>;
  }

  return (
    <div className="space-y-4 p-4">
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
        <MetricCard label="Total" value={metrics.total} valueClass="text-[#E2E8F0]" />
        <MetricCard label="Approved" value={metrics.approved} valueClass="text-[#86EFAC]" />
        <MetricCard label="Rejected" value={metrics.rejected} valueClass="text-[#FCA5A5]" />
        <MetricCard label="Top Indicator" value={metrics.topIndicator} valueClass="text-[#E2E8F0]" compact />
      </div>

      <div className="flex flex-wrap gap-2">
        <input
          value={search}
          onChange={(event) => setSearch(event.target.value)}
          placeholder="Search symbol"
          className="min-w-[180px] rounded-lg border border-[#1E2433] bg-[#0A0B10] px-3 py-2 text-sm text-[#E2E8F0] focus:outline-none"
        />
        <select
          value={stage}
          onChange={(event) => setStage(event.target.value)}
          className="rounded-lg border border-[#1E2433] bg-[#0A0B10] px-3 py-2 text-sm text-[#E2E8F0] focus:outline-none"
        >
          <option value="all">All stages</option>
          {metrics.stages.map((value) => (
            <option key={value} value={value}>{value}</option>
          ))}
        </select>
        <select
          value={status}
          onChange={(event) => setStatus(event.target.value as "all" | "approved" | "rejected")}
          className="rounded-lg border border-[#1E2433] bg-[#0A0B10] px-3 py-2 text-sm text-[#E2E8F0] focus:outline-none"
        >
          <option value="all">All statuses</option>
          <option value="approved">approved</option>
          <option value="rejected">rejected</option>
        </select>
        <select
          value={indicator}
          onChange={(event) => setIndicator(event.target.value)}
          className="rounded-lg border border-[#1E2433] bg-[#0A0B10] px-3 py-2 text-sm text-[#E2E8F0] focus:outline-none"
        >
          <option value="all">All indicators</option>
          {metrics.availableIndicators.map((value) => (
            <option key={value} value={value}>{value}</option>
          ))}
        </select>
      </div>

      {sortedFiltered.length === 0 ? (
        <div className="rounded-xl border border-[#1E2433] bg-[#06080E] px-4 py-10 text-center text-sm text-[#4B5563]">
          {emptyMessage ?? "No decision snapshots for the current filters."}
        </div>
      ) : (() => {
          // Dynamic column mode: when the backend supplies profile_indicators
          // (always at least `price`), render one column per indicator and
          // drop the legacy summary columns. Fallback to the legacy view
          // only when the watchlist truly has no profile-driven columns.
          const dynCols = indicatorCols ?? [];
          const useDynamic = dynCols.length > 0;
          // Column count: chevron + Symbol + [Score] + ML + [dynCols] + Exaustão + Stage + Status + Timestamp
          //          OR  chevron + Symbol + [Score] + ML + Exaustão + Stage + Status + Indicators + Conditions + Timestamp
          const scoreCol = showScore ? 1 : 0;
          const totalCols = useDynamic ? 9 + scoreCol + dynCols.length : 11 + scoreCol;
          const minWidth = useDynamic ? Math.max(1040, 740 + dynCols.length * 110) : 1360;
          return (
        <div className="overflow-x-auto">
          <table className="w-full text-xs" style={{ minWidth: `${minWidth}px` }}>
            <thead>
              <tr className="border-b border-[#1A2035] bg-[#060810]">
                <th className="w-8 px-2 py-2.5" />
                <th className="px-3 py-2.5 text-left text-[#4B5563]">Symbol</th>
                {showScore && (
                  <th className="px-3 py-2.5 text-left text-[#4B5563] min-w-[130px]">
                    <button onClick={() => toggleSort("score")} className="flex items-center gap-1 hover:text-[#94A3B8] transition-colors">
                      Score
                      <span className={`text-[9px] ${sortKey === "score" ? "text-[#60A5FA]" : "opacity-30"}`}>
                        {sortKey === "score" ? (sortDir === "desc" ? "▼" : "▲") : "⇅"}
                      </span>
                    </button>
                  </th>
                )}
                <th className="px-3 py-2.5 text-left text-[#4B5563] whitespace-nowrap">Social</th>
                <th className="px-3 py-2.5 text-center text-[#4B5563] whitespace-nowrap">
