function formatLargeNumber(num: number | null | undefined): string {
  if (!num) return "-";
  if (num >= 1e12) return `${(num / 1e12).toFixed(1)}T`;
  if (num >= 1e9) return `${(num / 1e9).toFixed(1)}B`;
  if (num >= 1e6) return `${(num / 1e6).toFixed(1)}M`;
  if (num >= 1e3) return `${(num / 1e3).toFixed(1)}K`;
  return num.toFixed(0);
}

"use client";

import useSWR from "swr";
import { apiGet, apiPut } from "@/lib/api";
import { useCallback } from "react";

/**
 * Hook for fetching and updating a config_type from the Scalpyn ConfigService.
 *
 * Usage:
 *   const { config, updateConfig, isLoading, error } = useConfig("risk");
 */
export function useConfig(configType: string, poolId?: string) {
  const endpoint = poolId
    ? `/config/${configType}?pool_id=${poolId}`
    : `/config/${configType}`;

  const { data, error, isLoading, mutate } = useSWR(
    endpoint,
    () => apiGet(endpoint).then((res) => res.data),
    { revalidateOnFocus: false, dedupingInterval: 5000 }
  );

  const updateConfig = useCallback(
    async (newConfig: Record<string, any>) => {
      const updateEndpoint = poolId
        ? `/config/${configType}?pool_id=${poolId}`
        : `/config/${configType}`;
      await apiPut(updateEndpoint, newConfig);
      await mutate();
    },
    [configType, poolId, mutate]
  );

  const resetConfig = useCallback(async () => {
    // POST reset endpoint would reload defaults
    await mutate();
  }, [mutate]);

  return {
    config: data ?? {},
    updateConfig,
    resetConfig,
    isLoading,
    error,
    mutate,
  };
}

"use client";

import useSWR from 'swr';
import { useCallback } from 'react';
import { apiGet, apiPost } from '@/lib/api';
import { extractPositions, extractPositionsSummary } from '@/lib/engineStatus';

export type TradingProfile = 'spot' | 'futures';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface EngineInfo {
  running: boolean;
  paused: boolean;
  state?: string;
  uptime_seconds?: number;
  [key: string]: any;
}

export interface CapitalInfo {
  total: number;
  used: number;
  free: number;
  [key: string]: any;
}

export interface EngineStatusResponse {
  engine?: EngineInfo;
  /** Raw payload — read via `extractPositions` / `extractPositionsSummary`. */
  positions?: unknown;
  capital?: CapitalInfo;
  balance?: Record<string, any>;
  [key: string]: any;
}

export interface UseEngineStatusReturn {
  /** Full raw API response from the status endpoint. */
  status: EngineStatusResponse | null;
  /** True if the engine is currently running (not stopped). */
  isRunning: boolean;
  /** True if the engine is paused. */
  isPaused: boolean;
  /** Always an array — normalised from the raw payload. */
  positions: Record<string, any>[];
  /** Original dict payload (spot/futures summary) or null when it was an array/missing. */
  positionsSummary: Record<string, any> | null;
  /** Capital summary from the status response. */
  capital: CapitalInfo | null;
  /** Balance information from the status response. */
  balance: Record<string, any> | null;
  /** True while the initial SWR fetch is in progress. */
  isLoading: boolean;
  /** Any error from the status fetch. */
  error: Error | null;
  /** Start the engine. */
  startEngine: () => Promise<void>;
  /** Pause a running engine. */
  pauseEngine: () => Promise<void>;
  /** Resume a paused engine. */
  resumeEngine: () => Promise<void>;
  /** Gracefully stop the engine. */
  stopEngine: () => Promise<void>;
  /** Manually re-fetch the status. */
  mutate: () => void;
}

// ---------------------------------------------------------------------------
// Hook
// ---------------------------------------------------------------------------

/**
 * Polls the engine status every 5 seconds and exposes lifecycle control functions.
 *
 * - profile: 'spot' | 'futures'
 * - Status endpoint: GET /api/{profile}-engine/status
 * - Control endpoints:
 *     POST /api/{profile}-engine/start
 *     POST /api/{profile}-engine/pause
 *     POST /api/{profile}-engine/resume
 *     POST /api/{profile}-engine/stop
 */
export function useEngineStatus(profile: TradingProfile): UseEngineStatusReturn {
  const baseUrl = `/api/${profile}-engine`;
  const statusEndpoint = `${baseUrl}/status`;

  const {
    data,
    error: swrError,
    isLoading,
    mutate,
  } = useSWR<EngineStatusResponse>(
    statusEndpoint,
    () => apiGet<EngineStatusResponse>(statusEndpoint),
    {
      refreshInterval: 5_000,
      revalidateOnFocus: true,
      dedupingInterval: 2_000,
    }
  );

  // ── Derived state ─────────────────────────────────────────────────────────
  const status = data ?? null;
  const isRunning = status?.engine?.running ?? false;
  const isPaused = status?.engine?.paused ?? false;
  const rawPositions = status?.positions;
  const positions = extractPositions(rawPositions);
  const positionsSummary = extractPositionsSummary(rawPositions);
  const capital = status?.capital ?? null;
  const balance = status?.balance ?? null;

  // ── Control helpers ───────────────────────────────────────────────────────

  const postControl = useCallback(
    async (action: 'start' | 'pause' | 'resume' | 'stop') => {
      await apiPost(`${baseUrl}/${action}`);
      // Action succeeded — refresh status best-effort; SWR will reconcile
      // on the next poll if this throws.
      try {
        await mutate();
      } catch (refreshErr) {
        // eslint-disable-next-line no-console
        console.warn(`[engine] post-${action} status refresh failed:`, refreshErr);
      }
    },
    [baseUrl, mutate]
  );

  const startEngine  = useCallback(() => postControl('start'),  [postControl]);
  const pauseEngine  = useCallback(() => postControl('pause'),  [postControl]);
  const resumeEngine = useCallback(() => postControl('resume'), [postControl]);
  const stopEngine   = useCallback(() => postControl('stop'),   [postControl]);

  // ── Normalise error ───────────────────────────────────────────────────────
  const error: Error | null =
    swrError instanceof Error
      ? swrError
      : swrError
      ? new Error(String(swrError))
      : null;

  // ── Return ────────────────────────────────────────────────────────────────
  return {
    status,
    isRunning,
    isPaused,
    positions,
    positionsSummary,
    capital,
    balance,
    isLoading,
    error,
    startEngine,
    pauseEngine,
    resumeEngine,
    stopEngine,
    mutate: () => { mutate(); },
  };
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";

/**
 * Decoded payload of a single ``trade_decisions`` row, as emitted by
 * the backend ``decision_event_bus`` and consumed via SSE.
 *
 * Shape mirrors the JSON dict built in
 * ``decision_audit_service._record_decision_raw``. All optional
 * fields are nullable in DB and therefore optional here too.
 */
export interface LiveDecisionEvent {
  trace_id: string;
  user_id?: string | null;
  pool_id?: string | null;
  symbol: string;
  market_type: "spot" | "futures" | string;
  exchange?: string | null;
  status: "APPROVED" | "REJECTED" | "SKIPPED" | "BLOCKED" | string;
  stage?: string | null;
  reason?: string | null;
  blocking_rule?: string | null;
  rule_details?: Record<string, unknown> | null;
  score_breakdown?: Record<string, unknown> | null;
  latency_ms?: Record<string, number> | null;
  trade_id?: string | null;
  decided_at?: string;
}

export type LogFilter = "all" | "spot" | "futures" | "APPROVED" | "REJECTED";

export type StreamStatus = "connecting" | "live" | "offline";

export interface UseLiveLogStreamOptions {
  /** Hard cap on the in-memory buffer (oldest events evicted). */
  maxBuffer?: number;
  /** Reconnect base delay in ms (capped exponential). */
  reconnectDelayMs?: number;
}

export interface UseLiveLogStreamReturn {
  /** Buffered + filtered + (when paused) frozen events list. */
  events: LiveDecisionEvent[];
  /** Total events received this session, ignoring filters/pause. */
  totalReceived: number;
  /** Raw APPROVED count over the in-memory buffer (NOT filtered by chip / pause). */
  rawApprovedCount: number;
  /** Raw REJECTED count over the in-memory buffer (NOT filtered by chip / pause). */
  rawRejectedCount: number;
  /** Current connection status. */
  status: StreamStatus;
  /** Active filter (clicked chip). */
  filter: LogFilter;
  setFilter: (f: LogFilter) => void;
  /** Pause the visible buffer (SSE stays connected). */
  paused: boolean;
  setPaused: (p: boolean) => void;
  /** Drop everything from the local buffer (does not disconnect). */
  clear: () => void;
}

const DEFAULT_MAX = 200;
const DEFAULT_RECONNECT_MS = 5_000;
const SSE_URL = "/api/live/log-stream";


/**
 * SSE consumer for the diagnostics page.
 *
 * EventSource doesn't allow custom headers, so we can't use the JWT
 * via ``Authorization: Bearer …`` with the native API. We hand-roll
 * the SSE protocol over ``fetch`` + a streamed ``ReadableStream`` so
 * the existing localStorage-token auth flow keeps working without
 * having to expose a token via query string (which would leak into
 * server access logs).
 *
 * Reconnect logic:
 *   * On any error / EOF / non-2xx response, status flips to
 *     ``"offline"`` and we wait ``reconnectDelayMs`` before retrying.
 *   * The retry loop runs until the component unmounts (AbortController
 *     drives shutdown).
 *   * Heartbeat comments (``: heartbeat``) sent by the server keep the
 *     stream alive but produce no event — they're skipped by the
 *     parser below since they don't start with ``data:``.
 *
 * Buffer management:
 *   * We push to a ref (``bufferRef``) and copy to React state on a
 *     micro-task to coalesce rapid bursts (avoids re-rendering once
 *     per event when the pipeline produces many decisions in a tick).
 *   * When ``paused`` is true, buffer keeps growing in the background
 *     up to ``maxBuffer``; the *visible* events array is the snapshot
 *     taken when ``paused`` was toggled on.
 */
export function useLiveLogStream(
  opts: UseLiveLogStreamOptions = {}
): UseLiveLogStreamReturn {
  const maxBuffer = opts.maxBuffer ?? DEFAULT_MAX;
  const reconnectDelayMs = opts.reconnectDelayMs ?? DEFAULT_RECONNECT_MS;

  const [events, setEvents] = useState<LiveDecisionEvent[]>([]);
  const [status, setStatus] = useState<StreamStatus>("connecting");
  const [filter, setFilter] = useState<LogFilter>("all");
  const [paused, setPausedState] = useState(false);

  // Counters used by the cycle-metrics card. Kept in refs so a burst
  // of N events causes a single coalesced React render (set inside
  // ``scheduleFlush``) instead of N renders — this is the "render
  // storm" pitfall the previous implementation had.
  const totalReceivedRef = useRef(0);
  const approvedRawRef = useRef(0);
  const rejectedRawRef = useRef(0);
  const [totalReceived, setTotalReceived] = useState(0);
  const [rawApprovedCount, setRawApprovedCount] = useState(0);
  const [rawRejectedCount, setRawRejectedCount] = useState(0);

  const bufferRef = useRef<LiveDecisionEvent[]>([]);
  const pausedRef = useRef(false);
  const frozenRef = useRef<LiveDecisionEvent[] | null>(null);
  const flushPendingRef = useRef(false);

  // Schedule a coalesced state update so a burst of N events triggers
  // a single React render instead of N. We flush both the visible
  // buffer AND the running counters in the same micro-task so the
  // BalanceMetrics card stays in sync with the trace viewer.
  const scheduleFlush = useCallback(() => {
    if (flushPendingRef.current) return;
    flushPendingRef.current = true;
    queueMicrotask(() => {
      flushPendingRef.current = false;
      // Counters always update — they're independent of pause state.
      setTotalReceived(totalReceivedRef.current);
      setRawApprovedCount(approvedRawRef.current);
      setRawRejectedCount(rejectedRawRef.current);
      if (pausedRef.current && frozenRef.current !== null) {
        // Visible buffer is frozen; ignore the events flush until unpause.
        return;
      }
      setEvents([...bufferRef.current]);
    });
  }, []);

  const setPaused = useCallback((p: boolean) => {
    pausedRef.current = p;
    if (p) {
      // Snapshot the current buffer so the table stops moving.
      frozenRef.current = [...bufferRef.current];
      setEvents(frozenRef.current);
    } else {
      frozenRef.current = null;
      setEvents([...bufferRef.current]);
    }
    setPausedState(p);
  }, []);

  const clear = useCallback(() => {
    bufferRef.current = [];
    frozenRef.current = pausedRef.current ? [] : null;
    // Counters reflect "events currently in buffer" — clearing the
    // buffer must also clear them. ``totalReceived`` keeps its session
    // tally so the operator can still see throughput.
    approvedRawRef.current = 0;
    rejectedRawRef.current = 0;
    setRawApprovedCount(0);
    setRawRejectedCount(0);
    setEvents([]);
  }, []);

  const pushEvent = useCallback(
    (evt: LiveDecisionEvent) => {
      const buf = bufferRef.current;
      buf.push(evt);
      if (evt.status === "APPROVED") approvedRawRef.current++;
      else if (evt.status === "REJECTED") rejectedRawRef.current++;
      if (buf.length > maxBuffer) {
        // Evict oldest; decrement the matching counter so the running
        // raw counts always reflect the current buffer contents (not
        // a session-wide tally — see ``totalReceivedRef`` for that).
        const evicted = buf.splice(0, buf.length - maxBuffer);
        for (const e of evicted) {
          if (e.status === "APPROVED" && approvedRawRef.current > 0) approvedRawRef.current--;
          else if (e.status === "REJECTED" && rejectedRawRef.current > 0) rejectedRawRef.current--;
        }
      }
      totalReceivedRef.current++;
      scheduleFlush();
    },
    [maxBuffer, scheduleFlush]
  );

  // ── Connection loop ────────────────────────────────────────────────
  useEffect(() => {
    const ac = new AbortController();
    let cancelled = false;
    let retryTimer: ReturnType<typeof setTimeout> | null = null;

    async function readStream() {
      while (!cancelled) {
        setStatus("connecting");

        const token =
          typeof window === "undefined"
            ? null
            : window.localStorage.getItem("token");
        const headers: Record<string, string> = { Accept: "text/event-stream" };
        if (token) headers.Authorization = `Bearer ${token}`;

        try {
          const res = await fetch(SSE_URL, {
            method: "GET",
            headers,
            signal: ac.signal,
            cache: "no-store",
          });

          if (!res.ok || !res.body) {
            if (!cancelled) setStatus("offline");
            await wait(reconnectDelayMs, ac.signal);
            continue;
          }

          if (!cancelled) setStatus("live");

          const reader = res.body
            .pipeThrough(new TextDecoderStream())
            .getReader();
          let pending = "";

          while (!cancelled) {
            const { value, done } = await reader.read();
            if (done) break;
            pending += value;

            // SSE messages end with a blank line (`\n\n`). Each message
            // can have multiple ``data:`` lines that should be joined
            // by ``\n`` per the spec; we use ``data:`` only here.
            let sepIdx;
            while ((sepIdx = pending.indexOf("\n\n")) !== -1) {
              const raw = pending.slice(0, sepIdx);
              pending = pending.slice(sepIdx + 2);

              const dataLines: string[] = [];
              for (const line of raw.split("\n")) {
                if (line.startsWith("data:")) {
                  dataLines.push(line.slice(5).trimStart());
                }
              }
              if (dataLines.length === 0) continue; // heartbeat or comment
              const dataStr = dataLines.join("\n");
              try {
                const parsed = JSON.parse(dataStr) as LiveDecisionEvent;
                if (parsed && typeof parsed === "object") {
                  pushEvent(parsed);
                }
              } catch {
                // Malformed payload — drop silently.
              }
            }
          }

          if (!cancelled) setStatus("offline");
          await wait(reconnectDelayMs, ac.signal);
        } catch (err) {
          if (cancelled || (err as Error)?.name === "AbortError") return;
          setStatus("offline");
          await wait(reconnectDelayMs, ac.signal);
        }
      }
    }

    readStream();

    return () => {
      cancelled = true;
      if (retryTimer) clearTimeout(retryTimer);
      ac.abort();
    };
  }, [reconnectDelayMs, pushEvent]);

  // ── Filtering ──────────────────────────────────────────────────────
  const filtered = useMemo(() => {
    if (filter === "all") return events;
    if (filter === "spot" || filter === "futures") {
      return events.filter((e) => e.market_type === filter);
    }
    return events.filter((e) => e.status === filter);
  }, [events, filter]);

  return {
    events: filtered,
    totalReceived,
    rawApprovedCount,
    rawRejectedCount,
    status,
    filter,
    setFilter,
    paused,
    setPaused,
    clear,
  };
}

/**
 * ``setTimeout`` with abort support that **always** removes its listener
 * on resolve. Earlier versions registered an ``abort`` listener with
 * ``{once: true}`` but never cleared it on the normal-resolve path,
 * so a long reconnect loop would accumulate listeners on the same
 * AbortSignal until the component unmounted.
 */
function wait(ms: number, signal: AbortSignal): Promise<void> {
  return new Promise((resolve) => {
    if (signal.aborted) {
      resolve();
      return;
    }
    let t: ReturnType<typeof setTimeout> | null = null;
    const onAbort = () => {
      if (t !== null) clearTimeout(t);
      signal.removeEventListener("abort", onAbort);
      resolve();
    };
    signal.addEventListener("abort", onAbort);
    t = setTimeout(() => {
      signal.removeEventListener("abort", onAbort);
      resolve();
    }, ms);
  });
}

"use client";

import useSWR from 'swr';
import { useMemo } from 'react';
import { apiGet } from '@/lib/api';

export type TradingProfile = 'spot' | 'futures';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface Position {
  id?: string;
  symbol?: string;
  side?: 'long' | 'short' | string;
  entry_price?: number;
  current_price?: number;
  mark_price?: number;
  size?: number;
  notional?: number;
  unrealised_pnl?: number;
  unrealised_pnl_pct?: number;
  liquidation_price?: number;
  leverage?: number;
  profile?: TradingProfile;
  is_underwater?: boolean;
  [key: string]: any;
}

export interface CapitalSummary {
  totalCapital: number;
  spotCapital: number;
  futuresCapital: number;
  freeCapital: number;
}

export interface UsePositionsReturn {
  /** Positions belonging to the spot engine. */
  spotPositions: Position[];
  /** Positions belonging to the futures engine. */
  futuresPositions: Position[];
  /** Merged array of all positions across both profiles. */
  allPositions: Position[];
  /** Number of positions where unrealised PnL < 0. */
  underwaterCount: number;
  /** Sum of negative unrealised PnL across underwater positions. */
  underwaterValue: number;
  /**
   * Futures position closest to liquidation.
   * "Closest" = smallest absolute distance between current/mark price and liquidation price.
   */
  nearestLiquidation: Position | null;
  /** Capital summary aggregated from both engines. */
  summary: CapitalSummary;
  /** True while either fetch is in flight. */
  isLoading: boolean;
  /** Re-fetch both status endpoints. */
  mutate: () => void;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function toPositionArray(raw: any, profile: TradingProfile): Position[] {
  const list: any[] = Array.isArray(raw?.positions) ? raw.positions : [];
  return list.map((p) => ({ ...p, profile }));
}

function extractCapital(raw: any): { total: number; free: number } {
  const capital = raw?.capital ?? raw?.balance ?? {};
  return {
    total: capital?.total ?? capital?.equity ?? 0,
    free:  capital?.free  ?? capital?.available ?? 0,
  };
}

function liquidationDistance(pos: Position): number {
  const price = pos.mark_price ?? pos.current_price ?? 0;
  const liq   = pos.liquidation_price;
  if (!liq || !price) return Infinity;
  return Math.abs(price - liq);
}

// ---------------------------------------------------------------------------
// Internal single-profile fetcher
// ---------------------------------------------------------------------------

function useProfileStatus(profile: TradingProfile | null) {
  const endpoint = profile ? `/api/${profile}-engine/status` : null;

  const { data, isLoading, mutate } = useSWR(
    endpoint,
    endpoint ? () => apiGet(endpoint) : null,
    {
      refreshInterval: 10_000,
      revalidateOnFocus: true,
      dedupingInterval: 4_000,
    }
  );

  return { data: data ?? null, isLoading, mutate };
}

// ---------------------------------------------------------------------------
// Hook
// ---------------------------------------------------------------------------

/**
 * Aggregates open positions from one or both trading engines.
 *
 * @param profile - 'spot' | 'futures' to fetch a single profile,
 *                  or undefined to fetch both and merge.
 */
export function usePositions(profile?: TradingProfile): UsePositionsReturn {
  const fetchSpot    = profile === undefined || profile === 'spot';
  const fetchFutures = profile === undefined || profile === 'futures';

  const spot    = useProfileStatus(fetchSpot    ? 'spot'    : null);
  const futures = useProfileStatus(fetchFutures ? 'futures' : null);

  // ── Positions ─────────────────────────────────────────────────────────────
  const spotPositions: Position[]    = useMemo(
    () => (fetchSpot    ? toPositionArray(spot.data,    'spot')    : []),
    [spot.data,    fetchSpot]
  );

  const futuresPositions: Position[] = useMemo(
    () => (fetchFutures ? toPositionArray(futures.data, 'futures') : []),
    [futures.data, fetchFutures]
  );

  const allPositions: Position[] = useMemo(
    () => [...spotPositions, ...futuresPositions],
    [spotPositions, futuresPositions]
  );

  // ── Underwater metrics ────────────────────────────────────────────────────
  const { underwaterCount, underwaterValue } = useMemo(() => {
    const underwater = allPositions.filter(
      (p) => (p.unrealised_pnl ?? 0) < 0 || p.is_underwater === true
    );
    return {
      underwaterCount: underwater.length,
      underwaterValue: underwater.reduce((sum, p) => sum + (p.unrealised_pnl ?? 0), 0),
    };
  }, [allPositions]);

  // ── Nearest liquidation (futures only) ───────────────────────────────────
  const nearestLiquidation: Position | null = useMemo(() => {
    if (futuresPositions.length === 0) return null;
    const withLiq = futuresPositions.filter((p) => p.liquidation_price != null);
    if (withLiq.length === 0) return null;
    return withLiq.reduce<Position>((closest, pos) =>
      liquidationDistance(pos) < liquidationDistance(closest) ? pos : closest
    , withLiq[0]);
  }, [futuresPositions]);

  // ── Capital summary ───────────────────────────────────────────────────────
  const summary: CapitalSummary = useMemo(() => {
    const s = extractCapital(spot.data);
    const f = extractCapital(futures.data);
    return {
      totalCapital:   s.total + f.total,
      spotCapital:    s.total,
      futuresCapital: f.total,
      freeCapital:    s.free  + f.free,
    };
  }, [spot.data, futures.data]);

  // ── Loading ───────────────────────────────────────────────────────────────
  const isLoading = spot.isLoading || futures.isLoading;

  // ── Mutate both ───────────────────────────────────────────────────────────
  const mutate = () => {
    spot.mutate();
    futures.mutate();
  };

  // ── Return ────────────────────────────────────────────────────────────────
  return {
    spotPositions,
    futuresPositions,
    allPositions,
    underwaterCount,
    underwaterValue,
    nearestLiquidation,
    summary,
    isLoading,
    mutate,
  };
}

"use client";

import useSWR from 'swr';
import { useCallback, useEffect, useState } from 'react';
import { apiGet, apiPut } from '@/lib/api';

export type TradingProfile = 'spot' | 'futures';

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Deep-clone a plain object via JSON round-trip. */
function deepClone<T>(value: T): T {
  return JSON.parse(JSON.stringify(value));
}

/** Structural equality via JSON serialisation. */
function isEqual(a: unknown, b: unknown): boolean {
  return JSON.stringify(a) === JSON.stringify(b);
}

/**
 * Set a nested property in an object using a dot-notation path.
 * Returns a new object (immutable update).
 *
 * Example: setByPath({ buying: { score_threshold: 70 } }, "buying.score_threshold", 80)
 */
function setByPath(obj: Record<string, any>, path: string, value: any): Record<string, any> {
  const keys = path.split('.');
  const next = deepClone(obj);
  let cursor: any = next;

  for (let i = 0; i < keys.length - 1; i++) {
    const key = keys[i];
    if (cursor[key] === null || typeof cursor[key] !== 'object') {
      cursor[key] = {};
    }
    cursor = cursor[key];
  }

  cursor[keys[keys.length - 1]] = value;
  return next;
}

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface UseTradingConfigReturn {
  /** Current locally-edited config (may differ from saved server config). */
  config: Record<string, any>;
  /** Factory defaults fetched from the /default endpoint. */
  defaultConfig: Record<string, any> | null;
  /** Deep-update a field using dot-notation path, e.g. "buying.score_threshold". */
  updateConfig: (path: string, value: any) => void;
  /** Discard local edits and restore the last server-fetched config. */
  resetConfig: () => void;
  /** Persist the current local config to the server via PUT. */
  saveConfig: () => Promise<void>;
  /** True while the initial SWR fetch is in progress. */
  isLoading: boolean;
  /** True while a PUT save request is in flight. */
  isSaving: boolean;
  /** True if the local config differs from the server config. */
  isDirty: boolean;
  /** Any fetch/save error. */
  error: Error | null;
}

// ---------------------------------------------------------------------------
// Hook
// ---------------------------------------------------------------------------

/**
 * Fetches and manages the trading engine config for the given profile.
 *
 * - profile: 'spot' | 'futures'
 * - Server config:  GET  /config/{profile}_engine
 * - Default config: GET  /api/{profile}-engine/config/default
 * - Save config:    PUT  /config/{profile}_engine
 */
export function useTradingConfig(profile: TradingProfile): UseTradingConfigReturn {
  const configEndpoint = `/config/${profile}_engine`;
  const defaultEndpoint = `/api/${profile}-engine/config/default`;

  // ── Server config via SWR ─────────────────────────────────────────────────
  const {
    data: serverData,
    error: fetchError,
    isLoading,
    mutate,
  } = useSWR<Record<string, any>>(
    configEndpoint,
    () => apiGet(configEndpoint).then((res) => res?.data ?? res),
    {
      revalidateOnFocus: false,
      dedupingInterval: 10_000,
    }
  );

  // ── Default config via SWR ────────────────────────────────────────────────
  const { data: defaultData } = useSWR<Record<string, any>>(
    defaultEndpoint,
    () => apiGet(defaultEndpoint).then((res) => res?.data ?? res),
    {
      revalidateOnFocus: false,
      dedupingInterval: 60_000,
    }
  );

  // ── Local edited state ────────────────────────────────────────────────────
  const [localConfig, setLocalConfig] = useState<Record<string, any>>({});
  const [isSaving, setIsSaving] = useState(false);
  const [saveError, setSaveError] = useState<Error | null>(null);

  // Seed / sync local state whenever fresh server data arrives.
  useEffect(() => {
    if (serverData && Object.keys(serverData).length > 0) {
      setLocalConfig((prev) => {
        // Only overwrite if local state is empty (first load) or matches server
        // (no pending edits). This prevents wiping unsaved changes on revalidation.
        if (Object.keys(prev).length === 0 || isEqual(prev, serverData)) {
          return deepClone(serverData);
        }
        return prev;
      });
    }
  }, [serverData]);

  // ── Derived ──────────────────────────────────────────────────────────────
  const isDirty =
    serverData != null &&
    Object.keys(localConfig).length > 0 &&
    !isEqual(localConfig, serverData);

  // ── Actions ───────────────────────────────────────────────────────────────

  const updateConfig = useCallback((path: string, value: any) => {
    setLocalConfig((prev) => setByPath(prev, path, value));
  }, []);

  const resetConfig = useCallback(() => {
    if (serverData) {
      setLocalConfig(deepClone(serverData));
    }
  }, [serverData]);

  const saveConfig = useCallback(async () => {
    if (!localConfig || Object.keys(localConfig).length === 0) return;
    setIsSaving(true);
    setSaveError(null);
    try {
      await apiPut(configEndpoint, localConfig);
      // Update SWR cache so isDirty immediately becomes false.
      await mutate(deepClone(localConfig), { revalidate: false });
    } catch (err) {
      const error = err instanceof Error ? err : new Error(String(err));
      setSaveError(error);
      throw error;
    } finally {
      setIsSaving(false);
    }
  }, [configEndpoint, localConfig, mutate]);

  // ── Return ────────────────────────────────────────────────────────────────
  return {
    config: localConfig,
    defaultConfig: defaultData ?? null,
    updateConfig,
    resetConfig,
    saveConfig,
    isLoading,
    isSaving,
    isDirty,
    error: saveError ?? (fetchError instanceof Error ? fetchError : fetchError ? new Error(String(fetchError)) : null),
  };
}

