"use client";

import { useEffect, useRef, useState, useCallback } from "react";

// ---------------------------------------------------------------------------
// Channel types
// ---------------------------------------------------------------------------

export type WSChannel =
  | "market"
  | "signals"
  | "trades"
  | "decisions"
  | "positions"
  | "alerts"
  | "engine"
  | "macro";

// ---------------------------------------------------------------------------
// Message types
// ---------------------------------------------------------------------------

export interface WSMessage {
  type: string;
  ts?: string;
  [key: string]: any;
}

export interface PositionUpdateMessage extends WSMessage {
  type: "position_update";
  position_id: string;
  symbol: string;
  profile: "spot" | "futures";
  unrealised_pnl: number;
  mark_price: number;
  liq_distance_pct?: number;
}

export interface AlertMessage extends WSMessage {
  type:
    | "TP_HIT"
    | "SL_HIT"
    | "EMERGENCY"
    | "ANTI_LIQ_WARNING"
    | "FUNDING_DRAIN"
    | "LIQUIDATED";
  symbol: string;
  profile: "spot" | "futures";
  details: Record<string, any>;
}

export interface EngineStatusMessage extends WSMessage {
  type: "engine_status";
  profile: "spot" | "futures";
  running: boolean;
  paused: boolean;
