export type AlertSeverity = "info" | "warning" | "critical" | "emergency";

export function getAlertSeverity(type: AlertMessage["type"]): AlertSeverity {
  switch (type) {
    case "TP_HIT":
    case "SL_HIT":
      return "info";
    case "ANTI_LIQ_WARNING":
    case "FUNDING_DRAIN":
      return "warning";
    case "EMERGENCY":
    case "LIQUIDATED":
      return "emergency";
    default:
      return "info";
  }
}

